/**
 * POST /api/attendance/send-notification
 * ─────────────────────────────────────────────────────────────────────────────
 * Send attendance-related email notifications.
 *
 * Allowed roles: admin, manager
 *
 * Body:
 * {
 *   type:      "late_checkin" | "absent_reminder" | "early_checkout";
 *   user_id:   string;              // Target employee UID
 *   message?:  string;              // Optional custom message (for absent_reminder)
 *   // For late_checkin — extra data auto-fetched from attendance record
 *   attendance_id?: string;
 *   // For early_checkout
 *   checkout_time?: string;
 *   reason?:       string;
 * }
 */

import { errorResponse } from "@/lib/api/error";
import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";
import { emailService, setEmailCompanyName, setEmailCompanyEmail, setEmailCompanyPhone } from "@/lib/services/email.service";
import { protect } from "@/lib/api/protect";

const NOTIFICATION_TYPES = ["late_checkin", "absent_reminder", "early_checkout"] as const;
type NotificationType = (typeof NOTIFICATION_TYPES)[number];

interface RequestBody {
  type: NotificationType;
  user_id: string;
  message?: string;
  attendance_id?: string;
  checkout_time?: string;
  reason?: string;
}

export async function POST(req: NextRequest) {
  const blocked = protect(req, { maxRequests: 20, windowMs: 60_000 });
  if (blocked) return blocked;

  // ── Auth: admin, manager, or employee (employee can only self-notify for late_checkin) ──
  const caller = await requireAuth(req, ["admin", "manager", "employee"]);
  if (isAuthError(caller)) return authError(caller);

  // ── Parse body ──
  let body: RequestBody;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  if (!body.user_id) {
    return NextResponse.json({ error: "Missing `user_id`" }, { status: 422 });
  }

  if (!body.type || !NOTIFICATION_TYPES.includes(body.type)) {
    return NextResponse.json(
      { error: `Invalid \`type\`. Must be one of: ${NOTIFICATION_TYPES.join(", ")}` },
      { status: 422 },
    );
  }

  // Employees can ONLY trigger late_checkin notifications for themselves
  if (caller.role === "employee") {
    if (body.type !== "late_checkin" || body.user_id !== caller.uid) {
      return NextResponse.json(
        { error: "Employees can only trigger late check-in notices for themselves" },
        { status: 403 },
      );
    }
  }

  try {
    // ── Fetch target employee ──
    const { data: targetUser, error: userError } = await supabaseAdmin
      .from("users")
      .select("*")
      .eq("id", body.user_id)
      .single();

    if (userError || !targetUser) {
      return NextResponse.json({ error: "User not found" }, { status: 404 });
    }
    if (!targetUser.email) {
      return NextResponse.json({ error: "User has no email address" }, { status: 422 });
    }

    const employeeName = targetUser.name || targetUser.email;

    // ── Fetch office settings ──
    const { data: configs } = await supabaseAdmin
      .from("system_config")
      .select("key, value")
      .in("key", [
        "office_start_time",
        "late_threshold_minutes", 
        "company_name",
        "email_notifications_enabled",
        "company_email",
        "company_phone",
      ]);

    const configMap = Object.fromEntries((configs || []).map((c) => [c.key, c.value]));
    let officeStartTime = "09:00";
    const rawStartTime = String(configMap.office_start_time || "09:00");
    if (/^\d{2}:\d{2}$/.test(rawStartTime)) {
      const [h, m] = rawStartTime.split(":").map(Number);
      if (h >= 0 && h <= 23 && m >= 0 && m <= 59) {
        officeStartTime = rawStartTime;
      }
    }
    const lateThreshold = parseInt(String(configMap.late_threshold_minutes || 15), 10);
    if (configMap.company_name) setEmailCompanyName(String(configMap.company_name));
    if (configMap.company_email) setEmailCompanyEmail(String(configMap.company_email));
    if (configMap.company_phone) setEmailCompanyPhone(String(configMap.company_phone));
    const emailEnabled = configMap.email_notifications_enabled !== "false";
    if (!emailEnabled) {
      return NextResponse.json({ error: "Email notifications are disabled in settings" }, { status: 403 });
    }

    // ── Fetch sender name ──
    const { data: callerUser } = await supabaseAdmin
      .from("users")
      .select("name, email")
      .eq("id", caller.uid)
      .single();
    const senderName = callerUser?.name || caller.email;

    const today = new Date();
    const todayStr = today.toLocaleDateString("en-IN", {
      day: "2-digit",
      month: "short",
      year: "numeric",
    });

    let result: { messageId?: string } | undefined;

    // ── Route by notification type ──
    switch (body.type) {
      case "late_checkin": {
        // Fetch the attendance record to get check-in time
        let checkInTimeStr = "N/A";
        let lateByMinutes = 0;

        if (body.attendance_id) {
          const { data: att } = await supabaseAdmin
            .from("attendance")
            .select("*")
            .eq("id", body.attendance_id)
            .single();

          if (att?.check_in) {
            const checkInDate = new Date(att.check_in);
            checkInTimeStr = checkInDate.toLocaleTimeString("en-IN", {
              hour: "2-digit",
              minute: "2-digit",
              hour12: true,
            });

            // Calculate late-by
            const [startH, startM] = officeStartTime.split(":").map(Number);
            const cutoff = new Date(
              checkInDate.getFullYear(),
              checkInDate.getMonth(),
              checkInDate.getDate(),
              startH,
              startM + lateThreshold,
            );
            lateByMinutes = Math.max(
              0,
              Math.round((checkInDate.getTime() - cutoff.getTime()) / 60000),
            );
          }
        }

        result = await emailService.sendLateCheckIn(targetUser.email, {
          employeeName,
          date: todayStr,
          checkInTime: checkInTimeStr,
          officeStartTime,
          lateByMinutes,
        });
        break;
      }

      case "absent_reminder": {
        result = await emailService.sendAbsentReminder(targetUser.email, {
          employeeName,
          date: todayStr,
          senderName,
          message: body.message,
        });
        break;
      }

      case "early_checkout": {
        result = await emailService.sendEarlyCheckoutNotice(targetUser.email, {
          employeeName,
          date: todayStr,
          checkOutTime: body.checkout_time || "N/A",
          approvedBy: senderName,
          reason: body.reason || "No reason provided",
        });
        break;
      }
    }

    // ── Also create in-app notification ──
    await supabaseAdmin.from("notifications").insert({
      user_id: body.user_id,
      title:
        body.type === "late_checkin"
          ? "Late Check-In Notice"
          : body.type === "absent_reminder"
            ? "Attendance Reminder"
            : "Early Checkout Approved",
      message:
        body.type === "late_checkin"
          ? `You were marked late today (${todayStr}).`
          : body.type === "absent_reminder"
            ? `You haven't checked in today. Please check in or inform your manager.`
            : `Your early checkout has been approved.`,
      type: "attendance",
      read: false,
      link: "/dashboard/attendance",
      created_at: new Date().toISOString(),
    });

    return NextResponse.json({
      success: true,
      messageId: result?.messageId,
      sentTo: targetUser.email,
      notificationType: body.type,
    });
  } catch (err: unknown) {
    console.error("[attendance/send-notification] Error:", err);
    return NextResponse.json(
      { error: "Failed to send attendance notification" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { createServiceClient } from "@/lib/supabase/server";

export async function GET(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params;
    const supabase = await createServiceClient();
    const { data, error } = await supabase.from("claims").select("*").eq("id", id).single();
    if (error) return NextResponse.json({ error: error.message }, { status: 404 });
    return NextResponse.json(data);
  } catch (_err) {
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

export async function PATCH(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params;
    const supabase = await createServiceClient();
    const body = await req.json();

    // If status change, add timeline entry
    if (body.status && body._userId) {
      const { data: current } = await supabase.from("claims").select("status").eq("id", id).single();
      if (current && current.status !== body.status) {
        await supabase.from("claim_timeline").insert({
          claim_id: id,
          action: "status_change",
          description: `Status changed from ${current.status} to ${body.status}`,
          old_value: current.status,
          new_value: body.status,
          performed_by: body._userId,
          performed_by_name: body._userName || "",
        });
      }
      delete body._userId;
      delete body._userName;
    }

    const { data, error } = await supabase.from("claims").update(body).eq("id", id).select().single();
    if (error) return NextResponse.json({ error: error.message }, { status: 500 });
    return NextResponse.json(data);
  } catch (_err) {
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

export async function DELETE(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params;
    const supabase = await createServiceClient();
    const { error } = await supabase.from("claims").delete().eq("id", id);
    if (error) return NextResponse.json({ error: error.message }, { status: 500 });
    return NextResponse.json({ success: true });
  } catch (_err) {
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

/**
 * PUT /api/commission-rates/[id]
 * Update commission rate (admin only).
 */

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";

export async function PUT(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const caller = await requireAuth(req, ["admin"]);
  if (isAuthError(caller)) return authError(caller);

  const { id } = await params;
  const db = supabaseAdmin as any;

  let body: any;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }

  const now = new Date().toISOString();
  const updatePayload: any = { updated_at: now };

  const allowedFields = [
    "insurer_name", "policy_type", "rate_type", "rate_value",
    "effective_from", "effective_to", "is_active",
  ];

  for (const field of allowedFields) {
    if (body[field] !== undefined) {
      updatePayload[field] = body[field];
    }
  }

  if (updatePayload.rate_type === "percentage" && updatePayload.rate_value !== undefined) {
    if (updatePayload.rate_value < 0 || updatePayload.rate_value > 100) {
      return NextResponse.json(
        { error: "Percentage rate must be between 0 and 100" },
        { status: 400 }
      );
    }
  }

  const { data: updated, error } = await db
    .from("commission_rates")
    .update(updatePayload)
    .eq("id", id)
    .select()
    .single();

  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
  if (!updated) return NextResponse.json({ error: "Rate not found" }, { status: 404 });

  // Audit log
  try {
    await supabaseAdmin.from("audit_logs").insert({
      action: "update",
      module: "commission_rates",
      details: `Updated commission rate ${id}`,
      user_id: caller.uid,
      user_name: caller.name ?? caller.email,
      user_role: caller.role,
      metadata: { rate_id: id, changes: updatePayload },
      created_at: now,
    } as any);
  } catch { /* non-critical */ }

  return NextResponse.json(updated);
}

/**
 * GET  /api/commission-rates  — List commission rates
 * POST /api/commission-rates  — Create rate (admin only)
 */

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";

export async function GET(req: NextRequest) {
  const caller = await requireAuth(req, ["admin", "manager", "employee"]);
  if (isAuthError(caller)) return authError(caller);

  const db = supabaseAdmin as any;
  const { searchParams } = new URL(req.url);
  const insurer = searchParams.get("insurer") ?? "";
  const policy_type = searchParams.get("policy_type") ?? "";
  const active_only = searchParams.get("active_only") !== "false";

  let query = db
    .from("commission_rates")
    .select("*")
    .order("insurer_name", { ascending: true })
    .order("policy_type", { ascending: true });

  if (insurer) query = query.ilike("insurer_name", `%${insurer}%`);
  if (policy_type) query = query.eq("policy_type", policy_type);
  if (active_only) query = query.eq("is_active", true);

  const { data, error } = await query;
  if (error) return NextResponse.json({ error: error.message }, { status: 500 });

  return NextResponse.json(data ?? []);
}

export async function POST(req: NextRequest) {
  const caller = await requireAuth(req, ["admin"]);
  if (isAuthError(caller)) return authError(caller);

  const db = supabaseAdmin as any;

  let body: any;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }

  const { insurer_name, policy_type, rate_type, rate_value, effective_from, effective_to } = body;

  if (!insurer_name || !policy_type || !rate_type || rate_value === undefined) {
    return NextResponse.json(
      { error: "insurer_name, policy_type, rate_type, and rate_value are required" },
      { status: 400 }
    );
  }

  if (!["percentage", "flat"].includes(rate_type)) {
    return NextResponse.json({ error: "rate_type must be percentage or flat" }, { status: 400 });
  }

  if (rate_type === "percentage" && (rate_value < 0 || rate_value > 100)) {
    return NextResponse.json(
      { error: "Percentage rate must be between 0 and 100" },
      { status: 400 }
    );
  }

  if (rate_value < 0) {
    return NextResponse.json({ error: "rate_value must be non-negative" }, { status: 400 });
  }

  const now = new Date().toISOString();

  const { data: created, error } = await db
    .from("commission_rates")
    .insert({
      insurer_name,
      policy_type,
      rate_type,
      rate_value,
      effective_from: effective_from ?? new Date().toISOString().split("T")[0],
      effective_to: effective_to ?? null,
      is_active: true,
      created_by: caller.uid,
      created_at: now,
      updated_at: now,
    })
    .select()
    .single();

  if (error) return NextResponse.json({ error: error.message }, { status: 500 });

  // Audit log
  try {
    await supabaseAdmin.from("audit_logs").insert({
      action: "create",
      module: "commission_rates",
      details: `Created commission rate: ${insurer_name} / ${policy_type} = ${rate_value}${rate_type === "percentage" ? "%" : " flat"}`,
      user_id: caller.uid,
      user_name: caller.name ?? caller.email,
      user_role: caller.role,
      metadata: { rate_id: created.id, insurer_name, policy_type, rate_type, rate_value },
      created_at: now,
    } as any);
  } catch { /* non-critical */ }

  return NextResponse.json(created, { status: 201 });
}

import { NextRequest, NextResponse } from "next/server";
import { createServiceClient } from "@/lib/supabase/server";

export async function GET(req: NextRequest) {
  try {
    const supabase = await createServiceClient();
    const { searchParams } = new URL(req.url);
    let query = supabase.from("communication_templates").select("*").order("created_at", { ascending: false });
    const channel = searchParams.get("channel");
    if (channel) query = query.eq("channel", channel);
    const { data, error } = await query;
    if (error) return NextResponse.json({ error: error.message }, { status: 500 });
    return NextResponse.json(data);
  } catch (_err) {
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

export async function POST(req: NextRequest) {
  try {
    const supabase = await createServiceClient();
    const body = await req.json();
    const { data, error } = await supabase.from("communication_templates").insert(body).select().single();
    if (error) return NextResponse.json({ error: error.message }, { status: 500 });
    return NextResponse.json(data, { status: 201 });
  } catch (_err) {
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { createServiceClient } from "@/lib/supabase/server";

export async function POST(req: NextRequest) {
  try {
    const supabase = await createServiceClient();
    const body = await req.json();

    // Handle bulk renewal reminders
    if (body.action === "renewal_reminders") {
      const { data: renewals } = await supabase
        .from("policies")
        .select("id, policy_number, customer_name, customer_id, end_date, premium_amount")
        .gte("end_date", new Date().toISOString().split("T")[0])
        .lte("end_date", new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split("T")[0])
        .eq("status", "active");

      const sent = (renewals ?? []).length;
      // Log each communication
      for (const policy of renewals ?? []) {
        await supabase.from("communication_logs").insert({
          customer_id: policy.customer_id,
          customer_name: policy.customer_name,
          policy_id: policy.id,
          channel: "email",
          recipient: policy.customer_name,
          subject: `Policy Renewal Reminder - ${policy.policy_number}`,
          body: `Your policy ${policy.policy_number} expires on ${policy.end_date}. Please renew.`,
          status: "sent",
          sent_at: new Date().toISOString(),
          created_by: body.userId,
        });
      }

      return NextResponse.json({ success: true, sent });
    }

    // Handle single email send
    const { channel, recipient, subject, body: emailBody, customerId, customerName, templateId } = body;

    // For now, log the communication (actual SMTP/WhatsApp integration can be added later)
    await supabase.from("communication_logs").insert({
      template_id: templateId,
      customer_id: customerId,
      customer_name: customerName,
      channel: channel || "email",
      recipient,
      subject,
      body: emailBody,
      status: "sent",
      sent_at: new Date().toISOString(),
      created_by: body.userId,
    });

    return NextResponse.json({ success: true });
  } catch (_err) {
    return NextResponse.json({ success: false, error: "Internal server error" }, { status: 500 });
  }
}

/**
 * POST /api/compliance/[id]/complete
 * Mark compliance item as completed.
 * For recurring items, creates the next occurrence.
 */

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";

function getNextDueDate(currentDueDate: string, recurrence: string): string | null {
  const date = new Date(currentDueDate);

  switch (recurrence) {
    case "monthly":
      date.setMonth(date.getMonth() + 1);
      break;
    case "quarterly":
      date.setMonth(date.getMonth() + 3);
      break;
    case "half_yearly":
      date.setMonth(date.getMonth() + 6);
      break;
    case "annual":
      date.setFullYear(date.getFullYear() + 1);
      break;
    default:
      return null; // one_time
  }

  return date.toISOString().split("T")[0];
}

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const caller = await requireAuth(req, ["admin", "manager"]);
  if (isAuthError(caller)) return authError(caller);

  const { id } = await params;
  const db = supabaseAdmin as any;

  let body: any;
  try {
    body = await req.json();
  } catch {
    body = {};
  }

  const { completion_notes, completion_document_url } = body;

  // Fetch the item
  const { data: item, error: fetchError } = await db
    .from("compliance_items")
    .select("*")
    .eq("id", id)
    .single();

  if (fetchError || !item) {
    return NextResponse.json({ error: "Compliance item not found" }, { status: 404 });
  }

  const now = new Date().toISOString();

  // Mark as completed
  const { data: updated, error } = await db
    .from("compliance_items")
    .update({
      status: "completed",
      completed_at: now,
      completed_by: caller.uid,
      completion_notes: completion_notes ?? null,
      completion_document_url: completion_document_url ?? null,
      updated_at: now,
    })
    .eq("id", id)
    .select()
    .single();

  if (error) return NextResponse.json({ error: error.message }, { status: 500 });

  // Create next occurrence for recurring items
  let nextItem = null;
  if (item.recurrence !== "one_time") {
    const nextDueDate = getNextDueDate(item.due_date, item.recurrence);
    if (nextDueDate) {
      const { data: next } = await db
        .from("compliance_items")
        .insert({
          title: item.title,
          category: item.category,
          description: item.description,
          due_date: nextDueDate,
          assigned_to: item.assigned_to,
          assigned_to_name: item.assigned_to_name,
          status: "pending",
          recurrence: item.recurrence,
          parent_item_id: id,
          created_by: caller.uid,
          created_at: now,
          updated_at: now,
        })
        .select()
        .single();
      nextItem = next;
    }
  }

  // Audit log
  try {
    await supabaseAdmin.from("audit_logs").insert({
      action: "update",
      module: "compliance",
      details: `Completed compliance item: ${item.title}${nextItem ? ` — next occurrence created for ${nextItem.due_date}` : ""}`,
      user_id: caller.uid,
      user_name: caller.name ?? caller.email,
      user_role: caller.role,
      metadata: { compliance_id: id, next_item_id: nextItem?.id },
      created_at: now,
    } as any);
  } catch { /* non-critical */ }

  return NextResponse.json({ completed: updated, next_occurrence: nextItem });
}

/**
 * GET /api/compliance/[id]  — Get compliance item
 * PUT /api/compliance/[id]  — Update compliance item
 */

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";

export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const caller = await requireAuth(req, ["admin", "manager", "employee"]);
  if (isAuthError(caller)) return authError(caller);

  const { id } = await params;
  const db = supabaseAdmin as any;

  const { data, error } = await db
    .from("compliance_items")
    .select("*")
    .eq("id", id)
    .single();

  if (error || !data) {
    return NextResponse.json({ error: "Compliance item not found" }, { status: 404 });
  }

  return NextResponse.json(data);
}

export async function PUT(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const caller = await requireAuth(req, ["admin", "manager"]);
  if (isAuthError(caller)) return authError(caller);

  const { id } = await params;
  const db = supabaseAdmin as any;

  let body: any;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }

  const now = new Date().toISOString();
  const updatePayload: any = { updated_at: now };

  const allowedFields = [
    "title", "category", "description", "due_date",
    "assigned_to", "assigned_to_name", "status", "recurrence",
  ];

  for (const field of allowedFields) {
    if (body[field] !== undefined) {
      updatePayload[field] = body[field];
    }
  }

  const { data: updated, error } = await db
    .from("compliance_items")
    .update(updatePayload)
    .eq("id", id)
    .select()
    .single();

  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
  if (!updated) return NextResponse.json({ error: "Compliance item not found" }, { status: 404 });

