/**
 * POST /api/customers/create-portal-account
 *
 * After creating a customer in database, call this to:
 * 1. Create a Supabase Auth user (role=customer)
 * 2. Store mapping in `customer_portal_users`
 * 3. Return credentials to admin/manager (no email sent)
 *
 * Body: { customerId, name, email, phone? }
 * Auth: Admin only
 */

import { errorResponse } from "@/lib/api/error";
import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";
import { protect } from "@/lib/api/protect";
import crypto from "crypto";

// ── Password generator ────────────────────────────────────────────────────────

function generatePassword(length = 10): string {
  const upper = "ABCDEFGHJKLMNPQRSTUVWXYZ";
  const lower = "abcdefghjkmnpqrstuvwxyz";
  const digits = "23456789";
  const symbols = "@#$!";
  const all = upper + lower + digits + symbols;

  let password = "";
  password += upper[crypto.randomInt(upper.length)];
  password += lower[crypto.randomInt(lower.length)];
  password += digits[crypto.randomInt(digits.length)];
  password += symbols[crypto.randomInt(symbols.length)];

  for (let i = password.length; i < length; i++) {
    password += all[crypto.randomInt(all.length)];
  }

  // Fisher-Yates shuffle for unbiased randomization
  const arr = password.split("");
  for (let i = arr.length - 1; i > 0; i--) {
    const j = crypto.randomInt(i + 1);
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr.join("");
}

// ── Route Handler ─────────────────────────────────────────────────────────────

export async function POST(req: NextRequest) {
  const blocked = protect(req, { maxRequests: 5, windowMs: 60_000 });
  if (blocked) return blocked;

  const caller = await requireAuth(req, ["admin"]);
  if (isAuthError(caller)) {
    return authError(caller);
  }

  let body: Record<string, unknown>;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }

  const { customerId, name, email, phone } = body as {
    customerId: string;
    name: string;
    email: string;
    phone?: string;
  };

  // ---- Validation ----
  if (!customerId || !email) {
    return NextResponse.json(
      { error: "customerId and email are required" },
      { status: 400 }
    );
  }

  // Security: Handle masked data from frontend (e.g. "bpa***mf@***il.***")
  // Use the privileged service_role client (supabaseAdmin) to fetch the actual unmasked
  // data from the DB using the customerId. We still trust the frontend's name/phone
  // for other metadata if they don't contain masks.
  let actualEmail = email;
  let actualPhone = phone || "";

  if (email.includes("*") || (phone && phone.includes("*"))) {
    console.log(`[create-portal-account] Detected masked data for customer ${customerId}. Fetching unmasked values...`);
    const { data: customer, error: fetchError } = await supabaseAdmin
      .from("customers")
      .select("email, phone")
      .eq("id", customerId)
      .single();

    if (fetchError || !customer) {
      console.error("[create-portal-account] Failed to fetch unmasked customer data:", fetchError);
      return NextResponse.json(
        { error: "Failed to verify customer data before account creation" },
        { status: 400 }
      );
    }

    if (email.includes("*")) {
      actualEmail = customer.email;
    }
    if (phone && phone.includes("*")) {
      actualPhone = customer.phone;
    }
  }

  try {
    // Check if portal account already exists
    const { data: existingPortal } = await supabaseAdmin
      .from("customer_portal_users")
      .select("id")
      .eq("customer_id", customerId)
      .limit(1)
      .maybeSingle();

    if (existingPortal) {
      return NextResponse.json(
        { message: "Portal account already exists", existing: true },
        { status: 200 }
      );
    }

    // Generate password
    const plainPassword = generatePassword(10);

    // Create or update Supabase Auth user
    let authUserId: string;
    const { data: createData, error: createError } = await supabaseAdmin.auth.admin.createUser({
      email: actualEmail as string,
      password: plainPassword,
      email_confirm: true,
      user_metadata: {
        name,
        role: "customer",
      },
    });

    if (createError) {
      // Check if user already exists
      if (createError.message?.includes("already been registered")) {
        // Find existing user by email — single page lookup (sufficient for most instances)
        let existing: { id: string; email?: string; user_metadata?: Record<string, unknown> } | undefined;
        const { data: listData } = await supabaseAdmin.auth.admin.listUsers({ page: 1, perPage: 1000 });
        existing = listData?.users?.find((u) => u.email === actualEmail);

        if (!existing) {
          return NextResponse.json(
            { error: "Email already in use but could not find existing user" },
            { status: 409 }
          );
        }

        // Safety check: never hijack an internal staff account
        if (existing.user_metadata?.role && existing.user_metadata.role !== "customer") {
          return NextResponse.json(
            { error: "This email belongs to a staff account and cannot be used for a customer portal" },
            { status: 409 }
          );
        }

        authUserId = existing.id;

        // Update password for existing user
        await supabaseAdmin.auth.admin.updateUserById(authUserId, {
          password: plainPassword,
          user_metadata: { name, role: "customer" },
        });
      } else {
        throw createError;
      }
    } else {
      authUserId = createData.user.id;
    }

    const now = new Date().toISOString();

    // Store in database (including password for admin/manager viewing in credentials page)
    const { error: insertError } = await supabaseAdmin
      .from("customer_portal_users")
      .insert({
        customer_id: customerId,
        auth_user_id: authUserId,
        name,
        email: actualEmail,
        phone: actualPhone,
        portal_password: plainPassword,
        is_active: true,
        first_login: false,
        created_at: now,
        updated_at: now,
        created_by: caller.uid,
      });

    if (insertError) {
      console.error("[create-portal-account] DB insert failed, rolling back auth user:", insertError);
      try {
        await supabaseAdmin.auth.admin.deleteUser(authUserId);
      } catch (rollbackErr) {
        console.error("[create-portal-account] Auth user rollback failed:", rollbackErr);
      }
      return NextResponse.json({ error: "Failed to create portal user record" }, { status: 500 });
    }

    // Proactively update the main customer table with the email used (especially if it was corrected)
    await supabaseAdmin
      .from("customers")
      .update({ email: actualEmail, updated_at: now })
      .eq("id", customerId);

    return NextResponse.json({
      success: true,
      auth_user_id: authUserId,
      portal_email: actualEmail,
      message: "Portal account created successfully.",
    });
  } catch (err: unknown) {
    console.error("[create-portal-account] Error:", err);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

/**
 * POST /api/customers/portal-access
 *
 * Enable or disable a customer's portal login access.
 * Does NOT soft-delete the customer — only toggles Supabase Auth ban state
 * and the is_active flag in customer_portal_users.
 *
 * Body: { portalUserId, action: "enable" | "disable" }
 * Auth: Admin only
 */

import { errorResponse } from "@/lib/api/error";
import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";
import { protect } from "@/lib/api/protect";

export async function POST(req: NextRequest) {
  const blocked = protect(req, { maxRequests: 20, windowMs: 60_000 });
  if (blocked) return blocked;

  const caller = await requireAuth(req, ["admin"]);
  if (isAuthError(caller)) return authError(caller);

  let body: Record<string, unknown>;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }

  const { portalUserId, action } = body as {
    portalUserId: string;
    action: "enable" | "disable";
  };

  if (!portalUserId || !["enable", "disable"].includes(action)) {
    return NextResponse.json(
      { error: "Missing or invalid fields: portalUserId, action (enable|disable)" },
      { status: 400 }
    );
  }

  try {
    const { data: portalUser, error: portalError } = await supabaseAdmin
      .from("customer_portal_users")
      .select("*")
      .eq("id", portalUserId)
      .single();

    if (portalError || !portalUser) {
      return NextResponse.json({ error: "Portal user not found" }, { status: 404 });
    }

    const authUserId = portalUser.auth_user_id;
    const isDisabling = action === "disable";
    const now = new Date().toISOString();

    // Update Supabase Auth - use ban_duration for disabling
    if (authUserId) {
      const { error: authUpdateError } = await supabaseAdmin.auth.admin.updateUserById(authUserId, {
        ban_duration: isDisabling ? "876600h" : "none", // ~100 years or no ban
      });
      if (authUpdateError) {
        console.error("[portal-access] Failed to update auth user:", authUpdateError);
        return NextResponse.json({ error: "Failed to update auth user" }, { status: 500 });
      }
    }

    // Update database
    const { error: dbUpdateError } = await supabaseAdmin
      .from("customer_portal_users")
      .update({
        is_active: !isDisabling,
        ...(isDisabling
          ? {
              deactivated_at: now,
              deactivated_by: caller.uid,
            }
          : {
              reactivated_at: now,
              reactivated_by: caller.uid,
            }),
        updated_at: now,
      })
      .eq("id", portalUserId);

    if (dbUpdateError) {
      console.error("[portal-access] Failed to update portal user:", dbUpdateError);
      return NextResponse.json({ error: "Failed to update portal user record" }, { status: 500 });
    }

    // Audit log
    try {
      const { error: auditError } = await supabaseAdmin.from("audit_logs").insert({
        action: isDisabling ? "deactivate" : "update",
        module: "customers",
        details: `${isDisabling ? "Disabled" : "Enabled"} portal access for: ${portalUser.name} (${portalUser.email})`,
        user_id: caller.uid,
        user_name: caller.name ?? caller.email,
        user_role: caller.role,
        metadata: {
          portal_user_id: portalUserId,
          customer_id: portalUser.customer_id,
          customer_name: portalUser.name,
          action,
        },
        created_at: now,
      });
      if (auditError) console.error("[portal-access] Audit log failed:", auditError);
    } catch (auditErr) {
      console.error("[portal-access] Audit log failed:", auditErr);
    }

    return NextResponse.json({
      success: true,
      is_active: !isDisabling,
      message: `Portal access ${isDisabling ? "disabled" : "enabled"} for ${portalUser.name}.`,
    });
  } catch (err: unknown) {
    console.error("[portal-access] Error:", err);
    return NextResponse.json({ error: "Failed to update portal access" }, { status: 500 });
  }
}

/**
 * POST /api/customers/portal-password
 *
 * Change/reset a customer portal user's password.
 * 1. Generate new password or use provided one
 * 2. Update Supabase Auth password
 * 3. Update stored password in customer_portal_users
 *
 * Body: { portalUserId, newPassword? }
 * Auth: Admin only
 */

import { errorResponse } from "@/lib/api/error";
import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";
import { protect } from "@/lib/api/protect";
import crypto from "crypto";

// ── Password generator ────────────────────────────────────────────────────────

function generatePassword(length = 10): string {
  const upper = "ABCDEFGHJKLMNPQRSTUVWXYZ";
  const lower = "abcdefghjkmnpqrstuvwxyz";
  const digits = "23456789";
  const symbols = "@#$!";
  const all = upper + lower + digits + symbols;

  let password = "";
  password += upper[crypto.randomInt(upper.length)];
  password += lower[crypto.randomInt(lower.length)];
  password += digits[crypto.randomInt(digits.length)];
  password += symbols[crypto.randomInt(symbols.length)];

  for (let i = password.length; i < length; i++) {
    password += all[crypto.randomInt(all.length)];
  }

  // Fisher-Yates shuffle for unbiased randomization
  const arr = password.split("");
  for (let i = arr.length - 1; i > 0; i--) {
    const j = crypto.randomInt(i + 1);
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr.join("");
}

// ── Route Handler ─────────────────────────────────────────────────────────────

export async function POST(req: NextRequest) {
  const blocked = protect(req, { maxRequests: 10, windowMs: 60_000 });
  if (blocked) return blocked;

  const caller = await requireAuth(req, ["admin"]);
  if (isAuthError(caller)) return authError(caller);

  let body: Record<string, unknown>;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }

  const { portalUserId, newPassword } = body as {
    portalUserId: string;
    newPassword?: string;
  };

  if (!portalUserId) {
    return NextResponse.json(
      { error: "Missing portalUserId" },
      { status: 400 }
    );
  }

  try {
    // Get the portal user
    const { data: portalUser, error: portalError } = await supabaseAdmin
      .from("customer_portal_users")
      .select("*")
      .eq("id", portalUserId)
      .single();

    if (portalError || !portalUser) {
      return NextResponse.json(
        { error: "Portal user not found" },
        { status: 404 }
      );
    }

    const authUserId = portalUser.auth_user_id;

    // Use provided password or generate a new one
    const password = newPassword?.trim() || generatePassword(10);

    if (password.length < 6) {
      return NextResponse.json(
        { error: "Password must be at least 6 characters" },
        { status: 400 }
      );
    }

    // Update Supabase Auth password
    if (authUserId) {
      const { error: authUpdateError } = await supabaseAdmin.auth.admin.updateUserById(authUserId, { password });
      if (authUpdateError) {
        console.error("[portal-password] Failed to update auth password:", authUpdateError);
        return NextResponse.json({ error: "Failed to update auth password" }, { status: 500 });
      }
    }

    const now = new Date().toISOString();

    // Update stored password in database
    const { error: dbUpdateError } = await supabaseAdmin
      .from("customer_portal_users")
      .update({
        portal_password: password,
        password_changed_at: now,
        password_changed_by: caller.uid,
        updated_at: now,
      })
      .eq("id", portalUserId);

    if (dbUpdateError) {
      console.error("[portal-password] Failed to update DB password:", dbUpdateError);
      return NextResponse.json({ error: "Failed to update password record" }, { status: 500 });
    }

    // Audit log
    try {
      const { error: auditError } = await supabaseAdmin.from("audit_logs").insert({
        action: "update",
        module: "customers",
        details: `Changed portal password for: ${portalUser.name} (${portalUser.email})`,
        user_id: caller.uid,
        user_name: caller.name ?? caller.email,
        user_role: caller.role,
        metadata: {
          portal_user_id: portalUserId,
          customer_id: portalUser.customer_id,
          customer_name: portalUser.name,
        },
        created_at: now,
      });
      if (auditError) console.error("[portal-password] Audit log failed:", auditError);
    } catch (auditErr) {
      console.error("[portal-password] Audit log failed:", auditErr);
    }

    return NextResponse.json({
      success: true,
      portal_password: password,
      message: "Password updated successfully.",
    });
  } catch (err: unknown) {
    console.error("[portal-password] Error:", err);
    return NextResponse.json(
      { error: "Failed to update password" },
      { status: 500 }
    );
  }
}

/**
 * GET  /api/customers  — paginated list with search, filters, metrics
 * POST /api/customers  — create with duplicate detection
 */

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";
import { protect } from "@/lib/api/protect";
import { createCustomerSchema } from "@/lib/validation";

// ── GET ───────────────────────────────────────────────────────────

export async function GET(req: NextRequest) {
  const caller = await requireAuth(req, ["admin", "manager", "employee"]);
  if (isAuthError(caller)) return authError(caller);

  const { searchParams } = new URL(req.url);
  const page = Math.max(1, parseInt(searchParams.get("page") ?? "1"));
  const limit = Math.min(100, parseInt(searchParams.get("limit") ?? "20"));
  const search = searchParams.get("search") ?? "";
  const type = searchParams.get("type") ?? "";
  const status = searchParams.get("status") ?? "active";
  const assignedRm = searchParams.get("assigned_rm") ?? "";
  const city = searchParams.get("city") ?? "";
  const state = searchParams.get("state") ?? "";
  const sort = searchParams.get("sort") ?? "created_at";
  const order = searchParams.get("order") === "asc" ? true : false;

  let query = supabaseAdmin.from("customers").select("*", { count: "exact" });

  // Role-based filtering: employees only see their assigned customers
  if (caller.role === "employee") {
    query = query.or(`assigned_rm.eq.${caller.uid},created_by.eq.${caller.uid}`);
  }

  // Status filter
  if (status === "active") {
    query = query.or("status.is.null,status.eq.active");
  } else if (status === "inactive") {
    query = query.eq("status", "inactive");
  }

  // Type filter
  if (type) query = query.eq("customer_type", type);

  // RM filter
  if (assignedRm) query = query.eq("assigned_rm", assignedRm);

  // City / State filter
  if (city) query = query.ilike("city", `%${city}%`);
  if (state) query = query.ilike("state", `%${state}%`);

  // Search
  if (search) {
    query = query.or(
      `name.ilike.%${search}%,phone.ilike.%${search}%,email.ilike.%${search}%,uid.ilike.%${search}%`
    );
  }

  // Sort + paginate
  query = query
    .order(sort, { ascending: order })
    .range((page - 1) * limit, page * limit - 1);

  const { data, count, error } = await query;
  if (error) return NextResponse.json({ error: error.message }, { status: 500 });

  // Metrics (only for admin/manager — employees get filtered counts)
  const metrics = { total: count ?? 0, active: 0, byType: {} as Record<string, number> };
  if (caller.role !== "employee") {
    const { data: allForMetrics } = await supabaseAdmin
      .from("customers")
      .select("customer_type, status")
      .or("status.is.null,status.eq.active");

    if (allForMetrics) {
      metrics.active = allForMetrics.length;
      for (const c of allForMetrics) {
        const t = c.customer_type || "individual";
        metrics.byType[t] = (metrics.byType[t] || 0) + 1;
      }
    }
  }

  return NextResponse.json({
    data: data ?? [],
    total: count ?? 0,
    page,
    limit,
    metrics,
  });
}

// ── POST ──────────────────────────────────────────────────────────

export async function POST(req: NextRequest) {
  const blocked = protect(req, { maxRequests: 20, windowMs: 60_000 });
  if (blocked) return blocked;

  const caller = await requireAuth(req, ["admin", "manager"]);
  if (isAuthError(caller)) return authError(caller);

  let body: unknown;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const result = createCustomerSchema.safeParse(body);
  if (!result.success) {
    return NextResponse.json({ error: "Validation failed", details: result.error.format() }, { status: 400 });
  }

  const validatedData = result.data;
  const { name, phone, email } = validatedData;
  const force_create = (body as any).force_create === true;

  // ── Duplicate detection ──────────────────────────────────────────
  if (!force_create) {
    const matches: { field: string; customer: unknown }[] = [];

    // Phone match
    if (phone) {
      const { data: byPhone } = await supabaseAdmin
        .from("customers")
        .select("id, uid, name, phone, email, customer_type, status")
        .eq("phone", phone)
        .neq("status", "inactive")
        .limit(3);
      (byPhone ?? []).forEach(c => matches.push({ field: "phone", customer: c }));
    }

    // Email match
    if (email && email !== "N/A" && email !== "") {
      const { data: byEmail } = await supabaseAdmin
        .from("customers")
        .select("id, uid, name, phone, email, customer_type, status")
        .ilike("email", email)
        .neq("status", "inactive")
        .limit(3);
      (byEmail ?? []).forEach(c => {
        if (!matches.find((m) => (m.customer as any).id === c.id)) {
          matches.push({ field: "email", customer: c });
        }
      });
    }

    // PAN match (from entity_meta)
    const panNumber = (validatedData.entity_meta as any)?.pan_number || validatedData.pan;
    if (panNumber) {
      const { data: byPan } = await supabaseAdmin
        .from("customers")
        .select("id, uid, name, phone, email, customer_type, status")
        .contains("entity_meta", { pan_number: panNumber })
        .neq("status", "inactive")
        .limit(3);
      (byPan ?? []).forEach(c => {
        if (!matches.find((m) => (m.customer as any).id === c.id)) {
          matches.push({ field: "pan", customer: c });
        }
      });
    }

    if (matches.length > 0) {
      return NextResponse.json(
        { duplicate: true, matches },
        { status: 409 }
      );
    }
  }

  // ── Create customer ──────────────────────────────────────────────
  // Get next UID via RPC
  const { data: uid, error: uidError } = await supabaseAdmin.rpc("next_customer_uid");
  if (uidError) return NextResponse.json({ error: "Failed to generate UID" }, { status: 500 });

  const now = new Date().toISOString();
  const payload = {
    uid,
    name: String(name).trim(),
    phone: String(phone).trim(),
    email: email ? String(email).toLowerCase().trim() : "N/A",
    address: validatedData.address || null,
    city: validatedData.city || null,
    state: validatedData.state || null,
    pincode: validatedData.pincode || null,
    status: validatedData.status || "active",
    customer_type: validatedData.type || "individual",
    entity_meta: validatedData.entity_meta || {},
    created_by: caller.uid,
    created_at: now,
    updated_at: now,
    family_id: (body as any).family_id || null,
    assigned_rm: (body as any).assigned_rm || null,
    kyc_status: "pending",
  };

  const { data: created, error: insertError } = await supabaseAdmin
    .from("customers")
    .insert(payload)
    .select()
    .single();

  if (insertError) return NextResponse.json({ error: insertError.message }, { status: 500 });

  // Audit log (best-effort)
  try {
    await supabaseAdmin.from("audit_logs").insert({
      action: "create",
      module: "customers",
      details: `Created customer: ${name} (${uid})`,
      user_id: caller.uid,
      user_name: caller.name ?? caller.email,
      user_role: caller.role,
      metadata: { customer_id: created.id, uid, type: payload.customer_type },
      created_at: now,
    });
  } catch { /* non-critical */ }

  return NextResponse.json(created, { status: 201 });
}

/**
 * POST /api/email
 * ─────────────────────────────────────────────────────────────────────────────
 * Server-side email dispatch via nodemailer.
 * Admin / manager / system usage only.
 *
 * Body:
 * {
 *   to: string | string[]
 *   template: "welcome" | "password_reset" | "policy_expiry" | "renewal_reminder" | "custom"
 *
 *   // For `custom` template or subject override:
 *   subject?: string
 *   html?: string
 *   text?: string
 *
 *   // Template variables (merged into template):
 *   vars?: Record<string, string>
 * }
 *
 * Env vars required:
 *   SMTP_HOST, SMTP_PORT, SMTP_USER, SMTP_PASS, SMTP_FROM
 */

import { errorResponse } from "@/lib/api/error";
import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { protect } from "@/lib/api/protect";
import nodemailer from "nodemailer";

// ── Template library ─────────────────────────────────────────────────────────

type TemplateVars = Record<string, string>;

interface EmailTemplate {
  subject: string;
  html: string;
  text: string;
}

function renderTemplate(name: string, vars: TemplateVars): EmailTemplate | null {
  /** HTML-escape a template variable to prevent XSS/injection */
  const esc = (k: string): string => {
    const raw = vars[k] ?? `{${k}}`;
    return raw
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  };

  switch (name) {
    case "welcome":
      return {
        subject: `Welcome to BPAF Insurance, ${esc("name")}!`,
        html: `<p>Dear ${esc("name")},</p><p>Welcome to BPAF Insurance. Your account has been created successfully.</p><p>Email: <strong>${esc("email")}</strong><br>Temporary password: <strong>${esc("password")}</strong></p><p>Please change your password upon first login.</p>`,
        text: `Welcome ${esc("name")}. Your BPAF Insurance account is ready.\nEmail: ${esc("email")}\nTemporary password: ${esc("password")}`,
      };

    case "password_reset":
      return {
        subject: "BPAF Insurance – Password Reset",
        html: `<p>Dear ${esc("name")},</p><p>A password reset was requested for your account.</p><p>Click the link below to reset your password (valid for 1 hour):</p><p><a href="${esc("reset_link")}">${esc("reset_link")}</a></p><p>If you didn't request this, please ignore this email.</p>`,
        text: `Password reset link (valid 1 hour):\n${esc("reset_link")}`,
      };

    case "policy_expiry":
      return {
        subject: `BPAF – Policy ${esc("policy_number")} Expiring Soon`,
        html: `<p>Dear ${esc("customer_name")},</p><p>Your insurance policy <strong>${esc("policy_number")}</strong> (${esc("policy_type")}) is expiring on <strong>${esc("expiry_date")}</strong>.</p><p>Please contact us to renew before the expiry date to avoid a lapse in coverage.</p>`,
        text: `Your policy ${esc("policy_number")} expires on ${esc("expiry_date")}. Please contact us to renew.`,
      };

    case "renewal_reminder":
      return {
        subject: `BPAF – Renewal Reminder for Policy ${esc("policy_number")}`,
        html: `<p>Dear ${esc("customer_name")},</p><p>This is a reminder that your policy <strong>${esc("policy_number")}</strong> is due for renewal.</p><p>Next due date: <strong>${esc("due_date")}</strong></p><p>Amount due: <strong>₹${esc("amount")}</strong></p><p>Please arrange payment at your earliest convenience.</p>`,
        text: `Renewal reminder: Policy ${esc("policy_number")} is due on ${esc("due_date")} for ₹${esc("amount")}.`,
      };

    default:
      return null;
  }
}

// ── Lazy transporter ─────────────────────────────────────────────────────────

let transporter: nodemailer.Transporter | null = null;

function getTransporter() {
  if (transporter) return transporter;
  transporter = nodemailer.createTransport({
    host: process.env.SMTP_HOST,
    port: Number(process.env.SMTP_PORT ?? 587),
    secure: process.env.SMTP_PORT === "465",
    auth: {
      user: process.env.SMTP_USER,
      pass: process.env.SMTP_PASS,
    },
  });
  return transporter;
}

// ── POST ──────────────────────────────────────────────────────────────────────

export async function POST(req: NextRequest) {
  const blocked = protect(req, { maxRequests: 10, windowMs: 60_000 });
  if (blocked) return blocked;

  const caller = await requireAuth(req, ["admin", "manager"]);
  if (isAuthError(caller)) return authError(caller);

  if (!process.env.SMTP_HOST || !process.env.SMTP_USER || !process.env.SMTP_PASS) {
    return NextResponse.json({ error: "SMTP not configured." }, { status: 503 });
  }

  let body: {
    to: string | string[];
    template?: string;
    subject?: string;
    html?: string;
    text?: string;
    vars?: TemplateVars;
  };

  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  if (!body.to) {
    return NextResponse.json({ error: "Missing `to` field" }, { status: 422 });
  }

  let subject = body.subject ?? "(no subject)";
  let html    = body.html   ?? "";
  let text    = body.text   ?? "";

  if (body.template && body.template !== "custom") {
    const tmpl = renderTemplate(body.template, body.vars ?? {});
    if (!tmpl) {
      return NextResponse.json({ error: `Unknown template: ${body.template}` }, { status: 400 });
    }
    subject = body.subject ?? tmpl.subject;
    html    = tmpl.html;
    text    = tmpl.text;
  }

  if (!html && !text) {
    return NextResponse.json(
      { error: "Provide either `template`, `html`, or `text` in the body." },
      { status: 422 }
    );
  }

  try {
    const info = await getTransporter().sendMail({
      from: process.env.SMTP_FROM ?? process.env.SMTP_USER,
      to: Array.isArray(body.to) ? body.to.join(", ") : body.to,
      subject,
      html: html || undefined,
      text: text || undefined,
    });

    return NextResponse.json({ messageId: info.messageId, accepted: info.accepted });
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : "Failed to send email";
    return NextResponse.json({ error: msg }, { status: 502 });
  }
}

import { errorResponse } from "@/lib/api/error";
/**
 * POST /api/email/send-kyc-reminder
 * ─────────────────────────────────────────────────────────────────────────────
 * Send a KYC document request reminder email to a customer.
 * Allowed roles: admin, manager, employee.
 *
 * Body:
 * {
 *   customer_id: string;
 * }
 */

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";
import { emailService } from "@/lib/services/email.service";
import { protect } from "@/lib/api/protect";

export async function POST(req: NextRequest) {
  const blocked = protect(req, { maxRequests: 10, windowMs: 60_000 });
  if (blocked) return blocked;

  const caller = await requireAuth(req, ["admin", "manager", "employee"]);
  if (isAuthError(caller)) return authError(caller);

  let body: { customer_id: string };
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  if (!body.customer_id) {
    return NextResponse.json({ error: "Missing `customer_id`" }, { status: 422 });
  }

  try {
    // ── Fetch customer ──
    const { data: customer, error: customerError } = await supabaseAdmin
      .from("customers")
      .select("*")
      .eq("id", body.customer_id)
      .single();

    if (customerError || !customer) {
      return NextResponse.json({ error: "Customer not found" }, { status: 404 });
    }

    if (!customer.email) {
      return NextResponse.json({ error: "Customer has no email address" }, { status: 422 });
    }

    // Default Customer Portal URL
    const portalUrl = process.env.NEXT_PUBLIC_PORTAL_URL || "http://localhost:3001/dashboard/profile";
    const senderName = caller.name || "Your Insurance Agent";

    // ── Send KYC request email ──
    const result = await emailService.sendKycReminder(customer.email, {
      customerName: customer.name || "Valued Customer",
      portalUrl,
      senderName,
    });

    if (!result.success) {
      return NextResponse.json(
        { error: `Failed to send email: ${result.error}` },
        { status: 500 }
      );
    }

    // ── Audit log ──
    try {
      await supabaseAdmin.from("audit_logs").insert({
        user_id: caller.uid,
        user_name: caller.name ?? caller.email,
        user_role: caller.role,
        action: "email_reminder",
        module: "kyc",
        details: `Sent KYC reminder email to ${customer.email} (Customer ID: ${body.customer_id})`,
        created_at: new Date().toISOString(),
      });

      // Also log in communication logs for tracking
      await supabaseAdmin.from("communication_logs").insert({
        customer_id: customer.id,
        customer_name: customer.name,
        channel: "email",
        recipient: customer.email,
        subject: "Action Required: Please Upload Your KYC Documents",
        body: "KYC reminder sent via system.",
        status: "sent",
        sent_at: new Date().toISOString(),
        created_by: caller.uid,
      });
    } catch (auditErr) {
      console.error("[send-kyc-reminder] Log failed:", auditErr);
    }

    return NextResponse.json({
      success: true,
      messageId: result.messageId,
      sentTo: customer.email,
    });
  } catch (err: unknown) {
    console.error("[send-kyc-reminder] Error:", err);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

/**
 * POST /api/email/send-reminder
 * ─────────────────────────────────────────────────────────────────────────────
 * Send a payment / renewal / expiry reminder email to a customer.
 *
 * Allowed roles: admin, manager, employee (employee only for their assigned policies).
 *
 * Body:
 * {
 *   policy_id: string;          // Required — the policy to remind about
 *   renewal_id?: string;        // Optional — if reminding about a specific renewal
 *   type: "policy_expiry" | "payment_due";  // Reminder type
 * }
 */

import { errorResponse } from "@/lib/api/error";
import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";
import { emailService, setEmailCompanyName, setEmailCompanyEmail, setEmailCompanyPhone, setPolicyEmailTemplate, setRenewalEmailTemplate } from "@/lib/services/email.service";
import { protect } from "@/lib/api/protect";

export async function POST(req: NextRequest) {
  const blocked = protect(req, { maxRequests: 10, windowMs: 60_000 });
  if (blocked) return blocked;

  // Allow admin, manager, AND employee
  const caller = await requireAuth(req, ["admin", "manager", "employee"]);
  if (isAuthError(caller)) return authError(caller);

  // ── Parse body ──
  let body: { policy_id: string; renewal_id?: string; type: "policy_expiry" | "payment_due" };
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  if (!body.policy_id) {
    return NextResponse.json({ error: "Missing `policy_id`" }, { status: 422 });
  }

  if (!body.type || !["policy_expiry", "payment_due"].includes(body.type)) {
    return NextResponse.json(
      { error: "Invalid `type`. Must be 'policy_expiry' or 'payment_due'" },
      { status: 422 }
    );
  }

  try {
    // ── Read email settings ──
    const { data: configs } = await supabaseAdmin
      .from("system_config")
      .select("key, value")
      .in("key", [
        "company_name",
        "email_notifications_enabled",
        "company_email",
        "company_phone",
        "policy_email_template",
        "renewal_email_template",
      ]);

    const configMap = Object.fromEntries((configs || []).map((c) => [c.key, c.value]));
    if (configMap.company_name) setEmailCompanyName(String(configMap.company_name));
    if (configMap.company_email) setEmailCompanyEmail(String(configMap.company_email));
    if (configMap.company_phone) setEmailCompanyPhone(String(configMap.company_phone));
    if (configMap.policy_email_template) setPolicyEmailTemplate(String(configMap.policy_email_template));
    if (configMap.renewal_email_template) setRenewalEmailTemplate(String(configMap.renewal_email_template));
    const emailEnabled = configMap.email_notifications_enabled !== "false";
    if (!emailEnabled) {
      return NextResponse.json({ error: "Email notifications are disabled in settings" }, { status: 403 });
    }

    // ── Fetch policy ──
    const { data: policy, error: policyError } = await supabaseAdmin
      .from("policies")
      .select("*")
      .eq("id", body.policy_id)
      .single();

    if (policyError || !policy) {
      return NextResponse.json({ error: "Policy not found" }, { status: 404 });
    }

    // ── Employee permission check: can only remind for their assigned policies ──
    if (caller.role === "employee" && policy.assigned_to !== caller.uid) {
      return NextResponse.json(
        { error: "You can only send reminders for policies assigned to you" },
        { status: 403 }
      );
    }

    // ── Fetch customer ──
    const { data: customer, error: customerError } = await supabaseAdmin
      .from("customers")
      .select("*")
      .eq("id", policy.customer_id)
      .single();

    if (customerError || !customer) {
      return NextResponse.json({ error: "Customer not found" }, { status: 404 });
    }

    if (!customer.email) {
      return NextResponse.json({ error: "Customer has no email address" }, { status: 422 });
    }

    // ── Fetch assigned agent info ──
    let agentName = "Your Insurance Agent";
    let agentPhone: string | undefined;
    if (policy.assigned_to) {
      const { data: agent } = await supabaseAdmin
        .from("users")
        .select("name, phone")
        .eq("id", policy.assigned_to)
        .single();
      if (agent) {
        agentName = agent.name || agentName;
        agentPhone = agent.phone ?? undefined;
      }
    }

    // ── Fetch renewal if provided ──
    let renewalDueDate: string | undefined;
    if (body.renewal_id) {
      const { data: renewal } = await supabaseAdmin
        .from("renewals")
        .select("due_date")
        .eq("id", body.renewal_id)
        .single();
      if (renewal?.due_date) {
        const d = new Date(renewal.due_date);
        renewalDueDate = d.toLocaleDateString("en-IN", {
          day: "2-digit",
          month: "short",
          year: "numeric",
        });
      }
    }

    // ── Format dates ──
    const endDate = policy.end_date ? new Date(policy.end_date) : null;

    const expiryDateStr = endDate
      ? endDate.toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" })
      : "N/A";

    const daysRemaining = endDate
      ? Math.ceil((endDate.getTime() - Date.now()) / (1000 * 60 * 60 * 24))
      : 0;

    // ── Format premium ──
    const premiumAmount = policy.premium_amount
      ? Number(policy.premium_amount).toLocaleString("en-IN")
      : "N/A";

    // ── Send email based on type ──
    let result;

    if (body.type === "policy_expiry") {
      result = await emailService.sendPolicyExpiryReminder(customer.email, {
        customerName: customer.name || "Valued Customer",
        policyNumber: policy.policy_number || "N/A",
        policyType: policy.policy_type || "Insurance",
        expiryDate: expiryDateStr,
        daysRemaining: Math.max(daysRemaining, 0),
        agentName,
        agentPhone,
      });
    } else {
      // payment_due — use the dedicated payment reminder template
      result = await emailService.sendPaymentReminder(customer.email, {
        customerName: customer.name || "Valued Customer",
        policyNumber: policy.policy_number || "N/A",
        policyType: policy.policy_type || "Insurance",
        premiumAmount,
        dueDate: renewalDueDate || expiryDateStr,
        daysOverdue: daysRemaining < 0 ? Math.abs(daysRemaining) : 0,
        agentName,
        agentPhone,
      });
    }

    if (!result.success) {
      return NextResponse.json(
        { error: `Failed to send email: ${result.error}` },
        { status: 500 }
      );
    }

    // ── Audit log ──
    try {
      const { error: auditError } = await supabaseAdmin.from("audit_logs").insert({
        user_id: caller.uid,
        user_name: caller.name ?? caller.email,
        user_role: caller.role,
        action: "email_reminder",
        module: body.type === "policy_expiry" ? "policies" : "renewals",
        details: `Sent ${body.type} reminder email to ${customer.email} for policy ${policy.policy_number}`,
        created_at: new Date().toISOString(),
      });
      if (auditError) console.error("[send-reminder] Audit log failed:", auditError);
    } catch {
      // Non-critical — don't fail the request
    }

    return NextResponse.json({
      success: true,
      messageId: result.messageId,
      sentTo: customer.email,
    });
  } catch (err: unknown) {
    console.error("[send-reminder] Error:", err);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

