/**
 * Background PDF Extraction API
 * Creates extraction jobs that run asynchronously
 */

import { NextRequest, NextResponse } from 'next/server';
import { createExtractionJob, getJobStatus } from '@/lib/workers/pdf-extraction-worker';
import { supabase } from '@/lib/supabase/client';
import { errorResponse } from '@/lib/api/error';

export const runtime = 'nodejs';
export const maxDuration = 60;

/**
 * POST /api/extract-pdf/background
 * Create a background extraction job
 */
export async function POST(request: NextRequest) {
  try {
    const formData = await request.formData();
    const file = formData.get('file') as File;
    
    if (!file) {
      return NextResponse.json(
        { error: 'No file provided' },
        { status: 400 }
      );
    }
    
    // Upload file to temporary storage
    const timestamp = Date.now();
    const fileName = `temp/${timestamp}_${file.name}`;
    
    const { data: uploadData, error: uploadError } = await supabase.storage
      .from('policy-documents')
      .upload(fileName, file, {
        cacheControl: '3600',
        upsert: false,
      });
    
    if (uploadError) {
      console.error('[Background Extract] Upload failed:', uploadError);
      return NextResponse.json(
        { error: 'Failed to upload file' },
        { status: 500 }
      );
    }
    
    // Get public URL
    const { data: { publicUrl } } = supabase.storage
      .from('policy-documents')
      .getPublicUrl(fileName);
    
    // Create extraction job
    const jobId = await createExtractionJob(publicUrl);
    
    return NextResponse.json({
      jobId,
      status: 'pending',
      message: 'Extraction job created. Poll /api/extract-pdf/background/status?jobId=<jobId> for results.',
    });
  } catch (err: unknown) {
    return errorResponse(err);
  }
}

/**
 * GET /api/extract-pdf/background/status?jobId=<jobId>
 * Get extraction job status
 */
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const jobId = searchParams.get('jobId');
    
    if (!jobId) {
      return NextResponse.json(
        { error: 'Job ID required' },
        { status: 400 }
      );
    }
    
    const job = getJobStatus(jobId);
    
    if (!job) {
      return NextResponse.json(
        { error: 'Job not found' },
        { status: 404 }
      );
    }
    
    return NextResponse.json({
      jobId: job.id,
      status: job.status,
      result: job.result,
      error: job.error,
      createdAt: job.createdAt,
      completedAt: job.completedAt,
    });
  } catch (err: unknown) {
    return errorResponse(err);
  }
}

/**
 * GET  /api/fleet/[customerId]/claims — list fleet claims
 * POST /api/fleet/[customerId]/claims — register fleet claim
 */

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";

type Params = { params: Promise<{ customerId: string }> };

export async function GET(req: NextRequest, { params }: Params) {
  const caller = await requireAuth(req, ["admin", "manager", "employee"]);
  if (isAuthError(caller)) return authError(caller);

  const { customerId } = await params;

  const { data, error } = await supabaseAdmin
    .from("claims")
    .select("*")
    .eq("customer_id", customerId)
    .order("created_at", { ascending: false });

  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
  return NextResponse.json({ data: data ?? [] });
}

export async function POST(req: NextRequest, { params }: Params) {
  const caller = await requireAuth(req, ["admin", "manager"]);
  if (isAuthError(caller)) return authError(caller);

  const { customerId } = await params;

  let body: Record<string, unknown>;
  try { body = await req.json(); } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const { policy_id, vehicle_id, claim_amount, claim_type, accident_details } = body as any;

  if (!policy_id || !claim_amount) {
    return NextResponse.json({ error: "policy_id and claim_amount are required" }, { status: 400 });
  }

  // Validate active policy
  const { data: policy } = await supabaseAdmin
    .from("policies")
    .select("id, status, assigned_to")
    .eq("id", policy_id)
    .single();

  if (!policy || policy.status !== "active") {
    return NextResponse.json({ error: "Policy must be active to register a claim" }, { status: 400 });
  }

  // Generate claim number
  const { data: counterData } = await supabaseAdmin
    .from("system_config").select("value").eq("key", "claim_counter_flt").maybeSingle();
  const next = (typeof counterData?.value === "number" ? counterData.value : 0) + 1;
  await supabaseAdmin.from("system_config").upsert({ key: "claim_counter_flt", value: next, category: "counters" }, { onConflict: "key" });
  const claimNumber = `CLM-FLT-${String(next).padStart(5, "0")}`;

  const now = new Date().toISOString();
  const { data: claim, error: insertErr } = await supabaseAdmin
    .from("claims")
    .insert({
      claim_number: claimNumber,
      policy_id,
      customer_id: customerId,
      claim_type: claim_type || "own_damage",
      claim_amount: Number(claim_amount),
      status: "registered",
      claim_date: now.split("T")[0],
      incident_description: accident_details || null,
      surveyor_name: (body.surveyor_name as string) || null,
      surveyor_phone: (body.surveyor_phone as string) || null,
      created_by: caller.uid,
      customer_name: "",
    } as any)
    .select()
    .single() as any;

  if (insertErr) return NextResponse.json({ error: insertErr.message }, { status: 500 });

  // Notify assigned RM
  if (policy.assigned_to) {
    await supabaseAdmin.from("notifications").insert({
      user_id: policy.assigned_to,
      title: "New Fleet Claim Registered",
      message: `Claim ${claimNumber} registered for policy ${policy_id}`,
      type: "claim_update",
      link: `/dashboard/claims/${claim.id}`,
      read: false,
      created_at: now,
      updated_at: now,
    } as any);
  }

  return NextResponse.json(claim, { status: 201 });
}

/**
 * PUT    /api/fleet/[customerId]/drivers/[id] — update driver
 * DELETE /api/fleet/[customerId]/drivers/[id] — delete driver
 */

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";

const db = supabaseAdmin as any;

type Params = { params: Promise<{ customerId: string; id: string }> };

export async function PUT(req: NextRequest, { params }: Params) {
  const caller = await requireAuth(req, ["admin", "manager"]);
  if (isAuthError(caller)) return authError(caller);

  const { customerId, id } = await params;

  let body: Record<string, unknown>;
  try { body = await req.json(); } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const { name, license_expiry, mobile, address } = body as any;

  if (!name) return NextResponse.json({ error: "name is required" }, { status: 400 });

  // Validate future date if provided
  if (license_expiry && new Date(license_expiry) <= new Date()) {
    return NextResponse.json({ error: "license_expiry must be a future date" }, { status: 400 });
  }

  const now = new Date().toISOString();
  const updates: Record<string, unknown> = { name, updated_at: now };
  if (license_expiry) updates.license_expiry = license_expiry;
  if (mobile !== undefined) updates.mobile = mobile;
  if (address !== undefined) updates.address = address;

  const { data, error } = await db
    .from("fleet_drivers")
    .update(updates)
    .eq("id", id)
    .eq("customer_id", customerId)
    .select()
    .single();

  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
  return NextResponse.json(data);
}

export async function DELETE(req: NextRequest, { params }: Params) {
  const caller = await requireAuth(req, ["admin", "manager"]);
  if (isAuthError(caller)) return authError(caller);

  const { customerId, id } = await params;

  const { error } = await db
    .from("fleet_drivers")
    .delete()
    .eq("id", id)
    .eq("customer_id", customerId);

  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
  return NextResponse.json({ success: true });
}

