/**
 * GET /api/fleet/[customerId]/validity — validity dashboard data
 */

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";

type Params = { params: Promise<{ customerId: string }> };

export async function GET(req: NextRequest, { params }: Params) {
  const caller = await requireAuth(req, ["admin", "manager", "employee"]);
  if (isAuthError(caller)) return authError(caller);

  const { customerId } = await params;
  const { searchParams } = new URL(req.url);
  const docType = searchParams.get("document_type") ?? "";
  const category = searchParams.get("vehicle_category") ?? "";

  // Get all vehicles for this customer
  let vehicleQuery = supabaseAdmin
    .from("fleet_vehicles")
    .select("id, registration_number, make, model, vehicle_category, status")
    .eq("customer_id", customerId)
    .eq("status", "Active");

  if (category) vehicleQuery = vehicleQuery.eq("vehicle_category", category);

  const { data: vehicles } = await vehicleQuery;
  if (!vehicles || vehicles.length === 0) {
    return NextResponse.json({ data: [], summary: { expired: 0, expiring_7: 0, expiring_15: 0, expiring_30: 0 } });
  }

  const vehicleIds = vehicles.map((v: any) => v.id);

  // Get validity documents
  let validityQuery = supabaseAdmin
    .from("fleet_validity_documents")
    .select("*")
    .in("vehicle_id", vehicleIds)
    .lte("expiry_date", new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split("T")[0]);

  if (docType) validityQuery = validityQuery.eq("document_type", docType);

  const { data: validityDocs } = await validityQuery;

  const vehicleMap = new Map(vehicles.map((v: any) => [v.id, v]));
  const today = new Date();

  const enriched = (validityDocs ?? []).map((doc: any) => {
    const vehicle = vehicleMap.get(doc.vehicle_id);
    const expiryDate = new Date(doc.expiry_date);
    const daysLeft = Math.floor((expiryDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
    return {
      ...doc,
      vehicle,
      days_remaining: daysLeft,
      expiry_bucket: daysLeft < 0 ? "expired" : daysLeft <= 7 ? "7_days" : daysLeft <= 15 ? "15_days" : "30_days",
    };
  }).sort((a: any, b: any) => a.days_remaining - b.days_remaining);

  const summary = {
    expired: enriched.filter((d: any) => d.days_remaining < 0).length,
    expiring_7: enriched.filter((d: any) => d.days_remaining >= 0 && d.days_remaining <= 7).length,
    expiring_15: enriched.filter((d: any) => d.days_remaining > 7 && d.days_remaining <= 15).length,
    expiring_30: enriched.filter((d: any) => d.days_remaining > 15 && d.days_remaining <= 30).length,
  };

  return NextResponse.json({ data: enriched, summary });
}

/**
 * PUT    /api/fleet/[customerId]/vehicles/[id]  — update vehicle
 * DELETE /api/fleet/[customerId]/vehicles/[id]  — delete vehicle (creates endorsement)
 */

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";

// Cast to any to support Phase 3 tables not yet in database.types.ts
const db = supabaseAdmin as any;

type Params = { params: Promise<{ customerId: string; id: string }> };

export async function PUT(req: NextRequest, { params }: Params) {
  const caller = await requireAuth(req, ["admin", "manager"]);
  if (isAuthError(caller)) return authError(caller);

  const { customerId, id } = await params;

  let body: Record<string, unknown>;
  try { body = await req.json(); } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const now = new Date().toISOString();
  const updates: Record<string, unknown> = { updated_at: now };

  const allowed = ["make", "model", "variant", "fuel_type", "idv", "primary_driver_id",
    "chassis_number", "engine_number", "seating_capacity", "gvw", "vehicle_category"];
  for (const key of allowed) {
    if (body[key] !== undefined) updates[key] = body[key];
  }

  // Validate primary driver uniqueness
  if (body.primary_driver_id) {
    const { data: otherVehicle } = await db
      .from("fleet_vehicles")
      .select("id")
      .eq("primary_driver_id", body.primary_driver_id)
      .neq("id", id)
      .neq("status", "Deleted")
      .limit(1);

    if (otherVehicle && otherVehicle.length > 0) {
      return NextResponse.json(
        { error: "This driver is already assigned as primary driver to another vehicle" },
        { status: 409 }
      );
    }
  }

  const { data, error } = await db
    .from("fleet_vehicles")
    .update(updates)
    .eq("id", id)
    .eq("customer_id", customerId)
    .select()
    .single();

  if (error) return NextResponse.json({ error: error.message }, { status: 500 });

  try {
    await supabaseAdmin.from("audit_logs").insert({
      action: "update", module: "fleet_vehicles",
      details: `Updated fleet vehicle: ${id}`,
      user_id: caller.uid, user_name: caller.name ?? caller.email,
      user_role: caller.role, created_at: now,
    } as any);
  } catch { /* non-critical */ }

  return NextResponse.json(data);
}

export async function DELETE(req: NextRequest, { params }: Params) {
  const caller = await requireAuth(req, ["admin", "manager"]);
  if (isAuthError(caller)) return authError(caller);

  const { customerId, id } = await params;

  const { data: vehicle, error: fetchErr } = await db
    .from("fleet_vehicles")
    .select("*")
    .eq("id", id)
    .eq("customer_id", customerId)
    .single();

  if (fetchErr || !vehicle) {
    return NextResponse.json({ error: "Vehicle not found" }, { status: 404 });
  }

  const now = new Date().toISOString();

  // Soft delete
  await db.from("fleet_vehicles").update({
    status: "Deleted", deleted_at: now, updated_at: now,
  }).eq("id", id);

  // Create endorsement
  const endKey = "endorsement_counter_FLT";
  const { data: cData } = await supabaseAdmin.from("system_config").select("value").eq("key", endKey).maybeSingle();
  const nextEnd = (typeof cData?.value === "number" ? cData.value : 0) + 1;
  await supabaseAdmin.from("system_config").upsert({ key: endKey, value: nextEnd, category: "counters" }, { onConflict: "key" });
  const endNumber = `END-FLT-${String(nextEnd).padStart(5, "0")}`;

  await db.from("fleet_vehicle_endorsements").insert({
    endorsement_number: endNumber,
    policy_id: vehicle.policy_id,
    customer_id: customerId,
    vehicle_id: id,
    endorsement_type: "Deletion",
    endorsement_date: now.split("T")[0],
    vehicle_details: {
      registration_number: vehicle.registration_number,
      make: vehicle.make,
      model: vehicle.model,
    },
    created_by: caller.uid,
    created_at: now,
  });

  try {
    await supabaseAdmin.from("audit_logs").insert({
      action: "delete", module: "fleet_vehicles",
      details: `Deleted fleet vehicle: ${vehicle.registration_number}`,
      user_id: caller.uid, user_name: caller.name ?? caller.email,
      user_role: caller.role, created_at: now,
    } as any);
  } catch { /* non-critical */ }

  return NextResponse.json({ success: true, endorsement_number: endNumber });
}

