  return NextResponse.json({ data: data ?? [] });
}

/**
 * POST /api/gmc/[customerId]/members/[id]/ecard — generate e-card PDF
 */

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";
import { PDFDocument, rgb, StandardFonts } from "pdf-lib";

// Cast to any to support Phase 3 tables not yet in database.types.ts
const db = supabaseAdmin as any;

type Params = { params: Promise<{ customerId: string; id: string }> };

export async function POST(req: NextRequest, { params }: Params) {
  const caller = await requireAuth(req, ["admin", "manager"]);
  if (isAuthError(caller)) return authError(caller);

  const { customerId, id: memberId } = await params;

  let body: Record<string, unknown> = {};
  try { body = await req.json(); } catch { /* optional body */ }

  // Fetch member, policy, and template in parallel
  const [memberRes, templateRes] = await Promise.all([
    db.from("gmc_members").select("*, policies(*)").eq("id", memberId).single(),
    db.from("gmc_ecard_templates").select("*").eq("customer_id", customerId).maybeSingle(),
  ]);

  if (memberRes.error || !memberRes.data) {
    return NextResponse.json({ error: "Member not found" }, { status: 404 });
  }

  const member = memberRes.data;
  const template = templateRes.data;
  const policy = member.policies;

  // Generate PDF using pdf-lib
  const pdfDoc = await PDFDocument.create();
  const page = pdfDoc.addPage([595, 420]); // A5 landscape
  const font = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const boldFont = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

  const { width, height } = page.getSize();

  // Background
  page.drawRectangle({ x: 0, y: 0, width, height, color: rgb(0.97, 0.97, 1) });

  // Header bar
  page.drawRectangle({ x: 0, y: height - 80, width, height: 80, color: rgb(0.1, 0.3, 0.7) });

  // Company name
  const companyName = template?.company_name || "Insurance Company";
  page.drawText(companyName, {
    x: 20, y: height - 50, size: 20, font: boldFont, color: rgb(1, 1, 1),
  });

  // E-Card label
  page.drawText("GROUP MEDICLAIM INSURANCE CARD", {
    x: 20, y: height - 70, size: 9, font, color: rgb(0.8, 0.9, 1),
  });

  // Member details section
  const leftX = 20;
  let y = height - 110;
  const lineH = 22;

  const drawField = (label: string, value: string) => {
    page.drawText(label + ":", { x: leftX, y, size: 9, font, color: rgb(0.4, 0.4, 0.4) });
    page.drawText(value || "—", { x: leftX + 120, y, size: 10, font: boldFont, color: rgb(0.1, 0.1, 0.1) });
    y -= lineH;
  };

  drawField("Member Name", member.name);
  drawField("Employee ID", member.employee_id);
  drawField("Date of Birth", member.dob || "—");
  drawField("Gender", member.gender || "—");
  drawField("Member Type", member.member_type === "employee" ? "Employee" : "Dependent");

  // Policy details (right column)
  let ry = height - 110;
  const rightX = width / 2 + 20;

  const drawRightField = (label: string, value: string) => {
    page.drawText(label + ":", { x: rightX, y: ry, size: 9, font, color: rgb(0.4, 0.4, 0.4) });
    page.drawText(value || "—", { x: rightX + 120, y: ry, size: 10, font: boldFont, color: rgb(0.1, 0.1, 0.1) });
    ry -= lineH;
  };

  drawRightField("Policy Number", policy?.policy_number || "—");
  drawRightField("Sum Insured", policy?.sum_insured ? `Rs.${policy.sum_insured.toLocaleString("en-IN")}` : "—");
  drawRightField("Valid From", policy?.start_date ? policy.start_date.split("T")[0] : "—");
  drawRightField("Valid To", policy?.end_date ? policy.end_date.split("T")[0] : "—");

  // TPA details
  if (template?.tpa_name) {
    drawRightField("TPA", template.tpa_name);
    if (template.tpa_contact) drawRightField("TPA Contact", template.tpa_contact);
  }

  // Emergency contact
  if (template?.emergency_contact) {
    page.drawText("Emergency: " + template.emergency_contact, {
      x: 20, y: 20, size: 9, font, color: rgb(0.8, 0.1, 0.1),
    });
  }

  // Footer
  page.drawRectangle({ x: 0, y: 0, width, height: 35, color: rgb(0.1, 0.3, 0.7) });
  page.drawText("This card is for identification purposes only. Subject to policy terms and conditions.", {
    x: 20, y: 12, size: 7, font, color: rgb(0.8, 0.9, 1),
  });

  const pdfBytes = await pdfDoc.save();

  // Upload to Supabase Storage
  const filePath = `ecards/${customerId}/${memberId}/${Date.now()}.pdf`;
  const { error: uploadErr } = await supabaseAdmin.storage
    .from("documents")
    .upload(filePath, pdfBytes, { contentType: "application/pdf", upsert: true });

  if (uploadErr) return NextResponse.json({ error: "Failed to upload PDF" }, { status: 500 });

  const { data: urlData } = supabaseAdmin.storage.from("documents").getPublicUrl(filePath);
  const fileUrl = urlData.publicUrl;

  // Record generation
  const now = new Date().toISOString();
  await db.from("gmc_ecard_generations").insert({
    member_id: memberId,
    policy_id: member.policy_id,
    file_url: fileUrl,
    file_path: filePath,
    generated_by: caller.uid,
    generated_by_name: caller.name ?? caller.email,
    emailed_to: (body.email_to as string) || null,
    created_at: now,
  });

  // Audit log
  try {
    await supabaseAdmin.from("audit_logs").insert({
      action: "create", module: "gmc_ecard",
      details: `Generated e-card for member: ${member.name}`,
      user_id: caller.uid, user_name: caller.name ?? caller.email,
      user_role: caller.role, created_at: now,
    } as any);
  } catch { /* non-critical */ }

  return NextResponse.json({ file_url: fileUrl, file_path: filePath });
}

/**
 * PUT    /api/gmc/[customerId]/members/[id]  — update member
 * DELETE /api/gmc/[customerId]/members/[id]  — delete member (creates endorsement)
 */

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";

// Cast to any to support Phase 3 tables not yet in database.types.ts
const db = supabaseAdmin as any;

type Params = { params: Promise<{ customerId: string; id: string }> };

export async function PUT(req: NextRequest, { params }: Params) {
  const caller = await requireAuth(req, ["admin", "manager"]);
  if (isAuthError(caller)) return authError(caller);

  const { customerId, id } = await params;

  let body: Record<string, unknown>;
  try { body = await req.json(); } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const now = new Date().toISOString();
  const updates: Record<string, unknown> = { updated_at: now };

  if (body.name !== undefined) updates.name = body.name;
  if (body.mobile !== undefined) updates.mobile = body.mobile;
  if (body.email !== undefined) updates.email = body.email;
  if (body.address !== undefined) updates.address = body.address;
  if (body.department !== undefined) updates.department = body.department;
  if (body.designation !== undefined) updates.designation = body.designation;

  const { data, error } = await db
    .from("gmc_members")
    .update(updates)
    .eq("id", id)
    .eq("customer_id", customerId)
    .select()
    .single();

  if (error) return NextResponse.json({ error: error.message }, { status: 500 });

  try {
    await supabaseAdmin.from("audit_logs").insert({
      action: "update", module: "gmc_members",
      details: `Updated GMC member: ${id}`,
      user_id: caller.uid, user_name: caller.name ?? caller.email,
      user_role: caller.role, created_at: now,
    } as any);
  } catch { /* non-critical */ }

  return NextResponse.json(data);
}

export async function DELETE(req: NextRequest, { params }: Params) {
  const caller = await requireAuth(req, ["admin", "manager"]);
  if (isAuthError(caller)) return authError(caller);

  const { customerId, id } = await params;

  const { data: member, error: fetchErr } = await db
    .from("gmc_members")
    .select("*")
    .eq("id", id)
    .eq("customer_id", customerId)
    .single();

  if (fetchErr || !member) {
    return NextResponse.json({ error: "Member not found" }, { status: 404 });
  }

  const now = new Date().toISOString();

  // Soft delete member
  await db.from("gmc_members").update({
    status: "Deleted", deleted_at: now, updated_at: now,
  }).eq("id", id);

  // Cascade: delete dependents
  await db.from("gmc_members").update({
    status: "Deleted", deleted_at: now, updated_at: now,
  }).eq("parent_member_id", id);

  // Create endorsement record
  const endNumber = await getNextEndorsementNumber("GMC");
  await db.from("gmc_member_endorsements").insert({
    endorsement_number: endNumber,
    policy_id: member.policy_id,
    customer_id: customerId,
    member_id: id,
    endorsement_type: "Deletion",
    endorsement_date: now.split("T")[0],
    member_details: { employee_id: member.employee_id, name: member.name },
    created_by: caller.uid,
    created_at: now,
  });

  try {
    await supabaseAdmin.from("audit_logs").insert({
      action: "delete", module: "gmc_members",
      details: `Deleted GMC member: ${member.name} (${member.employee_id})`,
      user_id: caller.uid, user_name: caller.name ?? caller.email,
      user_role: caller.role, created_at: now,
    } as any);
  } catch { /* non-critical */ }

  return NextResponse.json({ success: true, endorsement_number: endNumber });
}

async function getNextEndorsementNumber(type: "GMC" | "FLT"): Promise<string> {
  const key = `endorsement_counter_${type}`;
  const { data } = await supabaseAdmin.from("system_config").select("value").eq("key", key).maybeSingle();
  const current = typeof data?.value === "number" ? data.value : 0;
  const next = current + 1;
  await supabaseAdmin.from("system_config").upsert({ key, value: next, category: "counters" }, { onConflict: "key" });
  return `END-${type}-${String(next).padStart(5, "0")}`;
}

/**
 * POST /api/gmc/[customerId]/members/bulk — bulk upload GMC members from CSV/Excel
 */

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";
import * as XLSX from "xlsx";

type Params = { params: Promise<{ customerId: string }> };

export async function POST(req: NextRequest, { params }: Params) {
  const caller = await requireAuth(req, ["admin", "manager"]);
  if (isAuthError(caller)) return authError(caller);

  const { customerId } = await params;

  const formData = await req.formData();
  const file = formData.get("file") as File | null;
  const policyId = formData.get("policy_id") as string | null;

  if (!file) return NextResponse.json({ error: "file is required" }, { status: 400 });
  if (!policyId) return NextResponse.json({ error: "policy_id is required" }, { status: 400 });
  if (file.size > 10 * 1024 * 1024) return NextResponse.json({ error: "File size must be less than 10MB" }, { status: 400 });

  // Parse file
  const buffer = await file.arrayBuffer();
  const workbook = XLSX.read(buffer, { type: "array" });
  const sheet = workbook.Sheets[workbook.SheetNames[0]];
  const rows: Record<string, unknown>[] = XLSX.utils.sheet_to_json(sheet, { defval: "" });

  if (rows.length === 0) return NextResponse.json({ error: "File is empty" }, { status: 400 });

  // Validate required columns
  const firstRow = rows[0];
  const required = ["Employee ID", "Name", "DOB", "Gender"];
  for (const col of required) {
    if (!(col in firstRow)) {
      return NextResponse.json({ error: `Missing required column: ${col}` }, { status: 400 });
    }
  }

  const now = new Date().toISOString();
  const errors: { row: number; field: string; message: string }[] = [];
  const toInsert: Record<string, unknown>[] = [];

  // Get existing employee IDs for this customer
  const { data: existingMembers } = await supabaseAdmin
    .from("gmc_members")
    .select("employee_id")
    .eq("customer_id", customerId)
    .neq("status", "Deleted");

  const existingIds = new Set((existingMembers ?? []).map((m: any) => m.employee_id));
  const seenInFile = new Set<string>();

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const rowNum = i + 2; // 1-indexed + header row

    const employeeId = String(row["Employee ID"] || "").trim();
    const name = String(row["Name"] || "").trim();
    const dob = String(row["DOB"] || "").trim();
    const gender = String(row["Gender"] || "").trim();
    const mobile = String(row["Mobile"] || "").trim();
    const email = String(row["Email"] || "").trim();
    const department = String(row["Department"] || "").trim();
    const designation = String(row["Designation"] || "").trim();

    // Validate required fields
    if (!employeeId) { errors.push({ row: rowNum, field: "Employee ID", message: "Required" }); continue; }
    if (!name) { errors.push({ row: rowNum, field: "Name", message: "Required" }); continue; }
    if (!dob) { errors.push({ row: rowNum, field: "DOB", message: "Required" }); continue; }
    if (!gender) { errors.push({ row: rowNum, field: "Gender", message: "Required" }); continue; }

    // Validate gender
    if (!["Male", "Female", "Other"].includes(gender)) {
      errors.push({ row: rowNum, field: "Gender", message: "Must be Male, Female, or Other" }); continue;
    }

    // Validate DOB is in the past
    const dobDate = new Date(dob);
    if (isNaN(dobDate.getTime()) || dobDate >= new Date()) {
      errors.push({ row: rowNum, field: "DOB", message: "Must be a valid past date" }); continue;
    }

    // Validate mobile format
    if (mobile && !/^[6-9]\d{9}$/.test(mobile)) {
      errors.push({ row: rowNum, field: "Mobile", message: "Must be a valid 10-digit mobile number" }); continue;
    }

    // Validate email format
    if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      errors.push({ row: rowNum, field: "Email", message: "Invalid email format" }); continue;
    }

    // Check uniqueness
    if (existingIds.has(employeeId) || seenInFile.has(employeeId)) {
      errors.push({ row: rowNum, field: "Employee ID", message: `Duplicate: ${employeeId}` }); continue;
    }

    seenInFile.add(employeeId);
    toInsert.push({
      customer_id: customerId,
      policy_id: policyId,
      employee_id: employeeId,
      name,
      member_type: "employee",
      dob: dobDate.toISOString().split("T")[0],
      gender,
      mobile: mobile || null,
      email: email || null,
      department: department || null,
      designation: designation || null,
      status: "Active",
      created_by: caller.uid,
      created_at: now,
      updated_at: now,
    });
  }

  // Insert in batches of 100
  let successCount = 0;
  for (let i = 0; i < toInsert.length; i += 100) {
    const batch = toInsert.slice(i, i + 100);
    const { error: batchErr } = await supabaseAdmin.from("gmc_members").insert(batch as any);
    if (batchErr) {
      errors.push({ row: i + 2, field: "batch", message: batchErr.message });
    } else {
      successCount += batch.length;
    }
  }

  // Generate error report CSV if needed
  let errorReportUrl: string | null = null;
  if (errors.length > 0) {
    const csvRows = [["Row", "Field", "Error"], ...errors.map(e => [e.row, e.field, e.message])];
    const csv = csvRows.map(r => r.join(",")).join("\n");
    const blob = new Blob([csv], { type: "text/csv" });
    const path = `bulk-upload-errors/${customerId}/${Date.now()}.csv`;
    const { data: uploadData } = await supabaseAdmin.storage
      .from("documents")
      .upload(path, blob, { contentType: "text/csv" });
    if (uploadData) {
      const { data: urlData } = supabaseAdmin.storage.from("documents").getPublicUrl(path);
      errorReportUrl = urlData.publicUrl;
    }
  }

  // Notify uploader
  await supabaseAdmin.from("notifications").insert({
    user_id: caller.uid,
    title: "Bulk Upload Complete",
    message: `GMC member upload: ${successCount} added, ${errors.length} failed`,
    type: "system",
    read: false,
    created_at: now,
    updated_at: now,
  } as any);

  return NextResponse.json({
    total_rows: rows.length,
    successful_rows: successCount,
    failed_rows: errors.length,
    errors: errors.slice(0, 50), // Return first 50 errors
    error_report_url: errorReportUrl,
  });
}

/**
 * GET  /api/gmc/[customerId]/members  — list GMC members
 * POST /api/gmc/[customerId]/members  — add member manually
 */

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";

// Cast to any to support Phase 3 tables not yet in database.types.ts
const db = supabaseAdmin as any;

type Params = { params: Promise<{ customerId: string }> };

export async function GET(req: NextRequest, { params }: Params) {
  const caller = await requireAuth(req, ["admin", "manager", "employee"]);
  if (isAuthError(caller)) return authError(caller);

  const { customerId } = await params;
  const { searchParams } = new URL(req.url);
  const search = searchParams.get("search") ?? "";
  const status = searchParams.get("status") ?? "";
  const department = searchParams.get("department") ?? "";
  const page = Math.max(1, parseInt(searchParams.get("page") ?? "1"));
  const limit = Math.min(100, parseInt(searchParams.get("limit") ?? "50"));

  let query = db
    .from("gmc_members")
    .select("*", { count: "exact" })
    .eq("customer_id", customerId);

  if (status) query = query.eq("status", status);
  if (department) query = query.eq("department", department);
  if (search) {
    query = query.or(`name.ilike.%${search}%,employee_id.ilike.%${search}%,mobile.ilike.%${search}%`);
  }

  query = query
    .order("created_at", { ascending: false })
    .range((page - 1) * limit, page * limit - 1);

  const { data, count, error } = await query;
  if (error) return NextResponse.json({ error: error.message }, { status: 500 });

  return NextResponse.json({ data: data ?? [], total: count ?? 0, page, limit });
}

export async function POST(req: NextRequest, { params }: Params) {
  const caller = await requireAuth(req, ["admin", "manager"]);
  if (isAuthError(caller)) return authError(caller);

  const { customerId } = await params;

  let body: Record<string, unknown>;
  try { body = await req.json(); } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const { employee_id, name, member_type = "employee", policy_id, parent_member_id } = body as any;

  if (!employee_id || !name || !policy_id) {
    return NextResponse.json({ error: "employee_id, name, and policy_id are required" }, { status: 400 });
  }

  // Uniqueness check: employee_id within customer
  const { data: existing } = await db
    .from("gmc_members")
    .select("id")
    .eq("customer_id", customerId)
    .eq("employee_id", employee_id)
    .neq("status", "Deleted")
    .limit(1);

  if (existing && existing.length > 0) {
    return NextResponse.json({ error: `Employee ID ${employee_id} already exists for this customer` }, { status: 409 });
  }

  // Dependent linkage check
  if (member_type === "dependent") {
    if (!parent_member_id) {
      return NextResponse.json({ error: "parent_member_id is required for dependents" }, { status: 400 });
    }
    const { data: parent } = await db
      .from("gmc_members")
      .select("id, status")
      .eq("id", parent_member_id)
      .single();

    if (!parent || parent.status !== "Active") {
      return NextResponse.json({ error: "Parent employee must be active" }, { status: 400 });
    }
  }

  const now = new Date().toISOString();
  const { data: member, error: insertErr } = await db
    .from("gmc_members")
    .insert({
      customer_id: customerId,
      policy_id,
      employee_id,
      name,
      member_type,
      parent_member_id: parent_member_id || null,
      dob: (body.dob as string) || null,
      gender: (body.gender as string) || null,
      mobile: (body.mobile as string) || null,
      email: (body.email as string) || null,
      department: (body.department as string) || null,
      designation: (body.designation as string) || null,
      address: (body.address as string) || null,
      status: "Active",
      created_by: caller.uid,
      created_at: now,
      updated_at: now,
    })
    .select()
    .single();

  if (insertErr) return NextResponse.json({ error: insertErr.message }, { status: 500 });

  // Create endorsement record for addition
  const endCounter = await getNextEndorsementNumber("GMC");
  await db.from("gmc_member_endorsements").insert({
    endorsement_number: endCounter,
    policy_id,
    customer_id: customerId,
    member_id: member.id,
    endorsement_type: "Addition",
    endorsement_date: now.split("T")[0],
    member_details: { employee_id, name, member_type },
    created_by: caller.uid,
    created_at: now,
  });

  // Audit log
  try {
    await supabaseAdmin.from("audit_logs").insert({
      action: "create", module: "gmc_members",
      details: `Added GMC member: ${name} (${employee_id})`,
      user_id: caller.uid, user_name: caller.name ?? caller.email,
      user_role: caller.role, created_at: now,
    } as any);
  } catch { /* non-critical */ }

  return NextResponse.json(member, { status: 201 });
}

async function getNextEndorsementNumber(type: "GMC" | "FLT"): Promise<string> {
  const key = `endorsement_counter_${type}`;
  const { data } = await supabaseAdmin.from("system_config").select("value").eq("key", key).maybeSingle();
  const current = typeof data?.value === "number" ? data.value : 0;
  const next = current + 1;
  await supabaseAdmin.from("system_config").upsert({ key, value: next, category: "counters" }, { onConflict: "key" });
  return `END-${type}-${String(next).padStart(5, "0")}`;
}

import { NextRequest, NextResponse } from "next/server";
import { createServiceClient } from "@/lib/supabase/server";

