  const { data } = await supabaseAdmin
    .from("sales_leads")
    .select("assigned_to")
    .eq("id", leadId)
    .maybeSingle();
  if (!data) return NextResponse.json({ error: "Lead not found" }, { status: 404 });
  if (data.assigned_to !== caller.uid) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }
  return null;
}

