/**
 * PUT /api/renewals/[id]/stage
 * Update renewal stage with validation (no backward from renewed/lost).
 * Records stage history and audit log.
 */

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";

const STAGE_ORDER = ["due", "contacted", "negotiating", "renewed", "lost"] as const;
type Stage = (typeof STAGE_ORDER)[number];

const TERMINAL_STAGES: Stage[] = ["renewed", "lost"];

function isValidTransition(from: Stage, to: Stage): boolean {
  // Cannot go backward from terminal stages
  if (TERMINAL_STAGES.includes(from)) return false;
  // Cannot go backward in general (except to lost from any non-terminal)
  if (to === "lost") return true;
  const fromIdx = STAGE_ORDER.indexOf(from);
  const toIdx = STAGE_ORDER.indexOf(to);
  return toIdx > fromIdx;
}

export async function PUT(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const caller = await requireAuth(req, ["admin", "manager", "employee"]);
  if (isAuthError(caller)) return authError(caller);

  const { id } = await params;
  const db = supabaseAdmin as any;

  let body: any;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }

  const { stage, notes, lost_reason } = body;

  if (!stage || !STAGE_ORDER.includes(stage)) {
    return NextResponse.json({ error: "Invalid stage value" }, { status: 400 });
  }

  if (stage === "lost" && !lost_reason) {
    return NextResponse.json({ error: "lost_reason is required when stage is lost" }, { status: 400 });
  }

  // Fetch current renewal
  const { data: renewal, error: fetchError } = await db
    .from("renewal_pipeline")
    .select("*")
    .eq("id", id)
    .single();

  if (fetchError || !renewal) {
    return NextResponse.json({ error: "Renewal not found" }, { status: 404 });
  }

  const currentStage = renewal.stage as Stage;

  if (!isValidTransition(currentStage, stage as Stage)) {
    return NextResponse.json(
      {
        error: `Cannot transition from '${currentStage}' to '${stage}'. Stage cannot go backward from terminal stages.`,
      },
      { status: 422 }
    );
  }

  const now = new Date().toISOString();

  // Update renewal stage
  const updatePayload: any = {
    stage,
    stage_updated_at: now,
    updated_at: now,
  };

  if (stage === "lost" && lost_reason) {
    updatePayload.lost_reason = lost_reason;
  }

  if (stage === "contacted" || stage === "negotiating") {
    updatePayload.last_contact_date = now;
  }

  const { data: updated, error: updateError } = await db
    .from("renewal_pipeline")
    .update(updatePayload)
    .eq("id", id)
    .select()
    .single();

  if (updateError) {
    return NextResponse.json({ error: updateError.message }, { status: 500 });
  }

  // Insert stage history
  await db.from("renewal_stage_history").insert({
    renewal_id: id,
    from_stage: currentStage,
    to_stage: stage,
    changed_by: caller.uid,
    changed_by_name: caller.name ?? caller.email,
    notes: notes ?? null,
    created_at: now,
  });

  // Audit log
  try {
    await supabaseAdmin.from("audit_logs").insert({
      action: "update",
      module: "renewals",
      details: `Stage updated from '${currentStage}' to '${stage}' for renewal ${id}${lost_reason ? ` — reason: ${lost_reason}` : ""}`,
      user_id: caller.uid,
      user_name: caller.name ?? caller.email,
      user_role: caller.role,
      metadata: { renewal_id: id, from_stage: currentStage, to_stage: stage },
      created_at: now,
    } as any);
  } catch { /* non-critical */ }

  return NextResponse.json(updated);
}

/**
 * GET /api/renewals/analytics
 * Returns analytics: stage counts, conversion rate, premium at risk.
 */

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";

export async function GET(req: NextRequest) {
  const caller = await requireAuth(req, ["admin", "manager", "employee"]);
  if (isAuthError(caller)) return authError(caller);

  const db = supabaseAdmin as any;

  const { data: pipeline, error } = await db
    .from("renewal_pipeline")
    .select(
      `
      stage,
      policies!renewal_pipeline_policy_id_fkey(premium_amount, policy_type, insurer_name, assigned_to_name)
    `
    );

  if (error) return NextResponse.json({ error: error.message }, { status: 500 });

  const entries = pipeline ?? [];

  // Stage counts
  const stageCounts: Record<string, number> = {
    due: 0,
    contacted: 0,
    negotiating: 0,
    renewed: 0,
    lost: 0,
  };

  let premiumAtRisk = 0;
  let premiumRenewed = 0;

  for (const entry of entries) {
    const stage = entry.stage as string;
    stageCounts[stage] = (stageCounts[stage] ?? 0) + 1;

    const premium = entry.policies?.premium_amount ?? 0;
    if (stage !== "renewed" && stage !== "lost") {
      premiumAtRisk += premium;
    }
    if (stage === "renewed") {
      premiumRenewed += premium;
    }
  }

  const total = entries.length;
  const renewed = stageCounts.renewed ?? 0;
  const lost = stageCounts.lost ?? 0;
  const closed = renewed + lost;
  const conversionRate = closed > 0 ? Math.round((renewed / closed) * 100) : 0;

  // Breakdown by policy type
  const byPolicyType: Record<string, number> = {};
  const byInsurer: Record<string, number> = {};
  const byRM: Record<string, number> = {};

  for (const entry of entries) {
    const pt = entry.policies?.policy_type ?? "other";
    byPolicyType[pt] = (byPolicyType[pt] ?? 0) + 1;

    const ins = entry.policies?.insurer_name ?? "Unknown";
    byInsurer[ins] = (byInsurer[ins] ?? 0) + 1;

    const rm = entry.policies?.assigned_to_name ?? "Unassigned";
    byRM[rm] = (byRM[rm] ?? 0) + 1;
  }

  return NextResponse.json({
    stageCounts,
    total,
    conversionRate,
    premiumAtRisk,
    premiumRenewed,
    byPolicyType,
    byInsurer,
    byRM,
  });
}

/**
 * POST /api/renewals/bulk
 * Bulk operations: assign RM, stage update, export CSV.
 */

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";

export async function POST(req: NextRequest) {
  const caller = await requireAuth(req, ["admin", "manager"]);
  if (isAuthError(caller)) return authError(caller);

  const db = supabaseAdmin as any;

  let body: any;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }

  const { action, ids, rm_id, stage, lost_reason } = body;

  if (!action || !ids || !Array.isArray(ids) || ids.length === 0) {
    return NextResponse.json({ error: "action and ids[] are required" }, { status: 400 });
  }

  const now = new Date().toISOString();
  const results = { success: 0, failed: 0, errors: [] as string[] };

  if (action === "assign_rm") {
    if (!rm_id) return NextResponse.json({ error: "rm_id is required" }, { status: 400 });

    const { error } = await db
      .from("renewal_pipeline")
      .update({ assigned_rm: rm_id, updated_at: now })
      .in("id", ids);

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    results.success = ids.length;

    // Audit log
    try {
      await supabaseAdmin.from("audit_logs").insert({
        action: "update",
        module: "renewals",
        details: `Bulk assigned RM ${rm_id} to ${ids.length} renewals`,
        user_id: caller.uid,
        user_name: caller.name ?? caller.email,
        user_role: caller.role,
        metadata: { ids, rm_id },
        created_at: now,
      } as any);
    } catch { /* non-critical */ }
  } else if (action === "update_stage") {
    if (!stage) return NextResponse.json({ error: "stage is required" }, { status: 400 });
    if (stage === "lost" && !lost_reason) {
      return NextResponse.json({ error: "lost_reason required for lost stage" }, { status: 400 });
    }

    const TERMINAL_STAGES = ["renewed", "lost"];
    const updatePayload: any = { stage, stage_updated_at: now, updated_at: now };
    if (stage === "lost" && lost_reason) updatePayload.lost_reason = lost_reason;

    // Fetch current stages to validate transitions
    const { data: current } = await db
      .from("renewal_pipeline")
      .select("id, stage")
      .in("id", ids);

    for (const renewal of current ?? []) {
      if (TERMINAL_STAGES.includes(renewal.stage)) {
        results.failed++;
        results.errors.push(`Renewal ${renewal.id} is in terminal stage '${renewal.stage}'`);
        continue;
      }

      const { error } = await db
        .from("renewal_pipeline")
        .update(updatePayload)
        .eq("id", renewal.id);

      if (error) {
        results.failed++;
        results.errors.push(`Failed to update ${renewal.id}: ${error.message}`);
      } else {
        results.success++;
        // Stage history
        await db.from("renewal_stage_history").insert({
          renewal_id: renewal.id,
          from_stage: renewal.stage,
          to_stage: stage,
          changed_by: caller.uid,
          changed_by_name: caller.name ?? caller.email,
          notes: "Bulk stage update",
          created_at: now,
        });
      }
    }
  } else if (action === "export_csv") {
    const { data: renewals } = await db
      .from("renewal_pipeline")
      .select(
        `
        stage, risk_score, last_contact_date, entered_pipeline_at,
        policies!renewal_pipeline_policy_id_fkey(policy_number, policy_type, end_date, premium_amount, insurer_name),
        customers!renewal_pipeline_customer_id_fkey(name, phone, email)
      `
      )
      .in("id", ids);

    const rows = [
      ["Customer", "Phone", "Policy #", "Type", "Insurer", "Expiry", "Premium", "Stage", "Risk Score", "Last Contact"],
      ...(renewals ?? []).map((r: any) => [
        r.customers?.name ?? "",
        r.customers?.phone ?? "",
        r.policies?.policy_number ?? "",
        r.policies?.policy_type ?? "",
        r.policies?.insurer_name ?? "",
        r.policies?.end_date ?? "",
        r.policies?.premium_amount ?? "",
        r.stage,
        r.risk_score,
        r.last_contact_date ?? "",
      ]),
    ];

    const csv = rows.map((row) => row.map((v: any) => `"${v}"`).join(",")).join("\n");

    return new NextResponse(csv, {
      headers: {
        "Content-Type": "text/csv",
        "Content-Disposition": `attachment; filename="renewals-export-${Date.now()}.csv"`,
      },
    });
  } else {
    return NextResponse.json({ error: "Invalid action" }, { status: 400 });
  }

  return NextResponse.json(results);
}

