/**
 * POST /api/service-desk/tickets/[id]/documents — Upload document attachment
 */

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";
import { protect } from "@/lib/api/protect";

const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10 MB
const ALLOWED_TYPES = [
  "application/pdf",
  "image/jpeg",
  "image/jpg",
  "image/png",
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  "application/msword",
  "application/vnd.ms-excel",
];

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const blocked = protect(req, { maxRequests: 20, windowMs: 60_000 });
  if (blocked) return blocked;

  const caller = await requireAuth(req, ["admin", "manager", "employee"]);
  if (isAuthError(caller)) return authError(caller);

  const { id } = await params;

  // Verify ticket exists
  const { data: ticket } = await supabaseAdmin
    .from("service_tickets")
    .select("id, ticket_number")
    .eq("id", id)
    .maybeSingle();

  if (!ticket) {
    return NextResponse.json({ error: "Ticket not found" }, { status: 404 });
  }

  let formData: FormData;
  try {
    formData = await req.formData();
  } catch {
    return NextResponse.json({ error: "Invalid form data" }, { status: 400 });
  }

  const file = formData.get("file") as File | null;
  if (!file) {
    return NextResponse.json({ error: "No file provided" }, { status: 400 });
  }

  // Validate file size
  if (file.size > MAX_FILE_SIZE) {
    return NextResponse.json({ error: "File size exceeds 10 MB limit" }, { status: 400 });
  }

  // Validate file type
  if (!ALLOWED_TYPES.includes(file.type)) {
    return NextResponse.json(
      { error: "File type not allowed. Supported: PDF, JPG, PNG, DOCX, XLSX" },
      { status: 400 }
    );
  }

  // Upload to Supabase Storage
  const fileExt = file.name.split(".").pop() ?? "bin";
  const filePath = `service-desk/${id}/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g, "_")}`;

  const arrayBuffer = await file.arrayBuffer();
  const buffer = new Uint8Array(arrayBuffer);

  const { error: uploadError } = await supabaseAdmin.storage
    .from("documents")
    .upload(filePath, buffer, {
      contentType: file.type,
      upsert: false,
    });

  if (uploadError) {
    console.error("[documents/POST] Upload failed:", uploadError);
    return NextResponse.json({ error: "File upload failed" }, { status: 500 });
  }

  // Get public URL
  const { data: urlData } = supabaseAdmin.storage
    .from("documents")
    .getPublicUrl(filePath);

  const now = new Date().toISOString();

  // Save document record
  const { data: doc, error: dbError } = await supabaseAdmin
    .from("ticket_documents")
    .insert({
      ticket_id: id,
      file_name: file.name,
      file_path: filePath,
      file_url: urlData.publicUrl,
      file_size: file.size,
      uploaded_by: caller.uid,
      uploaded_by_name: caller.name ?? caller.email,
      created_at: now,
    })
    .select("*")
    .single();

  if (dbError) {
    // Cleanup uploaded file
    await supabaseAdmin.storage.from("documents").remove([filePath]);
    return NextResponse.json({ error: dbError.message }, { status: 500 });
  }

  // Activity log
  await supabaseAdmin.from("ticket_activity_log").insert({
    ticket_id: id,
    entry_type: "document_uploaded",
    description: `Document "${file.name}" uploaded by ${caller.name ?? caller.email}`,
    performed_by: caller.uid,
    performed_by_name: caller.name ?? caller.email,
    created_at: now,
  });

  return NextResponse.json(doc, { status: 201 });
}

/**
 * POST /api/service-desk/tickets/[id]/escalate — manual escalation
 */

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError, authError } from "@/lib/api/auth-middleware";
import { supabaseAdmin } from "@/lib/supabase/server";

type Params = { params: Promise<{ id: string }> };

export async function POST(req: NextRequest, { params }: Params) {
  const caller = await requireAuth(req, ["admin", "manager", "employee"]);
  if (isAuthError(caller)) return authError(caller);

  const { id } = await params;

  let body: Record<string, unknown>;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const { reason } = body as any;
  if (!reason?.trim()) {
    return NextResponse.json({ error: "Escalation reason is required" }, { status: 400 });
  }

  const { data: ticket, error: fetchErr } = await supabaseAdmin
    .from("service_tickets")
    .select("*")
    .eq("id", id)
    .single();

  if (fetchErr || !ticket) {
    return NextResponse.json({ error: "Ticket not found" }, { status: 404 });
  }

  if (ticket.status === "resolved" || ticket.status === "closed") {
    return NextResponse.json({ error: "Cannot escalate a resolved or closed ticket" }, { status: 422 });
  }

  // Employees can escalate to level 1; managers can escalate to level 2
  const currentLevel = ticket.escalation_level || 0;
  let newLevel = currentLevel + 1;

  if (caller.role === "employee" && newLevel > 1) newLevel = 1;
  if (newLevel > 2) {
    return NextResponse.json({ error: "Ticket is already at maximum escalation level" }, { status: 422 });
  }

  const now = new Date().toISOString();

  const { data: updated, error: updateErr } = await supabaseAdmin
    .from("service_tickets")
    .update({
      escalation_level: newLevel,
      escalated_at: now,
      escalation_reason: String(reason).trim(),
      updated_at: now,
    })
    .eq("id", id)
    .select()
    .single();

  if (updateErr) return NextResponse.json({ error: updateErr.message }, { status: 500 });

  // Activity log
  await supabaseAdmin.from("ticket_activity_log").insert({
    ticket_id: id,
    entry_type: "escalated",
    description: `Ticket escalated to Level ${newLevel}. Reason: ${reason}`,
    old_value: String(currentLevel),
    new_value: String(newLevel),
    performed_by: caller.uid,
    performed_by_name: caller.name ?? caller.email,
    created_at: now,
  } as any);

  // Notify managers (level 1) or admins (level 2)
  const notifyRole = newLevel === 1 ? "manager" : "admin";
  const { data: notifyUsers } = await supabaseAdmin
    .from("users")
    .select("id")
    .eq("role", notifyRole)
    .eq("status", "active");

  for (const u of notifyUsers ?? []) {
    await supabaseAdmin.from("notifications").insert({
      user_id: u.id,
      title: `Ticket Escalated to Level ${newLevel}`,
      message: `Ticket ${ticket.ticket_number} has been escalated. Reason: ${reason}`,
      type: "system",
      link: `/dashboard/service-desk/${id}`,
      read: false,
      created_at: now,
      updated_at: now,
    } as any);
  }

  return NextResponse.json(updated);
}

/**
