                <motion.div {...hoverLift}>
                  <Button className="bg-primary text-primary-foreground hover:bg-primary/90">
                    <Plus className="h-4 w-4 mr-2" />
                    New Campaign
                  </Button>
                </motion.div>
              </DialogTrigger>
              <CampaignDialog
                onClose={() => setAddOpen(false)}
                userId={dbUser?.id || ""}
                userName={dbUser?.name || ""}
              />
            </Dialog>
          </div>
        </div>
