            { icon: Hash, label: "Total Campaigns", value: stats.total, panel: "border-blue-500/30 bg-blue-500/10", text: "text-blue-700 dark:text-blue-300" },
            { icon: DollarSign, label: "Total Budget", value: formatCurrency(stats.totalBudget), panel: "border-indigo-500/30 bg-indigo-500/10", text: "text-indigo-700 dark:text-indigo-300" },
            { icon: TrendingUp, label: "Premium Generated", value: formatCurrency(stats.totalPremiumGenerated), panel: "border-emerald-500/30 bg-emerald-500/10", text: "text-emerald-700 dark:text-emerald-300" },
            { icon: Percent, label: "Overall ROI", value: `${stats.overallROI}%`, panel: "border-amber-500/30 bg-amber-500/10", text: "text-amber-700 dark:text-amber-300" },
          ].map((item) => (
            <motion.div key={item.label} variants={staggerItem} {...hoverLift}>
              <Card className={item.panel}>
                <CardContent className="px-4 py-3">
                  <div className="flex items-start justify-between gap-2">
                    <div>
                      <p className="text-[10px] font-bold uppercase tracking-[0.16em] text-muted-foreground">
                        {item.label}
                      </p>
                      <p className={`mt-1 text-xl font-semibold tracking-tight ${item.text}`}>{item.value}</p>
                    </div>
                    <div className="rounded-lg border border-border/70 bg-card px-2 py-1 shadow-inner">
                      <item.icon className={`h-4 w-4 ${item.text}`} />
                    </div>
                  </div>
                </CardContent>
              </Card>
            </motion.div>
          ))}
        </motion.div>
      )}

      {/* Filters */}
      <section className="rounded-2xl border border-border-strong/70 bg-card/90 p-3 shadow-[0_10px_24px_rgba(47,62,64,0.06)]">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              placeholder="Search campaigns..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-9 border-border/80 bg-background/80"
            />
          </div>
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <SelectTrigger className="w-full sm:w-37.5 border-border/80 bg-background/80 text-foreground">
              <SelectValue placeholder="Status" />
            </SelectTrigger>
            <SelectContent className="border-border bg-popover">
              <SelectItem value="all">All Status</SelectItem>
              {CAMPAIGN_STATUSES.map((s) => (
                <SelectItem key={s.value} value={s.value}>
                  {s.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Select value={channelFilter} onValueChange={setChannelFilter}>
            <SelectTrigger className="w-full sm:w-42.5 border-border/80 bg-background/80 text-foreground">
              <SelectValue placeholder="Channel" />
            </SelectTrigger>
            <SelectContent className="border-border bg-popover">
              <SelectItem value="all">All Channels</SelectItem>
              {CAMPAIGN_CHANNELS.map((c) => (
                <SelectItem key={c.value} value={c.value}>
                  {c.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </section>

      {/* Data Table */}
      {isLoading ? (
        <div className="rounded-2xl border border-border-strong/70 bg-card/90 p-6">
          <div className="flex items-center justify-center py-6">
            <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
          </div>
        </div>
      ) : filtered.length === 0 ? (
        <div className="rounded-2xl border border-dashed border-border-strong/70 bg-card/80 text-center py-12">
          <Megaphone className="h-12 w-12 mx-auto text-muted-foreground mb-3" />
          <p className="text-muted-foreground">No campaigns found</p>
        </div>
      ) : (
        <Card className="overflow-hidden rounded-2xl border border-border-strong/70 bg-card/95 shadow-[0_12px_28px_rgba(47,62,64,0.06)]">
          <CardContent className="p-0">
            <Table>
              <TableHeader>
                <TableRow className="border-border/80 bg-muted/20">
                  <TableHead className="font-heading text-[11px] uppercase tracking-[0.14em] text-muted-foreground">Name</TableHead>
                  <TableHead className="font-heading text-[11px] uppercase tracking-[0.14em] text-muted-foreground">Channel</TableHead>
                  <TableHead className="font-heading text-[11px] uppercase tracking-[0.14em] text-muted-foreground">Status</TableHead>
                  <TableHead className="text-right font-heading text-[11px] uppercase tracking-[0.14em] text-muted-foreground">Budget</TableHead>
                  <TableHead className="text-right font-heading text-[11px] uppercase tracking-[0.14em] text-muted-foreground">Linked Policies</TableHead>
                  <TableHead className="text-right font-heading text-[11px] uppercase tracking-[0.14em] text-muted-foreground">ROI</TableHead>
                  <TableHead className="text-right font-heading text-[11px] uppercase tracking-[0.14em] text-muted-foreground">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filtered.map((c) => {
                  const statusConfig = getCampaignStatusConfig(c.status || "draft");
                  return (
                    <TableRow key={c.id} className="border-border/70 hover:bg-muted/35">
                      <TableCell className="font-medium">{c.name}</TableCell>
                      <TableCell>
                        <Badge variant="outline" className="text-xs capitalize">
                          {channelLabel(c.channel)}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        {(() => {
                          const bg = statusConfig?.color ?? "#6b7280";
                          return (
                            <Badge
                              className="text-xs capitalize"
                              style={{ backgroundColor: bg, color: "#fff" }}
                            >
                              {statusConfig?.label ?? c.status}
                            </Badge>
                          );
                        })()}
                      </TableCell>
                      <TableCell className="text-right">
                        {formatCurrency(c.budget || 0)}
                      </TableCell>
                      <TableCell className="text-right">
                        {c.linked_policies_count || 0}
                      </TableCell>
                      <TableCell className="text-right">
                        {c.roi !== undefined ? `${c.roi}%` : "—"}
                      </TableCell>
                      <TableCell className="text-right">
                        <div className="flex items-center justify-end gap-1">
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => setEditCampaign(c)}
                            className="h-8 w-8 hover:bg-muted"
                          >
                            <Pencil className="h-4 w-4" />
                          </Button>
                          {dbUser?.role === "admin" && (
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => setDeleteTarget(c.id)}
                              disabled={deleting === c.id}
                              className="h-8 w-8 text-red-500 hover:text-red-400 hover:bg-red-500/10"
                            >
                              {deleting === c.id ? (
                                <Loader2 className="h-4 w-4 animate-spin" />
                              ) : (
                                <Trash2 className="h-4 w-4" />
                              )}
                            </Button>
                          )}
                        </div>
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      )}

      {/* Edit Dialog */}
      {editCampaign && (
        <Dialog open={!!editCampaign} onOpenChange={() => setEditCampaign(null)}>
          <CampaignDialog
            campaign={editCampaign}
            onClose={() => setEditCampaign(null)}
            userId={dbUser?.id || ""}
            userName={dbUser?.name || ""}
          />
        </Dialog>
      )}

      {/* Delete Confirmation Dialog */}
      <AlertDialog open={!!deleteTarget} onOpenChange={(open) => !open && setDeleteTarget(null)}>
        <AlertDialogContent className="border-border bg-card">
          <AlertDialogHeader>
            <AlertDialogTitle className="text-foreground">Delete Campaign</AlertDialogTitle>
            <AlertDialogDescription className="text-muted-foreground">
              Are you sure you want to delete this campaign? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="border-border text-foreground">Cancel</AlertDialogCancel>
            <AlertDialogAction
              className="bg-red-600 text-white hover:bg-red-700"
              onClick={() => {
                if (deleteTarget) handleDelete(deleteTarget);
                setDeleteTarget(null);
              }}
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </motion.div>
  );
}

// ---- Campaign Dialog (Create / Edit) ----

function CampaignDialog({
  campaign,
  onClose,
  userId,
  userName,
}: {
  campaign?: Campaign;
  onClose: () => void;
  userId: string;
  userName: string;
}) {
  const {
    register,
    handleSubmit,
    setValue,
    watch,
    formState: { errors, isSubmitting },
  } = useForm<CreateCampaignFormData>({
    resolver: zodResolver(createCampaignSchema),
    defaultValues: campaign
      ? {
          name: campaign.name,
          channel: campaign.channel,
          budget: campaign.budget,
          status: campaign.status || "draft",
          start_date: campaign.start_date
            ? new Date(typeof campaign.start_date === "object" && campaign.start_date !== null && "toDate" in campaign.start_date ? (campaign.start_date as any).toDate() : campaign.start_date).toISOString().split("T")[0]
            : "",
          end_date: campaign.end_date
            ? new Date(typeof campaign.end_date === "object" && campaign.end_date !== null && "toDate" in campaign.end_date ? (campaign.end_date as any).toDate() : campaign.end_date).toISOString().split("T")[0]
            : "",
        }
      : { status: "draft", budget: 0 },
  });

  const onSubmit = async (data: CreateCampaignFormData) => {
    try {
      const payload: Record<string, unknown> = {
        name: data.name,
        channel: data.channel,
        budget: data.budget,
        status: data.status,
        created_by: userId,
      };
      if (data.start_date) {
        payload.start_date = new Date(data.start_date).toISOString();
      }
      if (data.end_date) {
        payload.end_date = new Date(data.end_date).toISOString();
      }

      if (campaign) {
        await campaignService.update(campaign.id, payload as Partial<Campaign>);
        toast.success("Campaign updated");
      } else {
        await campaignService.create(payload as Omit<Campaign, "id" | "createdAt" | "updatedAt">);
        toast.success("Campaign created");
      }
      invalidateCampaigns();
      // Audit log: campaign create/update
      auditLogService.logAction(
        userId, userName, campaign ? "update" : "create", "campaigns",
        `${campaign ? "Updated" : "Created"} campaign: ${data.name}`
      ).catch(() => {});
      onClose();
    } catch {
      toast.error("Failed to save campaign");
    }
  };

  return (
    <DialogContent className="max-w-lg border-border bg-card text-foreground rounded-3xl">
      <DialogHeader>
        <DialogTitle className="text-foreground">
          {campaign ? "Edit Campaign" : "New Campaign"}
        </DialogTitle>
      </DialogHeader>
      <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
        <div className="space-y-2">
          <Label className="text-muted-foreground">Campaign Name</Label>
          <Input
            {...register("name")}
            className="bg-background border-border text-foreground"
            placeholder="e.g. Summer Health Insurance Drive"
          />
          {errors.name && (
            <p className="text-red-400 text-xs">{errors.name.message}</p>
          )}
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label className="text-muted-foreground">Channel</Label>
            <Select
              value={watch("channel") || ""}
              onValueChange={(v) => setValue("channel", v)}
            >
              <SelectTrigger className="bg-background border-border text-foreground">
                <SelectValue placeholder="Select channel" />
              </SelectTrigger>
              <SelectContent className="border-border bg-popover">
                {CAMPAIGN_CHANNELS.map((c) => (
                  <SelectItem key={c.value} value={c.value}>
                    {c.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            {errors.channel && (
              <p className="text-red-400 text-xs">{errors.channel.message}</p>
            )}
          </div>

          <div className="space-y-2">
            <Label className="text-muted-foreground">Status</Label>
            <Select
              value={watch("status") || "draft"}
              onValueChange={(v) =>
                setValue("status", v as "draft" | "active" | "completed")
              }
            >
              <SelectTrigger className="bg-background border-border text-foreground">
                <SelectValue />
              </SelectTrigger>
              <SelectContent className="border-border bg-popover">
                {CAMPAIGN_STATUSES.map((s) => (
                  <SelectItem key={s.value} value={s.value}>
                    {s.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>

        <div className="space-y-2">
          <Label className="text-muted-foreground">Budget (₹)</Label>
          <Input
            type="number"
            {...register("budget", { valueAsNumber: true })}
            className="bg-background border-border text-foreground"
            placeholder="0"
          />
          {errors.budget && (
            <p className="text-red-400 text-xs">{errors.budget.message}</p>
          )}
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label className="text-muted-foreground">Start Date</Label>
            <Input
              type="date"
              {...register("start_date")}
              className="bg-background border-border text-foreground"
            />
          </div>
          <div className="space-y-2">
            <Label className="text-muted-foreground">End Date</Label>
            <Input
              type="date"
              {...register("end_date")}
              className="bg-background border-border text-foreground"
            />
          </div>
        </div>

        <DialogFooter>
          <Button
            type="button"
            variant="ghost"
            onClick={onClose}
            className="text-muted-foreground"
          >
            Cancel
          </Button>
          <Button
            type="submit"
            disabled={isSubmitting}
            className="bg-primary text-primary-foreground hover:bg-primary/90"
          >
            {isSubmitting && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
            {campaign ? "Update" : "Create"}
          </Button>
        </DialogFooter>
      </form>
    </DialogContent>
  );
}

"use client";

import { useState } from "react";
import { motion } from "framer-motion";
import useSWR from "swr";
import { toast } from "sonner";
import { Percent, Plus, Pencil, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle,
} from "@/components/ui/dialog";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { pageTransition } from "@/lib/helpers/animations";
import { useAuth } from "@/lib/context/auth-context";

const POLICY_TYPES = [
  "motor", "health", "life", "fire", "marine", "burglary",
  "liability", "workmen_compensation", "travel", "other",
];

async function fetcher(url: string, token: string) {
  const res = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
  if (!res.ok) throw new Error("Failed to fetch");
  return res.json();
}

export default function CommissionRatesPage() {
  const { session, role } = useAuth();
  const token = session?.access_token ?? "";
  const isAdmin = role === "admin";

  const [dialogOpen, setDialogOpen] = useState(false);
  const [editRate, setEditRate] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  // Form state
  const [insurerName, setInsurerName] = useState("");
  const [policyType, setPolicyType] = useState("");
  const [rateType, setRateType] = useState("percentage");
  const [rateValue, setRateValue] = useState("");
  const [effectiveFrom, setEffectiveFrom] = useState(new Date().toISOString().split("T")[0]);

  const { data: rates, isLoading, mutate } = useSWR(
    token ? [`/api/commission-rates`, token] : null,
    ([url, t]) => fetcher(url, t),
    { revalidateOnFocus: false }
  );

  const openCreate = () => {
    setEditRate(null);
    setInsurerName("");
    setPolicyType("");
    setRateType("percentage");
    setRateValue("");
    setEffectiveFrom(new Date().toISOString().split("T")[0]);
    setDialogOpen(true);
  };

  const openEdit = (rate: any) => {
    setEditRate(rate);
    setInsurerName(rate.insurer_name);
    setPolicyType(rate.policy_type);
    setRateType(rate.rate_type);
    setRateValue(String(rate.rate_value));
    setEffectiveFrom(rate.effective_from);
    setDialogOpen(true);
  };

  const handleSave = async () => {
    if (!insurerName || !policyType || !rateValue) {
      toast.error("All fields are required");
      return;
    }

    setLoading(true);
    try {
      const token = session?.access_token;
      if (!token) throw new Error("Not authenticated");

      const payload = {
        insurer_name: insurerName,
        policy_type: policyType,
        rate_type: rateType,
        rate_value: parseFloat(rateValue),
        effective_from: effectiveFrom,
      };

      const url = editRate
        ? `/api/commission-rates/${editRate.id}`
        : "/api/commission-rates";
      const method = editRate ? "PUT" : "POST";

      const res = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(payload),
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error ?? "Failed to save");

      toast.success(editRate ? "Rate updated" : "Rate created");
      setDialogOpen(false);
      mutate();
    } catch (err: any) {
      toast.error(err.message ?? "Failed to save");
    } finally {
      setLoading(false);
    }
  };

  return (
    <motion.div {...pageTransition} className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-heading font-bold text-foreground uppercase tracking-wider flex items-center gap-2">
            <Percent className="w-6 h-6 text-primary" />
            Commission Rates
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            Configure commission rates by insurer and policy type
          </p>
        </div>
        {isAdmin && (
          <Button size="sm" onClick={openCreate} className="gap-2">
            <Plus className="w-4 h-4" /> Add Rate
          </Button>
        )}
      </div>

      {/* Table */}
      <div className="bg-card border border-border rounded-xl overflow-hidden">
        {isLoading ? (
          <div className="p-6 space-y-3">
            {[...Array(5)].map((_, i) => <Skeleton key={i} className="h-12 w-full" />)}
          </div>
        ) : (rates ?? []).length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 gap-4">
            <Percent className="w-12 h-12 text-muted-foreground/40" />
            <p className="text-muted-foreground">No commission rates configured.</p>
            {isAdmin && (
              <Button onClick={openCreate} className="gap-2">
                <Plus className="w-4 h-4" /> Add First Rate
              </Button>
            )}
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow className="border-border hover:bg-transparent">
                <TableHead className="text-xs uppercase tracking-wider font-heading">Insurer</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Policy Type</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Rate Type</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Rate Value</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden md:table-cell">Effective From</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Status</TableHead>
                {isAdmin && (
                  <TableHead className="text-xs uppercase tracking-wider font-heading text-right">Actions</TableHead>
                )}
              </TableRow>
            </TableHeader>
            <TableBody>
              {(rates ?? []).map((rate: any) => (
                <TableRow key={rate.id} className="border-border hover:bg-muted/30">
                  <TableCell className="font-medium text-sm">{rate.insurer_name}</TableCell>
                  <TableCell className="text-sm capitalize">
                    {rate.policy_type?.replace(/_/g, " ")}
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline" className="text-xs capitalize">
                      {rate.rate_type}
                    </Badge>
                  </TableCell>
                  <TableCell className="font-medium">
                    {rate.rate_value}{rate.rate_type === "percentage" ? "%" : " flat"}
                  </TableCell>
                  <TableCell className="hidden md:table-cell text-xs text-muted-foreground">
                    {rate.effective_from}
                  </TableCell>
                  <TableCell>
                    <Badge
                      variant="outline"
                      className={`text-xs ${
                        rate.is_active
                          ? "bg-green-500/10 text-green-400 border-green-500/20"
                          : "bg-gray-500/10 text-gray-400 border-gray-500/20"
                      }`}
                    >
                      {rate.is_active ? "Active" : "Inactive"}
                    </Badge>
                  </TableCell>
                  {isAdmin && (
                    <TableCell className="text-right">
                      <Button
                        variant="ghost"
                        size="sm"
                        className="h-7 w-7 p-0"
                        onClick={() => openEdit(rate)}
                      >
                        <Pencil className="w-3.5 h-3.5" />
                      </Button>
                    </TableCell>
                  )}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </div>

      {/* Create/Edit Dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="font-heading uppercase tracking-wider">
              {editRate ? "Edit Commission Rate" : "Add Commission Rate"}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div className="space-y-1.5">
              <Label>Insurer Name *</Label>
              <Input
                placeholder="e.g., HDFC Ergo"
                value={insurerName}
                onChange={(e) => setInsurerName(e.target.value)}
              />
            </div>
            <div className="space-y-1.5">
              <Label>Policy Type *</Label>
              <Select value={policyType} onValueChange={setPolicyType}>
                <SelectTrigger>
                  <SelectValue placeholder="Select type" />
                </SelectTrigger>
                <SelectContent>
                  {POLICY_TYPES.map((t) => (
                    <SelectItem key={t} value={t} className="capitalize">
                      {t.replace(/_/g, " ")}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <Label>Rate Type *</Label>
                <Select value={rateType} onValueChange={setRateType}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="percentage">Percentage</SelectItem>
                    <SelectItem value="flat">Flat Amount</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1.5">
                <Label>Rate Value *</Label>
                <Input
                  type="number"
                  step="0.01"
                  placeholder={rateType === "percentage" ? "0–100" : "Amount"}
                  value={rateValue}
                  onChange={(e) => setRateValue(e.target.value)}
                />
              </div>
            </div>
            <div className="space-y-1.5">
              <Label>Effective From</Label>
              <Input
                type="date"
                value={effectiveFrom}
                onChange={(e) => setEffectiveFrom(e.target.value)}
              />
            </div>
            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={() => setDialogOpen(false)}>
                Cancel
              </Button>
              <Button onClick={handleSave} disabled={loading}>
                {loading && <Loader2 className="w-4 h-4 animate-spin mr-2" />}
                {editRate ? "Update" : "Create"}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </motion.div>
  );
}

"use client";

import { use, useState } from "react";
import { useRouter } from "next/navigation";
import useSWR from "swr";
import { motion } from "framer-motion";
import { format } from "date-fns";
import {
  ArrowLeft, Download, CheckCircle2, AlertTriangle, Filter,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { pageTransition } from "@/lib/helpers/animations";
import { useAuth } from "@/lib/context/auth-context";
import { DiscrepancyResolutionDialog } from "@/components/reconciliation/DiscrepancyResolutionDialog";
import { toast } from "sonner";

const STATUS_COLORS: Record<string, string> = {
  pending: "bg-amber-500/10 text-amber-400 border-amber-500/20",
  processing: "bg-blue-500/10 text-blue-400 border-blue-500/20",
  completed: "bg-green-500/10 text-green-400 border-green-500/20",
  failed: "bg-red-500/10 text-red-400 border-red-500/20",
};

const RESOLUTION_COLORS: Record<string, string> = {
  unresolved: "bg-amber-500/10 text-amber-400 border-amber-500/20",
  accept_statement: "bg-green-500/10 text-green-400 border-green-500/20",
  accept_crm: "bg-blue-500/10 text-blue-400 border-blue-500/20",
  escalated: "bg-red-500/10 text-red-400 border-red-500/20",
};

async function fetcher(url: string, token: string) {
  const res = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
  if (!res.ok) throw new Error("Failed to fetch");
  return res.json();
}

export default function ReconciliationRunDetailPage({
  params,
}: {
  params: Promise<{ runId: string }>;
}) {
  const { runId } = use(params);
  const router = useRouter();
  const { session } = useAuth();
  const token = session?.access_token ?? "";

  const [discrepancyTypeFilter, setDiscrepancyTypeFilter] = useState("all");
  const [resolutionFilter, setResolutionFilter] = useState("all");
  const [selectedRecord, setSelectedRecord] = useState<any>(null);
  const [dialogOpen, setDialogOpen] = useState(false);

  const queryParams = new URLSearchParams();
  if (discrepancyTypeFilter !== "all") queryParams.set("discrepancy_type", discrepancyTypeFilter);
  if (resolutionFilter !== "all") queryParams.set("resolution_status", resolutionFilter);

  const { data: run, isLoading, mutate } = useSWR(
    token ? [`/api/reconciliation/${runId}?${queryParams}`, token] : null,
    ([url, t]) => fetcher(url, t),
    { revalidateOnFocus: false }
  );

  const handleDownloadReport = async () => {
    if (!token) return;
    try {
      const res = await fetch(`/api/reconciliation/${runId}/report`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) throw new Error("Download failed");
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `reconciliation-${runId}.xlsx`;
      a.click();
      URL.revokeObjectURL(url);
    } catch {
      toast.error("Download failed");
    }
  };

  if (isLoading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-10 w-48" />
        <Skeleton className="h-32 w-full" />
        <Skeleton className="h-64 w-full" />
      </div>
    );
  }

  if (!run) {
    return (
      <div className="flex flex-col items-center justify-center py-20 gap-4">
        <p className="text-muted-foreground">Run not found.</p>
        <Button variant="outline" onClick={() => router.back()}>
          <ArrowLeft className="w-4 h-4 mr-2" /> Back
        </Button>
      </div>
    );
  }

  const records = run.records ?? [];
  const discrepancies = records.filter((r: any) => r.match_status === "discrepancy");
  const matched = records.filter((r: any) => r.match_status === "matched");
  const unresolved = discrepancies.filter((r: any) => r.resolution_status === "unresolved");

  return (
    <motion.div {...pageTransition} className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="sm" onClick={() => router.back()}>
          <ArrowLeft className="w-4 h-4 mr-2" /> Back
        </Button>
        <div className="flex-1">
          <div className="flex items-center gap-3">
            <h1 className="text-xl font-heading font-bold uppercase tracking-wider">
              {run.insurer_name}
            </h1>
            <Badge
              variant="outline"
              className={`text-xs capitalize ${STATUS_COLORS[run.status] ?? ""}`}
            >
              {run.status}
            </Badge>
          </div>
          <p className="text-sm text-muted-foreground mt-0.5">
            {run.statement_period_start} – {run.statement_period_end} · {run.file_name}
          </p>
        </div>
        <Button variant="outline" size="sm" onClick={handleDownloadReport} className="gap-2">
          <Download className="w-4 h-4" /> Download Report
        </Button>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        {[
          { label: "Total Records", value: run.total_records ?? 0, color: "text-foreground" },
          { label: "Matched", value: run.matched_count ?? 0, color: "text-green-400" },
          { label: "Discrepancies", value: run.discrepancy_count ?? 0, color: "text-red-400" },
          { label: "Unresolved", value: unresolved.length, color: "text-amber-400" },
        ].map(({ label, value, color }) => (
          <div key={label} className="bg-card border border-border rounded-xl p-4">
            <p className="text-xs text-muted-foreground uppercase tracking-wider font-heading">{label}</p>
            <p className={`text-2xl font-bold mt-1 ${color}`}>{value}</p>
          </div>
        ))}
      </div>

      {/* Discrepancy Table */}
      {discrepancies.length > 0 && (
        <div className="bg-card border border-border rounded-xl overflow-hidden">
          <div className="p-4 border-b border-border flex items-center justify-between gap-3 flex-wrap">
            <h2 className="text-sm font-heading font-bold uppercase tracking-wider flex items-center gap-2">
              <AlertTriangle className="w-4 h-4 text-red-400" />
              Discrepancies ({discrepancies.length})
            </h2>
            <div className="flex gap-2">
              <Select value={discrepancyTypeFilter} onValueChange={setDiscrepancyTypeFilter}>
                <SelectTrigger className="w-[160px] h-8 text-xs">
                  <Filter className="w-3 h-3 mr-1" />
                  <SelectValue placeholder="Type" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Types</SelectItem>
                  <SelectItem value="amount_mismatch">Amount Mismatch</SelectItem>
                  <SelectItem value="policy_not_found">Policy Not Found</SelectItem>
                  <SelectItem value="duplicate">Duplicate</SelectItem>
                  <SelectItem value="missing_in_statement">Missing in Statement</SelectItem>
                </SelectContent>
              </Select>
              <Select value={resolutionFilter} onValueChange={setResolutionFilter}>
                <SelectTrigger className="w-[140px] h-8 text-xs">
                  <SelectValue placeholder="Resolution" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All</SelectItem>
                  <SelectItem value="unresolved">Unresolved</SelectItem>
                  <SelectItem value="accept_statement">Accepted Statement</SelectItem>
                  <SelectItem value="accept_crm">Accepted CRM</SelectItem>
                  <SelectItem value="escalated">Escalated</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          <Table>
            <TableHeader>
              <TableRow className="border-border hover:bg-transparent">
                <TableHead className="text-xs uppercase tracking-wider font-heading">Policy #</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Type</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">CRM Amount</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Statement Amount</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Difference</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Resolution</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {discrepancies.map((record: any) => (
                <TableRow key={record.id} className="border-border hover:bg-muted/30">
                  <TableCell className="font-mono text-xs">{record.policy_number ?? "—"}</TableCell>
                  <TableCell>
                    <Badge variant="outline" className="text-xs capitalize">
                      {record.discrepancy_type?.replace(/_/g, " ") ?? "—"}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-xs">
                    {record.crm_commission != null
                      ? `₹${record.crm_commission.toLocaleString("en-IN")}`
                      : "—"}
                  </TableCell>
                  <TableCell className="text-xs">
                    {record.statement_commission != null
                      ? `₹${record.statement_commission.toLocaleString("en-IN")}`
                      : "—"}
                  </TableCell>
                  <TableCell className="text-xs text-red-400">
                    {record.discrepancy_amount != null
                      ? `₹${record.discrepancy_amount.toLocaleString("en-IN")}`
                      : "—"}
                  </TableCell>
                  <TableCell>
                    <Badge
                      variant="outline"
                      className={`text-xs capitalize ${RESOLUTION_COLORS[record.resolution_status] ?? ""}`}
                    >
                      {record.resolution_status?.replace(/_/g, " ")}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-right">
                    {record.resolution_status === "unresolved" && (
                      <Button
                        variant="ghost"
                        size="sm"
                        className="h-7 text-xs"
                        onClick={() => {
                          setSelectedRecord(record);
                          setDialogOpen(true);
                        }}
                      >
                        Resolve
                      </Button>
                    )}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      )}

      {/* Matched Records */}
      {matched.length > 0 && (
        <div className="bg-card border border-border rounded-xl overflow-hidden">
          <div className="p-4 border-b border-border">
            <h2 className="text-sm font-heading font-bold uppercase tracking-wider flex items-center gap-2">
              <CheckCircle2 className="w-4 h-4 text-green-400" />
              Matched Records ({matched.length})
            </h2>
          </div>
          <Table>
            <TableHeader>
              <TableRow className="border-border hover:bg-transparent">
                <TableHead className="text-xs uppercase tracking-wider font-heading">Policy #</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">CRM Commission</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Statement Commission</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {matched.slice(0, 20).map((record: any) => (
                <TableRow key={record.id} className="border-border hover:bg-muted/30">
                  <TableCell className="font-mono text-xs">{record.policy_number ?? "—"}</TableCell>
                  <TableCell className="text-xs text-green-400">
                    {record.crm_commission != null
                      ? `₹${record.crm_commission.toLocaleString("en-IN")}`
                      : "—"}
                  </TableCell>
                  <TableCell className="text-xs">
                    {record.statement_commission != null
                      ? `₹${record.statement_commission.toLocaleString("en-IN")}`
                      : "—"}
                  </TableCell>
                </TableRow>
              ))}
              {matched.length > 20 && (
                <TableRow>
                  <TableCell colSpan={3} className="text-center text-xs text-muted-foreground py-3">
                    +{matched.length - 20} more matched records
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </div>
      )}

      <DiscrepancyResolutionDialog
        runId={runId}
        record={selectedRecord}
        open={dialogOpen}
        onOpenChange={setDialogOpen}
        onResolved={() => mutate()}
      />
    </motion.div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { motion } from "framer-motion";
import { toast } from "sonner";
import { ArrowLeft, Upload, Loader2, FileSpreadsheet } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { pageTransition } from "@/lib/helpers/animations";
import { useAuth } from "@/lib/context/auth-context";

export default function NewReconciliationPage() {
  const router = useRouter();
  const { session } = useAuth();
  const [loading, setLoading] = useState(false);
  const [file, setFile] = useState<File | null>(null);
  const [insurerName, setInsurerName] = useState("");
  const [periodStart, setPeriodStart] = useState("");
  const [periodEnd, setPeriodEnd] = useState("");

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file || !insurerName || !periodStart || !periodEnd) {
      toast.error("All fields are required");
      return;
    }

    if (file.size > 20 * 1024 * 1024) {
      toast.error("File size must be less than 20 MB");
      return;
    }

    setLoading(true);
    try {
      const token = session?.access_token;
      if (!token) throw new Error("Not authenticated");

      const formData = new FormData();
      formData.append("file", file);
      formData.append("insurer_name", insurerName);
      formData.append("period_start", periodStart);
      formData.append("period_end", periodEnd);

      const res = await fetch("/api/reconciliation", {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
        body: formData,
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error ?? "Import failed");

      toast.success(
        `Import complete: ${data.matched_count} matched, ${data.discrepancy_count} discrepancies`
      );
      router.push(`/dashboard/commission-reconciliation/${data.run_id}`);
    } catch (err: any) {
      toast.error(err.message ?? "Import failed");
    } finally {
      setLoading(false);
    }
  };

  return (
    <motion.div {...pageTransition} className="space-y-6 max-w-2xl">
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="sm" onClick={() => router.back()}>
          <ArrowLeft className="w-4 h-4 mr-2" /> Back
        </Button>
        <h1 className="text-xl font-heading font-bold uppercase tracking-wider">
          Import Commission Statement
        </h1>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="bg-card border border-border rounded-xl p-6 space-y-4">
          <h2 className="text-sm font-heading font-bold uppercase tracking-wider">
            Statement Details
          </h2>

          <div className="space-y-1.5">
            <Label htmlFor="insurer_name">Insurer Name *</Label>
            <Input
              id="insurer_name"
              placeholder="e.g., HDFC Ergo"
              value={insurerName}
              onChange={(e) => setInsurerName(e.target.value)}
              required
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label htmlFor="period_start">Period Start *</Label>
              <Input
                id="period_start"
                type="date"
                value={periodStart}
                onChange={(e) => setPeriodStart(e.target.value)}
                required
              />
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="period_end">Period End *</Label>
              <Input
                id="period_end"
                type="date"
                value={periodEnd}
                onChange={(e) => setPeriodEnd(e.target.value)}
                required
              />
            </div>
          </div>
        </div>

        {/* File Upload */}
        <div className="bg-card border border-border rounded-xl p-6 space-y-4">
          <h2 className="text-sm font-heading font-bold uppercase tracking-wider">
            Upload File
          </h2>
          <p className="text-xs text-muted-foreground">
            Supported formats: Excel (.xlsx, .xls) or CSV. Max size: 20 MB.
            Required columns: Policy Number, Premium Amount, Commission Amount.
          </p>

          <div
            className={`border-2 border-dashed rounded-xl p-8 text-center transition-colors ${
              file ? "border-primary/50 bg-primary/5" : "border-border hover:border-primary/30"
            }`}
          >
            {file ? (
              <div className="space-y-2">
                <FileSpreadsheet className="w-10 h-10 mx-auto text-primary" />
                <p className="text-sm font-medium">{file.name}</p>
                <p className="text-xs text-muted-foreground">
                  {(file.size / 1024).toFixed(1)} KB
                </p>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => setFile(null)}
                >
                  Remove
                </Button>
              </div>
            ) : (
              <div className="space-y-3">
                <Upload className="w-10 h-10 mx-auto text-muted-foreground/40" />
                <p className="text-sm text-muted-foreground">
                  Drop your file here or click to browse
                </p>
                <label className="cursor-pointer">
                  <span className="inline-flex items-center gap-2 px-4 py-2 rounded-lg bg-primary text-primary-foreground text-sm font-medium hover:bg-primary/90 transition-colors">
                    <Upload className="w-4 h-4" /> Choose File
                  </span>
                  <input
                    type="file"
                    accept=".xlsx,.xls,.csv"
                    className="hidden"
                    onChange={(e) => setFile(e.target.files?.[0] ?? null)}
                  />
                </label>
              </div>
            )}
          </div>
        </div>

        <div className="flex justify-end gap-3">
          <Button type="button" variant="outline" onClick={() => router.back()}>
            Cancel
          </Button>
          <Button type="submit" disabled={loading || !file}>
            {loading ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin mr-2" />
                Processing...
              </>
            ) : (
              <>
                <Upload className="w-4 h-4 mr-2" />
                Import & Reconcile
              </>
            )}
          </Button>
        </div>
      </form>
    </motion.div>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { motion } from "framer-motion";
import useSWR from "swr";
import { format } from "date-fns";
import {
  FileSpreadsheet, Plus, CheckCircle2, AlertTriangle, Clock, XCircle,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import { pageTransition } from "@/lib/helpers/animations";
import { useAuth } from "@/lib/context/auth-context";

const STATUS_COLORS: Record<string, string> = {
  pending: "bg-amber-500/10 text-amber-400 border-amber-500/20",
  processing: "bg-blue-500/10 text-blue-400 border-blue-500/20",
  completed: "bg-green-500/10 text-green-400 border-green-500/20",
  failed: "bg-red-500/10 text-red-400 border-red-500/20",
};

async function fetcher(url: string, token: string) {
  const res = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
  if (!res.ok) throw new Error("Failed to fetch");
  return res.json();
}

export default function CommissionReconciliationPage() {
  const router = useRouter();
  const { session, role } = useAuth();
  const token = session?.access_token ?? "";

  const { data, isLoading } = useSWR(
    token ? [`/api/reconciliation?limit=50`, token] : null,
    ([url, t]) => fetcher(url, t),
    { revalidateOnFocus: false }
  );

  const runs = data?.data ?? [];

  // Summary metrics
  const total = runs.length;
  const pending = runs.filter((r: any) => r.status === "pending" || r.status === "processing").length;
  const completed = runs.filter((r: any) => r.status === "completed").length;
  const totalDiscrepancies = runs.reduce((s: number, r: any) => s + (r.discrepancy_count ?? 0), 0);

  const metrics = [
    { label: "Total Runs", value: total, icon: FileSpreadsheet, color: "text-foreground" },
    { label: "Pending", value: pending, icon: Clock, color: "text-amber-400" },
    { label: "Completed", value: completed, icon: CheckCircle2, color: "text-green-400" },
    { label: "Total Discrepancies", value: totalDiscrepancies, icon: AlertTriangle, color: "text-red-400" },
  ];

  return (
    <motion.div {...pageTransition} className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-heading font-bold text-foreground uppercase tracking-wider flex items-center gap-2">
            <FileSpreadsheet className="w-6 h-6 text-primary" />
            Commission Reconciliation
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            Import and reconcile insurer commission statements
          </p>
        </div>
        {(role === "admin" || role === "manager") && (
          <Button
            size="sm"
            onClick={() => router.push("/dashboard/commission-reconciliation/new")}
            className="gap-2"
          >
            <Plus className="w-4 h-4" /> Import Statement
          </Button>
        )}
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        {metrics.map(({ label, value, icon: Icon, color }) => (
          <div key={label} className="bg-card border border-border rounded-xl p-4 flex flex-col gap-1">
            <div className="flex items-center gap-1.5">
              <Icon className={`w-3.5 h-3.5 ${color}`} />
              <p className="text-xs text-muted-foreground font-heading uppercase tracking-wider">{label}</p>
            </div>
            <p className={`text-2xl font-bold ${color}`}>{value}</p>
          </div>
        ))}
      </div>

      {/* Runs Table */}
      <div className="bg-card border border-border rounded-xl overflow-hidden">
        {isLoading ? (
          <div className="p-6 space-y-3">
            {[...Array(5)].map((_, i) => <Skeleton key={i} className="h-12 w-full" />)}
          </div>
        ) : runs.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 gap-4">
            <FileSpreadsheet className="w-12 h-12 text-muted-foreground/40" />
            <p className="text-muted-foreground">No reconciliation runs yet.</p>
            {(role === "admin" || role === "manager") && (
              <Button
                onClick={() => router.push("/dashboard/commission-reconciliation/new")}
                className="gap-2"
              >
                <Plus className="w-4 h-4" /> Import First Statement
              </Button>
            )}
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow className="border-border hover:bg-transparent">
                <TableHead className="text-xs uppercase tracking-wider font-heading">Insurer</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden md:table-cell">Period</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden lg:table-cell">File</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Records</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Matched</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Discrepancies</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Status</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden lg:table-cell">Date</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {runs.map((run: any) => (
                <TableRow
                  key={run.id}
                  className="border-border hover:bg-muted/30 cursor-pointer"
                  onClick={() => router.push(`/dashboard/commission-reconciliation/${run.id}`)}
                >
                  <TableCell className="font-medium text-sm">{run.insurer_name}</TableCell>
                  <TableCell className="hidden md:table-cell text-xs text-muted-foreground">
                    {run.statement_period_start} – {run.statement_period_end}
                  </TableCell>
                  <TableCell className="hidden lg:table-cell text-xs text-muted-foreground truncate max-w-[150px]">
                    {run.file_name}
                  </TableCell>
                  <TableCell className="text-sm">{run.total_records ?? 0}</TableCell>
                  <TableCell>
                    <span className="text-green-400 font-medium">{run.matched_count ?? 0}</span>
                  </TableCell>
                  <TableCell>
                    <span className={run.discrepancy_count > 0 ? "text-red-400 font-medium" : "text-muted-foreground"}>
                      {run.discrepancy_count ?? 0}
                    </span>
                  </TableCell>
                  <TableCell>
                    <Badge
                      variant="outline"
                      className={`text-xs capitalize ${STATUS_COLORS[run.status] ?? ""}`}
                    >
                      {run.status}
                    </Badge>
                  </TableCell>
                  <TableCell className="hidden lg:table-cell text-xs text-muted-foreground">
                    {run.created_at ? format(new Date(run.created_at), "dd MMM yyyy") : "—"}
                  </TableCell>
                  <TableCell className="text-right">
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-7 text-xs"
                      onClick={(e) => {
                        e.stopPropagation();
                        router.push(`/dashboard/commission-reconciliation/${run.id}`);
                      }}
                    >
                      View
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </div>
    </motion.div>
  );
}

"use client";

import { use, useState } from "react";
import { useRouter } from "next/navigation";
import useSWR from "swr";
import { motion } from "framer-motion";
import { format, differenceInDays } from "date-fns";
import { ArrowLeft, Shield, CheckCircle2, Loader2, Pencil } from "lucide-react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Input } from "@/components/ui/input";
import { pageTransition } from "@/lib/helpers/animations";
import { useAuth } from "@/lib/context/auth-context";
import { ComplianceItemForm } from "@/components/compliance/ComplianceItemForm";

const STATUS_COLORS: Record<string, string> = {
  pending: "bg-amber-500/10 text-amber-400 border-amber-500/20",
  in_progress: "bg-blue-500/10 text-blue-400 border-blue-500/20",
  completed: "bg-green-500/10 text-green-400 border-green-500/20",
  overdue: "bg-red-500/10 text-red-400 border-red-500/20",
};

async function fetcher(url: string, token: string) {
  const res = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
  if (!res.ok) throw new Error("Failed to fetch");
  return res.json();
}

export default function ComplianceItemDetailPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = use(params);
  const router = useRouter();
  const { session, role } = useAuth();
  const token = session?.access_token ?? "";

  const [completing, setCompleting] = useState(false);
  const [completionNotes, setCompletionNotes] = useState("");
  const [completionDocUrl, setCompletionDocUrl] = useState("");
  const [editOpen, setEditOpen] = useState(false);

  const { data: item, isLoading, mutate } = useSWR(
    token ? [`/api/compliance/${id}`, token] : null,
    ([url, t]) => fetcher(url, t),
    { revalidateOnFocus: false }
  );

  const handleComplete = async () => {
    setCompleting(true);
    try {
      const t = session?.access_token;
      if (!t) throw new Error("Not authenticated");

      const res = await fetch(`/api/compliance/${id}/complete`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${t}`,
        },
        body: JSON.stringify({
          completion_notes: completionNotes,
          completion_document_url: completionDocUrl || null,
        }),
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error ?? "Failed to complete");

      toast.success(
        data.next_occurrence
          ? `Completed! Next occurrence created for ${data.next_occurrence.due_date}`
          : "Compliance item completed"
      );
      mutate();
    } catch (err: any) {
      toast.error(err.message ?? "Failed to complete");
    } finally {
      setCompleting(false);
    }
  };

  if (isLoading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-10 w-48" />
        <Skeleton className="h-40 w-full" />
      </div>
    );
  }

  if (!item) {
    return (
      <div className="flex flex-col items-center justify-center py-20 gap-4">
        <p className="text-muted-foreground">Compliance item not found.</p>
        <Button variant="outline" onClick={() => router.back()}>
          <ArrowLeft className="w-4 h-4 mr-2" /> Back
        </Button>
      </div>
    );
  }

  const daysUntil = differenceInDays(new Date(item.due_date), new Date());
  const isOverdue = daysUntil < 0 && item.status !== "completed";

  return (
    <motion.div {...pageTransition} className="space-y-6 max-w-2xl">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="sm" onClick={() => router.back()}>
          <ArrowLeft className="w-4 h-4 mr-2" /> Back
        </Button>
        <div className="flex-1">
          <h1 className="text-xl font-heading font-bold uppercase tracking-wider">
            {item.title}
          </h1>
          <p className="text-sm text-muted-foreground mt-0.5 capitalize">
            {item.category?.replace(/_/g, " ")} · {item.recurrence?.replace(/_/g, " ")}
          </p>
        </div>
        {(role === "admin" || role === "manager") && (
          <Button variant="outline" size="sm" onClick={() => setEditOpen(true)} className="gap-2">
            <Pencil className="w-3.5 h-3.5" /> Edit
          </Button>
        )}
      </div>

      {/* Status Card */}
      <div className="bg-card border border-border rounded-xl p-5 space-y-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Shield className="w-5 h-5 text-primary" />
            <Badge
              variant="outline"
              className={`text-sm capitalize ${STATUS_COLORS[item.status] ?? ""}`}
            >
              {item.status?.replace(/_/g, " ")}
            </Badge>
          </div>
          <div className="text-right">
            <p className={`text-sm font-medium ${isOverdue ? "text-red-400" : daysUntil <= 7 ? "text-orange-400" : daysUntil <= 30 ? "text-yellow-400" : "text-green-400"}`}>
              {isOverdue
                ? `${Math.abs(daysUntil)} days overdue`
                : daysUntil === 0
                ? "Due today"
                : `${daysUntil} days left`}
            </p>
            <p className="text-xs text-muted-foreground">
              Due: {format(new Date(item.due_date), "dd MMM yyyy")}
            </p>
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4 text-sm">
          <div>
            <p className="text-xs text-muted-foreground uppercase tracking-wider">Assigned To</p>
            <p className="mt-0.5">{item.assigned_to_name ?? "Unassigned"}</p>
          </div>
          <div>
            <p className="text-xs text-muted-foreground uppercase tracking-wider">Category</p>
            <p className="capitalize mt-0.5">{item.category?.replace(/_/g, " ")}</p>
          </div>
        </div>

        {item.description && (
          <div>
            <p className="text-xs text-muted-foreground uppercase tracking-wider mb-1">Description</p>
            <p className="text-sm">{item.description}</p>
          </div>
        )}
      </div>

      {/* Completion Workflow */}
      {item.status !== "completed" && (role === "admin" || role === "manager") && (
        <div className="bg-card border border-border rounded-xl p-5 space-y-4">
          <h2 className="text-sm font-heading font-bold uppercase tracking-wider flex items-center gap-2">
            <CheckCircle2 className="w-4 h-4 text-green-400" /> Mark as Completed
          </h2>

          <div className="space-y-1.5">
            <Label htmlFor="completion_doc">Completion Document URL</Label>
            <Input
              id="completion_doc"
              placeholder="https://..."
              value={completionDocUrl}
              onChange={(e) => setCompletionDocUrl(e.target.value)}
            />
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="completion_notes">Completion Notes</Label>
            <Textarea
              id="completion_notes"
              placeholder="Describe how this was completed..."
              rows={3}
              value={completionNotes}
              onChange={(e) => setCompletionNotes(e.target.value)}
            />
          </div>

          <Button onClick={handleComplete} disabled={completing} className="gap-2">
            {completing && <Loader2 className="w-4 h-4 animate-spin" />}
            <CheckCircle2 className="w-4 h-4" />
            Mark Complete
            {item.recurrence !== "one_time" && " & Create Next Occurrence"}
          </Button>
        </div>
      )}

      {/* Completion Info */}
      {item.status === "completed" && (
        <div className="bg-green-500/5 border border-green-500/20 rounded-xl p-5 space-y-3">
          <h2 className="text-sm font-heading font-bold uppercase tracking-wider text-green-400 flex items-center gap-2">
            <CheckCircle2 className="w-4 h-4" /> Completed
          </h2>
          <div className="text-sm space-y-2">
            <div>
              <p className="text-xs text-muted-foreground">Completed At</p>
              <p>{item.completed_at ? format(new Date(item.completed_at), "dd MMM yyyy, HH:mm") : "—"}</p>
            </div>
            {item.completion_notes && (
              <div>
                <p className="text-xs text-muted-foreground">Notes</p>
                <p>{item.completion_notes}</p>
              </div>
            )}
            {item.completion_document_url && (
              <div>
                <p className="text-xs text-muted-foreground">Document</p>
                <a
                  href={item.completion_document_url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-primary hover:underline text-xs"
                >
                  View Document
                </a>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Edit Dialog */}
      <ComplianceItemForm
        editData={item}
        open={editOpen}
        onOpenChange={setEditOpen}
        onCreated={() => { mutate(); setEditOpen(false); }}
      />
    </motion.div>
  );
}

"use client";

import { useState } from "react";
import { motion } from "framer-motion";
import { useRouter } from "next/navigation";
import useSWR from "swr";
import { differenceInDays, format } from "date-fns";
import {
  Shield, CheckCircle2, Clock, AlertTriangle, XCircle, Filter, ChevronLeft, ChevronRight,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { pageTransition } from "@/lib/helpers/animations";
import { useAuth } from "@/lib/context/auth-context";
import { ComplianceItemForm } from "@/components/compliance/ComplianceItemForm";
import { RegulatoryCalendar } from "@/components/compliance/RegulatoryCalendar";

const STATUS_COLORS: Record<string, string> = {
  pending: "bg-amber-500/10 text-amber-400 border-amber-500/20",
  in_progress: "bg-blue-500/10 text-blue-400 border-blue-500/20",
  completed: "bg-green-500/10 text-green-400 border-green-500/20",
  overdue: "bg-red-500/10 text-red-400 border-red-500/20",
};

const CATEGORY_LABELS: Record<string, string> = {
  license_renewal: "License Renewal",
  regulatory_filing: "Regulatory Filing",
  audit_submission: "Audit Submission",
  training_certification: "Training/Certification",
  policy_review: "Policy Review",
  other: "Other",
};

function getUrgencyColor(dueDate: string, status: string): string {
  if (status === "completed") return "text-green-400";
  const days = differenceInDays(new Date(dueDate), new Date());
  if (days < 0) return "text-red-400";
  if (days <= 7) return "text-orange-400";
  if (days <= 30) return "text-yellow-400";
  return "text-green-400";
}

async function fetcher(url: string, token: string) {
  const res = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
  if (!res.ok) throw new Error("Failed to fetch");
  return res.json();
}

export default function CompliancePage() {
  const router = useRouter();
  const { session, role } = useAuth();
  const token = session?.access_token ?? "";

  const [statusFilter, setStatusFilter] = useState("all");
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [calendarMonth, setCalendarMonth] = useState(new Date());

  const params = new URLSearchParams();
  if (statusFilter !== "all") params.set("status", statusFilter);
  if (categoryFilter !== "all") params.set("category", categoryFilter);
  params.set("limit", "100");

  const { data, isLoading, mutate } = useSWR(
    token ? [`/api/compliance?${params}`, token] : null,
    ([url, t]) => fetcher(url, t),
    { revalidateOnFocus: false }
  );

  const { data: calendarData } = useSWR(
    token ? [`/api/compliance/calendar`, token] : null,
    ([url, t]) => fetcher(url, t),
    { revalidateOnFocus: false }
  );

  const items = data?.data ?? [];
  const calendarItems = calendarData?.items ?? [];

  // Metrics
  const total = items.length;
  const completed = items.filter((i: any) => i.status === "completed").length;
  const inProgress = items.filter((i: any) => i.status === "in_progress").length;
  const pending = items.filter((i: any) => i.status === "pending").length;
  const overdue = items.filter((i: any) => i.status === "overdue" || (i.status !== "completed" && differenceInDays(new Date(i.due_date), new Date()) < 0)).length;

  const metrics = [
    { label: "Total", value: total, color: "text-foreground", icon: Shield },
    { label: "Completed", value: completed, color: "text-green-400", icon: CheckCircle2 },
    { label: "In Progress", value: inProgress, color: "text-blue-400", icon: Clock },
    { label: "Pending", value: pending, color: "text-amber-400", icon: Clock },
    { label: "Overdue", value: overdue, color: "text-red-400", icon: AlertTriangle },
  ];

  // Group by category
  const grouped: Record<string, any[]> = {};
  for (const item of items) {
    const cat = item.category ?? "other";
    if (!grouped[cat]) grouped[cat] = [];
    grouped[cat].push(item);
  }

  return (
    <motion.div {...pageTransition} className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-heading font-bold text-foreground uppercase tracking-wider flex items-center gap-2">
            <Shield className="w-6 h-6 text-primary" />
            IRDA Compliance
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            Track regulatory requirements and deadlines
          </p>
        </div>
        {(role === "admin" || role === "manager") && (
          <ComplianceItemForm onCreated={() => mutate()} />
        )}
      </div>

      {/* Metrics */}
      <div className="grid grid-cols-2 sm:grid-cols-5 gap-3">
        {metrics.map(({ label, value, color, icon: Icon }) => (
          <div key={label} className="bg-card border border-border rounded-xl p-4 flex flex-col gap-1">
            <div className="flex items-center gap-1.5">
              <Icon className={`w-3.5 h-3.5 ${color}`} />
              <p className="text-xs text-muted-foreground font-heading uppercase tracking-wider">{label}</p>
            </div>
            <p className={`text-2xl font-bold ${color}`}>{value}</p>
          </div>
        ))}
      </div>

      {/* Calendar */}
      <div className="bg-card border border-border rounded-xl p-5">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-sm font-heading font-bold uppercase tracking-wider">
            Regulatory Calendar
          </h2>
          <div className="flex gap-1">
            <Button
              variant="ghost"
              size="sm"
              className="h-7 w-7 p-0"
              onClick={() => {
                const d = new Date(calendarMonth);
                d.setMonth(d.getMonth() - 1);
                setCalendarMonth(d);
              }}
            >
              <ChevronLeft className="w-4 h-4" />
            </Button>
            <Button
              variant="ghost"
              size="sm"
              className="h-7 w-7 p-0"
              onClick={() => {
                const d = new Date(calendarMonth);
                d.setMonth(d.getMonth() + 1);
                setCalendarMonth(d);
              }}
            >
              <ChevronRight className="w-4 h-4" />
            </Button>
          </div>
        </div>
        <RegulatoryCalendar
          items={calendarItems}
          currentMonth={calendarMonth}
          onItemClick={(item) => router.push(`/dashboard/compliance/${item.id}`)}
        />
      </div>

      {/* Filters */}
      <div className="flex gap-3 flex-wrap">
        <Select value={statusFilter} onValueChange={setStatusFilter}>
          <SelectTrigger className="w-[140px]">
            <Filter className="w-3.5 h-3.5 mr-2 text-muted-foreground" />
            <SelectValue placeholder="Status" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Status</SelectItem>
            <SelectItem value="pending">Pending</SelectItem>
            <SelectItem value="in_progress">In Progress</SelectItem>
            <SelectItem value="completed">Completed</SelectItem>
            <SelectItem value="overdue">Overdue</SelectItem>
          </SelectContent>
        </Select>

        <Select value={categoryFilter} onValueChange={setCategoryFilter}>
          <SelectTrigger className="w-[180px]">
            <SelectValue placeholder="Category" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Categories</SelectItem>
            {Object.entries(CATEGORY_LABELS).map(([k, v]) => (
              <SelectItem key={k} value={k}>{v}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {/* Checklist grouped by category */}
      {isLoading ? (
        <div className="space-y-3">
          {[...Array(5)].map((_, i) => <Skeleton key={i} className="h-16 w-full" />)}
        </div>
      ) : items.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-20 gap-4 bg-card border border-border rounded-xl">
          <Shield className="w-12 h-12 text-muted-foreground/40" />
          <p className="text-muted-foreground">No compliance items found.</p>
        </div>
      ) : (
        <div className="space-y-4">
          {Object.entries(grouped).map(([category, categoryItems]) => (
            <div key={category} className="bg-card border border-border rounded-xl overflow-hidden">
              <div className="px-4 py-3 border-b border-border bg-muted/20">
                <h3 className="text-xs font-heading font-bold uppercase tracking-wider">
                  {CATEGORY_LABELS[category] ?? category} ({categoryItems.length})
                </h3>
              </div>
              <div className="divide-y divide-border/50">
                {categoryItems.map((item: any) => {
                  const daysUntil = differenceInDays(new Date(item.due_date), new Date());
                  const urgencyColor = getUrgencyColor(item.due_date, item.status);

                  return (
                    <button
                      key={item.id}
                      onClick={() => router.push(`/dashboard/compliance/${item.id}`)}
                      className="w-full flex items-center gap-4 px-4 py-3 hover:bg-muted/30 transition-colors text-left"
                    >
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium truncate">{item.title}</p>
                        <p className="text-xs text-muted-foreground mt-0.5">
                          {item.assigned_to_name ?? "Unassigned"} · {item.recurrence?.replace(/_/g, " ")}
                        </p>
                      </div>
                      <div className="flex items-center gap-3 flex-shrink-0">
                        <div className="text-right">
                          <p className={`text-xs font-medium ${urgencyColor}`}>
                            {daysUntil < 0
                              ? `${Math.abs(daysUntil)}d overdue`
                              : daysUntil === 0
                              ? "Today"
                              : `${daysUntil}d left`}
                          </p>
                          <p className="text-xs text-muted-foreground">
                            {format(new Date(item.due_date), "dd MMM yyyy")}
                          </p>
                        </div>
                        <Badge
                          variant="outline"
                          className={`text-xs capitalize ${STATUS_COLORS[item.status] ?? ""}`}
                        >
                          {item.status?.replace(/_/g, " ")}
                        </Badge>
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      )}
    </motion.div>
  );
}

"use client";

import { useState } from "react";
import { motion } from "framer-motion";
import { 
  Upload, 
  FileCheck, 
  AlertCircle, 
  Download, 
  CheckCircle2, 
  ShieldAlert,
  Loader2,
  Table as TableIcon,
  Trash2,
  Inbox
} from "lucide-react";
import { pageTransition, staggerContainer, staggerItem, hoverLift } from "@/lib/helpers/animations";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";

export default function BulkOnboardingPage() {
  const [isDragging, setIsDragging] = useState(false);
  const [file, setFile] = useState<File | null>(null);
  const [uploadState, setUploadState] = useState<'idle' | 'validating' | 'processing' | 'success' | 'error'>('idle');
  const [progress, setProgress] = useState(0);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      if (selectedFile.name.endsWith('.csv') || selectedFile.name.endsWith('.xlsx')) {
        setFile(selectedFile);
        startValidation();
      } else {
        toast.error("Invalid file format. Please upload .csv or .xlsx");
      }
    }
  };

  const startValidation = () => {
    setUploadState('validating');
    setProgress(0);
    const interval = setInterval(() => {
      setProgress(prev => {
        if (prev >= 100) {
          clearInterval(interval);
          setUploadState('processing');
          startProcessing();
          return 100;
        }
        return prev + 10;
      });
    }, 200);
  };

  const startProcessing = () => {
    setProgress(0);
    const interval = setInterval(() => {
      setProgress(prev => {
        if (prev >= 100) {
          clearInterval(interval);
          setUploadState('success');
          toast.success("Bulk customer data processed successfully!");
          return 100;
        }
        return prev + 5;
      });
    }, 150);
  };

  const reset = () => {
    setFile(null);
    setUploadState('idle');
    setProgress(0);
  };

  return (
    <motion.div className="max-w-5xl mx-auto space-y-8 pb-20" {...pageTransition}>
      {/* Header */}
      <section className="space-y-4">
        <div className="flex items-center gap-3 text-primary">
          <Badge variant="outline" className="bg-primary/5 text-primary border-primary/20">IRDA Standard Compliant</Badge>
          <span className="text-xs font-bold uppercase tracking-widest opacity-50">Enterprise Module</span>
        </div>
        <h1 className="text-4xl font-bold tracking-tight font-heading sm:text-5xl">
          Bulk <span className="text-primary italic">Onboarding</span> Center
        </h1>
        <p className="text-muted-foreground text-lg max-w-2xl leading-relaxed">
          Upload customer populations for GMC (Group Mediclaim), Fleet, or Large Corporates. 
          Our validation engine ensures data integrity before entry.
        </p>
      </section>

      <div className="grid md:grid-cols-3 gap-8">
        {/* Upload Zone */}
        <div className="md:col-span-2 space-y-6">
          <motion.div 
            variants={staggerItem}
            className={cn(
              "relative border-2 border-dashed rounded-[2.5rem] p-12 transition-all overflow-hidden flex flex-col items-center justify-center min-h-[400px]",
              isDragging ? "border-primary bg-primary/5 scale-[0.99]" : "border-border bg-card/40 hover:bg-card hover:border-primary/50",
              uploadState !== 'idle' && "pointer-events-none"
            )}
            onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
            onDragLeave={() => setIsDragging(false)}
            onDrop={(e) => { e.preventDefault(); setIsDragging(false); const f = e.dataTransfer.files[0]; if(f) handleFileSelect({ target: { files: [f] } } as any); }}
          >
             {uploadState === 'idle' ? (
               <>
                 <div className="h-20 w-20 rounded-full bg-primary/10 flex items-center justify-center mb-6">
                   <Upload className="h-10 w-10 text-primary" />
                 </div>
                 <h3 className="text-2xl font-bold mb-2">Drop population file here</h3>
                 <p className="text-muted-foreground mb-8">Support for .csv, .xlsx (Max 50k rows)</p>
                 <Input type="file" id="file-upload" className="hidden" onChange={handleFileSelect} accept=".csv, .xlsx" />
                 <Button asChild className="h-12 px-8 rounded-xl font-bold">
                   <label htmlFor="file-upload" className="cursor-pointer">Browse Files</label>
                 </Button>
               </>
             ) : (
               <div className="w-full max-w-md space-y-6 text-center">
                 <div className="h-20 w-20 rounded-full bg-primary/10 flex items-center justify-center mb-6 mx-auto">
                   {uploadState === 'success' ? <CheckCircle2 className="h-12 w-12 text-emerald-500" /> : <Loader2 className="h-12 w-12 text-primary animate-spin" />}
                 </div>
                 <h3 className="text-2xl font-bold capitalize">
                   {uploadState === 'validating' && "Validating Schema..."}
                   {uploadState === 'processing' && "Injecting Records..."}
                   {uploadState === 'success' && "Import Complete"}
                 </h3>
                 <Progress value={progress} className="h-3 rounded-full" />
                 <p className="text-muted-foreground text-sm">
                   {uploadState === 'validating' && "Checking mandatory fields (PAN, GST, Mobile)..."}
                   {uploadState === 'processing' && `Processing records... ${progress}%`}
                   {uploadState === 'success' && "248 records successfully added to Customer Master."}
                 </p>
                 {uploadState === 'success' && (
                   <div className="pt-6">
                     <Button variant="outline" className="rounded-xl px-8" onClick={reset}>Onboard Another Population</Button>
                   </div>
                 )}
               </div>
             )}
          </motion.div>

          {/* Guidelines info */}
          <div className="grid grid-cols-2 gap-4">
            <Card className="border-none bg-blue-500/5">
              <CardContent className="p-4 flex gap-3">
                <ShieldAlert className="h-5 w-5 text-blue-500 shrink-0" />
                <div className="space-y-1">
                  <p className="text-sm font-bold">IRDA Validation</p>
                  <p className="text-xs text-muted-foreground">Mobile number and PAN/GST are mandatory for all entity records.</p>
                </div>
              </CardContent>
            </Card>
            <Card className="border-none bg-amber-500/5">
              <CardContent className="p-4 flex gap-3">
                <AlertCircle className="h-5 w-5 text-amber-500 shrink-0" />
                <div className="space-y-1">
                  <p className="text-sm font-bold">Duplicate Check</p>
                  <p className="text-xs text-muted-foreground">Entries matching existing Mobile or Email will be flagged for merge.</p>
                </div>
              </CardContent>
            </Card>
          </div>
        </div>

        {/* Templates & Side info */}
        <div className="space-y-6">
          <Card className="rounded-[2rem] border-border bg-card/40 overflow-hidden">
            <CardContent className="p-8 space-y-6">
              <div className="h-12 w-12 rounded-xl bg-primary/10 flex items-center justify-center mb-2">
                <FileCheck className="h-6 w-6 text-primary" />
              </div>
              <h3 className="text-xl font-bold">Import Templates</h3>
              <p className="text-sm text-muted-foreground leading-relaxed">
                Use our pre-formatted templates to ensure zero validation errors.
              </p>
              
              <div className="space-y-2">
                <Button variant="outline" className="w-full justify-between h-14 rounded-xl border-border px-4 hover:border-primary/50 group">
                  <div className="flex items-center gap-3">
                    <TableIcon className="h-5 w-5 opacity-50" />
                    <span className="text-sm font-bold">Individual / Family</span>
                  </div>
                  <Download className="h-4 w-4 opacity-0 group-hover:opacity-100 transition-opacity" />
                </Button>
                <Button variant="outline" className="w-full justify-between h-14 rounded-xl border-border px-4 hover:border-primary/50 group">
                  <div className="flex items-center gap-3">
                    <Inbox className="h-5 w-5 opacity-50" />
                    <span className="text-sm font-bold">Corporate (GMC)</span>
                  </div>
                  <Download className="h-4 w-4 opacity-0 group-hover:opacity-100 transition-opacity" />
                </Button>
                <Button variant="outline" className="w-full justify-between h-14 rounded-xl border-border px-4 hover:border-primary/50 group">
                  <Trash2 className="h-5 w-5 opacity-50" />
                  <span className="text-sm font-bold">Fleet Population</span>
                  <Download className="h-4 w-4 opacity-0 group-hover:opacity-100 transition-opacity" />
                </Button>
              </div>
            </CardContent>
          </Card>

          <Card className="rounded-[2rem] border-none bg-gradient-to-br from-primary to-indigo-600 text-white overflow-hidden shadow-2xl shadow-primary/20">
            <CardContent className="p-8 space-y-4">
              <h4 className="font-bold">Need Help?</h4>
              <p className="text-xs opacity-90 leading-relaxed">
                If you have a population above 50,000 records or custom data mapping requirements, please contact technical support.
              </p>
              <Button className="w-full bg-white/20 hover:bg-white/30 border-none text-white font-bold h-12 rounded-xl backdrop-blur-md">
                Raise Ticket
              </Button>
            </CardContent>
          </Card>
        </div>
      </div>
    </motion.div>
  );
}

"use client";

import { useState, useMemo } from "react";
import { motion } from "framer-motion";
import {
  Search, Plus, Upload, Users, Building2, User, MoreHorizontal,
  Eye, Pencil, Trash2, Copy, Check, Loader2, ChevronDown,
  UserPlus, Filter, X, RefreshCw, Download, Shield,
} from "lucide-react";
import { toast } from "sonner";
import { useRouter } from "next/navigation";

import { useAuth } from "@/lib/context/auth-context";
import { useCustomers, invalidateCustomers } from "@/lib/hooks/use-customers";
import { customerService } from "@/lib/services/customer.service";
import { auditLogService } from "@/lib/services/audit-log.service";

import { Customer, ClientType } from "@/lib/types";
import { pageTransition, staggerContainer, staggerItem } from "@/lib/helpers/animations";
import { useIsMobile } from "@/lib/hooks/use-media-query";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  DropdownMenu, DropdownMenuContent, DropdownMenuItem,
  DropdownMenuSeparator, DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { CustomerForm } from "@/components/customers/customer-form";
import { CustomerLookup } from "@/components/customers/customer-lookup";
import { CustomerBulkImport } from "@/components/customers/customer-bulk-import";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

const PAGE_SIZE = 20;

const TYPE_LABELS: Record<string, string> = {
  individual: "Individual",
  corporate: "Corporate",
  sme: "SME",
  government: "Government",
  contractor: "Contractor",
  manufacturer: "Manufacturer",
  transporter: "Transporter",
  trader: "Trader",
  other: "Other",
};

const TYPE_COLORS: Record<string, string> = {
  individual: "bg-blue-500/10 text-blue-400 border-blue-500/20",
  corporate: "bg-amber-500/10 text-amber-400 border-amber-500/20",
  sme: "bg-purple-500/10 text-purple-400 border-purple-500/20",
  government: "bg-green-500/10 text-green-400 border-green-500/20",
  contractor: "bg-orange-500/10 text-orange-400 border-orange-500/20",
  manufacturer: "bg-cyan-500/10 text-cyan-400 border-cyan-500/20",
  transporter: "bg-rose-500/10 text-rose-400 border-rose-500/20",
  trader: "bg-teal-500/10 text-teal-400 border-teal-500/20",
  other: "bg-gray-500/10 text-gray-400 border-gray-500/20",
};

const KYC_COLORS: Record<string, string> = {
  verified: "bg-green-500/10 text-green-400",
  pending: "bg-amber-500/10 text-amber-400",
  rejected: "bg-red-500/10 text-red-400",
  expired: "bg-gray-500/10 text-gray-400",
};

export default function CustomersPage() {
  const { role } = useAuth();
  if (role === "employee") return <CustomerLookup />;
  return <CustomerListView />;
}

function CustomerListView() {
  const router = useRouter();
  const { role, session, user } = useAuth();
  const { data: customers, isLoading } = useCustomers();
  const isMobile = useIsMobile();

  const [searchQuery, setSearchQuery] = useState("");
  const [typeFilter, setTypeFilter] = useState<string>("all");
  const [statusFilter, setStatusFilter] = useState<"active" | "inactive" | "all">("active");
  const [formOpen, setFormOpen] = useState(false);
  const [bulkImportOpen, setBulkImportOpen] = useState(false);
  const [editCustomer, setEditCustomer] = useState<Customer | null>(null);
  const [deleteCustomer, setDeleteCustomer] = useState<Customer | null>(null);
  const [deleting, setDeleting] = useState(false);
  const [copiedUID, setCopiedUID] = useState<string | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [showInactive, setShowInactive] = useState(false);

  // Compute metrics
  const metrics = useMemo(() => {
    if (!customers) return { total: 0, active: 0, individual: 0, corporate: 0, sme: 0, other: 0 };
    const all = customers;
    return {
      total: all.length,
      active: all.filter(c => !c.status || c.status === "active").length,
      individual: all.filter(c => c.type === "individual").length,
      corporate: all.filter(c => c.type === "corporate").length,
      sme: all.filter(c => c.type === "sme").length,
      other: all.filter(c => !["individual", "corporate", "sme"].includes(c.type)).length,
    };
  }, [customers]);

  // Filter customers
  const filtered = useMemo(() => {
    if (!customers) return [];
    let list = customers;

    // Status filter
    if (!showInactive) {
      list = list.filter(c => !c.status || c.status === "active");
    }

    // Type filter
    if (typeFilter !== "all") {
      list = list.filter(c => c.type === typeFilter);
    }

    // Search
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase().trim();
      list = list.filter(c =>
        c.name?.toLowerCase().includes(q) ||
        c.uid?.toLowerCase().includes(q) ||
        c.phone?.includes(q) ||
        c.email?.toLowerCase().includes(q) ||
        c.city?.toLowerCase().includes(q)
      );
    }

    return list;
  }, [customers, searchQuery, typeFilter, showInactive]);

  // Pagination
  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
  const paginated = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  const handleCopyUID = async (uid: string) => {
    await navigator.clipboard.writeText(uid);
    setCopiedUID(uid);
    toast.success("UID copied");
    setTimeout(() => setCopiedUID(null), 2000);
  };

  const handleDelete = async () => {
    if (!deleteCustomer || !user) return;
    setDeleting(true);
    try {
      try {
        const token = session?.access_token;
        if (token) {
          await fetch(`/api/customers/${deleteCustomer.id}/deactivate`, {
            method: "POST",
            headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
          });
        }
      } catch { /* non-critical */ }

      const cascade = await customerService.deleteWithCascade(deleteCustomer.id, user.id);
      const parts = [
        cascade.cancelledPolicies && `${cascade.cancelledPolicies} policy(ies)`,
        cascade.cancelledPremiums && `${cascade.cancelledPremiums} premium(s)`,
        cascade.rejectedCommissions && `${cascade.rejectedCommissions} commission(s)`,
        cascade.lostRenewals && `${cascade.lostRenewals} renewal(s)`,
      ].filter(Boolean);
      const msg = parts.length ? ` — also affected ${parts.join(", ")}` : "";
      await auditLogService.logAction(user.id, user.name, "deactivate", "customer",
        `Deactivated customer: ${deleteCustomer.name} (${deleteCustomer.uid})${msg}`);
      toast.success(`Customer deactivated${msg}`);
      invalidateCustomers();
    } catch {
      toast.error("Failed to deactivate");
    } finally {
      setDeleting(false);
      setDeleteCustomer(null);
    }
  };

  const handleExport = () => {
    const rows = [
      ["UID", "Name", "Type", "Phone", "Email", "City", "State", "KYC Status", "Status"],
      ...filtered.map(c => [
        c.uid, c.name, c.type || "individual", c.phone, c.email,
        c.city || "", c.state || "", c.kyc_status || "pending", c.status || "active",
      ]),
    ];
    const csv = rows.map(r => r.map(v => `"${v}"`).join(",")).join("\n");
    const blob = new Blob([csv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `customers-${new Date().toISOString().split("T")[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    toast.success(`Exported ${filtered.length} customers`);
  };

  return (
    <motion.div {...pageTransition} className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-heading font-bold text-foreground uppercase tracking-wider flex items-center gap-2">
            <Users className="w-6 h-6 text-primary" />
            All Entities
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            Unified customer registry — {metrics.total} total entities
          </p>
        </div>
        <div className="flex gap-2 flex-wrap">
          <Button variant="outline" size="sm" onClick={handleExport} className="gap-2">
            <Download className="w-4 h-4" /> Export
          </Button>
          {(role === "admin" || role === "manager") && (
            <Button variant="outline" size="sm" onClick={() => setBulkImportOpen(true)} className="gap-2">
              <Upload className="w-4 h-4" /> Bulk Import
            </Button>
          )}
          {(role === "admin" || role === "manager") && (
            <Button size="sm" onClick={() => router.push("/dashboard/customers/new")} className="gap-2">
              <UserPlus className="w-4 h-4" /> Add Customer
            </Button>
          )}
        </div>
      </div>

      {/* Metrics Bar */}
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3">
        {[
          { label: "Total", value: metrics.total, icon: Users, color: "text-foreground" },
          { label: "Active", value: metrics.active, icon: Check, color: "text-green-400" },
          { label: "Individual", value: metrics.individual, icon: User, color: "text-blue-400" },
          { label: "Corporate", value: metrics.corporate, icon: Building2, color: "text-amber-400" },
          { label: "SME", value: metrics.sme, icon: Building2, color: "text-purple-400" },
          { label: "Other", value: metrics.other, icon: Users, color: "text-gray-400" },
        ].map(({ label, value, icon: Icon, color }) => (
          <div key={label} className="bg-card border border-border rounded-xl p-4 flex flex-col gap-1">
            <div className="flex items-center gap-1.5">
              <Icon className={`w-3.5 h-3.5 ${color}`} />
              <p className="text-xs text-muted-foreground font-heading uppercase tracking-wider">{label}</p>
            </div>
            <p className={`text-2xl font-bold ${color}`}>{isLoading ? "—" : value}</p>
          </div>
        ))}
      </div>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Search by name, UID, phone, email, city..."
            value={searchQuery}
            onChange={e => { setSearchQuery(e.target.value); setCurrentPage(1); }}
            className="pl-9"
          />
          {searchQuery && (
            <button onClick={() => setSearchQuery("")} className="absolute right-3 top-1/2 -translate-y-1/2">
              <X className="w-4 h-4 text-muted-foreground hover:text-foreground" />
            </button>
          )}
        </div>

        {/* Type filter */}
        <Select value={typeFilter} onValueChange={v => { setTypeFilter(v); setCurrentPage(1); }}>
          <SelectTrigger className="w-[160px]">
            <SelectValue placeholder="All Types" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Types</SelectItem>
            {Object.entries(TYPE_LABELS).map(([k, v]) => (
              <SelectItem key={k} value={k}>{v}</SelectItem>
            ))}
          </SelectContent>
        </Select>

        {/* Show inactive toggle */}
        <Button
          variant={showInactive ? "default" : "outline"}
          size="sm"
          onClick={() => setShowInactive(!showInactive)}
          className="gap-2 whitespace-nowrap"
        >
          <Filter className="w-4 h-4" />
          {showInactive ? "Hiding Inactive" : "Show Inactive"}
        </Button>
      </div>

      {/* Type filter chips */}
      <div className="flex gap-2 flex-wrap">
        {["all", "individual", "corporate", "sme", "government", "contractor", "other"].map(t => (
          <button
            key={t}
            onClick={() => { setTypeFilter(t); setCurrentPage(1); }}
            className={`px-3 py-1 rounded-full text-xs font-medium border transition-colors ${
              typeFilter === t
                ? "bg-primary text-primary-foreground border-primary"
                : "bg-muted/30 text-muted-foreground border-border hover:border-primary/50"
            }`}
          >
            {t === "all" ? "All" : TYPE_LABELS[t] || t}
          </button>
        ))}
      </div>

      {/* Table */}
      <div className="bg-card border border-border rounded-xl overflow-hidden">
        {isLoading ? (
          <div className="p-6 space-y-3">
            {[...Array(8)].map((_, i) => <Skeleton key={i} className="h-12 w-full" />)}
          </div>
        ) : paginated.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 gap-4">
            <Users className="w-12 h-12 text-muted-foreground/40" />
            <p className="text-muted-foreground">
              {searchQuery || typeFilter !== "all" ? "No customers match your filters." : "No customers yet."}
            </p>
            {(role === "admin" || role === "manager") && (
              <Button onClick={() => router.push("/dashboard/customers/new")} className="gap-2">
                <UserPlus className="w-4 h-4" /> Add First Customer
              </Button>
            )}
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow className="border-border hover:bg-transparent">
                <TableHead className="text-xs uppercase tracking-wider font-heading">UID</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Name</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden md:table-cell">Type</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden sm:table-cell">Phone</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden lg:table-cell">City</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden lg:table-cell">KYC</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden xl:table-cell">Status</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {paginated.map(customer => (
                <TableRow
                  key={customer.id}
                  className="border-border hover:bg-muted/30 cursor-pointer"
                  onClick={() => router.push(`/dashboard/customers/${customer.id}`)}
                >
                  <TableCell>
                    <button
                      onClick={e => { e.stopPropagation(); handleCopyUID(customer.uid); }}
                      className="flex items-center gap-1.5 group"
                    >
                      <Badge variant="secondary" className="font-mono text-primary bg-primary/10 text-xs">
                        {customer.uid}
                      </Badge>
                      {copiedUID === customer.uid
                        ? <Check className="w-3 h-3 text-green-400" />
                        : <Copy className="w-3 h-3 text-muted-foreground opacity-0 group-hover:opacity-100 transition-opacity" />
                      }
                    </button>
                  </TableCell>
                  <TableCell>
                    <div className="flex items-center gap-2">
                      <div className="w-7 h-7 rounded-full bg-primary/10 flex items-center justify-center flex-shrink-0">
                        <span className="text-xs font-bold text-primary">
                          {customer.name?.charAt(0)?.toUpperCase() || "?"}
                        </span>
                      </div>
                      <span className="font-medium text-sm truncate max-w-[160px]">{customer.name}</span>
                    </div>
                  </TableCell>
                  <TableCell className="hidden md:table-cell">
                    <Badge variant="outline" className={`text-xs ${TYPE_COLORS[customer.type] || TYPE_COLORS.other}`}>
                      {TYPE_LABELS[customer.type] || customer.type || "Individual"}
                    </Badge>
                  </TableCell>
                  <TableCell className="hidden sm:table-cell text-sm text-muted-foreground">
                    {customer.phone}
                  </TableCell>
                  <TableCell className="hidden lg:table-cell text-sm text-muted-foreground">
                    {customer.city || "—"}
                  </TableCell>
                  <TableCell className="hidden lg:table-cell">
                    <Badge variant="outline" className={`text-xs ${KYC_COLORS[customer.kyc_status || "pending"]}`}>
                      <Shield className="w-3 h-3 mr-1" />
                      {customer.kyc_status || "pending"}
                    </Badge>
                  </TableCell>
                  <TableCell className="hidden xl:table-cell">
                    <Badge variant="outline" className={`text-xs ${
                      customer.status === "inactive"
                        ? "bg-red-500/10 text-red-400 border-red-500/20"
                        : "bg-green-500/10 text-green-400 border-green-500/20"
                    }`}>
                      {customer.status || "active"}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-right" onClick={e => e.stopPropagation()}>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                          <MoreHorizontal className="w-4 h-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem onClick={() => router.push(`/dashboard/customers/${customer.id}`)}>
                          <Eye className="w-4 h-4 mr-2" /> View 360
                        </DropdownMenuItem>
                        {(role === "admin" || role === "manager") && (
                          <DropdownMenuItem onClick={() => { setEditCustomer(customer); setFormOpen(true); }}>
                            <Pencil className="w-4 h-4 mr-2" /> Edit
                          </DropdownMenuItem>
                        )}
                        <DropdownMenuItem onClick={() => router.push(`/dashboard/policies?customer=${customer.id}`)}>
                          <Plus className="w-4 h-4 mr-2" /> Create Policy
                        </DropdownMenuItem>
                        <DropdownMenuSeparator />
                        {role === "admin" && (
                          <DropdownMenuItem
                            onClick={() => setDeleteCustomer(customer)}
                            className="text-red-400 focus:text-red-400"
                          >
                            <Trash2 className="w-4 h-4 mr-2" /> Deactivate
                          </DropdownMenuItem>
                        )}
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <p className="text-sm text-muted-foreground">
            Showing {(currentPage - 1) * PAGE_SIZE + 1}–{Math.min(currentPage * PAGE_SIZE, filtered.length)} of {filtered.length}
          </p>
          <div className="flex gap-2">
            <Button variant="outline" size="sm" disabled={currentPage === 1} onClick={() => setCurrentPage(p => p - 1)}>
              Previous
            </Button>
            <Button variant="outline" size="sm" disabled={currentPage === totalPages} onClick={() => setCurrentPage(p => p + 1)}>
              Next
            </Button>
          </div>
        </div>
      )}

      {/* Edit dialog */}
      <CustomerForm
        open={formOpen}
        onOpenChange={open => { setFormOpen(open); if (!open) setEditCustomer(null); }}
        editData={editCustomer}
        onSuccess={() => { setFormOpen(false); setEditCustomer(null); }}
      />

      {/* Bulk import */}
      <CustomerBulkImport open={bulkImportOpen} onOpenChange={setBulkImportOpen} />

      {/* Deactivate confirmation */}
      <AlertDialog open={!!deleteCustomer} onOpenChange={open => !open && setDeleteCustomer(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle className="font-heading uppercase tracking-wider">Deactivate Customer</AlertDialogTitle>
            <AlertDialogDescription>
              Deactivate <strong>{deleteCustomer?.name}</strong> ({deleteCustomer?.uid})?
              This will cancel active policies, pending premiums, commissions, and renewals.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} disabled={deleting} className="bg-red-600 hover:bg-red-700">
              {deleting && <Loader2 className="w-4 h-4 animate-spin mr-2" />}
              Deactivate
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </motion.div>
  );
}

"use client";

import { useState } from "react";
import { useParams, useRouter } from "next/navigation";
import useSWR from "swr";
import { motion } from "framer-motion";
import { ArrowLeft, Plus, Shield, MoreHorizontal, Eye } from "lucide-react";
import { format } from "date-fns";

import { useAuth } from "@/lib/context/auth-context";
import { pageTransition } from "@/lib/helpers/animations";
import { FleetClaimForm } from "@/components/fleet/FleetClaimForm";

import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

const STATUS_COLORS: Record<string, string> = {
  registered: "bg-blue-500/10 text-blue-400",
  surveyor_appointed: "bg-purple-500/10 text-purple-400",
  assessment_done: "bg-amber-500/10 text-amber-400",
  approved: "bg-green-500/10 text-green-400",
  settled: "bg-emerald-500/10 text-emerald-400",
  rejected: "bg-red-500/10 text-red-400",
};

async function fetchClaims(customerId: string, token: string) {
  const res = await fetch(`/api/fleet/${customerId}/claims`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) throw new Error("Failed to fetch claims");
  return res.json();
}

export default function FleetClaimsPage() {
  const params = useParams();
  const router = useRouter();
  const { session, role } = useAuth();
  const token = session?.access_token ?? "";
  const customerId = params.customerId as string;

  const [addOpen, setAddOpen] = useState(false);

  const { data, isLoading, mutate } = useSWR(
    token ? `fleet-claims-${customerId}` : null,
    () => fetchClaims(customerId, token),
    { revalidateOnFocus: false }
  );

  const claims = data?.data ?? [];
  const canEdit = role === "admin" || role === "manager";

  return (
    <motion.div {...pageTransition} className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="sm" onClick={() => router.push(`/dashboard/fleet/${customerId}/vehicles`)} className="gap-2">
            <ArrowLeft className="w-4 h-4" />
          </Button>
          <div>
            <h1 className="text-xl font-heading font-bold uppercase tracking-wider flex items-center gap-2">
              <Shield className="w-5 h-5 text-primary" />
              Fleet Claims
            </h1>
            <p className="text-sm text-muted-foreground">{claims.length} claims</p>
          </div>
        </div>
        {canEdit && (
          <Button size="sm" onClick={() => setAddOpen(true)} className="gap-2">
            <Plus className="w-4 h-4" /> New Claim
          </Button>
        )}
      </div>

      <div className="bg-card border border-border rounded-xl overflow-hidden">
        {isLoading ? (
          <div className="p-6 space-y-3">
            {[...Array(5)].map((_, i) => <Skeleton key={i} className="h-12 w-full" />)}
          </div>
        ) : claims.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 gap-4">
            <Shield className="w-10 h-10 text-muted-foreground/40" />
            <p className="text-muted-foreground text-sm">No claims registered yet.</p>
            {canEdit && (
              <Button size="sm" onClick={() => setAddOpen(true)} className="gap-2">
                <Plus className="w-4 h-4" /> Register First Claim
              </Button>
            )}
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow className="border-border hover:bg-transparent">
                <TableHead className="text-xs uppercase tracking-wider font-heading">Claim Number</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden md:table-cell">Vehicle</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Amount</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Status</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden md:table-cell">Surveyor</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden sm:table-cell">Date</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {claims.map((c: any) => (
                <TableRow
                  key={c.id}
                  className="border-border hover:bg-muted/30 cursor-pointer"
                  onClick={() => router.push(`/dashboard/claims/${c.id}`)}
                >
                  <TableCell className="font-mono text-sm font-medium">{c.claim_number}</TableCell>
                  <TableCell className="hidden md:table-cell text-sm text-muted-foreground">
                    {c.customer_name || "—"}
                  </TableCell>
                  <TableCell className="text-sm font-medium">
                    {c.claim_amount ? `₹${Number(c.claim_amount).toLocaleString("en-IN")}` : "—"}
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline" className={`text-xs ${STATUS_COLORS[c.status] || ""}`}>
                      {c.status?.replace(/_/g, " ")}
                    </Badge>
                  </TableCell>
                  <TableCell className="hidden md:table-cell text-sm text-muted-foreground">
                    {c.surveyor_name || "—"}
                  </TableCell>
                  <TableCell className="hidden sm:table-cell text-sm text-muted-foreground">
                    {c.claim_date ? format(new Date(c.claim_date), "dd MMM yyyy") : "—"}
                  </TableCell>
                  <TableCell className="text-right" onClick={e => e.stopPropagation()}>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                          <MoreHorizontal className="w-4 h-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem onClick={() => router.push(`/dashboard/claims/${c.id}`)}>
                          <Eye className="w-4 h-4 mr-2" /> View Detail
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </div>

      <FleetClaimForm
        open={addOpen}
        onOpenChange={setAddOpen}
        customerId={customerId}
        onSuccess={() => mutate()}
      />
    </motion.div>
  );
}

"use client";

import { useState } from "react";
import { useParams, useRouter } from "next/navigation";
import useSWR from "swr";
import { motion } from "framer-motion";
import {
  ArrowLeft, Plus, Search, X, User, Loader2,
  MoreHorizontal, Pencil, Trash2, AlertTriangle,
} from "lucide-react";
import { toast } from "sonner";
import { format, differenceInDays } from "date-fns";

import { useAuth } from "@/lib/context/auth-context";
import { pageTransition } from "@/lib/helpers/animations";
import { DriverForm } from "@/components/fleet/DriverForm";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from "@/components/ui/alert-dialog";

function getExpiryColor(daysLeft: number): string {
  if (daysLeft < 0) return "bg-red-500/10 text-red-400";
  if (daysLeft <= 30) return "bg-orange-500/10 text-orange-400";
  return "bg-green-500/10 text-green-400";
}

function getExpiryLabel(daysLeft: number): string {
  if (daysLeft < 0) return `Expired ${Math.abs(daysLeft)}d ago`;
  if (daysLeft === 0) return "Expires today";
  return `${daysLeft}d remaining`;
}

async function fetchDrivers(customerId: string, token: string) {
  const res = await fetch(`/api/fleet/${customerId}/drivers`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) throw new Error("Failed to fetch drivers");
  return res.json();
}

export default function FleetDriversPage() {
  const params = useParams();
  const router = useRouter();
  const { session, role } = useAuth();
  const token = session?.access_token ?? "";
  const customerId = params.customerId as string;

  const [search, setSearch] = useState("");
  const [addOpen, setAddOpen] = useState(false);
  const [editDriver, setEditDriver] = useState<any>(null);
  const [deleteTarget, setDeleteTarget] = useState<any>(null);
  const [deleting, setDeleting] = useState(false);

  const { data, isLoading, mutate } = useSWR(
    token ? `fleet-drivers-${customerId}` : null,
    () => fetchDrivers(customerId, token),
    { revalidateOnFocus: false }
  );

  const drivers = (data?.data ?? []).filter((d: any) => {
    if (!search.trim()) return true;
    const q = search.toLowerCase();
    return d.name?.toLowerCase().includes(q) || d.license_number?.toLowerCase().includes(q);
  });

  const handleDelete = async () => {
    if (!deleteTarget) return;
    setDeleting(true);
    try {
      const res = await fetch(`/api/fleet/${customerId}/drivers/${deleteTarget.id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || "Failed to delete driver");
      }
      toast.success("Driver deleted");
      setDeleteTarget(null);
      mutate();
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setDeleting(false);
    }
  };

  const canEdit = role === "admin" || role === "manager";

  return (
    <motion.div {...pageTransition} className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="sm" onClick={() => router.push(`/dashboard/fleet/${customerId}/vehicles`)} className="gap-2">
            <ArrowLeft className="w-4 h-4" />
          </Button>
          <div>
            <h1 className="text-xl font-heading font-bold uppercase tracking-wider flex items-center gap-2">
              <User className="w-5 h-5 text-primary" />
              Fleet Drivers
            </h1>
            <p className="text-sm text-muted-foreground">{drivers.length} drivers</p>
          </div>
        </div>
        {canEdit && (
          <Button size="sm" onClick={() => setAddOpen(true)} className="gap-2">
            <Plus className="w-4 h-4" /> Add Driver
          </Button>
        )}
      </div>

      {/* Search */}
      <div className="relative max-w-md">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
        <Input
          placeholder="Search by name or license number..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          className="pl-9"
        />
        {search && (
          <button onClick={() => setSearch("")} className="absolute right-3 top-1/2 -translate-y-1/2">
            <X className="w-4 h-4 text-muted-foreground" />
          </button>
        )}
      </div>

      {/* Table */}
      <div className="bg-card border border-border rounded-xl overflow-hidden">
        {isLoading ? (
          <div className="p-6 space-y-3">
            {[...Array(5)].map((_, i) => <Skeleton key={i} className="h-12 w-full" />)}
          </div>
        ) : drivers.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 gap-4">
            <User className="w-10 h-10 text-muted-foreground/40" />
            <p className="text-muted-foreground text-sm">No drivers found.</p>
            {canEdit && (
              <Button size="sm" onClick={() => setAddOpen(true)} className="gap-2">
                <Plus className="w-4 h-4" /> Add First Driver
              </Button>
            )}
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow className="border-border hover:bg-transparent">
                <TableHead className="text-xs uppercase tracking-wider font-heading">Name</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">License Number</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden md:table-cell">License Expiry</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden sm:table-cell">Mobile</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Status</TableHead>
                {canEdit && <TableHead className="text-xs uppercase tracking-wider font-heading text-right">Actions</TableHead>}
              </TableRow>
            </TableHeader>
            <TableBody>
              {drivers.map((d: any) => {
                const daysLeft = d.license_expiry
                  ? differenceInDays(new Date(d.license_expiry), new Date())
                  : 999;
                return (
                  <TableRow key={d.id} className="border-border hover:bg-muted/30">
                    <TableCell>
                      <div className="flex items-center gap-2">
                        <div className="w-7 h-7 rounded-full bg-primary/10 flex items-center justify-center flex-shrink-0">
                          <span className="text-xs font-bold text-primary">{d.name?.charAt(0)?.toUpperCase()}</span>
                        </div>
                        <span className="text-sm font-medium">{d.name}</span>
                      </div>
                    </TableCell>
                    <TableCell className="font-mono text-sm">{d.license_number}</TableCell>
                    <TableCell className="hidden md:table-cell text-sm text-muted-foreground">
                      {d.license_expiry ? format(new Date(d.license_expiry), "dd MMM yyyy") : "—"}
                    </TableCell>
                    <TableCell className="hidden sm:table-cell text-sm text-muted-foreground">
                      {d.mobile || "—"}
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline" className={`text-xs ${getExpiryColor(daysLeft)}`}>
                        {daysLeft < 0 && <AlertTriangle className="w-3 h-3 mr-1" />}
                        {getExpiryLabel(daysLeft)}
                      </Badge>
                    </TableCell>
                    {canEdit && (
                      <TableCell className="text-right">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                              <MoreHorizontal className="w-4 h-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem onClick={() => setEditDriver(d)}>
                              <Pencil className="w-4 h-4 mr-2" /> Edit
                            </DropdownMenuItem>
                            <DropdownMenuItem
                              onClick={() => setDeleteTarget(d)}
                              className="text-red-400 focus:text-red-400"
                            >
                              <Trash2 className="w-4 h-4 mr-2" /> Delete
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    )}
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        )}
      </div>

      {/* Add Driver Dialog */}
      <DriverForm
        open={addOpen}
        onOpenChange={setAddOpen}
        customerId={customerId}
        onSuccess={() => mutate()}
      />

      {/* Edit Driver Dialog */}
      <DriverForm
        open={!!editDriver}
        onOpenChange={open => !open && setEditDriver(null)}
        customerId={customerId}
        editData={editDriver}
        onSuccess={() => { mutate(); setEditDriver(null); }}
      />

      {/* Delete Confirmation */}
      <AlertDialog open={!!deleteTarget} onOpenChange={open => !open && setDeleteTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle className="font-heading uppercase tracking-wider">Delete Driver</AlertDialogTitle>
            <AlertDialogDescription>
              Delete driver <strong>{deleteTarget?.name}</strong> ({deleteTarget?.license_number})?
              This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} disabled={deleting} className="bg-red-600 hover:bg-red-700">
              {deleting && <Loader2 className="w-4 h-4 animate-spin mr-2" />}
              Delete Driver
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </motion.div>
  );
}

"use client";

import { useState } from "react";
import { useParams, useRouter } from "next/navigation";
import useSWR from "swr";
import { motion } from "framer-motion";
import { ArrowLeft, ShieldCheck, AlertTriangle, Clock, CheckCircle, Filter } from "lucide-react";
import { format } from "date-fns";

import { useAuth } from "@/lib/context/auth-context";
import { pageTransition } from "@/lib/helpers/animations";

import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";

const DOC_TYPE_LABELS: Record<string, string> = {
  permit_state: "Permit (State)",
  permit_national: "Permit (National)",
  fitness: "Fitness",
  puc: "PUC",
  rc: "RC",
  tax_state: "Tax (State)",
  tax_national: "Tax (National)",
};

function getRowColor(daysLeft: number): string {
  if (daysLeft < 0) return "bg-red-500/5 border-l-2 border-l-red-500";
  if (daysLeft <= 7) return "bg-orange-500/5 border-l-2 border-l-orange-500";
  if (daysLeft <= 15) return "bg-yellow-500/5 border-l-2 border-l-yellow-500";
  return "bg-amber-500/5 border-l-2 border-l-amber-400";
}

async function fetchValidity(customerId: string, token: string, params: string) {
  const res = await fetch(`/api/fleet/${customerId}/validity?${params}`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) throw new Error("Failed to fetch validity data");
  return res.json();
}

export default function FleetValidityPage() {
  const params = useParams();
  const router = useRouter();
  const { session } = useAuth();
  const token = session?.access_token ?? "";
  const customerId = params.customerId as string;

  const [docTypeFilter, setDocTypeFilter] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("");

  const queryParams = new URLSearchParams({
    document_type: docTypeFilter,
    vehicle_category: categoryFilter,
  }).toString();

  const { data, isLoading } = useSWR(
    token ? `fleet-validity-${customerId}-${queryParams}` : null,
    () => fetchValidity(customerId, token, queryParams),
    { revalidateOnFocus: false }
  );

  const validityDocs = data?.data ?? [];
  const summary = data?.summary ?? { expired: 0, expiring_7: 0, expiring_15: 0, expiring_30: 0 };

  return (
    <motion.div {...pageTransition} className="space-y-6">
      <div className="flex items-center gap-3">
        <Button variant="ghost" size="sm" onClick={() => router.push(`/dashboard/fleet/${customerId}/vehicles`)} className="gap-2">
          <ArrowLeft className="w-4 h-4" />
        </Button>
        <div>
          <h1 className="text-xl font-heading font-bold uppercase tracking-wider flex items-center gap-2">
            <ShieldCheck className="w-5 h-5 text-primary" />
            Validity Dashboard
          </h1>
          <p className="text-sm text-muted-foreground">Track expiring vehicle documents</p>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        {[
          { label: "Expired", value: summary.expired, color: "text-red-400", bg: "bg-red-500/10", icon: AlertTriangle },
          { label: "≤ 7 Days", value: summary.expiring_7, color: "text-orange-400", bg: "bg-orange-500/10", icon: AlertTriangle },
          { label: "≤ 15 Days", value: summary.expiring_15, color: "text-yellow-400", bg: "bg-yellow-500/10", icon: Clock },
          { label: "≤ 30 Days", value: summary.expiring_30, color: "text-amber-400", bg: "bg-amber-500/10", icon: Clock },
        ].map(({ label, value, color, bg, icon: Icon }) => (
          <div key={label} className="bg-card border border-border rounded-xl p-4">
            <div className={`w-9 h-9 rounded-lg ${bg} flex items-center justify-center mb-2`}>
              <Icon className={`w-4 h-4 ${color}`} />
            </div>
            <p className={`text-2xl font-bold ${color}`}>{value}</p>
            <p className="text-xs text-muted-foreground mt-0.5">{label}</p>
          </div>
        ))}
      </div>

      {/* Filters */}
      <div className="flex gap-3 flex-wrap">
        <Select value={docTypeFilter} onValueChange={setDocTypeFilter}>
          <SelectTrigger className="w-[180px]"><SelectValue placeholder="All Document Types" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="">All Document Types</SelectItem>
            {Object.entries(DOC_TYPE_LABELS).map(([k, v]) => (
              <SelectItem key={k} value={k}>{v}</SelectItem>
            ))}
          </SelectContent>
        </Select>
        <Select value={categoryFilter} onValueChange={setCategoryFilter}>
          <SelectTrigger className="w-[160px]"><SelectValue placeholder="All Categories" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="">All Categories</SelectItem>
            <SelectItem value="Two-wheeler">Two-wheeler</SelectItem>
            <SelectItem value="Four-wheeler">Four-wheeler</SelectItem>
            <SelectItem value="Commercial">Commercial</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {/* Table */}
      <div className="bg-card border border-border rounded-xl overflow-hidden">
        {isLoading ? (
          <div className="p-6 space-y-3">
            {[...Array(5)].map((_, i) => <Skeleton key={i} className="h-12 w-full" />)}
          </div>
        ) : validityDocs.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 gap-4">
            <CheckCircle className="w-10 h-10 text-green-400/40" />
            <p className="text-muted-foreground text-sm">No expiring documents in the next 30 days.</p>
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow className="border-border hover:bg-transparent">
                <TableHead className="text-xs uppercase tracking-wider font-heading">Registration #</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden sm:table-cell">Make / Model</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Document Type</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Expiry Date</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Days Remaining</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Status</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {validityDocs.map((doc: any) => (
                <TableRow key={doc.id} className={`border-border ${getRowColor(doc.days_remaining)}`}>
                  <TableCell className="font-mono text-sm font-medium">
                    {doc.vehicle?.registration_number || "—"}
                  </TableCell>
                  <TableCell className="hidden sm:table-cell text-sm text-muted-foreground">
                    {doc.vehicle ? `${doc.vehicle.make} ${doc.vehicle.model}` : "—"}
                  </TableCell>
                  <TableCell className="text-sm">
                    {DOC_TYPE_LABELS[doc.document_type] || doc.document_type}
                  </TableCell>
                  <TableCell className="text-sm">
                    {doc.expiry_date ? format(new Date(doc.expiry_date), "dd MMM yyyy") : "—"}
                  </TableCell>
                  <TableCell>
                    <span className={`text-sm font-bold ${
                      doc.days_remaining < 0 ? "text-red-400"
                      : doc.days_remaining <= 7 ? "text-orange-400"
                      : doc.days_remaining <= 15 ? "text-yellow-400"
                      : "text-amber-400"
                    }`}>
                      {doc.days_remaining < 0 ? `${Math.abs(doc.days_remaining)}d overdue` : `${doc.days_remaining}d`}
                    </span>
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline" className={`text-xs ${
                      doc.status === "expired" ? "bg-red-500/10 text-red-400"
                      : "bg-amber-500/10 text-amber-400"
                    }`}>
                      {doc.status?.replace(/_/g, " ")}
                    </Badge>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </div>
    </motion.div>
  );
}

"use client";

import { useState } from "react";
import { useParams, useRouter } from "next/navigation";
import useSWR from "swr";
import { motion } from "framer-motion";
import {
  ArrowLeft, Plus, Search, X, Upload, Car,
  Loader2, MoreHorizontal, Trash2, ShieldCheck,
} from "lucide-react";
import { toast } from "sonner";

import { useAuth } from "@/lib/context/auth-context";
import { pageTransition } from "@/lib/helpers/animations";
import { Policy } from "@/lib/types";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter,
} from "@/components/ui/dialog";
import {
  DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from "@/components/ui/alert-dialog";

interface FleetVehicle {
  id: string;
  registration_number: string;
  make: string;
  model: string;
  variant?: string;
  fuel_type?: string;
  mfg_year?: number;
  vehicle_category?: string;
  idv?: number;
  status: string;
  fleet_drivers?: { name: string };
}

const STATUS_COLORS: Record<string, string> = {
  Active: "bg-green-500/10 text-green-400",
  Inactive: "bg-amber-500/10 text-amber-400",
  Deleted: "bg-red-500/10 text-red-400",
};

async function fetchVehicles(customerId: string, token: string, params: string) {
  const res = await fetch(`/api/fleet/${customerId}/vehicles?${params}`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) throw new Error("Failed to fetch vehicles");
  return res.json();
}

export default function FleetVehiclesPage() {
  const params = useParams();
  const router = useRouter();
  const { session, role } = useAuth();
  const token = session?.access_token ?? "";
  const customerId = params.customerId as string;

  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("Active");
  const [categoryFilter, setCategoryFilter] = useState("");
  const [page, setPage] = useState(1);
  const [addOpen, setAddOpen] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<FleetVehicle | null>(null);
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState(false);

  const queryParams = new URLSearchParams({
    search, status: statusFilter, category: categoryFilter, page: String(page), limit: "50",
  }).toString();

  const { data: vehiclesData, isLoading, mutate } = useSWR(
    token ? `fleet-vehicles-${customerId}-${queryParams}` : null,
    () => fetchVehicles(customerId, token, queryParams),
    { revalidateOnFocus: false }
  );

  const vehicles = (vehiclesData?.data ?? []) as FleetVehicle[];
  const total = vehiclesData?.total ?? 0;

  const [form, setForm] = useState({
    registration_number: "", make: "", model: "", variant: "",
    fuel_type: "", mfg_year: "", vehicle_category: "", idv: "",
    seating_capacity: "", gvw: "", policy_id: "",
  });

  const { data: policiesData } = useSWR(
    token ? `policies-fleet-${customerId}` : null,
    async () => {
      // Actually fetch policies
      const pRes = await fetch(`/api/policies?customer_id=${customerId}&limit=50`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!pRes.ok) return [];
      const d = await pRes.json();
      return (d.data ?? []) as Policy[];
    },
    { revalidateOnFocus: false }
  );

  const handleAdd = async () => {
    if (!form.registration_number || !form.make || !form.model || !form.policy_id) {
      toast.error("Registration Number, Make, Model, and Policy are required");
      return;
    }
    setSaving(true);
    try {
      const res = await fetch(`/api/fleet/${customerId}/vehicles`, {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({
          ...form,
          mfg_year: form.mfg_year ? Number(form.mfg_year) : null,
          idv: form.idv ? Number(form.idv) : null,
          seating_capacity: form.seating_capacity ? Number(form.seating_capacity) : null,
          gvw: form.gvw ? Number(form.gvw) : null,
        }),
      });
      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || "Failed to add vehicle");
      }
      toast.success("Vehicle added successfully");
      setAddOpen(false);
      setForm({ registration_number: "", make: "", model: "", variant: "", fuel_type: "", mfg_year: "", vehicle_category: "", idv: "", seating_capacity: "", gvw: "", policy_id: "" });
      void mutate();
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Failed to add vehicle");
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!deleteTarget) return;
    setDeleting(true);
    try {
      const res = await fetch(`/api/fleet/${customerId}/vehicles/${deleteTarget.id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || "Failed to delete vehicle");
      }
      toast.success("Vehicle deleted and endorsement created");
      setDeleteTarget(null);
      void mutate();
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Failed to delete vehicle");
    } finally {
      setDeleting(false);
    }
  };

  const canEdit = role === "admin" || role === "manager";

  return (
    <motion.div {...pageTransition} className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="sm" onClick={() => router.push("/dashboard/fleet")} className="gap-2">
            <ArrowLeft className="w-4 h-4" />
          </Button>
          <div>
            <h1 className="text-xl font-heading font-bold uppercase tracking-wider flex items-center gap-2">
              <Car className="w-5 h-5 text-primary" />
              Fleet Vehicles
            </h1>
            <p className="text-sm text-muted-foreground">{total} vehicles</p>
          </div>
        </div>
        {canEdit && (
          <div className="flex gap-2">
            <Button variant="outline" size="sm" onClick={() => router.push(`/dashboard/fleet/${customerId}/validity`)} className="gap-2">
              <ShieldCheck className="w-4 h-4" /> Validity Dashboard
            </Button>
            <Button size="sm" onClick={() => setAddOpen(true)} className="gap-2">
              <Plus className="w-4 h-4" /> Add Vehicle
            </Button>
          </div>
        )}
      </div>

      {/* Filters */}
      <div className="flex gap-3 flex-wrap">
        <div className="relative flex-1 min-w-[200px]">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Search by registration, make, model..."
            value={search}
            onChange={e => { setSearch(e.target.value); setPage(1); }}
            className="pl-9"
          />
          {search && <button onClick={() => setSearch("")} className="absolute right-3 top-1/2 -translate-y-1/2"><X className="w-4 h-4 text-muted-foreground" /></button>}
        </div>
        <Select value={statusFilter} onValueChange={v => { setStatusFilter(v); setPage(1); }}>
          <SelectTrigger className="w-[130px]"><SelectValue /></SelectTrigger>
          <SelectContent>
            <SelectItem value="Active">Active</SelectItem>
            <SelectItem value="Inactive">Inactive</SelectItem>
            <SelectItem value="">All</SelectItem>
          </SelectContent>
        </Select>
        <Select value={categoryFilter} onValueChange={v => { setCategoryFilter(v); setPage(1); }}>
          <SelectTrigger className="w-[160px]"><SelectValue placeholder="All Categories" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="">All Categories</SelectItem>
            <SelectItem value="Two-wheeler">Two-wheeler</SelectItem>
            <SelectItem value="Four-wheeler">Four-wheeler</SelectItem>
            <SelectItem value="Commercial">Commercial</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {/* Table */}
      <div className="bg-card border border-border rounded-xl overflow-hidden">
        {isLoading ? (
          <div className="p-6 space-y-3">
            {[...Array(5)].map((_, i) => <Skeleton key={i} className="h-12 w-full" />)}
          </div>
        ) : vehicles.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 gap-4">
            <Car className="w-10 h-10 text-muted-foreground/40" />
            <p className="text-muted-foreground text-sm">No vehicles found.</p>
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow className="border-border hover:bg-transparent">
                <TableHead className="text-xs uppercase tracking-wider font-heading">Reg. Number</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Make / Model</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden md:table-cell">Category</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden md:table-cell">IDV</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden sm:table-cell">Driver</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Status</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {vehicles.map((v) => (
                <TableRow key={v.id} className="border-border hover:bg-muted/30">
                  <TableCell className="font-mono text-sm font-medium">{v.registration_number}</TableCell>
                  <TableCell>
                    <p className="text-sm font-medium">{v.make} {v.model}</p>
                    {v.variant && <p className="text-xs text-muted-foreground">{v.variant} · {v.mfg_year}</p>}
                  </TableCell>
                  <TableCell className="hidden md:table-cell">
                    <Badge variant="outline" className="text-xs">{v.vehicle_category || "—"}</Badge>
                  </TableCell>
                  <TableCell className="hidden md:table-cell text-sm text-muted-foreground">
                    {v.idv ? `₹${Number(v.idv).toLocaleString("en-IN")}` : "—"}
                  </TableCell>
                  <TableCell className="hidden sm:table-cell text-sm text-muted-foreground">
                    {v.fleet_drivers?.name || "Unassigned"}
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline" className={`text-xs ${STATUS_COLORS[v.status] || ""}`}>{v.status}</Badge>
                  </TableCell>
                  <TableCell className="text-right">
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                          <MoreHorizontal className="w-4 h-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem onClick={() => router.push(`/dashboard/fleet/${customerId}/validity`)}>
                          <ShieldCheck className="w-4 h-4 mr-2" /> View Validity
                        </DropdownMenuItem>
                        {canEdit && (
                          <DropdownMenuItem
                            onClick={() => setDeleteTarget(v)}
                            className="text-red-400 focus:text-red-400"
                          >
                            <Trash2 className="w-4 h-4 mr-2" /> Delete Vehicle
                          </DropdownMenuItem>
                        )}
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </div>

      {/* Add Vehicle Dialog */}
      <Dialog open={addOpen} onOpenChange={setAddOpen}>
        <DialogContent className="sm:max-w-lg max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="font-heading uppercase tracking-wider">Add Fleet Vehicle</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div className="space-y-1.5">
              <Label>Registration Number <span className="text-destructive">*</span></Label>
              <Input value={form.registration_number} onChange={e => setForm(f => ({ ...f, registration_number: e.target.value.toUpperCase() }))} placeholder="MH01AB1234" />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <Label>Make <span className="text-destructive">*</span></Label>
                <Input value={form.make} onChange={e => setForm(f => ({ ...f, make: e.target.value }))} placeholder="e.g. Tata" />
              </div>
              <div className="space-y-1.5">
                <Label>Model <span className="text-destructive">*</span></Label>
                <Input value={form.model} onChange={e => setForm(f => ({ ...f, model: e.target.value }))} placeholder="e.g. Nexon" />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <Label>Variant</Label>
                <Input value={form.variant} onChange={e => setForm(f => ({ ...f, variant: e.target.value }))} placeholder="e.g. XZ+" />
              </div>
              <div className="space-y-1.5">
                <Label>Fuel Type</Label>
                <Select value={form.fuel_type} onValueChange={v => setForm(f => ({ ...f, fuel_type: v }))}>
                  <SelectTrigger><SelectValue placeholder="Select" /></SelectTrigger>
                  <SelectContent>
                    {["Petrol", "Diesel", "CNG", "Electric", "Hybrid"].map(ft => (
                      <SelectItem key={ft} value={ft}>{ft}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="grid grid-cols-3 gap-4">
              <div className="space-y-1.5">
                <Label>MFG Year</Label>
                <Input type="number" value={form.mfg_year} onChange={e => setForm(f => ({ ...f, mfg_year: e.target.value }))} placeholder="2020" />
              </div>
              <div className="space-y-1.5">
                <Label>IDV (₹)</Label>
                <Input type="number" value={form.idv} onChange={e => setForm(f => ({ ...f, idv: e.target.value }))} placeholder="500000" />
              </div>
              <div className="space-y-1.5">
                <Label>Category</Label>
                <Select value={form.vehicle_category} onValueChange={v => setForm(f => ({ ...f, vehicle_category: v }))}>
                  <SelectTrigger><SelectValue placeholder="Select" /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="Two-wheeler">Two-wheeler</SelectItem>
                    <SelectItem value="Four-wheeler">Four-wheeler</SelectItem>
                    <SelectItem value="Commercial">Commercial</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="space-y-1.5">
              <Label>Policy <span className="text-destructive">*</span></Label>
              <Select value={form.policy_id} onValueChange={v => setForm(f => ({ ...f, policy_id: v }))}>
                <SelectTrigger><SelectValue placeholder="Select policy" /></SelectTrigger>
                <SelectContent>
                  {(policiesData ?? []).map((p) => (
                    <SelectItem key={p.id} value={p.id}>{p.policy_number} · {p.policy_type}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter>
            <Button variant="ghost" onClick={() => setAddOpen(false)}>Cancel</Button>
            <Button onClick={() => void handleAdd()} disabled={saving} className="gap-2">
              {saving && <Loader2 className="w-4 h-4 animate-spin" />}
              Add Vehicle
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation */}
      <AlertDialog open={!!deleteTarget} onOpenChange={open => !open && setDeleteTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle className="font-heading uppercase tracking-wider">Delete Vehicle</AlertDialogTitle>
            <AlertDialogDescription>
              Delete vehicle <strong>{deleteTarget?.registration_number}</strong>?
              This will create a deletion endorsement record.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={() => void handleDelete()} disabled={deleting} className="bg-red-600 hover:bg-red-700">
              {deleting && <Loader2 className="w-4 h-4 animate-spin mr-2" />}
              Delete Vehicle
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </motion.div>
  );
}

"use client";

import { useState } from "react";
import { useParams, useRouter } from "next/navigation";
import useSWR from "swr";
import { motion } from "framer-motion";
import { ArrowLeft, Plus, Shield, MoreHorizontal, Eye } from "lucide-react";
import { format } from "date-fns";

import { useAuth } from "@/lib/context/auth-context";
import { pageTransition } from "@/lib/helpers/animations";
import { GMCClaimForm } from "@/components/gmc/GMCClaimForm";

import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

const STATUS_COLORS: Record<string, string> = {
  registered: "bg-blue-500/10 text-blue-400",
  submitted_to_tpa: "bg-purple-500/10 text-purple-400",
  under_review: "bg-amber-500/10 text-amber-400",
  approved: "bg-green-500/10 text-green-400",
  settled: "bg-emerald-500/10 text-emerald-400",
  rejected: "bg-red-500/10 text-red-400",
};

async function fetchClaims(customerId: string, token: string) {
  const res = await fetch(`/api/gmc/${customerId}/claims`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) throw new Error("Failed to fetch claims");
  return res.json();
}

export default function GMCClaimsPage() {
  const params = useParams();
  const router = useRouter();
  const { session, role } = useAuth();
  const token = session?.access_token ?? "";
  const customerId = params.customerId as string;

  const [addOpen, setAddOpen] = useState(false);

  const { data, isLoading, mutate } = useSWR(
    token ? `gmc-claims-${customerId}` : null,
    () => fetchClaims(customerId, token),
    { revalidateOnFocus: false }
  );

  const claims = data?.data ?? [];
  const canEdit = role === "admin" || role === "manager";

  return (
    <motion.div {...pageTransition} className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="sm" onClick={() => router.push(`/dashboard/gmc/${customerId}/members`)} className="gap-2">
            <ArrowLeft className="w-4 h-4" />
          </Button>
          <div>
            <h1 className="text-xl font-heading font-bold uppercase tracking-wider flex items-center gap-2">
              <Shield className="w-5 h-5 text-primary" />
              GMC Claims
            </h1>
            <p className="text-sm text-muted-foreground">{claims.length} claims</p>
          </div>
        </div>
        {canEdit && (
          <Button size="sm" onClick={() => setAddOpen(true)} className="gap-2">
            <Plus className="w-4 h-4" /> New Claim
          </Button>
        )}
      </div>

      <div className="bg-card border border-border rounded-xl overflow-hidden">
        {isLoading ? (
          <div className="p-6 space-y-3">
            {[...Array(5)].map((_, i) => <Skeleton key={i} className="h-12 w-full" />)}
          </div>
        ) : claims.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 gap-4">
            <Shield className="w-10 h-10 text-muted-foreground/40" />
            <p className="text-muted-foreground text-sm">No claims registered yet.</p>
            {canEdit && (
              <Button size="sm" onClick={() => setAddOpen(true)} className="gap-2">
                <Plus className="w-4 h-4" /> Register First Claim
              </Button>
            )}
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow className="border-border hover:bg-transparent">
                <TableHead className="text-xs uppercase tracking-wider font-heading">Claim Number</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden md:table-cell">Member</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden md:table-cell">TPA</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Amount</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Status</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden sm:table-cell">Date</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {claims.map((c: any) => (
                <TableRow
                  key={c.id}
                  className="border-border hover:bg-muted/30 cursor-pointer"
                  onClick={() => router.push(`/dashboard/claims/${c.id}`)}
                >
                  <TableCell className="font-mono text-sm font-medium">{c.claim_number}</TableCell>
                  <TableCell className="hidden md:table-cell text-sm text-muted-foreground">
                    {c.customer_name || "—"}
                  </TableCell>
                  <TableCell className="hidden md:table-cell text-sm text-muted-foreground">
                    {c.remarks?.replace("TPA: ", "") || "—"}
                  </TableCell>
                  <TableCell className="text-sm font-medium">
                    {c.claim_amount ? `₹${Number(c.claim_amount).toLocaleString("en-IN")}` : "—"}
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline" className={`text-xs ${STATUS_COLORS[c.status] || ""}`}>
                      {c.status?.replace(/_/g, " ")}
                    </Badge>
                  </TableCell>
                  <TableCell className="hidden sm:table-cell text-sm text-muted-foreground">
                    {c.claim_date ? format(new Date(c.claim_date), "dd MMM yyyy") : "—"}
                  </TableCell>
                  <TableCell className="text-right" onClick={e => e.stopPropagation()}>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                          <MoreHorizontal className="w-4 h-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem onClick={() => router.push(`/dashboard/claims/${c.id}`)}>
                          <Eye className="w-4 h-4 mr-2" /> View Detail
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </div>

      <GMCClaimForm
        open={addOpen}
        onOpenChange={setAddOpen}
        customerId={customerId}
        onSuccess={() => mutate()}
      />
    </motion.div>
  );
}

