const STATUS_COLORS: Record<string, string> = {
  active: "bg-green-500/20 text-green-400 border-green-500/30",
  expired: "bg-red-500/20 text-red-400 border-red-500/30",
  cancelled: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30",
  archived: "bg-muted-foreground/20 text-muted-foreground border-muted-foreground/30",
};

export default function PolicyDetailPage() {
  const params = useParams();
  const router = useRouter();
  const { user } = useAuth();
  const { settings } = useAppSettings();
  const policyId = params.id as string;

  const { data: policy, isLoading, error, mutate } = usePolicy(policyId);
  const { data: customer } = useCustomer(policy?.customer_id || "");
  const { data: documents, isLoading: documentsLoading } = usePolicyDocuments(policyId);
  const { url: pdfSignedUrl } = useStorageUrl(policy?.pdf_url ?? null);

  const [showEdit, setShowEdit] = useState(false);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [remark, setRemark] = useState("");
  const [isSavingRemark, setIsSavingRemark] = useState(false);
  const [isLocking, setIsLocking] = useState(false);
  const [archiveDialog, setArchiveDialog] = useState(false);
  const [cancelDialog, setCancelDialog] = useState(false);
  const [isChangingStatus, setIsChangingStatus] = useState(false);

  const isAdminOrManager = user?.role === "admin" || user?.role === "manager";
  const isEmployee = user?.role === "employee";
  const isAssigned = policy?.assigned_to === user?.uid;

  function formatDate(timestamp: string | Date | null | undefined): string {
    if (!timestamp) return "—";
      const date = new Date(timestamp);
      return date.toLocaleDateString("en-IN", {
        day: "2-digit",
        month: "long",
        year: "numeric",
      });
    } catch {
      return "—";
    }
  }

  function getDaysUntilExpiry(policy: Policy): number | null {
    if (!policy.end_date) return null;
    try {
      const endMs = new Date(policy.end_date as string).getTime();
      return Math.ceil((endMs - Date.now()) / (1000 * 60 * 60 * 24));
    } catch {
      return null;
    }
  }

  async function copyToClipboard(text: string, field: string) {
    await navigator.clipboard.writeText(text);
    setCopiedField(field);
    setTimeout(() => setCopiedField(null), 2000);
  }

  async function handleSaveRemark() {
    if (!policy?.id || !user || !remark.trim()) return;
    setIsSavingRemark(true);
    try {
      await policyService.updateRemark(policy.id, remark.trim(), user.uid);
      toast.success("Remark saved");
      mutate();
      setRemark("");
      auditLogService.logAction(
        user.uid, user.name || "", "update", "policies",
        `Added remark on policy ${policy.id}`
      ).catch(() => {});
    } catch (err: unknown) {
      toast.error(friendlyError(err instanceof Error ? err : new Error(String(err)), "Failed to save remark"));
    } finally {
      setIsSavingRemark(false);
    }
  }

  async function handleToggleLock() {
    if (!policy?.id || !user) return;
    setIsLocking(true);
    try {
      if (policy.lockedForEmployee) {
        await policyService.unlockForEmployee(policy.id);
        toast.success("Policy unlocked for employee");
      } else {
        await policyService.lockForEmployee(policy.id);
        toast.success("Policy locked for employee editing");
      }
      mutate();
      auditLogService.logAction(
        user.uid, user.name || "", "update", "policies",
        `${policy.lockedForEmployee ? "Unlocked" : "Locked"} policy ${policy.id}`
      ).catch(() => {});
    } catch (err: unknown) {
      toast.error(friendlyError(err instanceof Error ? err : new Error(String(err)), "Failed to toggle lock"));
    } finally {
      setIsLocking(false);
    }
  }

  async function handleStatusChange(newStatus: "archived" | "cancelled") {
    if (!policy?.id || !user) return;
    setIsChangingStatus(true);
    try {
      await policyService.update(policy.id, { status: newStatus });
      toast.success(
        newStatus === "archived"
          ? "Policy archived successfully"
          : "Policy cancelled successfully"
      );
      mutate();
      invalidateArchives();
      auditLogService
        .logAction(
          user.uid,
          user.name || "",
          "update",
          "policies",
          `Changed policy ${policy.policy_number} status to ${newStatus}`
        )
        .catch(() => {});
    } catch (err: unknown) {
      toast.error(friendlyError(err instanceof Error ? err : new Error(String(err)), `Failed to ${newStatus === "archived" ? "archive" : "cancel"} policy`));
    } finally {
      setIsChangingStatus(false);
      setArchiveDialog(false);
      setCancelDialog(false);
    }
  }

  // Loading state
  if (isLoading) {
    return (
      <div className="space-y-6">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-64 w-full rounded-lg" />
        <Skeleton className="h-48 w-full rounded-lg" />
      </div>
    );
  }

  // Not found
  if (error || !policy) {
    return (
      <div className="flex flex-col items-center justify-center gap-4 py-20">
        <AlertCircle className="h-12 w-12 text-muted-foreground" />
        <h2 className="text-lg font-bold">Policy not found</h2>
        <Button variant="outline" onClick={() => router.push("/dashboard/policies")}>
          <ArrowLeft className="mr-2 h-4 w-4" /> Back to Policies
        </Button>
      </div>
    );
  }

  const daysLeft = getDaysUntilExpiry(policy);

  return (
    <motion.div {...pageTransition} className="space-y-6">
      {/* Back + Header */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex items-center gap-3">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => router.push("/dashboard/policies")}
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="font-heading text-xl font-bold text-foreground">
                {policy.policy_number}
              </h1>
              <button
                onClick={() => copyToClipboard(policy.policy_number, "pn")}
                className="rounded p-1 transition-colors hover:bg-muted-foreground/20"
              >
                {copiedField === "pn" ? (
                  <Check className="h-3.5 w-3.5 text-green-400" />
                ) : (
                  <Copy className="h-3.5 w-3.5 text-muted-foreground" />
                )}
              </button>
            </div>
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Badge variant="outline" className="text-xs capitalize">
                {policy.policy_type}
              </Badge>
              <Badge
                className={`text-xs capitalize ${
                  STATUS_COLORS[policy.status] || ""
                }`}
              >
                {policy.status}
              </Badge>
              {daysLeft !== null && policy.status === "active" && (
                <span
                  className={`text-xs ${
                    daysLeft <= 0
                      ? "text-red-400"
                      : daysLeft <= settings.policy_expiry_warning_days
                      ? "text-yellow-400"
                      : "text-muted-foreground"
                  }`}
                >
                  {daysLeft <= 0
                    ? "Expired"
                    : `${daysLeft} days left`}
                </span>
              )}
            </div>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {/* Lock/Unlock — Admin only */}
          {isAdminOrManager && (
            <Button
              variant="outline"
              size="sm"
              onClick={handleToggleLock}
              disabled={isLocking}
              className="flex items-center gap-1.5"
            >
              {policy.lockedForEmployee ? (
                <><Unlock className="h-4 w-4" /> Unlock</>
              ) : (
                <><Lock className="h-4 w-4" /> Lock</>
              )}
            </Button>
          )}

          {/* Edit — Admin/Manager only */}
          {isAdminOrManager && (
            <Button
              size="sm"
              onClick={() => setShowEdit(true)}
              className="flex items-center gap-1.5 bg-primary text-primary-foreground hover:bg-primary/90"
            >
              <Edit className="h-4 w-4" /> Edit
            </Button>
          )}

          {/* More Actions — Archive / Cancel (Admin/Manager, active policies only) */}
          {isAdminOrManager && policy.status === "active" && (
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="outline" size="sm" className="h-8 w-8 p-0">
                  <MoreVertical className="h-4 w-4" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="w-48">
                <DropdownMenuItem
                  onClick={() => setArchiveDialog(true)}
                  className="flex items-center gap-2 text-muted-foreground cursor-pointer"
                >
                  <Archive className="h-4 w-4" />
                  Archive Policy
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem
                  onClick={() => setCancelDialog(true)}
                  className="flex items-center gap-2 text-red-400 focus:text-red-400 cursor-pointer"
                >
                  <XCircle className="h-4 w-4" />
                  Cancel Policy
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          )}
        </div>
      </div>

      {/* Tabs */}
      <Tabs defaultValue="summary">
        <TabsList className="w-full justify-start">
          <TabsTrigger value="summary">Summary</TabsTrigger>
          <TabsTrigger value="customer">Customer</TabsTrigger>
          <TabsTrigger value="documents">Documents</TabsTrigger>
          <TabsTrigger value="activity">Activity</TabsTrigger>
        </TabsList>

        {/* Summary Tab */}
        <TabsContent value="summary" className="space-y-4 pt-4">
          <motion.div
            variants={staggerContainer}
            initial="hidden"
            animate="visible"
            className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"
          >
            {/* Policy Details Card */}
            <motion.div variants={staggerItem} className="sm:col-span-2 lg:col-span-2">
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2 text-base">
                    <Shield className="h-4 w-4 text-primary" />
                    Policy Details
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="grid gap-4 sm:grid-cols-2">
                    <InfoRow icon={Shield} label="Policy Number" value={policy.policy_number} />
                    <InfoRow icon={Shield} label="Policy Type" value={policy.policy_type} capitalize />
                    <InfoRow icon={Calendar} label="Start Date" value={formatDate(policy.start_date)} />
                    <InfoRow icon={Calendar} label="End Date" value={formatDate(policy.end_date)} />
                    <InfoRow icon={IndianRupee} label="Premium" value={formatCurrency(policy.premium_amount)} ariaLabel={formatCurrencyLabel(policy.premium_amount)} />
                    <InfoRow icon={IndianRupee} label="Sum Insured" value={policy.sum_insured ? formatCurrency(policy.sum_insured) : "—"} ariaLabel={policy.sum_insured ? formatCurrencyLabel(policy.sum_insured) : undefined} />
                    <InfoRow icon={Building2} label="Insurer" value={policy.insurer_name || "—"} />
                    <InfoRow icon={Clock} label="Payment Frequency" value={policy.payment_frequency || "—"} capitalize />
                  </div>
                </CardContent>
              </Card>

              {/* Enhanced Operational Depth */}
              <PolicyMetadataView policy={policy} />
            </motion.div>

            {/* Assigned Employee Card */}
            <motion.div variants={staggerItem}>
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2 text-base">
                    <User className="h-4 w-4 text-primary" />
                    Assignment
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-3">
                  <div>
                    <p className="text-xs text-muted-foreground">Assigned To</p>
                    <p className="font-medium">
                      {policy.assigned_to_name || policy.assigned_to}
                    </p>
                  </div>
                  <div>
                    <p className="text-xs text-muted-foreground">Lock Status</p>
                    <div className="flex items-center gap-1.5">
                      {policy.lockedForEmployee ? (
                        <Badge variant="outline" className="gap-1 text-xs">
                          <Lock className="h-3 w-3" /> Locked
                        </Badge>
                      ) : (
                        <Badge variant="outline" className="gap-1 text-xs">
                          <Unlock className="h-3 w-3" /> Unlocked
                        </Badge>
                      )}
                    </div>
                  </div>
                  <div>
                    <p className="text-xs text-muted-foreground">Verified</p>
                    <p className="text-sm">
                      {policy.verification_confirmed ? "Yes ✓" : "No"}
                    </p>
                  </div>
                </CardContent>
              </Card>
            </motion.div>
          </motion.div>

          {/* Remark Section */}
          <Card>
            <CardHeader>
              <CardTitle className="text-base">Remarks</CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              {policy.remark && (
                <div className="rounded-md border border-muted-foreground/20 bg-card p-3">
                  <p className="text-sm">{policy.remark}</p>
                  {policy.remark_updated_by && (
                    <p className="mt-1 text-xs text-muted-foreground">
                      Updated by {policy.remark_updated_by} •{" "}
                      {formatDate(policy.remark_updated_at)}
                    </p>
                  )}
                </div>
              )}
              <div className="flex items-end gap-2">
                <Textarea
                  placeholder="Add a remark..."
                  value={remark}
                  onChange={(e) => setRemark(e.target.value)}
                  rows={2}
                  className="flex-1"
                />
                <Button
                  size="sm"
                  onClick={handleSaveRemark}
                  disabled={!remark.trim() || isSavingRemark}
                  className="bg-primary text-primary-foreground hover:bg-primary/90"
                >
                  {isSavingRemark ? "Saving..." : "Save"}
                </Button>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Customer Tab */}
        <TabsContent value="customer" className="pt-4">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-base">
                <User className="h-4 w-4 text-primary" />
                Customer Information
              </CardTitle>
            </CardHeader>
            <CardContent>
              {customer ? (
                <div className="grid gap-4 sm:grid-cols-2">
                  <InfoRow icon={User} label="Name" value={customer.name} />
                  <InfoRow icon={Shield} label="Customer UID" value={customer.uid} />
                  <InfoRow icon={Phone} label="Phone" value={customer.phone || "—"} />
                  <InfoRow icon={Mail} label="Email" value={customer.email || "—"} />
                  <InfoRow icon={MapPin} label="City" value={customer.city || "—"} />
                  <InfoRow icon={MapPin} label="State" value={customer.state || "—"} />
                  {customer.address && (
                    <div className="sm:col-span-2">
                      <InfoRow icon={MapPin} label="Address" value={customer.address} />
                    </div>
                  )}
                  <div className="sm:col-span-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() =>
                        router.push(`/dashboard/customers/${customer.id}`)
                      }
                    >
                      View Full Profile →
                    </Button>
                  </div>
                </div>
              ) : (
                <div className="py-8 text-center text-sm text-muted-foreground">
                  <p className="font-medium">{policy.customer_name}</p>
                  <p className="mt-1">Customer ID: {policy.customer_id}</p>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* Documents Tab */}
        <TabsContent value="documents" className="pt-4">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between pb-2">
              <CardTitle className="flex items-center gap-2 text-base">
                <FileText className="h-4 w-4 text-primary" />
                Policy Assets
              </CardTitle>
              <Button size="sm" variant="outline" className="h-8 gap-2 text-xs" onClick={() => toast.info("Deep-field document upload coming in Phase 4")}>
                <Upload className="h-3 w-3" /> Upload New
              </Button>
            </CardHeader>
            <CardContent>
              {documentsLoading ? (
                <div className="space-y-2 py-4">
                  <Skeleton className="h-10 w-full" />
                  <Skeleton className="h-10 w-full" />
                </div>
              ) : documents && documents.length > 0 ? (
                <div className="space-y-2">
                  {documents.map((doc) => (
                    <div key={doc.id} className="flex items-center justify-between p-3 rounded-xl border border-border/60 bg-muted/20 hover:bg-muted/40 transition-colors">
                      <div className="flex items-center gap-3">
                        <div className="h-9 w-9 rounded-lg bg-primary/10 flex items-center justify-center text-primary">
                           <FileText className="h-4 w-4" />
                        </div>
                        <div>
                          <p className="text-sm font-bold truncate max-w-[200px]">{doc.file_name}</p>
                          <p className="text-[10px] text-muted-foreground font-black uppercase tracking-tight">{doc.document_type || "General Asset"}</p>
                        </div>
                      </div>
                      <Button variant="ghost" size="sm" asChild className="h-8 text-xs font-bold uppercase tracking-wider text-primary hover:text-primary hover:bg-primary/10">
                        <a href={doc.file_url} target="_blank" rel="noopener noreferrer">
                          Open File
                        </a>
                      </Button>
                    </div>
                  ))}
                </div>
              ) : policy.pdf_url ? (
                <div className="flex items-center justify-between p-3 rounded-xl border border-primary/30 bg-primary/5">
                   <div className="flex items-center gap-3">
                      <FileCheck className="h-5 w-5 text-primary" />
                      <div>
                        <p className="text-sm font-bold">Policy Copy (Main)</p>
                        <p className="text-[10px] text-muted-foreground font-black uppercase">Source: OCR Intake Desk</p>
                      </div>
                   </div>
                   <Button size="sm" asChild className="h-8 text-xs font-bold uppercase">
                     <a href={policy.pdf_url} target="_blank" rel="noopener noreferrer">
                       View PDF
                     </a>
                   </Button>
                </div>
              ) : (
                <div className="py-12 flex flex-col items-center justify-center gap-3 border-2 border-dashed border-border/60 rounded-xl">
                  <Upload className="h-8 w-8 text-muted-foreground opacity-20" />
                  <p className="text-center text-xs font-bold text-muted-foreground uppercase tracking-widest">
                    No documents indexed for this policy
                  </p>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* Activity Tab */}
        <TabsContent value="activity" className="pt-4">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-base">
                <Clock className="h-4 w-4 text-primary" />
                Activity Timeline
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                <TimelineItem
                  title="Policy Created"
                  date={formatDate(policy.createdAt)}
                  description={`Created by ${policy.created_by}`}
                />
                {policy.verification_confirmed && (
                  <TimelineItem
                    title="Verification Confirmed"
                    date="—"
                    description="Employee verified all policy details"
                  />
                )}
                {policy.remark && (
                  <TimelineItem
                    title="Remark Added"
                    date={formatDate(policy.remark_updated_at)}
                    description={policy.remark}
                  />
                )}
                {policy.status !== "active" && (
                  <TimelineItem
                    title={`Status: ${policy.status}`}
                    date={formatDate(policy.updatedAt)}
                    description={`Policy marked as ${policy.status}`}
                  />
                )}
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* Edit Dialog */}
      <PolicyForm
        open={showEdit}
        onOpenChange={setShowEdit}
        editPolicy={policy}
        onSuccess={() => mutate()}
      />

      {/* Archive Confirmation Dialog */}
      <AlertDialog open={archiveDialog} onOpenChange={setArchiveDialog}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Archive Policy</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to archive policy{" "}
              <strong>{policy.policy_number}</strong>? The policy will be moved
              to Archives and can be restored later.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isChangingStatus}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => handleStatusChange("archived")}
              disabled={isChangingStatus}
            >
              {isChangingStatus ? "Archiving..." : "Archive"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Cancel Confirmation Dialog */}
      <AlertDialog open={cancelDialog} onOpenChange={setCancelDialog}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel Policy</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to cancel policy{" "}
              <strong>{policy.policy_number}</strong>? This will also cancel any
              pending commissions linked to this policy.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isChangingStatus}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => handleStatusChange("cancelled")}
              disabled={isChangingStatus}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {isChangingStatus ? "Cancelling..." : "Cancel Policy"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </motion.div>
  );
}

// ---- Sub-components ----

function InfoRow({
  icon: Icon,
  label,
  value,
  capitalize,
  ariaLabel,
}: {
  icon: LucideIcon;
  label: string;
  value: string;
  capitalize?: boolean;
  ariaLabel?: string;
}) {
  return (
    <div className="flex items-start gap-2">
      <Icon className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" />
      <div>
        <p className="text-xs text-muted-foreground">{label}</p>
        <p className={`text-sm font-medium ${capitalize ? "capitalize" : ""}`} aria-label={ariaLabel}>
          {value}
        </p>
      </div>
    </div>
  );
}

function TimelineItem({
  title,
  date,
  description,
}: {
  title: string;
  date: string;
  description: string;
}) {
  return (
    <div className="relative flex gap-3 pl-4">
      <div className="absolute left-0 top-1.5 h-2 w-2 rounded-full bg-primary" />
      <div className="absolute left-[3px] top-4 h-full w-0.5 bg-muted-foreground/20" />
      <div className="pb-4">
        <div className="flex items-center gap-2">
          <p className="text-sm font-medium">{title}</p>
          <span className="text-xs text-muted-foreground">{date}</span>
        </div>
        <p className="mt-0.5 text-xs text-muted-foreground">{description}</p>
      </div>
    </div>
  );
}

"use client";

import { useState, useMemo } from "react";
import { motion } from "framer-motion";
import { toast } from "sonner";
import { useRouter } from "next/navigation";
import {
  Plus,
  Search,
  FileSpreadsheet,
  Filter,
  Shield,
  ChevronLeft,
  ChevronRight,
  Eye,
  Calendar,
  IndianRupee,
  Building2,
  AlertCircle,
  Trash2,
  Loader2,
  Mail,
  Sparkles,
} from "lucide-react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Skeleton } from "@/components/ui/skeleton";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";

import { PolicyForm } from "@/components/policies/policy-form";
import { BulkImport } from "@/components/policies/bulk-import";
import { usePolicies, usePolicyCount, invalidatePolicies } from "@/lib/hooks/use-policies";
import { policyService } from "@/lib/services/policy.service";
import { auditLogService } from "@/lib/services/audit-log.service";
import { exportPoliciesToCSV } from "@/lib/utils/export";

import { useAuth } from "@/lib/context/auth-context";
import { useAppSettings } from "@/lib/context/app-settings-context";
import { parsePolicyTypes } from "@/lib/validations/policy";
import { hoverLift, pageTransition, staggerContainer, staggerItem } from "@/lib/helpers/animations";
import { formatCurrency, formatCurrencyLabel } from "@/lib/utils";
import { PolicyTable } from "@/components/policies/PolicyTable";
import type { Policy } from "@/lib/types";

const PAGE_SIZE = 20;

const STATUS_COLORS: Record<string, string> = {
  active: "bg-green-500/20 text-green-400",
  expired: "bg-red-500/20 text-red-400",
  cancelled: "bg-yellow-500/20 text-yellow-400",
  archived: "bg-muted-foreground/20 text-muted-foreground",
};

export default function PoliciesPage() {
  const { user } = useAuth();
  const { settings } = useAppSettings();
  const router = useRouter();
  const [nowMs] = useState(() => Date.now());
  const isEmployee = user?.role === "employee";
  const isAdminOrManager = user?.role === "admin" || user?.role === "manager";
  const policyTypes = parsePolicyTypes(settings.policy_types);

  // State
  const [showAddForm, setShowAddForm] = useState(false);
  const [showBulkImport, setShowBulkImport] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [typeFilter, setTypeFilter] = useState<string>("all");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [currentPage, setCurrentPage] = useState(1);
  const [deletingPolicyId, setDeletingPolicyId] = useState<string | null>(null);
  const [deleteTargetPolicy, setDeleteTargetPolicy] = useState<Policy | null>(null);
  const [sendingReminderId, setSendingReminderId] = useState<string | null>(null);

  // Fetch
  const { data: allPolicies, isLoading, error, mutate } = usePolicies();
  const { data: totalCount } = usePolicyCount();

  // Filter + search
  const filteredPolicies = useMemo(() => {
    if (!allPolicies) return [];

    let result = [...allPolicies];

    // Employee sees only assigned policies
    if (isEmployee && user) {
      result = result.filter((p) => p.assigned_to === user.uid);
    }

    // Type filter
    if (typeFilter !== "all") {
      result = result.filter((p) => p.policy_type === typeFilter);
    }

    // Status filter
    if (statusFilter !== "all") {
      result = result.filter((p) => p.status === statusFilter);
    }

    // Search
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      result = result.filter(
        (p) =>
          p.policy_number?.toLowerCase().includes(q) ||
          p.customer_name?.toLowerCase().includes(q) ||
          p.insurer_name?.toLowerCase().includes(q) ||
          p.assigned_to_name?.toLowerCase().includes(q)
      );
    }

    return result;
  }, [allPolicies, searchQuery, typeFilter, statusFilter, isEmployee, user]);

  // Pagination
  const totalPages = Math.ceil(filteredPolicies.length / PAGE_SIZE);
  const paginatedPolicies = filteredPolicies.slice(
    (currentPage - 1) * PAGE_SIZE,
    currentPage * PAGE_SIZE
  );

  const expiringSoonCount = useMemo(
    () =>
      filteredPolicies.filter((policy) => {
        if (!policy.end_date) return false;
        try {
          const endMs = new Date(policy.end_date as string).getTime();
          const daysLeft = (endMs - nowMs) / (1000 * 60 * 60 * 24);
          return daysLeft > 0 && daysLeft <= settings.policy_expiry_warning_days;
        } catch {
          return false;
        }
      }).length,
    [filteredPolicies, nowMs, settings.policy_expiry_warning_days]
  );

  function formatDate(timestamp: unknown): string {
    if (!timestamp) return "—";
    try {
      const isSecondsObject =
        typeof timestamp === "object" &&
        timestamp !== null &&
        "seconds" in timestamp &&
        typeof (timestamp as { seconds: unknown }).seconds === "number";

      const date = isSecondsObject
        ? new Date((timestamp as { seconds: number }).seconds * 1000)
        : new Date(timestamp as string | number | Date);
      return date.toLocaleDateString("en-IN", {
        day: "2-digit",
        month: "short",
        year: "numeric",
      });
    } catch {
      return "—";
    }
  }

  // Check if policy is expiring soon (within admin-configured days)
  function isExpiringSoon(policy: Policy): boolean {
    if (!policy.end_date) return false;
    try {
      const endMs = new Date(policy.end_date as string).getTime();
      const daysLeft = (endMs - nowMs) / (1000 * 60 * 60 * 24);
      return daysLeft > 0 && daysLeft <= settings.policy_expiry_warning_days;
    } catch {
      return false;
    }
  }

  // Check if policy is eligible for email reminder
  function canSendReminder(policy: Policy): boolean {
    // Allow sending email for any policy that has an end_date
    return !!policy.end_date;
  }

  // Send email reminder for a policy
  async function handleSendEmailReminder(policy: Policy) {
    if (!user) return;
    // Employee can only remind for assigned policies
    if (isEmployee && policy.assigned_to !== user.uid) return;

    setSendingReminderId(policy.id);
    try {
      const { supabase } = await import("@/lib/supabase/client");
      const { data: { session } } = await supabase.auth.getSession();
      const token = session?.access_token;
      if (!token) {
        toast.error("Not authenticated");
        return;
      }

      const res = await fetch("/api/email/send-reminder", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          policy_id: policy.id,
          type: "policy_expiry",
        }),
      });

      const data = await res.json();
      if (!res.ok) {
        toast.error(data.error || "Failed to send reminder");
        return;
      }

      toast.success(`Reminder email sent to ${data.sentTo}`);
    } catch {
      toast.error("Failed to send reminder email");
    } finally {
      setSendingReminderId(null);
    }
  }

  return (
    <motion.div
      initial={pageTransition.initial}
      animate={pageTransition.animate}
      transition={pageTransition.transition}
      className="space-y-5"
    >
      <motion.div
      variants={staggerContainer}
      initial="initial"
      animate="animate"
      className="space-y-5"
    >
      {/* Header */}
      <motion.div
        variants={staggerItem}
        className="flex flex-col gap-4 rounded-[2rem] border border-border bg-card/85 p-6 shadow-[0_12px_28px_rgba(47,62,64,0.05)] backdrop-blur sm:flex-row sm:items-end sm:justify-between"
      >
        <div>
          <p className="text-[11px] font-bold uppercase tracking-[0.2em] text-muted-foreground">Policy Operations</p>
          <h1 className="mt-2 font-heading text-3xl font-bold tracking-tight text-foreground">
            Policies
          </h1>
          <p className="mt-2 text-sm text-muted-foreground">
            {isEmployee
              ? "Your assigned policies"
              : `${totalCount ?? "..."} total policies`}
          </p>
        </div>
        <div className="flex items-center gap-2">
          {isAdminOrManager && (
            <motion.div {...hoverLift}>
              <Button
                variant="outline"
                size="sm"
                onClick={() => exportPoliciesToCSV(filteredPolicies)}
                className="flex items-center gap-2 border-border bg-card text-muted-foreground hover:bg-muted hover:text-foreground"
              >
                <FileSpreadsheet className="h-4 w-4" />
                <span className="hidden sm:inline">Export CSV</span>
              </Button>
            </motion.div>
          )}
          {isAdminOrManager && (
            <motion.div {...hoverLift}>
              <Button
                variant="outline"
                size="sm"
                onClick={() => setShowBulkImport(true)}
                className="flex items-center gap-2 border-border bg-card text-muted-foreground hover:bg-muted hover:text-foreground"
              >
                <Plus className="h-4 w-4" />
                <span className="hidden sm:inline">Bulk Import</span>
              </Button>
            </motion.div>
          )}
          <motion.div {...hoverLift}>
            <Button
              size="sm"
              onClick={() => setShowAddForm(true)}
              className="flex items-center gap-2 bg-[#2f3e40] text-white hover:bg-[#5d787a]"
            >
              <Plus className="h-4 w-4" />
              <span className="hidden sm:inline">Add Policy</span>
            </Button>
          </motion.div>
        </div>
      </motion.div>

      {/* Filters */}
      <motion.div
        variants={staggerItem}
        className="flex flex-col gap-3 rounded-2xl border border-border bg-card/90 p-3 shadow-[0_8px_18px_rgba(47,62,64,0.04)] sm:flex-row sm:items-center"
      >
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            placeholder="Search policies..."
            value={searchQuery}
            onChange={(e) => {
              setSearchQuery(e.target.value);
              setCurrentPage(1);
            }}
            className="border-border bg-muted/35 pl-9"
          />
        </div>

        <div className="flex items-center gap-2">
          <motion.div {...hoverLift}>
            <Select
              value={typeFilter}
              onValueChange={(v) => {
                setTypeFilter(v);
                setCurrentPage(1);
              }}
            >
              <SelectTrigger className="w-35 border-border bg-muted/35 text-muted-foreground">
                <Filter className="mr-1 h-3.5 w-3.5" />
                <SelectValue placeholder="Type" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Types</SelectItem>
                {policyTypes.map((t) => (
                  <SelectItem key={t.value} value={t.value}>
                    {t.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </motion.div>

          <motion.div {...hoverLift}>
            <Select
              value={statusFilter}
              onValueChange={(v) => {
                setStatusFilter(v);
                setCurrentPage(1);
              }}
            >
              <SelectTrigger className="w-32.5 border-border bg-muted/35 text-muted-foreground">
                <SelectValue placeholder="Status" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Status</SelectItem>
                <SelectItem value="active">Active</SelectItem>
                <SelectItem value="expired">Expired</SelectItem>
                <SelectItem value="cancelled">Cancelled</SelectItem>
                <SelectItem value="archived">Archived</SelectItem>
              </SelectContent>
            </Select>
          </motion.div>
        </div>
      </motion.div>

      <motion.div variants={staggerItem} className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <motion.div {...hoverLift} className="rounded-xl border border-border bg-card/85 px-3 py-2">
          <p className="text-[10px] font-bold uppercase tracking-[0.14em] text-muted-foreground">Visible Policies</p>
          <p className="mt-1 text-xl font-semibold tracking-tight text-foreground">{filteredPolicies.length}</p>
        </motion.div>
        <motion.div {...hoverLift} className="rounded-xl border border-emerald-500/35 bg-emerald-500/10 px-3 py-2">
          <p className="text-[10px] font-bold uppercase tracking-[0.14em] text-emerald-600 dark:text-emerald-300">Active</p>
          <p className="mt-1 text-xl font-semibold tracking-tight text-emerald-700 dark:text-emerald-300">{filteredPolicies.filter((p) => p.status === "active").length}</p>
        </motion.div>
        <motion.div {...hoverLift} className="rounded-xl border border-amber-500/35 bg-amber-500/10 px-3 py-2">
          <p className="text-[10px] font-bold uppercase tracking-[0.14em] text-amber-600 dark:text-amber-300">Expiring Soon</p>
          <p className="mt-1 text-xl font-semibold tracking-tight text-amber-700 dark:text-amber-300">{expiringSoonCount}</p>
        </motion.div>
        <motion.div {...hoverLift} className="rounded-xl border border-primary/35 bg-primary/10 px-3 py-2">
          <p className="text-[10px] font-bold uppercase tracking-[0.14em] text-primary">Smart Ops</p>
          <p className="mt-1 inline-flex items-center gap-1.5 text-sm font-semibold text-primary"><Sparkles className="h-3.5 w-3.5" /> Reminder Ready</p>
        </motion.div>
      </motion.div>

      {/* Loading */}
      {isLoading && (
        <div className="space-y-3">
          {Array.from({ length: 5 }).map((_, i) => (
            <Skeleton key={i} className="h-16 w-full rounded-2xl bg-skeleton" />
          ))}
        </div>
      )}

      {/* Error */}
      {error && (
        <Card className="border-red-300/60 bg-red-100/60">
          <CardContent className="flex items-center gap-3 p-4">
            <AlertCircle className="h-5 w-5 text-red-700" />
            <p className="text-sm text-red-700">
              Failed to load policies. Please try again.
            </p>
          </CardContent>
        </Card>
      )}

      {/* Desktop Table */}
      {!isLoading && !error && (
        <>
          <div className="hidden md:block">
            <PolicyTable 
              policies={paginatedPolicies}
              isAdmin={isAdminOrManager}
              onDelete={(p) => setDeleteTargetPolicy(p)}
              onSendEmail={(p) => handleSendEmailReminder(p)}
              sendingReminderId={sendingReminderId}
              deletingPolicyId={deletingPolicyId}
            />
          </div>

          {/* Mobile Cards */}
          <div
            className="space-y-3 md:hidden"
          >
            {paginatedPolicies.length === 0 ? (
              <Card>
                <CardContent className="p-6 text-center text-sm text-muted-foreground">
                  {searchQuery || typeFilter !== "all"
                    ? "No policies match your filters"
                    : "No policies yet"}
                </CardContent>
              </Card>
            ) : (
              paginatedPolicies.map((policy) => (
                <motion.div
                  key={policy.id}
                  variants={staggerItem}
                  {...hoverLift}
                  onClick={() =>
                    router.push(`/dashboard/policies/${policy.id}`)
                  }
                >
                  <Card className="cursor-pointer border-border bg-card/90 shadow-[0_8px_18px_rgba(47,62,64,0.04)] transition-colors hover:border-border-strong hover:bg-card">
                    <CardContent className="p-4">
                      <div className="flex items-start justify-between">
                        <div className="space-y-1">
                          <p className="font-mono text-sm font-bold">
                            {policy.policy_number}
                          </p>
                          <p className="text-sm text-foreground">
                            {policy.customer_name}
                          </p>
                        </div>
                        <Badge
                          className={`text-xs capitalize ${
                            STATUS_COLORS[policy.status] || ""
                          }`}
                        >
                          {policy.status}
                        </Badge>
                      </div>

                      <div className="mt-3 flex flex-wrap items-center gap-3 text-xs text-muted-foreground">
                        <span className="flex items-center gap-1">
                          <Shield className="h-3 w-3" />
                          {policy.policy_type}
                        </span>
                        <span className="flex items-center gap-1" aria-label={formatCurrencyLabel(policy.premium_amount)}>
                          <IndianRupee className="h-3 w-3" />
                          {formatCurrency(policy.premium_amount)}
                        </span>
                        <span className="flex items-center gap-1">
                          <Calendar className="h-3 w-3" />
                          {formatDate(policy.end_date)}
                        </span>
                        {policy.insurer_name && (
                          <span className="flex items-center gap-1">
                            <Building2 className="h-3 w-3" />
                            {policy.insurer_name}
                          </span>
                        )}
                      </div>

                      {canSendReminder(policy) && (
                        <div className="mt-2 border-t border-muted-foreground/10 pt-2">
                          <Button
                            variant="ghost"
                            size="sm"
                            className="h-7 text-xs text-amber-500 hover:text-amber-400 hover:bg-amber-500/10"
                            disabled={sendingReminderId === policy.id}
                            onClick={(e) => {
                              e.stopPropagation();
                              handleSendEmailReminder(policy);
                            }}
                          >
                            {sendingReminderId === policy.id ? (
                              <Loader2 className="mr-1 h-3 w-3 animate-spin" />
                            ) : (
                              <Mail className="mr-1 h-3 w-3" />
                            )}
                            Send Reminder
                          </Button>
                        </div>
                      )}
                    </CardContent>
                  </Card>
                </motion.div>
              ))
            )}
          </div>

          {/* Pagination */}
          {totalPages > 1 && (
            <div
              className="flex items-center justify-between"
            >
              <p className="text-xs text-muted-foreground">
                Showing {(currentPage - 1) * PAGE_SIZE + 1}—
                {Math.min(currentPage * PAGE_SIZE, filteredPolicies.length)} of{" "}
                {filteredPolicies.length}
              </p>
              <div className="flex items-center gap-1">
                <Button
                  variant="outline"
                  size="icon"
                  className="h-8 w-8 border-border bg-card text-muted-foreground hover:bg-muted hover:text-foreground"
                  disabled={currentPage === 1}
                  onClick={() => setCurrentPage((p) => p - 1)}
                >
                  <ChevronLeft className="h-4 w-4" />
                </Button>
                <span className="px-3 text-sm text-foreground/85">
                  {currentPage} / {totalPages}
                </span>
                <Button
                  variant="outline"
                  size="icon"
                  className="h-8 w-8 border-border bg-card text-muted-foreground hover:bg-muted hover:text-foreground"
                  disabled={currentPage === totalPages}
                  onClick={() => setCurrentPage((p) => p + 1)}
                >
                  <ChevronRight className="h-4 w-4" />
                </Button>
              </div>
            </div>
          )}
        </>
      )}
      </motion.div>

      {/* Dialogs */}
      <PolicyForm
        open={showAddForm}
        onOpenChange={setShowAddForm}
        onSuccess={() => mutate()}
      />
      {isAdminOrManager && (
        <>
          <BulkImport
            open={showBulkImport}
            onOpenChange={setShowBulkImport}
            onSuccess={() => mutate()}
          />
        </>
      )}

      {/* Delete Policy Confirmation */}
      <AlertDialog open={!!deleteTargetPolicy} onOpenChange={(open) => !open && setDeleteTargetPolicy(null)}>
        <AlertDialogContent className="bg-card border-border">
          <AlertDialogHeader>
            <AlertDialogTitle className="text-foreground">Delete Policy</AlertDialogTitle>
            <AlertDialogDescription className="text-muted-foreground">
              Are you sure you want to delete policy <strong className="text-foreground">{deleteTargetPolicy?.policy_number}</strong>? This will also remove all related premiums, commissions, renewals, and documents. This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="border-border-strong text-foreground">Cancel</AlertDialogCancel>
            <AlertDialogAction
              className="bg-red-600 hover:bg-red-700 text-white"
              disabled={!!deletingPolicyId}
              onClick={async () => {
                if (!deleteTargetPolicy || !user) return;
                setDeletingPolicyId(deleteTargetPolicy.id);
                try {
                  const cascade = await policyService.deleteWithCascade(deleteTargetPolicy.id);
                  const parts = [
                    cascade.deletedPremiums && `${cascade.deletedPremiums} premium(s)`,
                    cascade.deletedCommissions && `${cascade.deletedCommissions} commission(s)`,
                    cascade.deletedRenewals && `${cascade.deletedRenewals} renewal(s)`,
                    cascade.deletedDocuments && `${cascade.deletedDocuments} document(s)`,
                  ].filter(Boolean);
                  const cascadeMsg = parts.length ? ` — also removed ${parts.join(", ")}` : "";
                  toast.success(`Policy deleted${cascadeMsg}`);
                  invalidatePolicies();
                  mutate();
                  auditLogService.logAction(
                    user.uid, user.name || "", "delete", "policies",
                    `Deleted policy ${deleteTargetPolicy.id} (${deleteTargetPolicy.policy_number})${cascadeMsg}`
                  ).catch(() => {});
                } catch {
                  toast.error("Failed to delete policy");
                } finally {
                  setDeletingPolicyId(null);
                  setDeleteTargetPolicy(null);
                }
              }}
            >
              {deletingPolicyId ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </motion.div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { motion } from "framer-motion";
import { useAuth } from "@/lib/context/auth-context";
import { useAppSettings } from "@/lib/context/app-settings-context";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { toast } from "sonner";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { userService } from "@/lib/services/user.service";
import { auditLogService } from "@/lib/services/audit-log.service";
import type { AuditLog } from "@/lib/types";
import type { LucideIcon } from "lucide-react";
import {
  Pencil,
  Mail,
  Phone,
  Building2,
  Shield,
  Clock,
  Loader2,
  Save,
  Activity,
  LogIn,
  LogOut,
  FileText,
  UserPlus,
  Settings,
  Sparkles,
  UserCircle,
} from "lucide-react";
import {
  pageTransition,
  staggerContainer,
  staggerItem,
  hoverLift,
} from "@/lib/helpers/animations";

const profileSchema = z.object({
  name: z.string().min(2, "Name must be at least 2 characters"),
  phone: z.string().optional(),
  bio: z.string().max(500, "Bio must be under 500 characters").optional(),
});

type ProfileFormData = z.infer<typeof profileSchema>;

export default function ProfilePage() {
  const { user: dbUser, refreshUser } = useAuth();
  const { settings } = useAppSettings();
  const [editOpen, setEditOpen] = useState(false);
  const [activityLogs, setActivityLogs] = useState<AuditLog[]>([]);
  const [logsLoading, setLogsLoading] = useState(true);

  useEffect(() => {
    if (!dbUser) return;
    auditLogService
      .getByUser(dbUser.id)
      .then((logs) => {
        setActivityLogs(logs.slice(0, 15));
      })
      .catch(() => {})
      .finally(() => setLogsLoading(false));
  }, [dbUser]);

  if (!dbUser) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="h-6 w-6 animate-spin text-primary" />
      </div>
    );
  }

  const roleBadgeColor =
    dbUser.role === "admin"
      ? "#ef4444"
      : dbUser.role === "manager"
        ? "#3b82f6"
        : "#10b981";

  const recentActions = activityLogs.length;
  const latestActionAt = activityLogs[0]?.createdAt;
  const initials = dbUser.name
    .split(" ")
    .map((n) => n[0])
    .join("")
    .toUpperCase()
    .slice(0, 2);

  const formatDateTime = (value?: string | null) =>
    value
      ? new Date(value).toLocaleString("en-IN", {
          day: "2-digit",
          month: "short",
          year: "numeric",
          hour: "2-digit",
          minute: "2-digit",
        })
      : "Never";

  return (
    <motion.div className="mx-auto max-w-6xl space-y-6" {...pageTransition}>
      <section className="relative overflow-hidden rounded-3xl border border-border-strong/70 bg-card/95 p-5 shadow-[0_18px_42px_rgba(47,62,64,0.08)] sm:p-6">
        <div className="pointer-events-none absolute -right-20 -top-20 h-48 w-48 rounded-full bg-primary/10 blur-3xl" />
        <div className="pointer-events-none absolute -left-14 bottom-0 h-32 w-32 rounded-full bg-sky-500/10 blur-2xl" />
        <div className="relative z-10 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
          <div className="space-y-2">
            <div className="inline-flex items-center gap-2 rounded-full border border-border/80 bg-card px-3 py-1 text-xs font-medium text-muted-foreground">
              <Sparkles className="h-3.5 w-3.5 text-primary" />
              Personal account hub
            </div>
            <h1 className="text-2xl font-bold text-foreground font-heading uppercase tracking-[0.16em] sm:text-3xl">
              My Profile
            </h1>
            <p className="text-sm text-muted-foreground">
              View account details, update personal information, and monitor your recent actions.
            </p>
          </div>
          <Badge
            style={{
              backgroundColor: roleBadgeColor + "20",
              color: roleBadgeColor,
              borderColor: roleBadgeColor + "40",
            }}
            variant="outline"
            className="w-fit"
          >
            {dbUser.role}
          </Badge>
        </div>
      </section>

      <motion.div
        variants={staggerContainer}
        initial="initial"
        animate="animate"
        className="grid grid-cols-2 gap-3 lg:grid-cols-4"
      >
        {[
          {
            icon: UserCircle,
            label: "Status",
            value: dbUser.status.toUpperCase(),
            panel: "border-emerald-500/30 bg-emerald-500/10",
            text: "text-emerald-700 dark:text-emerald-300",
          },
          {
            icon: Shield,
            label: "Role",
            value: dbUser.role.toUpperCase(),
            panel: "border-indigo-500/30 bg-indigo-500/10",
            text: "text-indigo-700 dark:text-indigo-300",
          },
          {
            icon: Activity,
            label: "Recent Actions",
            value: recentActions,
            panel: "border-blue-500/30 bg-blue-500/10",
            text: "text-blue-700 dark:text-blue-300",
          },
          {
            icon: Clock,
            label: "Last Activity",
            value: latestActionAt
              ? formatDateTime(latestActionAt)
              : formatDateTime(dbUser.lastLoginAt),
            panel: "border-amber-500/30 bg-amber-500/10",
            text: "text-amber-700 dark:text-amber-300",
          },
        ].map((item) => (
          <motion.div key={item.label} variants={staggerItem} {...hoverLift}>
            <div className={`${item.panel} rounded-xl border px-4 py-3`}>
              <div className="flex items-start justify-between gap-2">
                <div className="min-w-0">
                  <p className="text-[10px] font-bold uppercase tracking-[0.16em] text-muted-foreground">
                    {item.label}
                  </p>
                  <p
                    className={`mt-1 line-clamp-2 text-sm font-semibold tracking-tight sm:text-base ${item.text}`}
                  >
                    {item.value}
                  </p>
                </div>
                <div className="rounded-lg border border-border/70 bg-card px-2 py-1 shadow-inner">
                  <item.icon className={`h-4 w-4 ${item.text}`} />
                </div>
              </div>
            </div>
          </motion.div>
        ))}
      </motion.div>

      <div className="grid gap-6 xl:grid-cols-[1.05fr_0.95fr]">
        <Card className="border-border-strong/70 bg-card/95 shadow-[0_12px_28px_rgba(47,62,64,0.07)]">
          <CardHeader className="pb-4">
            <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
              <div className="flex items-center gap-4">
                <div className="flex h-16 w-16 items-center justify-center rounded-full bg-primary/20">
                  {dbUser.avatarUrl ? (
                    <img
                      src={dbUser.avatarUrl}
                      alt={dbUser.name}
                      className="h-16 w-16 rounded-full object-cover"
                    />
                  ) : (
                    <span className="text-2xl font-bold text-primary">{initials}</span>
                  )}
                </div>
                <div>
                  <CardTitle className="text-xl text-foreground font-heading">
                    {dbUser.name}
                  </CardTitle>
                  <CardDescription className="break-all text-muted-foreground">
                    {dbUser.email}
                  </CardDescription>
                  <div className="mt-2 flex flex-wrap items-center gap-2">
                    <Badge
                      style={{
                        backgroundColor: roleBadgeColor + "20",
                        color: roleBadgeColor,
                        borderColor: roleBadgeColor + "40",
                      }}
                      variant="outline"
                    >
                      {dbUser.role}
                    </Badge>
                    <Badge
                      variant="outline"
                      className={
                        dbUser.status === "active"
                          ? "border-green-600/40 bg-green-600/10 text-green-400"
                          : "border-border-strong text-muted-foreground"
                      }
                    >
                      {dbUser.status}
                    </Badge>
                  </div>
                </div>
              </div>

              <Dialog open={editOpen} onOpenChange={setEditOpen}>
                <DialogTrigger asChild>
                  <motion.div {...hoverLift}>
                    <Button
                      variant="outline"
                      size="sm"
                      className="border-border/80 bg-background/80 text-foreground hover:bg-muted/60"
                    >
                      <Pencil className="h-4 w-4 mr-1" />
                      Edit
                    </Button>
                  </motion.div>
                </DialogTrigger>
                <ProfileEditDialog
                  user={dbUser}
                  onClose={() => setEditOpen(false)}
                  onSaved={refreshUser}
                />
              </Dialog>
            </div>
          </CardHeader>

          <CardContent className="space-y-4 border-t border-border-strong/70 pt-5">
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
              <DetailRow icon={Mail} label="Email" value={dbUser.email} />
              <DetailRow icon={Phone} label="Phone" value={dbUser.phone || "Not set"} />
              <DetailRow
                icon={Shield}
                label="Role"
                value={dbUser.role.charAt(0).toUpperCase() + dbUser.role.slice(1)}
              />
              {settings.multi_branch_enabled && (
                <DetailRow
                  icon={Building2}
                  label="Branch"
                  value={dbUser.branch_id || "Not assigned"}
                />
              )}
              <DetailRow
                icon={Clock}
                label="Last Login"
                value={formatDateTime(dbUser.lastLoginAt)}
              />
              <DetailRow
                icon={Clock}
                label="Member Since"
                value={
                  dbUser.createdAt
                    ? new Date(dbUser.createdAt).toLocaleDateString("en-IN")
                    : "-"
                }
              />
            </div>

            {dbUser.bio && (
              <div className="border-t border-border-strong/70 pt-3">
                <p className="mb-1 text-xs uppercase tracking-[0.12em] text-muted-foreground">
                  Bio
                </p>
                <p className="whitespace-pre-wrap text-sm text-foreground">{dbUser.bio}</p>
              </div>
            )}
          </CardContent>
        </Card>

        <Card className="border-border-strong/70 bg-card/95 shadow-[0_12px_28px_rgba(47,62,64,0.07)]">
          <CardHeader className="pb-3">
            <div className="flex items-center gap-2">
              <Activity className="h-5 w-5 text-primary" />
              <CardTitle className="text-lg text-foreground">Recent Activity</CardTitle>
            </div>
            <CardDescription className="text-muted-foreground">
              Latest login timestamps and module actions.
            </CardDescription>
          </CardHeader>
          <CardContent>
            {logsLoading ? (
              <div className="flex items-center justify-center py-8">
                <Loader2 className="h-5 w-5 animate-spin text-primary" />
              </div>
            ) : activityLogs.length === 0 ? (
              <p className="py-6 text-center text-sm text-muted-foreground">
                No activity recorded yet
              </p>
            ) : (
              <div className="space-y-2">
                {activityLogs.map((log) => {
                  const actionIcon = getActivityIcon(log.action);
                  const ts = log.createdAt;
                  const timeStr = ts ? formatDateTime(ts) : "-";

                  return (
                    <div
                      key={log.id}
                      className="flex items-center gap-3 rounded-lg border border-border/70 bg-background/60 p-2.5 transition-colors hover:bg-muted/40"
                    >
                      <div className="h-8 w-8 shrink-0 rounded-full bg-muted flex items-center justify-center">
                        {actionIcon}
                      </div>
                      <div className="min-w-0 flex-1">
                        <p className="truncate text-sm text-foreground">
                          {log.action.replace(/_/g, " ").toUpperCase()}
                          {log.module ? (
                            <span className="text-muted-foreground"> - {log.module}</span>
                          ) : null}
                        </p>
                        <p className="truncate text-xs text-muted-foreground">
                          {log.details || "-"}
                        </p>
                      </div>
                      <span className="whitespace-nowrap text-xs text-muted-foreground shrink-0">
                        {timeStr}
                      </span>
                    </div>
                  );
                })}
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </motion.div>
  );
}

function getActivityIcon(action: string) {
  switch (action) {
    case "login":
      return <LogIn className="h-4 w-4 text-green-400" />;
    case "logout":
      return <LogOut className="h-4 w-4 text-muted-foreground" />;
    case "create":
      return <UserPlus className="h-4 w-4 text-blue-400" />;
    case "update":
      return <Settings className="h-4 w-4 text-amber-400" />;
    case "delete":
      return <FileText className="h-4 w-4 text-red-400" />;
    default:
      return <Activity className="h-4 w-4 text-primary" />;
  }
}

function DetailRow({
  icon: Icon,
  label,
  value,
}: {
  icon: LucideIcon;
  label: string;
  value: string;
}) {
  return (
    <div className="flex items-start gap-3 rounded-lg border border-border/60 bg-background/60 px-3 py-2.5">
      <div className="h-9 w-9 shrink-0 rounded-lg border border-border/50 bg-background flex items-center justify-center">
        <Icon className="h-4 w-4 text-muted-foreground" />
      </div>
      <div className="min-w-0">
        <p className="text-xs uppercase tracking-[0.08em] text-muted-foreground">{label}</p>
        <p className="text-sm text-foreground break-all">{value}</p>
      </div>
    </div>
  );
}

function ProfileEditDialog({
  user,
  onClose,
  onSaved,
}: {
  user: { id: string; name: string; phone?: string; bio?: string };
  onClose: () => void;
  onSaved?: () => void;
}) {
  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting },
  } = useForm<ProfileFormData>({
    resolver: zodResolver(profileSchema),
    defaultValues: {
      name: user.name,
      phone: user.phone || "",
      bio: user.bio || "",
    },
  });

  const onSubmit = async (data: ProfileFormData) => {
    try {
      await userService.update(user.id, {
        name: data.name,
        phone: data.phone || undefined,
        bio: data.bio || undefined,
      });
      toast.success("Profile updated");
      auditLogService
        .logAction(
          user.id,
          user.name || "",
          "update",
          "profile",
          `Updated profile: name=${data.name}`,
        )
        .catch(() => {});
      if (onSaved) onSaved();
      onClose();
    } catch {
      toast.error("Failed to update profile");
    }
  };

  return (
    <DialogContent className="max-w-md rounded-3xl border border-border-strong/80 bg-card/95 text-foreground shadow-[0_18px_36px_rgba(47,62,64,0.14)]">
      <DialogHeader>
        <DialogTitle className="font-heading uppercase tracking-[0.12em] text-foreground">
          Edit Profile
        </DialogTitle>
      </DialogHeader>
      <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
        <div className="space-y-2">
          <Label className="text-muted-foreground">Full Name</Label>
          <Input
            {...register("name")}
            className="border-border/80 bg-background/80 text-foreground"
          />
          {errors.name && (
            <p className="text-xs text-red-400">{errors.name.message}</p>
          )}
        </div>

        <div className="space-y-2">
          <Label className="text-muted-foreground">Phone</Label>
          <Input
            {...register("phone")}
            className="border-border/80 bg-background/80 text-foreground"
            placeholder="+91 XXXXX XXXXX"
          />
        </div>

        <div className="space-y-2">
          <Label className="text-muted-foreground">Bio</Label>
          <Textarea
            {...register("bio")}
            rows={4}
            className="resize-none border-border/80 bg-background/80 text-foreground"
            placeholder="A short bio about yourself..."
          />
          {errors.bio && <p className="text-xs text-red-400">{errors.bio.message}</p>}
        </div>

        <DialogFooter>
          <Button
            type="button"
            variant="outline"
            onClick={onClose}
            className="border-border/80 bg-background/80 text-muted-foreground"
          >
            Cancel
          </Button>
          <Button
            type="submit"
            disabled={isSubmitting}
            className="bg-primary text-primary-foreground hover:bg-primary/90"
          >
            {isSubmitting && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
            <Save className="h-4 w-4 mr-1" />
            Save
          </Button>
        </DialogFooter>
      </form>
    </DialogContent>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { motion } from "framer-motion";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { toast } from "sonner";
import { ArrowLeft, Loader2, Plus, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { pageTransition } from "@/lib/helpers/animations";
import { useAuth } from "@/lib/context/auth-context";

const POLICY_TYPES = [
  "motor", "health", "life", "fire", "marine", "burglary",
  "liability", "workmen_compensation", "travel", "other",
];

const INSURERS = [
  "HDFC Ergo", "ICICI Lombard", "Bajaj Allianz", "New India Assurance",
  "Oriental Insurance", "United India Insurance", "National Insurance",
  "Star Health", "Niva Bupa", "Care Health", "Tata AIG", "Reliance General",
  "SBI General", "Kotak Mahindra General", "Future Generali",
];

const schema = z.object({
  customer_id: z.string().min(1, "Customer is required"),
  policy_type: z.string().min(1, "Policy type is required"),
  coverage_requirements: z.string().optional(),
  notes: z.string().optional(),
  assigned_to: z.string().min(1, "Assigned to is required"),
});

type FormData = z.infer<typeof schema>;

export default function NewQuoteRequestPage() {
  const router = useRouter();
  const { session, user } = useAuth();
  const [loading, setLoading] = useState(false);
  const [targetInsurers, setTargetInsurers] = useState<string[]>([]);
  const [customInsurer, setCustomInsurer] = useState("");

  const {
    register,
    handleSubmit,
    setValue,
    watch,
    formState: { errors },
  } = useForm<FormData>({
    resolver: zodResolver(schema),
    defaultValues: {
      assigned_to: user?.uid ?? "",
    },
  });

  const policyType = watch("policy_type");

  const addInsurer = (insurer: string) => {
    if (insurer && !targetInsurers.includes(insurer)) {
      setTargetInsurers((prev) => [...prev, insurer]);
    }
  };

  const removeInsurer = (insurer: string) => {
    setTargetInsurers((prev) => prev.filter((i) => i !== insurer));
  };

  const onSubmit = async (data: FormData) => {
    setLoading(true);
    try {
      const token = session?.access_token;
      if (!token) throw new Error("Not authenticated");

      const res = await fetch("/api/quotes", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ ...data, target_insurers: targetInsurers }),
      });

      const result = await res.json();
      if (!res.ok) throw new Error(result.error ?? "Failed to create quote request");

      toast.success(`Quote request ${result.quote_request_number} created`);
      router.push(`/dashboard/quotes/${result.id}`);
    } catch (err: any) {
      toast.error(err.message ?? "Failed to create quote request");
    } finally {
      setLoading(false);
    }
  };

  return (
    <motion.div {...pageTransition} className="space-y-6 max-w-2xl">
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="sm" onClick={() => router.back()}>
          <ArrowLeft className="w-4 h-4 mr-2" /> Back
        </Button>
        <h1 className="text-xl font-heading font-bold uppercase tracking-wider">
          New Quote Request
        </h1>
      </div>

      <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
        <div className="bg-card border border-border rounded-xl p-6 space-y-4">
          <h2 className="text-sm font-heading font-bold uppercase tracking-wider">
            Request Details
          </h2>

          <div className="space-y-1.5">
            <Label htmlFor="customer_id">Customer ID *</Label>
            <Input
              id="customer_id"
              placeholder="Enter customer UUID"
              {...register("customer_id")}
            />
            {errors.customer_id && (
              <p className="text-xs text-red-400">{errors.customer_id.message}</p>
            )}
            <p className="text-xs text-muted-foreground">
              Paste the customer UUID from the customer list.
            </p>
          </div>

          <div className="space-y-1.5">
            <Label>Policy Type *</Label>
            <Select value={policyType} onValueChange={(v) => setValue("policy_type", v)}>
              <SelectTrigger>
                <SelectValue placeholder="Select policy type" />
              </SelectTrigger>
              <SelectContent>
                {POLICY_TYPES.map((t) => (
                  <SelectItem key={t} value={t} className="capitalize">
                    {t.replace(/_/g, " ")}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            {errors.policy_type && (
              <p className="text-xs text-red-400">{errors.policy_type.message}</p>
            )}
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="coverage_requirements">Coverage Requirements</Label>
            <Textarea
              id="coverage_requirements"
              placeholder="Describe coverage requirements, sum insured range, special needs..."
              rows={3}
              {...register("coverage_requirements")}
            />
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="notes">Notes</Label>
            <Textarea
              id="notes"
              placeholder="Additional notes..."
              rows={2}
              {...register("notes")}
            />
          </div>
        </div>

        {/* Target Insurers */}
        <div className="bg-card border border-border rounded-xl p-6 space-y-4">
          <h2 className="text-sm font-heading font-bold uppercase tracking-wider">
            Target Insurers
          </h2>

          <div className="flex flex-wrap gap-2">
            {INSURERS.map((ins) => (
              <button
                key={ins}
                type="button"
                onClick={() =>
                  targetInsurers.includes(ins) ? removeInsurer(ins) : addInsurer(ins)
                }
                className={`px-3 py-1 rounded-full text-xs border transition-colors ${
                  targetInsurers.includes(ins)
                    ? "bg-primary text-primary-foreground border-primary"
                    : "bg-muted/30 text-muted-foreground border-border hover:border-primary/50"
                }`}
              >
                {ins}
              </button>
            ))}
          </div>

          {/* Custom insurer */}
          <div className="flex gap-2">
            <Input
              placeholder="Add custom insurer..."
              value={customInsurer}
              onChange={(e) => setCustomInsurer(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault();
                  addInsurer(customInsurer);
                  setCustomInsurer("");
                }
              }}
            />
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={() => {
                addInsurer(customInsurer);
                setCustomInsurer("");
              }}
            >
              <Plus className="w-4 h-4" />
            </Button>
          </div>

          {targetInsurers.length > 0 && (
            <div className="flex flex-wrap gap-2">
              {targetInsurers.map((ins) => (
                <Badge key={ins} variant="outline" className="gap-1 text-xs">
                  {ins}
                  <button onClick={() => removeInsurer(ins)}>
                    <X className="w-3 h-3" />
                  </button>
                </Badge>
              ))}
            </div>
          )}
        </div>

        <div className="flex justify-end gap-3">
          <Button type="button" variant="outline" onClick={() => router.back()}>
            Cancel
          </Button>
          <Button type="submit" disabled={loading}>
            {loading && <Loader2 className="w-4 h-4 animate-spin mr-2" />}
            Create Quote Request
          </Button>
        </div>
      </form>
    </motion.div>
  );
}

"use client";

import { useState } from "react";
import { motion } from "framer-motion";
import { useRouter } from "next/navigation";
import useSWR from "swr";
import { FileText, Plus, Search, X } from "lucide-react";
import { format } from "date-fns";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { pageTransition } from "@/lib/helpers/animations";
import { useAuth } from "@/lib/context/auth-context";

const STATUS_COLORS: Record<string, string> = {
  open: "bg-blue-500/10 text-blue-400 border-blue-500/20",
  quotes_received: "bg-amber-500/10 text-amber-400 border-amber-500/20",
  converted: "bg-green-500/10 text-green-400 border-green-500/20",
  expired: "bg-gray-500/10 text-gray-400 border-gray-500/20",
  cancelled: "bg-red-500/10 text-red-400 border-red-500/20",
};

async function fetcher(url: string, token: string) {
  const res = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
  if (!res.ok) throw new Error("Failed to fetch");
  return res.json();
}

export default function QuotesPage() {
  const router = useRouter();
  const { session } = useAuth();
  const token = session?.access_token ?? "";

  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");

  const params = new URLSearchParams();
  if (statusFilter !== "all") params.set("status", statusFilter);
  params.set("limit", "50");

  const { data, isLoading } = useSWR(
    token ? [`/api/quotes?${params}`, token] : null,
    ([url, t]) => fetcher(url, t),
    { revalidateOnFocus: false }
  );

  const requests = (data?.data ?? []).filter((r: any) => {
    if (!search) return true;
    const q = search.toLowerCase();
    return (
      r.quote_request_number?.toLowerCase().includes(q) ||
      r.customers?.name?.toLowerCase().includes(q) ||
      r.policy_type?.toLowerCase().includes(q)
    );
  });

  return (
    <motion.div {...pageTransition} className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-heading font-bold text-foreground uppercase tracking-wider flex items-center gap-2">
            <FileText className="w-6 h-6 text-primary" />
            Quote Requests
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            Manage multi-insurer quote comparisons
          </p>
        </div>
        <Button size="sm" onClick={() => router.push("/dashboard/quotes/new")} className="gap-2">
          <Plus className="w-4 h-4" /> New Quote Request
        </Button>
      </div>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Search by QR#, customer, policy type..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9"
          />
          {search && (
            <button onClick={() => setSearch("")} className="absolute right-3 top-1/2 -translate-y-1/2">
              <X className="w-4 h-4 text-muted-foreground" />
            </button>
          )}
        </div>
        <Select value={statusFilter} onValueChange={setStatusFilter}>
          <SelectTrigger className="w-[160px]">
            <SelectValue placeholder="All Status" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Status</SelectItem>
            <SelectItem value="open">Open</SelectItem>
            <SelectItem value="quotes_received">Quotes Received</SelectItem>
            <SelectItem value="converted">Converted</SelectItem>
            <SelectItem value="expired">Expired</SelectItem>
            <SelectItem value="cancelled">Cancelled</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {/* Table */}
      <div className="bg-card border border-border rounded-xl overflow-hidden">
        {isLoading ? (
          <div className="p-6 space-y-3">
            {[...Array(5)].map((_, i) => <Skeleton key={i} className="h-12 w-full" />)}
          </div>
        ) : requests.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 gap-4">
            <FileText className="w-12 h-12 text-muted-foreground/40" />
            <p className="text-muted-foreground">No quote requests yet.</p>
            <Button onClick={() => router.push("/dashboard/quotes/new")} className="gap-2">
              <Plus className="w-4 h-4" /> Create First Quote Request
            </Button>
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow className="border-border hover:bg-transparent">
                <TableHead className="text-xs uppercase tracking-wider font-heading">QR #</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Customer</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden md:table-cell">Policy Type</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden lg:table-cell">Insurers</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden md:table-cell">Quotes</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Status</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden lg:table-cell">Created</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {requests.map((r: any) => (
                <TableRow
                  key={r.id}
                  className="border-border hover:bg-muted/30 cursor-pointer"
                  onClick={() => router.push(`/dashboard/quotes/${r.id}`)}
                >
                  <TableCell className="font-mono text-xs text-primary">
                    {r.quote_request_number}
                  </TableCell>
                  <TableCell>
                    <p className="text-sm font-medium">{r.customers?.name ?? "—"}</p>
                    <p className="text-xs text-muted-foreground">{r.customers?.phone ?? ""}</p>
                  </TableCell>
                  <TableCell className="hidden md:table-cell text-xs capitalize">
                    {r.policy_type?.replace(/_/g, " ") ?? "—"}
                  </TableCell>
                  <TableCell className="hidden lg:table-cell text-xs text-muted-foreground">
                    {(r.target_insurers ?? []).slice(0, 2).join(", ")}
                    {(r.target_insurers ?? []).length > 2 && ` +${r.target_insurers.length - 2}`}
                  </TableCell>
                  <TableCell className="hidden md:table-cell">
                    <Badge variant="outline" className="text-xs">
                      {(r.quotes ?? []).length} quotes
                    </Badge>
                  </TableCell>
                  <TableCell>
                    <Badge
                      variant="outline"
                      className={`text-xs capitalize ${STATUS_COLORS[r.status] ?? ""}`}
                    >
                      {r.status?.replace(/_/g, " ")}
                    </Badge>
                  </TableCell>
                  <TableCell className="hidden lg:table-cell text-xs text-muted-foreground">
                    {r.created_at ? format(new Date(r.created_at), "dd MMM yyyy") : "—"}
                  </TableCell>
                  <TableCell className="text-right">
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-7 text-xs"
                      onClick={(e) => {
                        e.stopPropagation();
                        router.push(`/dashboard/quotes/${r.id}`);
                      }}
                    >
                      Compare
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </div>
    </motion.div>
  );
}

"use client";

import { use } from "react";
import { useRouter } from "next/navigation";
import useSWR from "swr";
import { motion } from "framer-motion";
import { format } from "date-fns";
import {
  ArrowLeft, RefreshCw, Calendar, IndianRupee, Building2,
  User, Clock, History,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { pageTransition } from "@/lib/helpers/animations";
import { useAuth } from "@/lib/context/auth-context";
import { RenewalRiskBadge } from "@/components/renewals/RenewalRiskBadge";
import { RenewalStageSelector } from "@/components/renewals/RenewalStageSelector";
import { FollowUpTaskForm } from "@/components/renewals/FollowUpTaskForm";
import { FollowUpTaskList } from "@/components/renewals/FollowUpTaskList";

const STAGE_COLORS: Record<string, string> = {
  due: "bg-amber-500/10 text-amber-400 border-amber-500/20",
  contacted: "bg-blue-500/10 text-blue-400 border-blue-500/20",
  negotiating: "bg-purple-500/10 text-purple-400 border-purple-500/20",
  renewed: "bg-green-500/10 text-green-400 border-green-500/20",
  lost: "bg-red-500/10 text-red-400 border-red-500/20",
};

async function fetcher(url: string, token: string) {
  const res = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
  if (!res.ok) throw new Error("Failed to fetch");
  return res.json();
}

export default function RenewalDetailPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = use(params);
  const router = useRouter();
  const { session } = useAuth();
  const token = session?.access_token ?? "";

  const { data: entry, isLoading, mutate } = useSWR(
    token ? [`/api/renewals/pipeline?limit=1`, token, id] : null,
    async ([, t]) => {
      // Fetch single renewal by querying pipeline with all data
      const res = await fetch(`/api/renewals/pipeline?limit=200`, {
        headers: { Authorization: `Bearer ${t}` },
      });
      const data = await res.json();
      return (data.data ?? []).find((e: any) => e.id === id) ?? null;
    },
    { revalidateOnFocus: false }
  );

  // Fetch stage history
  const { data: historyData } = useSWR(
    token && id ? [`stage-history-${id}`, token] : null,
    async ([, t]) => {
      // We'll use supabase client directly for stage history
      const { supabase } = await import("@/lib/supabase/client");
      const { data } = await supabase
        .from("renewal_stage_history" as any)
        .select("*")
        .eq("renewal_id", id)
        .order("created_at", { ascending: false });
      return data ?? [];
    },
    { revalidateOnFocus: false }
  );

  if (isLoading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-10 w-48" />
        <Skeleton className="h-40 w-full" />
        <Skeleton className="h-60 w-full" />
      </div>
    );
  }

  if (!entry) {
    return (
      <div className="flex flex-col items-center justify-center py-20 gap-4">
        <p className="text-muted-foreground">Renewal not found.</p>
        <Button variant="outline" onClick={() => router.back()}>
          <ArrowLeft className="w-4 h-4 mr-2" /> Back
        </Button>
      </div>
    );
  }

  const policy = entry.policies;
  const customer = entry.customers;
  const tasks = entry.follow_up_tasks ?? [];

  return (
    <motion.div {...pageTransition} className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="sm" onClick={() => router.back()}>
          <ArrowLeft className="w-4 h-4 mr-2" /> Back
        </Button>
        <div className="flex-1">
          <h1 className="text-xl font-heading font-bold uppercase tracking-wider">
            Renewal Detail
          </h1>
          <p className="text-sm text-muted-foreground">
            {policy?.policy_number ?? "—"} · {customer?.name ?? "—"}
          </p>
        </div>
        <RenewalRiskBadge score={entry.risk_score ?? 0} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Main Info */}
        <div className="lg:col-span-2 space-y-4">
          {/* Policy Info */}
          <div className="bg-card border border-border rounded-xl p-5 space-y-4">
            <h2 className="text-sm font-heading font-bold uppercase tracking-wider flex items-center gap-2">
              <Building2 className="w-4 h-4 text-primary" /> Policy Information
            </h2>
            <div className="grid grid-cols-2 gap-4 text-sm">
              <div>
                <p className="text-xs text-muted-foreground uppercase tracking-wider">Policy #</p>
                <p className="font-mono font-medium mt-0.5">{policy?.policy_number ?? "—"}</p>
              </div>
              <div>
                <p className="text-xs text-muted-foreground uppercase tracking-wider">Type</p>
                <p className="capitalize mt-0.5">{policy?.policy_type?.replace(/_/g, " ") ?? "—"}</p>
              </div>
              <div>
                <p className="text-xs text-muted-foreground uppercase tracking-wider">Insurer</p>
                <p className="mt-0.5">{policy?.insurer_name ?? "—"}</p>
              </div>
              <div>
                <p className="text-xs text-muted-foreground uppercase tracking-wider">Premium</p>
                <p className="font-medium mt-0.5">
                  {policy?.premium_amount
                    ? `₹${policy.premium_amount.toLocaleString("en-IN")}`
                    : "—"}
                </p>
              </div>
              <div>
                <p className="text-xs text-muted-foreground uppercase tracking-wider">Expiry Date</p>
                <p className="mt-0.5 flex items-center gap-1">
                  <Calendar className="w-3.5 h-3.5 text-muted-foreground" />
                  {policy?.end_date
                    ? format(new Date(policy.end_date), "dd MMM yyyy")
                    : "—"}
                </p>
              </div>
              <div>
                <p className="text-xs text-muted-foreground uppercase tracking-wider">Sum Insured</p>
                <p className="mt-0.5">
                  {policy?.sum_insured
                    ? `₹${policy.sum_insured.toLocaleString("en-IN")}`
                    : "—"}
                </p>
              </div>
            </div>
          </div>

          {/* Customer Info */}
          <div className="bg-card border border-border rounded-xl p-5 space-y-4">
            <h2 className="text-sm font-heading font-bold uppercase tracking-wider flex items-center gap-2">
              <User className="w-4 h-4 text-primary" /> Customer
            </h2>
            <div className="grid grid-cols-2 gap-4 text-sm">
              <div>
                <p className="text-xs text-muted-foreground uppercase tracking-wider">Name</p>
                <p className="font-medium mt-0.5">{customer?.name ?? "—"}</p>
              </div>
              <div>
                <p className="text-xs text-muted-foreground uppercase tracking-wider">Phone</p>
                <p className="mt-0.5">{customer?.phone ?? "—"}</p>
              </div>
              <div>
                <p className="text-xs text-muted-foreground uppercase tracking-wider">Email</p>
                <p className="mt-0.5 truncate">{customer?.email ?? "—"}</p>
              </div>
              <div>
                <p className="text-xs text-muted-foreground uppercase tracking-wider">Last Contact</p>
                <p className="mt-0.5">
                  {entry.last_contact_date
                    ? format(new Date(entry.last_contact_date), "dd MMM yyyy")
                    : "Never"}
                </p>
              </div>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={() => router.push(`/dashboard/customers/${entry.customer_id}`)}
            >
              View Client 360
            </Button>
          </div>

          {/* Follow-up Tasks */}
          <div className="bg-card border border-border rounded-xl p-5 space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-sm font-heading font-bold uppercase tracking-wider flex items-center gap-2">
                <Clock className="w-4 h-4 text-primary" /> Follow-up Tasks
              </h2>
              <FollowUpTaskForm renewalId={id} onCreated={() => mutate()} />
            </div>
            <FollowUpTaskList
              renewalId={id}
              tasks={tasks}
              onTaskUpdated={() => mutate()}
            />
          </div>
        </div>

        {/* Sidebar */}
        <div className="space-y-4">
          {/* Stage Management */}
          <div className="bg-card border border-border rounded-xl p-5 space-y-4">
            <h2 className="text-sm font-heading font-bold uppercase tracking-wider flex items-center gap-2">
              <RefreshCw className="w-4 h-4 text-primary" /> Stage
            </h2>
            <div className="flex items-center gap-3">
              <Badge
                variant="outline"
                className={`text-sm capitalize ${STAGE_COLORS[entry.stage] ?? ""}`}
              >
                {entry.stage}
              </Badge>
              <RenewalStageSelector
                renewalId={id}
                currentStage={entry.stage}
                onStageUpdated={() => mutate()}
              />
            </div>
            {entry.lost_reason && (
              <div className="text-xs text-muted-foreground bg-red-500/5 border border-red-500/20 rounded-lg p-3">
                <p className="font-medium text-red-400 mb-1">Lost Reason</p>
                <p>{entry.lost_reason}</p>
              </div>
            )}
          </div>

          {/* Stage History */}
          <div className="bg-card border border-border rounded-xl p-5 space-y-3">
            <h2 className="text-sm font-heading font-bold uppercase tracking-wider flex items-center gap-2">
              <History className="w-4 h-4 text-primary" /> Stage History
            </h2>
            {(historyData ?? []).length === 0 ? (
              <p className="text-xs text-muted-foreground">No history yet.</p>
            ) : (
              <div className="space-y-2">
                {(historyData ?? []).map((h: any) => (
                  <div key={h.id} className="text-xs border-l-2 border-primary/30 pl-3">
                    <p className="font-medium">
                      {h.from_stage ? `${h.from_stage} → ` : ""}{h.to_stage}
                    </p>
                    <p className="text-muted-foreground">
                      {h.changed_by_name ?? "System"} · {format(new Date(h.created_at), "dd MMM, HH:mm")}
                    </p>
                    {h.notes && <p className="text-muted-foreground italic">{h.notes}</p>}
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Pipeline Info */}
          <div className="bg-card border border-border rounded-xl p-5 space-y-3">
            <h2 className="text-sm font-heading font-bold uppercase tracking-wider">Pipeline Info</h2>
            <div className="space-y-2 text-xs">
              <div className="flex justify-between">
                <span className="text-muted-foreground">Entered Pipeline</span>
                <span>
                  {entry.entered_pipeline_at
                    ? format(new Date(entry.entered_pipeline_at), "dd MMM yyyy")
                    : "—"}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground">Stage Updated</span>
                <span>
                  {entry.stage_updated_at
                    ? format(new Date(entry.stage_updated_at), "dd MMM yyyy")
                    : "—"}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground">Risk Score</span>
                <RenewalRiskBadge score={entry.risk_score ?? 0} />
              </div>
            </div>
          </div>
        </div>
      </div>
    </motion.div>
  );
}

"use client";

import { useState, useMemo } from "react";
import { motion } from "framer-motion";
import { useRouter } from "next/navigation";
import useSWR from "swr";
import {
  RefreshCw, Search, Filter, List, LayoutGrid, Download,
  AlertCircle, Phone, TrendingUp, CheckCircle2, XCircle,
  IndianRupee, Eye, Loader2, X,
} from "lucide-react";
import { toast } from "sonner";
import { format } from "date-fns";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { pageTransition, staggerContainer, staggerItem } from "@/lib/helpers/animations";
import { useAuth } from "@/lib/context/auth-context";
import { RenewalRiskBadge } from "@/components/renewals/RenewalRiskBadge";
import { RenewalStageSelector } from "@/components/renewals/RenewalStageSelector";

const PAGE_SIZE = 50;

const STAGE_COLORS: Record<string, string> = {
  due: "bg-amber-500/10 text-amber-400 border-amber-500/20",
  contacted: "bg-blue-500/10 text-blue-400 border-blue-500/20",
  negotiating: "bg-purple-500/10 text-purple-400 border-purple-500/20",
  renewed: "bg-green-500/10 text-green-400 border-green-500/20",
  lost: "bg-red-500/10 text-red-400 border-red-500/20",
};

const KANBAN_STAGES = ["due", "contacted", "negotiating", "renewed", "lost"] as const;

function fmt(n: number) {
  if (n >= 10_00_000) return `₹${(n / 10_00_000).toFixed(1)}L`;
  if (n >= 1_000) return `₹${(n / 1_000).toFixed(0)}K`;
  return `₹${n.toLocaleString("en-IN")}`;
}

async function fetcher(url: string, token: string) {
  const res = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
  if (!res.ok) throw new Error("Failed to fetch");
  return res.json();
}

export default function RenewalCockpitPage() {
  const router = useRouter();
  const { session, role } = useAuth();
  const token = session?.access_token ?? "";

  const [viewMode, setViewMode] = useState<"list" | "kanban">("list");
  const [search, setSearch] = useState("");
  const [stageFilter, setStageFilter] = useState("all");
  const [policyTypeFilter, setPolicyTypeFilter] = useState("all");
  const [page, setPage] = useState(1);

  // Build query params
  const params = new URLSearchParams();
  if (stageFilter !== "all") params.set("stage", stageFilter);
  if (policyTypeFilter !== "all") params.set("policy_type", policyTypeFilter);
  if (search) params.set("search", search);
  params.set("limit", "200"); // load more for kanban

  const { data: pipelineData, isLoading, mutate } = useSWR(
    token ? [`/api/renewals/pipeline?${params}`, token] : null,
    ([url, t]) => fetcher(url, t),
    { revalidateOnFocus: false }
  );

  const { data: analytics } = useSWR(
    token ? [`/api/renewals/analytics`, token] : null,
    ([url, t]) => fetcher(url, t),
    { revalidateOnFocus: false }
  );

  const entries = pipelineData?.data ?? [];

  // Paginate for list view
  const totalPages = Math.ceil(entries.length / PAGE_SIZE);
  const paginated = entries.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  // Kanban grouping
  const kanbanGroups = useMemo(() => {
    const groups: Record<string, any[]> = {};
    for (const stage of KANBAN_STAGES) groups[stage] = [];
    for (const entry of entries) {
      if (groups[entry.stage]) groups[entry.stage].push(entry);
    }
    return groups;
  }, [entries]);

  const handleExport = async () => {
    if (!token) return;
    const ids = entries.map((e: any) => e.id);
    if (ids.length === 0) { toast.error("No renewals to export"); return; }

    try {
      const res = await fetch("/api/renewals/bulk", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({ action: "export_csv", ids }),
      });
      if (!res.ok) throw new Error("Export failed");
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `renewals-${Date.now()}.csv`;
      a.click();
      URL.revokeObjectURL(url);
      toast.success("Exported successfully");
    } catch {
      toast.error("Export failed");
    }
  };

  const stageCounts = analytics?.stageCounts ?? {};
  const conversionRate = analytics?.conversionRate ?? 0;
  const premiumAtRisk = analytics?.premiumAtRisk ?? 0;

  const metrics = [
    { label: "Due", value: stageCounts.due ?? 0, color: "text-amber-400", icon: AlertCircle },
    { label: "Contacted", value: stageCounts.contacted ?? 0, color: "text-blue-400", icon: Phone },
    { label: "Negotiating", value: stageCounts.negotiating ?? 0, color: "text-purple-400", icon: TrendingUp },
    { label: "Renewed", value: stageCounts.renewed ?? 0, color: "text-green-400", icon: CheckCircle2 },
    { label: "Lost", value: stageCounts.lost ?? 0, color: "text-red-400", icon: XCircle },
    { label: "Conversion", value: `${conversionRate}%`, color: "text-primary", icon: TrendingUp },
    { label: "Premium at Risk", value: fmt(premiumAtRisk), color: "text-orange-400", icon: IndianRupee },
  ];

  return (
    <motion.div {...pageTransition} className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-heading font-bold text-foreground uppercase tracking-wider flex items-center gap-2">
            <RefreshCw className="w-6 h-6 text-primary" />
            Renewal Cockpit
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            Manage your renewal pipeline — {entries.length} renewals
          </p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" onClick={handleExport} className="gap-2">
            <Download className="w-4 h-4" /> Export
          </Button>
          {(role === "admin" || role === "manager") && (
            <Button size="sm" onClick={() => router.push("/dashboard/renewals/new")} className="gap-2">
              + Add Renewal
            </Button>
          )}
        </div>
      </div>

      {/* Metrics Bar */}
      <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-7 gap-3">
        {metrics.map(({ label, value, color, icon: Icon }) => (
          <div key={label} className="bg-card border border-border rounded-xl p-3 flex flex-col gap-1">
            <div className="flex items-center gap-1.5">
              <Icon className={`w-3.5 h-3.5 ${color}`} />
              <p className="text-xs text-muted-foreground font-heading uppercase tracking-wider truncate">{label}</p>
            </div>
            <p className={`text-xl font-bold ${color}`}>{value}</p>
          </div>
        ))}
      </div>

      {/* Filters + View Toggle */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Search customer, policy #, insurer..."
            value={search}
            onChange={(e) => { setSearch(e.target.value); setPage(1); }}
            className="pl-9"
          />
          {search && (
            <button onClick={() => setSearch("")} className="absolute right-3 top-1/2 -translate-y-1/2">
              <X className="w-4 h-4 text-muted-foreground" />
            </button>
          )}
        </div>

        <Select value={stageFilter} onValueChange={(v) => { setStageFilter(v); setPage(1); }}>
          <SelectTrigger className="w-[140px]">
            <Filter className="w-3.5 h-3.5 mr-2 text-muted-foreground" />
            <SelectValue placeholder="Stage" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Stages</SelectItem>
            {KANBAN_STAGES.map((s) => (
              <SelectItem key={s} value={s} className="capitalize">{s}</SelectItem>
            ))}
          </SelectContent>
        </Select>

        <Select value={policyTypeFilter} onValueChange={(v) => { setPolicyTypeFilter(v); setPage(1); }}>
          <SelectTrigger className="w-[150px]">
            <SelectValue placeholder="Policy Type" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Types</SelectItem>
            {["motor", "health", "life", "fire", "marine", "other"].map((t) => (
              <SelectItem key={t} value={t} className="capitalize">{t}</SelectItem>
            ))}
          </SelectContent>
        </Select>

        <div className="flex gap-1 border border-border rounded-lg p-1">
          <Button
            size="sm"
            variant={viewMode === "list" ? "default" : "ghost"}
            className="h-7 px-2"
            onClick={() => setViewMode("list")}
          >
            <List className="w-3.5 h-3.5" />
          </Button>
          <Button
            size="sm"
            variant={viewMode === "kanban" ? "default" : "ghost"}
            className="h-7 px-2"
            onClick={() => setViewMode("kanban")}
          >
            <LayoutGrid className="w-3.5 h-3.5" />
          </Button>
        </div>
      </div>

      {/* Content */}
      {isLoading ? (
        <div className="space-y-3">
          {[...Array(5)].map((_, i) => <Skeleton key={i} className="h-14 w-full" />)}
        </div>
      ) : entries.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-20 gap-4 bg-card border border-border rounded-xl">
          <RefreshCw className="w-12 h-12 text-muted-foreground/40" />
          <p className="text-muted-foreground">No renewals in pipeline.</p>
        </div>
      ) : viewMode === "list" ? (
        <>
          <div className="bg-card border border-border rounded-xl overflow-hidden">
            <Table>
              <TableHeader>
                <TableRow className="border-border hover:bg-transparent">
                  <TableHead className="text-xs uppercase tracking-wider font-heading">Customer</TableHead>
                  <TableHead className="text-xs uppercase tracking-wider font-heading hidden md:table-cell">Policy #</TableHead>
                  <TableHead className="text-xs uppercase tracking-wider font-heading hidden lg:table-cell">Type</TableHead>
                  <TableHead className="text-xs uppercase tracking-wider font-heading">Expiry</TableHead>
                  <TableHead className="text-xs uppercase tracking-wider font-heading hidden md:table-cell">Premium</TableHead>
                  <TableHead className="text-xs uppercase tracking-wider font-heading">Risk</TableHead>
                  <TableHead className="text-xs uppercase tracking-wider font-heading">Stage</TableHead>
                  <TableHead className="text-xs uppercase tracking-wider font-heading hidden lg:table-cell">Last Contact</TableHead>
                  <TableHead className="text-xs uppercase tracking-wider font-heading text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {paginated.map((entry: any) => (
                  <TableRow
                    key={entry.id}
                    className="border-border hover:bg-muted/30 cursor-pointer"
                    onClick={() => router.push(`/dashboard/renewals/${entry.id}`)}
                  >
                    <TableCell>
                      <div>
                        <p className="text-sm font-medium">{entry.customers?.name ?? "—"}</p>
                        <p className="text-xs text-muted-foreground">{entry.customers?.phone ?? ""}</p>
                      </div>
                    </TableCell>
                    <TableCell className="hidden md:table-cell font-mono text-xs">
                      {entry.policies?.policy_number ?? "—"}
                    </TableCell>
                    <TableCell className="hidden lg:table-cell text-xs capitalize">
                      {entry.policies?.policy_type?.replace(/_/g, " ") ?? "—"}
                    </TableCell>
                    <TableCell className="text-xs">
                      {entry.policies?.end_date
                        ? format(new Date(entry.policies.end_date), "dd MMM yyyy")
                        : "—"}
                    </TableCell>
                    <TableCell className="hidden md:table-cell text-xs">
                      {entry.policies?.premium_amount
                        ? fmt(entry.policies.premium_amount)
                        : "—"}
                    </TableCell>
                    <TableCell>
                      <RenewalRiskBadge score={entry.risk_score ?? 0} />
                    </TableCell>
                    <TableCell>
                      <Badge
                        variant="outline"
                        className={`text-xs capitalize ${STAGE_COLORS[entry.stage] ?? ""}`}
                      >
                        {entry.stage}
                      </Badge>
                    </TableCell>
                    <TableCell className="hidden lg:table-cell text-xs text-muted-foreground">
                      {entry.last_contact_date
                        ? format(new Date(entry.last_contact_date), "dd MMM")
                        : "Never"}
                    </TableCell>
                    <TableCell className="text-right" onClick={(e) => e.stopPropagation()}>
                      <Button
                        variant="ghost"
                        size="sm"
                        className="h-7 w-7 p-0"
                        onClick={() => router.push(`/dashboard/renewals/${entry.id}`)}
                      >
                        <Eye className="w-3.5 h-3.5" />
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex items-center justify-between">
              <p className="text-sm text-muted-foreground">
                Showing {(page - 1) * PAGE_SIZE + 1}–{Math.min(page * PAGE_SIZE, entries.length)} of {entries.length}
              </p>
              <div className="flex gap-2">
                <Button variant="outline" size="sm" disabled={page === 1} onClick={() => setPage((p) => p - 1)}>
                  Previous
                </Button>
                <Button variant="outline" size="sm" disabled={page === totalPages} onClick={() => setPage((p) => p + 1)}>
                  Next
                </Button>
              </div>
            </div>
          )}
        </>
      ) : (
        /* Kanban View */
        <div className="grid grid-cols-1 sm:grid-cols-3 lg:grid-cols-5 gap-4 overflow-x-auto">
          {KANBAN_STAGES.map((stage) => (
            <div key={stage} className="min-w-[220px]">
              <div className={`flex items-center justify-between mb-3 px-3 py-2 rounded-lg border ${STAGE_COLORS[stage]}`}>
                <span className="text-xs font-heading font-bold uppercase tracking-wider capitalize">{stage}</span>
                <Badge variant="outline" className={`text-xs ${STAGE_COLORS[stage]}`}>
                  {kanbanGroups[stage]?.length ?? 0}
                </Badge>
              </div>
              <div className="space-y-2">
                {(kanbanGroups[stage] ?? []).map((entry: any) => (
                  <button
                    key={entry.id}
                    onClick={() => router.push(`/dashboard/renewals/${entry.id}`)}
                    className="w-full text-left p-3 rounded-xl bg-card border border-border hover:bg-muted/30 transition-colors"
                  >
                    <p className="text-sm font-medium truncate">{entry.customers?.name ?? "—"}</p>
                    <p className="text-xs text-muted-foreground font-mono mt-0.5">
                      {entry.policies?.policy_number ?? "—"}
                    </p>
                    <div className="flex items-center justify-between mt-2">
                      <RenewalRiskBadge score={entry.risk_score ?? 0} showScore={false} />
                      <span className="text-xs text-muted-foreground">
                        {entry.policies?.end_date
                          ? format(new Date(entry.policies.end_date), "dd MMM")
                          : "—"}
                      </span>
                    </div>
                    {entry.policies?.premium_amount && (
                      <p className="text-xs text-muted-foreground mt-1">
                        {fmt(entry.policies.premium_amount)}
                      </p>
                    )}
                  </button>
                ))}
                {(kanbanGroups[stage] ?? []).length === 0 && (
                  <div className="text-center py-6 text-xs text-muted-foreground border border-dashed border-border rounded-xl">
                    No renewals
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </motion.div>
  );
}

"use client";

import { useSearchParams } from "next/navigation";
import { CreateTicketDialog } from "@/components/service-desk/CreateTicketDialog";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";

export default function NewTicketPage() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const customerId = searchParams.get("customer") || undefined;
  const policyId = searchParams.get("policy") || undefined;
  const [open, setOpen] = useState(true);

  return (
    <CreateTicketDialog
      open={open}
      onOpenChange={open => {
        setOpen(open);
        if (!open) router.push("/dashboard/service-desk");
      }}
      prefillCustomerId={customerId}
      prefillPolicyId={policyId}
    />
  );
}

"use client";

import { useState, useMemo, useCallback } from "react";
import { useRouter } from "next/navigation";
import { motion } from "framer-motion";
import useSWR from "swr";
import {
  Ticket, Plus, Search, Filter, X, AlertTriangle, Clock,
  CheckCircle, Users, User, Inbox, LayoutList, RefreshCw,
  Download,
} from "lucide-react";
import { toast } from "sonner";
import { format } from "date-fns";

import { useAuth } from "@/lib/context/auth-context";
import { pageTransition } from "@/lib/helpers/animations";
import { SLACountdown } from "@/components/service-desk/SLACountdown";
import { CreateTicketDialog } from "@/components/service-desk/CreateTicketDialog";
import { Ticket as ServiceTicket, TicketMetrics } from "@/lib/types/service-desk";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";

type Queue = "my" | "team" | "unassigned" | "all";

const STATUS_COLORS: Record<string, string> = {
  open:        "bg-blue-500/10 text-blue-400 border-blue-500/20",
  in_progress: "bg-amber-500/10 text-amber-400 border-amber-500/20",
  pending:     "bg-orange-500/10 text-orange-400 border-orange-500/20",
  resolved:    "bg-green-500/10 text-green-400 border-green-500/20",
  closed:      "bg-gray-500/10 text-gray-400 border-gray-500/20",
};

const PRIORITY_COLORS: Record<string, string> = {
  urgent: "bg-red-500/10 text-red-400",
  high:   "bg-orange-500/10 text-orange-400",
  medium: "bg-amber-500/10 text-amber-400",
  low:    "bg-gray-500/10 text-gray-400",
};

const CATEGORY_LABELS: Record<string, string> = {
  ecard_request:     "E-Card Request",
  member_endorsement:"Member Endorsement",
  name_correction:   "Name Correction",
  address_correction:"Address Correction",
  invoice_dispute:   "Invoice Dispute",
  claim_assistance:  "Claim Assistance",
  general_query:     "General Query",
};

async function fetchTickets(url: string, token: string): Promise<{ data: ServiceTicket[], total: number }> {
  const res = await fetch(url, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) throw new Error("Failed to fetch tickets");
  return res.json();
}

async function fetchMetrics(token: string): Promise<TicketMetrics | null> {
  const res = await fetch("/api/service-desk/metrics?days=30", {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) return null;
  return res.json();
}

export default function ServiceDeskPage() {
  const router = useRouter();
  const { session } = useAuth();
  const token = session?.access_token ?? "";

  const [queue, setQueue] = useState<Queue>("all");
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("");
  const [priorityFilter, setPriorityFilter] = useState("");
  const [breachedOnly, setBreachedOnly] = useState(false);
  const [escalatedOnly, setEscalatedOnly] = useState(false);
  const [page, setPage] = useState(1);
  const [createOpen, setCreateOpen] = useState(false);

  const buildUrl = useCallback(() => {
    const params = new URLSearchParams({
      queue,
      page: String(page),
      limit: "25",
      sort: "created_at",
      order: "desc",
    });
    if (search) params.set("search", search);
    if (statusFilter) params.set("status", statusFilter);
    if (categoryFilter) params.set("category", categoryFilter);
    if (priorityFilter) params.set("priority", priorityFilter);
    if (breachedOnly) params.set("breached_only", "true");
    if (escalatedOnly) params.set("escalated_only", "true");
    return `/api/service-desk/tickets?${params}`;
  }, [queue, page, search, statusFilter, categoryFilter, priorityFilter, breachedOnly, escalatedOnly]);

  const { data: ticketsData, isLoading, mutate } = useSWR(
    token ? buildUrl() : null,
    (url) => fetchTickets(url, token),
    { revalidateOnFocus: false }
  );

  const { data: metrics } = useSWR(
    token ? `metrics-${token}` : null,
    () => fetchMetrics(token),
    { revalidateOnFocus: false, refreshInterval: 300_000 }
  );

  const tickets = ticketsData?.data ?? [];
  const total = ticketsData?.total ?? 0;
  const totalPages = Math.ceil(total / 25);

  const handleExport = () => {
    const rows = [
      ["Ticket #", "Customer", "Category", "Priority", "Status", "Created", "SLA Deadline"],
      ...tickets.map((t: ServiceTicket) => [
        t.ticket_number,
        t.customers?.name || "",
        CATEGORY_LABELS[t.category] || t.category,
        t.priority,
        t.status,
        t.created_at ? format(new Date(t.created_at), "dd/MM/yyyy HH:mm") : "",
        t.sla_deadline ? format(new Date(t.sla_deadline), "dd/MM/yyyy HH:mm") : "",
      ]),
    ];
    const csv = rows.map(r => r.map(v => `"${String(v)}"`).join(",")).join("\n");
    const blob = new Blob([csv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `tickets-${new Date().toISOString().split("T")[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    toast.success(`Exported ${tickets.length} tickets`);
  };

  const QUEUES: { key: Queue; label: string; icon: React.ComponentType<{ className?: string }> }[] = useMemo(() => [
    { key: "my",        label: "My Tickets",   icon: User },
    { key: "team",      label: "Team Tickets", icon: Users },
    { key: "unassigned",label: "Unassigned",   icon: Inbox },
    { key: "all",       label: "All Tickets",  icon: LayoutList },
  ], []);

  return (
    <motion.div {...pageTransition} className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-heading font-bold uppercase tracking-wider flex items-center gap-2">
            <Ticket className="w-6 h-6 text-primary" />
            Service Desk
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            {total} tickets · {metrics?.breach_count ?? 0} breached
          </p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" onClick={handleExport} className="gap-2">
            <Download className="w-4 h-4" /> Export
          </Button>
          <Button variant="outline" size="sm" onClick={() => void mutate()} className="gap-2">
            <RefreshCw className="w-4 h-4" />
          </Button>
          <Button size="sm" onClick={() => setCreateOpen(true)} className="gap-2">
            <Plus className="w-4 h-4" /> New Ticket
          </Button>
        </div>
      </div>

      {/* Metrics Bar */}
      {metrics && (
        <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-7 gap-3">
          {[
            { label: "Open",        value: metrics.status_counts?.open || 0,        color: "text-blue-400" },
            { label: "In Progress", value: metrics.status_counts?.in_progress || 0, color: "text-amber-400" },
            { label: "Pending",     value: metrics.status_counts?.pending || 0,     color: "text-orange-400" },
            { label: "Overdue",     value: metrics.breach_count || 0,               color: "text-red-400" },
            { label: "Resolved",    value: metrics.status_counts?.resolved || 0,    color: "text-green-400" },
            { label: "SLA Rate",    value: `${metrics.sla_on_time_rate}%`,          color: "text-emerald-400", isText: true },
            { label: "Avg Resolve", value: metrics.avg_resolution_minutes > 0
                ? `${Math.round(metrics.avg_resolution_minutes / 60)}h`
                : "—",                                                               color: "text-purple-400", isText: true },
          ].map(({ label, value, color, isText }) => (
            <div key={label} className="bg-card border border-border rounded-xl p-3">
              <p className="text-xs text-muted-foreground uppercase tracking-wider font-heading">{label}</p>
              <p className={`font-bold mt-0.5 ${isText ? "text-sm" : "text-xl"} ${color}`}>{value}</p>
            </div>
          ))}
        </div>
      )}

      {/* Queue Tabs */}
      <div className="flex gap-1 border-b border-border overflow-x-auto">
        {QUEUES.map(({ key, label, icon: Icon }) => (
          <button
            key={key}
            onClick={() => { setQueue(key); setPage(1); }}
            className={`flex items-center gap-1.5 px-4 py-2.5 text-sm font-medium transition-colors border-b-2 -mb-px whitespace-nowrap ${
              queue === key
                ? "border-primary text-primary"
                : "border-transparent text-muted-foreground hover:text-foreground"
            }`}
          >
            <Icon className="w-4 h-4" />
            {label}
          </button>
        ))}
      </div>

      {/* Filters */}
      <div className="flex flex-wrap gap-3">
        <div className="relative flex-1 min-w-[200px]">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Search ticket #, description..."
            value={search}
            onChange={e => { setSearch(e.target.value); setPage(1); }}
            className="pl-9"
          />
          {search && (
            <button onClick={() => setSearch("")} className="absolute right-3 top-1/2 -translate-y-1/2">
              <X className="w-4 h-4 text-muted-foreground" />
            </button>
          )}
        </div>

        <Select value={statusFilter} onValueChange={v => { setStatusFilter(v === "all" ? "" : v); setPage(1); }}>
          <SelectTrigger className="w-[140px]">
            <SelectValue placeholder="All Status" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Status</SelectItem>
            {["open","in_progress","pending","resolved","closed"].map(s => (
              <SelectItem key={s} value={s}>{s.replace(/_/g, " ")}</SelectItem>
            ))}
          </SelectContent>
        </Select>

        <Select value={categoryFilter} onValueChange={v => { setCategoryFilter(v === "all" ? "" : v); setPage(1); }}>
          <SelectTrigger className="w-[160px]">
            <SelectValue placeholder="All Categories" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Categories</SelectItem>
            {Object.entries(CATEGORY_LABELS).map(([k, v]) => (
              <SelectItem key={k} value={k}>{v}</SelectItem>
            ))}
          </SelectContent>
        </Select>

        <Select value={priorityFilter} onValueChange={v => { setPriorityFilter(v === "all" ? "" : v); setPage(1); }}>
          <SelectTrigger className="w-[130px]">
            <SelectValue placeholder="All Priority" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Priority</SelectItem>
            {["urgent","high","medium","low"].map(p => (
              <SelectItem key={p} value={p} className="capitalize">{p}</SelectItem>
            ))}
          </SelectContent>
        </Select>

        <Button
          variant={breachedOnly ? "default" : "outline"}
          size="sm"
          onClick={() => { setBreachedOnly(!breachedOnly); setPage(1); }}
          className="gap-2 whitespace-nowrap"
        >
          <AlertTriangle className="w-4 h-4" />
          Breached Only
        </Button>
      </div>

      {/* Ticket Table */}
      <div className="bg-card border border-border rounded-xl overflow-hidden">
        {isLoading ? (
          <div className="p-6 space-y-3">
            {[...Array(6)].map((_, i) => <Skeleton key={i} className="h-12 w-full" />)}
          </div>
        ) : tickets.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 gap-4">
            <Ticket className="w-12 h-12 text-muted-foreground/40" />
            <p className="text-muted-foreground">No tickets found.</p>
            <Button onClick={() => setCreateOpen(true)} className="gap-2">
              <Plus className="w-4 h-4" /> Create First Ticket
            </Button>
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow className="border-border hover:bg-transparent">
                <TableHead className="text-xs uppercase tracking-wider font-heading">Ticket #</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden sm:table-cell">Customer</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden md:table-cell">Category</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden sm:table-cell">Priority</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Status</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden lg:table-cell">SLA</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden xl:table-cell">Created</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {tickets.map((t: ServiceTicket) => (
                <TableRow
                  key={t.id}
                  className="border-border hover:bg-muted/30 cursor-pointer"
                  onClick={() => router.push(`/dashboard/service-desk/${t.id}`)}
                >
                  <TableCell>
                    <div className="flex items-center gap-2">
                      <span className="font-mono text-sm font-medium">{t.ticket_number}</span>
                      {t.escalation_level > 0 && (
                        <Badge className="bg-red-500/10 text-red-400 text-xs">L{t.escalation_level}</Badge>
                      )}
                    </div>
                  </TableCell>
                  <TableCell className="hidden sm:table-cell text-sm text-muted-foreground">
                    {t.customers?.name || "—"}
                  </TableCell>
                  <TableCell className="hidden md:table-cell">
                    <span className="text-xs text-muted-foreground">
                      {CATEGORY_LABELS[t.category] || t.category}
                    </span>
                  </TableCell>
                  <TableCell className="hidden sm:table-cell">
                    <Badge variant="outline" className={`text-xs ${PRIORITY_COLORS[t.priority] || ""}`}>
                      {t.priority}
                    </Badge>
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline" className={`text-xs ${STATUS_COLORS[t.status] || ""}`}>
                      {t.status?.replace(/_/g, " ")}
                    </Badge>
                  </TableCell>
                  <TableCell className="hidden lg:table-cell">
                    {t.sla_deadline ? (
                      <SLACountdown
                        createdAt={t.created_at}
                        slaDeadline={t.sla_deadline}
                        isPaused={t.status === "pending"}
                        isBreached={t.is_breached}
                        compact
                      />
                    ) : (
                      <span className="text-xs text-muted-foreground">—</span>
                    )}
                  </TableCell>
                  <TableCell className="hidden xl:table-cell text-xs text-muted-foreground">
                    {t.created_at ? format(new Date(t.created_at), "dd MMM yyyy") : "—"}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <p className="text-sm text-muted-foreground">
            Showing {(page - 1) * 25 + 1}–{Math.min(page * 25, total)} of {total}
          </p>
          <div className="flex gap-2">
            <Button variant="outline" size="sm" disabled={page === 1} onClick={() => setPage(p => p - 1)}>
              Previous
            </Button>
            <Button variant="outline" size="sm" disabled={page === totalPages} onClick={() => setPage(p => p + 1)}>
              Next
            </Button>
          </div>
        </div>
      )}

      {/* Create Ticket Dialog */}
      <CreateTicketDialog
        open={createOpen}
        onOpenChange={open => { setCreateOpen(open); if (!open) void mutate(); }}
      />
    </motion.div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { toast } from "sonner";
import { Plus, Pencil, Trash2, Loader2, FileText } from "lucide-react";

import { useAuth } from "@/lib/context/auth-context";
import { pageTransition } from "@/lib/helpers/animations";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";

const CATEGORIES = [
  { value: "ecard_request", label: "E-Card Request" },
  { value: "member_endorsement", label: "Member Endorsement" },
  { value: "name_correction", label: "Name Correction" },
  { value: "address_correction", label: "Address Correction" },
  { value: "invoice_dispute", label: "Invoice Dispute" },
  { value: "claim_assistance", label: "Claim Assistance" },
  { value: "general_query", label: "General Query" },
  { value: "validity_renewal", label: "Validity Renewal" },
  { value: "vehicle_endorsement", label: "Vehicle Endorsement" },
  { value: "policy_query", label: "Policy Query" },
  { value: "document_request", label: "Document Request" },
];

const PRIORITIES = [
  { value: "urgent", label: "Urgent" },
  { value: "high", label: "High" },
  { value: "medium", label: "Medium" },
  { value: "low", label: "Low" },
];

interface Template {
  id: string;
  name: string;
  category: string;
  priority: string;
  description_template?: string;
  internal_notes_template?: string;
}

interface TemplateFormData {
  name: string;
  category: string;
  priority: string;
  description_template: string;
  internal_notes_template: string;
}

const DEFAULT_FORM: TemplateFormData = {
  name: "",
  category: "",
  priority: "medium",
  description_template: "",
  internal_notes_template: "",
};

export default function TemplatesPage() {
  const { session, role } = useAuth();
  const token = session?.access_token ?? "";

  const [templates, setTemplates] = useState<Template[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [formOpen, setFormOpen] = useState(false);
  const [editTemplate, setEditTemplate] = useState<Template | null>(null);
  const [deleteTemplate, setDeleteTemplate] = useState<Template | null>(null);
  const [formData, setFormData] = useState<TemplateFormData>(DEFAULT_FORM);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const fetchTemplates = async () => {
    if (!token) return;
    try {
      const res = await fetch("/api/service-desk/templates", {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await res.json();
      if (res.ok) {
        setTemplates(Array.isArray(data) ? data : (data?.data || []));
      } else {
        setTemplates([]);
        toast.error(data?.error || "Failed to load templates");
      }
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchTemplates(); }, [token]);

  const handleOpenCreate = () => {
    setEditTemplate(null);
    setFormData(DEFAULT_FORM);
    setFormOpen(true);
  };

  const handleOpenEdit = (template: Template) => {
    setEditTemplate(template);
    setFormData({
      name: template.name,
      category: template.category,
      priority: template.priority,
      description_template: template.description_template ?? "",
      internal_notes_template: template.internal_notes_template ?? "",
    });
    setFormOpen(true);
  };

  const handleSubmit = async () => {
    if (!formData.name.trim() || !formData.category || !token) return;
    setIsSubmitting(true);
    try {
      const url = editTemplate
        ? `/api/service-desk/templates/${editTemplate.id}`
        : "/api/service-desk/templates";
      const method = editTemplate ? "PUT" : "POST";

      const res = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify(formData),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error);

      toast.success(editTemplate ? "Template updated" : "Template created");
      setFormOpen(false);
      fetchTemplates();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to save template");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDelete = async () => {
    if (!deleteTemplate || !token) return;
    setIsSubmitting(true);
    try {
      const res = await fetch(`/api/service-desk/templates/${deleteTemplate.id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error);
      toast.success("Template deleted");
      setDeleteTemplate(null);
      fetchTemplates();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to delete template");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (role === "employee") {
    return (
      <div className="flex items-center justify-center py-20">
        <p className="text-muted-foreground">Manager or Admin access required.</p>
      </div>
    );
  }

  return (
    <motion.div {...pageTransition} className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <FileText className="w-6 h-6 text-primary" />
          <h1 className="text-2xl font-heading font-bold uppercase tracking-wider">
            Ticket Templates
          </h1>
        </div>
        <Button onClick={handleOpenCreate} className="gap-2">
          <Plus className="w-4 h-4" />
          New Template
        </Button>
      </div>

      <div className="bg-card border border-border rounded-xl overflow-hidden">
        {isLoading ? (
          <div className="p-6 space-y-3">
            {[...Array(4)].map((_, i) => (
              <div key={i} className="h-16 bg-muted/30 rounded-lg animate-pulse" />
            ))}
          </div>
        ) : templates.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 gap-3">
            <FileText className="w-10 h-10 text-muted-foreground/30" />
            <p className="text-muted-foreground text-sm">No templates yet.</p>
            <Button onClick={handleOpenCreate} variant="outline" className="gap-2">
              <Plus className="w-4 h-4" />
              Create First Template
            </Button>
          </div>
        ) : (
          <div className="divide-y divide-border">
            {templates.map(template => (
              <div key={template.id} className="flex items-center justify-between px-6 py-4">
                <div className="space-y-1">
                  <p className="font-medium">{template.name}</p>
                  <div className="flex items-center gap-2">
                    <Badge variant="outline" className="text-xs capitalize">
                      {template.category.replace(/_/g, " ")}
                    </Badge>
                    <Badge variant="outline" className="text-xs capitalize">
                      {template.priority}
                    </Badge>
                  </div>
                  {template.description_template && (
                    <p className="text-xs text-muted-foreground truncate max-w-md">
                      {template.description_template}
                    </p>
                  )}
                </div>
                <div className="flex gap-2">
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-8 w-8 p-0"
                    onClick={() => handleOpenEdit(template)}
                  >
                    <Pencil className="w-4 h-4" />
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-8 w-8 p-0 text-red-400 hover:text-red-400"
                    onClick={() => setDeleteTemplate(template)}
                  >
                    <Trash2 className="w-4 h-4" />
                  </Button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Create/Edit dialog */}
      <Dialog open={formOpen} onOpenChange={setFormOpen}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle className="font-heading uppercase tracking-wider">
              {editTemplate ? "Edit Template" : "New Template"}
            </DialogTitle>
          </DialogHeader>

          <div className="space-y-4 py-2">
            <div className="space-y-1.5">
              <Label>Template Name *</Label>
              <Input
                placeholder="e.g., E-Card Request - Standard"
                value={formData.name}
                onChange={e => setFormData(prev => ({ ...prev, name: e.target.value }))}
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1.5">
                <Label>Category *</Label>
                <Select
                  value={formData.category}
                  onValueChange={v => setFormData(prev => ({ ...prev, category: v }))}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select..." />
                  </SelectTrigger>
                  <SelectContent>
                    {CATEGORIES.map(c => (
                      <SelectItem key={c.value} value={c.value}>{c.label}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-1.5">
                <Label>Default Priority</Label>
                <Select
                  value={formData.priority}
                  onValueChange={v => setFormData(prev => ({ ...prev, priority: v }))}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {PRIORITIES.map(p => (
                      <SelectItem key={p.value} value={p.value}>{p.label}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="space-y-1.5">
              <Label>Description Template</Label>
              <Textarea
                placeholder="Pre-filled description for this ticket type..."
                value={formData.description_template}
                onChange={e => setFormData(prev => ({ ...prev, description_template: e.target.value }))}
                rows={3}
              />
            </div>

            <div className="space-y-1.5">
              <Label>Internal Notes Template</Label>
              <Textarea
                placeholder="Pre-filled internal notes..."
                value={formData.internal_notes_template}
                onChange={e => setFormData(prev => ({ ...prev, internal_notes_template: e.target.value }))}
                rows={2}
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setFormOpen(false)} disabled={isSubmitting}>
              Cancel
            </Button>
            <Button
              onClick={handleSubmit}
              disabled={isSubmitting || !formData.name.trim() || !formData.category}
            >
              {isSubmitting && <Loader2 className="w-4 h-4 animate-spin mr-2" />}
              {editTemplate ? "Save Changes" : "Create Template"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete confirmation */}
      <AlertDialog open={!!deleteTemplate} onOpenChange={open => !open && setDeleteTemplate(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Template</AlertDialogTitle>
            <AlertDialogDescription>
              Delete &quot;{deleteTemplate?.name}&quot;? This cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isSubmitting}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              disabled={isSubmitting}
              className="bg-red-600 hover:bg-red-700"
            >
              {isSubmitting && <Loader2 className="w-3 h-3 animate-spin mr-1" />}
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </motion.div>
  );
}

"use client";

import { useState, useMemo } from "react";
import { useParams, useRouter } from "next/navigation";
import { motion } from "framer-motion";
import { 
  ArrowLeft, 
  LifeBuoy, 
  Clock, 
  CheckCircle2, 
  AlertCircle, 
  User, 
  Phone, 
  Mail, 
  FileText,
  MessageSquare,
  History,
  Send,
  MoreVertical,
  ArrowUpRight,
  ShieldCheck,
  AlertTriangle,
  ExternalLink,
  LucideIcon
} from "lucide-react";
import { format } from "date-fns";
import { useServiceTickets } from "@/lib/hooks/use-business-cases";
import { ServiceTicket, TicketStatus, TicketPriority } from "@/lib/types";
import { pageTransition, staggerContainer, staggerItem } from "@/lib/helpers/animations";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Separator } from "@/components/ui/separator";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "sonner";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

const STATUS_CONFIG: Record<TicketStatus, { label: string; color: string; icon: LucideIcon }> = {
  open: { label: "Open", color: "bg-blue-500/10 text-blue-500 border-blue-500/20", icon: Clock },
  in_progress: { label: "In Progress", color: "bg-indigo-500/10 text-indigo-500 border-indigo-500/20", icon: SparklesIcon },
  pending: { label: "Pending", color: "bg-orange-500/10 text-orange-600 border-orange-500/20", icon: Clock },
  pending_customer: { label: "Pending Customer", color: "bg-amber-500/10 text-amber-500 border-amber-500/20", icon: AlertCircle },
  resolved: { label: "Resolved", color: "bg-emerald-500/10 text-emerald-500 border-emerald-500/20", icon: CheckCircle2 },
  closed: { label: "Closed", color: "bg-slate-500/10 text-slate-500 border-slate-500/20", icon: History },
};

const PRIORITY_CONFIG: Record<TicketPriority, { label: string; color: string; icon: LucideIcon }> = {
  low: { label: "Low", color: "text-slate-400", icon: ShieldCheck },
  medium: { label: "Medium", color: "text-amber-500", icon: AlertCircle },
  high: { label: "High", color: "text-orange-500", icon: AlertTriangle },
  urgent: { label: "Urgent", color: "text-rose-500", icon: AlertTriangle },
};

function SparklesIcon({ className }: { className?: string }) {
  return <div className={cn("h-3 w-3 rounded-full bg-primary/40 blur-sm animate-pulse", className)} />;
}

export default function TicketDetailPage() {
  const params = useParams();
  const router = useRouter();
  const ticketId = params.id as string;
  const { data: tickets, isLoading } = useServiceTickets();
  
  const [comment, setComment] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const ticket = useMemo(() => {
    return tickets?.find(t => t.id === ticketId);
  }, [tickets, ticketId]);

  if (isLoading) {
    return (
      <div className="max-w-7xl mx-auto space-y-6 pt-10">
        <Skeleton className="h-12 w-48 rounded-xl" />
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <Skeleton className="h-96 md:col-span-2 rounded-3xl" />
          <Skeleton className="h-96 rounded-3xl" />
        </div>
      </div>
    );
  }

  if (!ticket) {
    return (
      <div className="h-[60vh] flex flex-col items-center justify-center space-y-4">
        <LifeBuoy className="h-12 w-12 text-muted-foreground opacity-20" />
        <h2 className="text-xl font-bold tracking-tight">Ticket Not Found</h2>
        <Button onClick={() => router.push("/dashboard/service-tickets")}>
          <ArrowLeft className="mr-2 h-4 w-4" /> Go Back
        </Button>
      </div>
    );
  }

  const handlePostComment = () => {
    if (!comment.trim()) return;
    setIsSubmitting(true);
    setTimeout(() => {
      toast.success("Update posted to timeline");
      setComment("");
      setIsSubmitting(false);
    }, 800);
  };

  return (
    <motion.div className="max-w-7xl mx-auto space-y-6 pb-20" {...pageTransition}>
      {/* Header Actions */}
      <div className="flex items-center justify-between">
        <Button variant="ghost" onClick={() => router.push("/dashboard/service-tickets")} className="h-10 rounded-xl px-4 text-muted-foreground hover:text-foreground">
          <ArrowLeft className="mr-2 h-4 w-4" /> Back to Desk
        </Button>
        
        <div className="flex items-center gap-2">
           <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="outline" className="h-10 rounded-xl px-4 bg-card/50 border-border/60">
                Action Workflow <MoreVertical className="ml-2 h-4 w-4" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="rounded-2xl border-border p-2">
              <DropdownMenuItem className="rounded-xl py-2 cursor-pointer">
                <ArrowUpRight className="h-4 w-4 mr-2" /> Assign to Agent
              </DropdownMenuItem>
              <DropdownMenuItem className="rounded-xl py-2 cursor-pointer">
                <Clock className="h-4 w-4 mr-2" /> Mark In Progress
              </DropdownMenuItem>
              <DropdownMenuSeparator className="bg-border/50" />
              <DropdownMenuItem className="rounded-xl py-2 cursor-pointer text-emerald-500 focus:text-emerald-500">
                <CheckCircle2 className="h-4 w-4 mr-2" /> Resolve Ticket
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>

      {/* Main Info Hero */}
      <section className="relative overflow-hidden rounded-[2.5rem] border border-border bg-card/40 p-10 shadow-2xl shadow-primary/5">
        <div className="absolute -top-24 -right-24 h-64 w-64 rounded-full bg-primary/10 blur-3xl opacity-50" />
        
        <div className="relative z-10 grid grid-cols-1 md:grid-cols-3 gap-10">
          <div className="md:col-span-2 space-y-4">
             <div className="flex items-center gap-3">
               <span className="font-black font-mono text-primary text-xl tracking-tighter">{ticket.ticket_number}</span>
               <Badge className={cn("rounded-lg px-2 py-1 flex items-center gap-1.5 w-fit border-2", STATUS_CONFIG[ticket.status]?.color)}>
                  <span className="text-[10px] font-black uppercase tracking-tight">{STATUS_CONFIG[ticket.status]?.label}</span>
               </Badge>
             </div>
             <h1 className="text-4xl font-bold tracking-tighter capitalize font-heading">
               {ticket.category.replace(/_/g, ' ')}
             </h1>
             <p className="text-muted-foreground max-w-xl leading-relaxed">
               {ticket.description || "No detailed description provided for this service request."}
             </p>
          </div>
          
          <div className="flex flex-col justify-between items-end gap-6 border-l border-border/60 pl-10 hidden md:flex">
             <div className="text-right">
                <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground mb-1">Priority Level</p>
                <div className="flex items-center gap-2 justify-end">
                   <span className={cn("text-lg font-bold uppercase tracking-tight", PRIORITY_CONFIG[ticket.priority]?.color)}>
                      {PRIORITY_CONFIG[ticket.priority]?.label}
                   </span>
                   {(() => {
                      const Icon = PRIORITY_CONFIG[ticket.priority]?.icon;
                      return <Icon className={cn("h-5 w-5", PRIORITY_CONFIG[ticket.priority]?.color)} />;
                   })()}
                </div>
             </div>
             <div className="text-right">
                <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground mb-1">SLA Deadline</p>
                <p className="text-lg font-bold tracking-tight text-rose-500">
                   {format(new Date(new Date(ticket.createdAt).getTime() + 48*60*60*1000), "dd MMM, hh:mm a")}
                </p>
             </div>
          </div>
        </div>
      </section>

      {/* Details Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-6">
           <Tabs defaultValue="timeline">
             <TabsList className="bg-muted/10 p-1 h-12 rounded-2xl border border-border/40">
               <TabsTrigger value="timeline" className="rounded-xl px-6 data-[state=active]:bg-card shadow-sm">Process Timeline</TabsTrigger>
               <TabsTrigger value="details" className="rounded-xl px-6 data-[state=active]:bg-card shadow-sm">Technical Specs</TabsTrigger>
               <TabsTrigger value="documents" className="rounded-xl px-6 data-[state=active]:bg-card shadow-sm">Attachments</TabsTrigger>
             </TabsList>

             <TabsContent value="timeline" className="pt-6 space-y-6">
                <Card className="border-border/60 bg-card/20 rounded-[2rem]">
                  <CardContent className="p-8">
                     <div className="space-y-8 relative">
                        <div className="absolute left-4 top-1 bottom-1 w-[2px] bg-border/40" />
                        
                        <TimelineItem 
                          icon={Clock}
                          title="Ticket Created"
                          date={format(new Date(ticket.createdAt), "dd MMM, hh:mm a")}
                          user="System Logic"
                          text="Service request successfully registered from the central intake desk."
                        />
                        
                        <TimelineItem 
                          icon={User}
                          title="Assignment Update"
                          date={format(new Date(ticket.createdAt), "dd MMM, hh:mm a")}
                          user="AI Orchestrator"
                          text={`Auto-assigned to ${ticket.assigned_to_name || 'Agent Desk #1'} based on category specialization.`}
                        />

                        {/* Interactive Post Section */}
                        <div className="relative pl-12 pt-4">
                           <div className="p-6 rounded-[2rem] border border-primary/20 bg-primary/5 space-y-4 shadow-inner">
                              <Textarea 
                                placeholder="Post an update or internal note..." 
                                className="min-h-[100px] border-none bg-transparent focus-visible:ring-0 px-0 text-sm font-medium"
                                value={comment}
                                onChange={(e) => setComment(e.target.value)}
                              />
                              <div className="flex items-center justify-between border-t border-primary/10 pt-4">
                                 <p className="text-[10px] text-primary/60 font-black uppercase tracking-widest">Visibility: Internal Only</p>
                                 <Button 
                                    className="h-10 rounded-xl px-6 bg-primary text-primary-foreground font-bold shadow-lg shadow-primary/20"
                                    onClick={handlePostComment}
                                    disabled={!comment.trim() || isSubmitting}
                                 >
                                    {isSubmitting ? "Posting..." : <><Send className="mr-2 h-4 w-4" /> Post Update</>}
                                 </Button>
                              </div>
                           </div>
                        </div>
                     </div>
                  </CardContent>
                </Card>
             </TabsContent>

             <TabsContent value="details" className="pt-6">
                <Card className="border-border/60 bg-card/20 rounded-[2rem]">
                  <CardContent className="p-8 grid gap-8 md:grid-cols-2">
                     <DetailRow label="Policy Reference" value={ticket.policy_id || "N/A"} mono />
                     <DetailRow label="Case Category" value={ticket.category} color="text-primary" capitalize />
                     <DetailRow label="Sub-type" value="Endorsement / Alteration" />
                     <DetailRow label="Request ID" value={ticket.id} mono />
                  </CardContent>
                </Card>
             </TabsContent>

             <TabsContent value="documents" className="pt-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                   <DocumentCard name="Request_Copy.pdf" type="Request Letter" size="1.2 MB" />
                   <DocumentCard name="Policy_Pre_Alt.pdf" type="Existing Policy" size="4.5 MB" />
                </div>
             </TabsContent>
           </Tabs>
        </div>

        {/* Sidebar Info */}
        <div className="space-y-6">
           <Card className="border-border/60 bg-card overflow-hidden rounded-[2rem] shadow-xl shadow-black/5">
              <CardHeader className="bg-muted/30 border-b border-border/40 py-6">
                 <CardTitle className="text-sm font-black uppercase tracking-[0.2em] text-muted-foreground flex items-center gap-2">
                    <User className="h-4 w-4 text-primary" /> Associated Customer
                 </CardTitle>
              </CardHeader>
              <CardContent className="p-8 space-y-6">
                 <div className="flex items-center gap-4">
                    <div className="h-14 w-14 rounded-full bg-primary/10 border border-primary/20 flex items-center justify-center text-primary text-xl font-black">
                       {ticket.customers?.name ? ticket.customers.name[0] : 'C'}
                    </div>
                    <div>
                       <p className="text-xl font-bold tracking-tight">{ticket.customers?.name || "Premium Client"}</p>
                       <p className="text-xs text-muted-foreground font-mono">UID: {ticket.customers?.uid || "C-8812"}</p>
                    </div>
                 </div>
                 
                 <Separator className="bg-border/40" />
                 
                 <div className="space-y-4">
                    <SidebarInfoRow icon={Phone} label="Contact" value={ticket.customers?.phone || "N/A"} />
                    <SidebarInfoRow icon={Mail} label="Email" value={ticket.customers?.email || "N/A"} />
                 </div>

                 <Button 
                    variant="outline" 
                    className="w-full h-12 rounded-xl border-border hover:bg-muted font-bold tracking-tight"
                    onClick={() => router.push(`/dashboard/customers/${ticket.customer_id}`)}
                 >
                    View Account Hub
                 </Button>
              </CardContent>
           </Card>

           <Card className="border-border/60 bg-primary/5 rounded-[2rem] shadow-sm overflow-hidden">
              <CardContent className="p-8 space-y-4">
                 <div className="flex items-center gap-2">
                    <Sparkles className="h-3 w-3 bg-primary" />
                    <p className="text-[10px] font-black uppercase tracking-widest text-primary">Operational Intelligence</p>
                 </div>
                 <p className="text-xs leading-relaxed font-medium text-foreground/80">
                    This ticket is linked to a **Critical Renewal** window. Prioritize resolution within 24 hours to prevent policy lapse.
                 </p>
                 <Button className="w-full h-10 rounded-xl bg-primary/10 text-primary hover:bg-primary/20 border-none font-bold text-[10px] uppercase shadow-none">
                    View Policy Linked (3)
                 </Button>
              </CardContent>
           </Card>
        </div>
      </div>
    </motion.div>
  );
}

function TimelineItem({ icon: Icon, title, date, user, text }: { icon: LucideIcon, title: string, date: string, user: string, text: string }) {
