"use client";

import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { toast } from "sonner";
import { Loader2, Plus } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { useAuth } from "@/lib/context/auth-context";

const schema = z.object({
  title: z.string().min(1, "Title is required"),
  category: z.enum([
    "license_renewal", "regulatory_filing", "audit_submission",
    "training_certification", "policy_review", "other",
  ]),
  description: z.string().optional(),
  due_date: z.string().min(1, "Due date is required"),
  assigned_to_name: z.string().optional(),
  recurrence: z.enum(["one_time", "monthly", "quarterly", "half_yearly", "annual"]),
});

type FormData = z.infer<typeof schema>;

interface ComplianceItemFormProps {
  onCreated?: () => void;
  editData?: any;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
}

export function ComplianceItemForm({
  onCreated,
  editData,
  open: controlledOpen,
  onOpenChange: controlledOnOpenChange,
}: ComplianceItemFormProps) {
  const { session } = useAuth();
  const [internalOpen, setInternalOpen] = useState(false);
  const [loading, setLoading] = useState(false);

  const isControlled = controlledOpen !== undefined;
  const open = isControlled ? controlledOpen : internalOpen;
  const setOpen = isControlled ? controlledOnOpenChange! : setInternalOpen;

  const {
    register,
    handleSubmit,
    setValue,
    watch,
    reset,
    formState: { errors },
  } = useForm<FormData>({
    resolver: zodResolver(schema),
    defaultValues: {
      category: editData?.category ?? "regulatory_filing",
      recurrence: editData?.recurrence ?? "one_time",
      title: editData?.title ?? "",
      description: editData?.description ?? "",
      due_date: editData?.due_date ?? "",
      assigned_to_name: editData?.assigned_to_name ?? "",
    },
  });

  const category = watch("category");
  const recurrence = watch("recurrence");

  const onSubmit = async (data: FormData) => {
    setLoading(true);
    try {
      const token = session?.access_token;
      if (!token) throw new Error("Not authenticated");

      const url = editData ? `/api/compliance/${editData.id}` : "/api/compliance";
      const method = editData ? "PUT" : "POST";

      const res = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(data),
      });

      const result = await res.json();
      if (!res.ok) throw new Error(result.error ?? "Failed to save");

      toast.success(editData ? "Compliance item updated" : "Compliance item created");
      reset();
      setOpen(false);
      onCreated?.();
    } catch (err: any) {
      toast.error(err.message ?? "Failed to save");
    } finally {
      setLoading(false);
    }
  };

  const trigger = !isControlled ? (
    <DialogTrigger asChild>
      <Button size="sm" className="gap-2">
        <Plus className="w-3.5 h-3.5" /> Add Item
      </Button>
    </DialogTrigger>
  ) : null;

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      {trigger}
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle className="font-heading uppercase tracking-wider">
            {editData ? "Edit Compliance Item" : "New Compliance Item"}
          </DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
          <div className="space-y-1.5">
            <Label htmlFor="title">Title *</Label>
            <Input id="title" placeholder="e.g., IRDA License Renewal" {...register("title")} />
            {errors.title && <p className="text-xs text-red-400">{errors.title.message}</p>}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label>Category *</Label>
              <Select value={category} onValueChange={(v) => setValue("category", v as any)}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="license_renewal">License Renewal</SelectItem>
                  <SelectItem value="regulatory_filing">Regulatory Filing</SelectItem>
                  <SelectItem value="audit_submission">Audit Submission</SelectItem>
                  <SelectItem value="training_certification">Training/Certification</SelectItem>
                  <SelectItem value="policy_review">Policy Review</SelectItem>
                  <SelectItem value="other">Other</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-1.5">
              <Label>Recurrence</Label>
              <Select value={recurrence} onValueChange={(v) => setValue("recurrence", v as any)}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="one_time">One Time</SelectItem>
                  <SelectItem value="monthly">Monthly</SelectItem>
                  <SelectItem value="quarterly">Quarterly</SelectItem>
                  <SelectItem value="half_yearly">Half Yearly</SelectItem>
                  <SelectItem value="annual">Annual</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="due_date">Due Date *</Label>
            <Input id="due_date" type="date" {...register("due_date")} />
            {errors.due_date && <p className="text-xs text-red-400">{errors.due_date.message}</p>}
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="assigned_to_name">Assigned To</Label>
            <Input
              id="assigned_to_name"
              placeholder="Assignee name"
              {...register("assigned_to_name")}
            />
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="description">Description</Label>
            <Textarea
              id="description"
              placeholder="Describe the compliance requirement..."
              rows={3}
              {...register("description")}
            />
          </div>

          <div className="flex justify-end gap-2">
            <Button type="button" variant="outline" onClick={() => setOpen(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={loading}>
              {loading && <Loader2 className="w-4 h-4 animate-spin mr-2" />}
              {editData ? "Update" : "Create"}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState } from "react";
import { toast } from "sonner";
import { Loader2, Download, FileSpreadsheet } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import {
  Card, CardContent, CardHeader, CardTitle,
} from "@/components/ui/card";
import { useAuth } from "@/lib/context/auth-context";

interface IRDAReportGeneratorProps {
  onGenerated?: () => void;
}

export function IRDAReportGenerator({ onGenerated }: IRDAReportGeneratorProps) {
  const { session } = useAuth();
  const [loading, setLoading] = useState(false);
  const [reportType, setReportType] = useState("business_summary");
  const [periodType, setPeriodType] = useState("monthly");
  const [periodStart, setPeriodStart] = useState("");
  const [periodEnd, setPeriodEnd] = useState("");
  const [fileFormat, setFileFormat] = useState("excel");

  const handleGenerate = async () => {
    if (!periodStart || !periodEnd) {
      toast.error("Period start and end dates are required");
      return;
    }

    setLoading(true);
    try {
      const token = session?.access_token;
      if (!token) throw new Error("Not authenticated");

      const res = await fetch("/api/irda-reports", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          report_type: reportType,
          period_type: periodType,
          period_start: periodStart,
          period_end: periodEnd,
          file_format: fileFormat,
        }),
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error ?? "Failed to generate report");

      toast.success("Report generated successfully");
      onGenerated?.();

      // Trigger download
      if (data.id) {
        const downloadRes = await fetch(`/api/irda-reports/${data.id}/download`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (downloadRes.ok) {
          const blob = await downloadRes.blob();
          const url = URL.createObjectURL(blob);
          const a = document.createElement("a");
          a.href = url;
          a.download = `irda-${reportType}-${periodStart}.xlsx`;
          a.click();
          URL.revokeObjectURL(url);
        }
      }
    } catch (err: any) {
      toast.error(err.message ?? "Failed to generate report");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-sm font-heading uppercase tracking-wider flex items-center gap-2">
          <FileSpreadsheet className="w-4 h-4 text-primary" />
          Generate IRDA Report
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-1.5">
            <Label>Report Type</Label>
            <Select value={reportType} onValueChange={setReportType}>
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="business_summary">Business Summary</SelectItem>
                <SelectItem value="premium_register">Premium Register</SelectItem>
                <SelectItem value="commission_register">Commission Register</SelectItem>
                <SelectItem value="claims_register">Claims Register</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-1.5">
            <Label>Period Type</Label>
            <Select value={periodType} onValueChange={setPeriodType}>
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="monthly">Monthly</SelectItem>
                <SelectItem value="quarterly">Quarterly</SelectItem>
                <SelectItem value="annual">Annual</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="period_start">Period Start</Label>
            <Input
              id="period_start"
              type="date"
              value={periodStart}
              onChange={(e) => setPeriodStart(e.target.value)}
            />
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="period_end">Period End</Label>
            <Input
              id="period_end"
              type="date"
              value={periodEnd}
              onChange={(e) => setPeriodEnd(e.target.value)}
            />
          </div>

          <div className="space-y-1.5">
            <Label>Format</Label>
            <Select value={fileFormat} onValueChange={setFileFormat}>
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="excel">Excel (.xlsx)</SelectItem>
                <SelectItem value="pdf">PDF</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>

        <Button
          onClick={handleGenerate}
          disabled={loading || !periodStart || !periodEnd}
          className="gap-2"
        >
          {loading ? (
            <Loader2 className="w-4 h-4 animate-spin" />
          ) : (
            <Download className="w-4 h-4" />
          )}
          {loading ? "Generating..." : "Generate & Download"}
        </Button>
      </CardContent>
    </Card>
  );
}

"use client";

import { useMemo } from "react";
import { format, startOfMonth, endOfMonth, eachDayOfInterval, isSameMonth, isToday, differenceInDays } from "date-fns";

interface ComplianceItem {
  id: string;
  title: string;
  due_date: string;
  status: string;
  category: string;
}

interface RegulatoryCalendarProps {
  items: ComplianceItem[];
  currentMonth?: Date;
  onItemClick?: (item: ComplianceItem) => void;
}

function getItemColor(dueDate: string, status: string): string {
  if (status === "completed") return "bg-green-500/20 text-green-400";
  const today = new Date();
  const due = new Date(dueDate);
  const daysUntil = differenceInDays(due, today);

  if (daysUntil < 0) return "bg-red-500/20 text-red-400"; // overdue
  if (daysUntil <= 7) return "bg-orange-500/20 text-orange-400"; // ≤7d
  if (daysUntil <= 30) return "bg-yellow-500/20 text-yellow-400"; // ≤30d
  return "bg-green-500/20 text-green-400"; // >30d
}

export function RegulatoryCalendar({
  items,
  currentMonth = new Date(),
  onItemClick,
}: RegulatoryCalendarProps) {
  const monthStart = startOfMonth(currentMonth);
  const monthEnd = endOfMonth(currentMonth);
  const days = eachDayOfInterval({ start: monthStart, end: monthEnd });

  // Group items by date
  const itemsByDate = useMemo(() => {
    const map: Record<string, ComplianceItem[]> = {};
    for (const item of items) {
      const date = item.due_date;
      if (!map[date]) map[date] = [];
      map[date].push(item);
    }
    return map;
  }, [items]);

  // Get day of week for first day (0=Sun)
  const firstDayOfWeek = monthStart.getDay();

  const weekDays = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-heading font-bold uppercase tracking-wider">
          {format(currentMonth, "MMMM yyyy")}
        </h3>
        <div className="flex items-center gap-3 text-xs">
          <span className="flex items-center gap-1">
            <span className="w-3 h-3 rounded-full bg-green-500/30 inline-block" /> &gt;30d
          </span>
          <span className="flex items-center gap-1">
            <span className="w-3 h-3 rounded-full bg-yellow-500/30 inline-block" /> ≤30d
          </span>
          <span className="flex items-center gap-1">
            <span className="w-3 h-3 rounded-full bg-orange-500/30 inline-block" /> ≤7d
          </span>
          <span className="flex items-center gap-1">
            <span className="w-3 h-3 rounded-full bg-red-500/30 inline-block" /> Overdue
          </span>
        </div>
      </div>

      <div className="grid grid-cols-7 gap-1">
        {/* Week day headers */}
        {weekDays.map((day) => (
          <div key={day} className="text-center text-xs text-muted-foreground font-medium py-1">
            {day}
          </div>
        ))}

        {/* Empty cells for first week */}
        {Array.from({ length: firstDayOfWeek }).map((_, i) => (
          <div key={`empty-${i}`} />
        ))}

        {/* Day cells */}
        {days.map((day) => {
          const dateStr = format(day, "yyyy-MM-dd");
          const dayItems = itemsByDate[dateStr] ?? [];
          const hasItems = dayItems.length > 0;

          return (
            <div
              key={dateStr}
              className={`min-h-[60px] p-1 rounded-lg border transition-colors ${
                isToday(day)
                  ? "border-primary/50 bg-primary/5"
                  : "border-border/50 hover:border-border"
              }`}
            >
              <p className={`text-xs font-medium mb-1 ${isToday(day) ? "text-primary" : "text-muted-foreground"}`}>
                {format(day, "d")}
              </p>
              <div className="space-y-0.5">
                {dayItems.slice(0, 2).map((item) => (
                  <button
                    key={item.id}
                    onClick={() => onItemClick?.(item)}
                    className={`w-full text-left text-[10px] px-1 py-0.5 rounded truncate ${getItemColor(item.due_date, item.status)}`}
                    title={item.title}
                  >
                    {item.title}
                  </button>
                ))}
                {dayItems.length > 2 && (
                  <p className="text-[10px] text-muted-foreground pl-1">
                    +{dayItems.length - 2} more
                  </p>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

