"use client";

import useSWR from "swr";
import { MessageSquare, Mail, Phone, MessageCircle } from "lucide-react";
import { supabase } from "@/lib/supabase/client";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { format } from "date-fns";

const CHANNEL_ICONS: Record<string, React.ComponentType<{ className?: string }>> = {
  email: Mail,
  sms: Phone,
  whatsapp: MessageCircle,
};

const STATUS_COLORS: Record<string, string> = {
  sent: "bg-green-500/10 text-green-400",
  delivered: "bg-emerald-500/10 text-emerald-400",
  failed: "bg-red-500/10 text-red-400",
  pending: "bg-amber-500/10 text-amber-400",
  bounced: "bg-orange-500/10 text-orange-400",
};

async function fetchCommunications(customerId: string) {
  const { data, error } = await supabase
    .from("communication_logs")
    .select("*")
    .eq("customer_id", customerId)
    .order("created_at", { ascending: false })
    .limit(50);
  if (error) throw error;
  return data ?? [];
}

export function CommunicationTab({ customerId }: { customerId: string }) {
  const { data: logs, isLoading } = useSWR(
    `comm-logs-${customerId}`,
    () => fetchCommunications(customerId),
    { revalidateOnFocus: false }
  );

  if (isLoading) {
    return (
      <div className="space-y-3">
        {[1, 2, 3].map(i => <Skeleton key={i} className="h-16 w-full rounded-xl" />)}
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <MessageSquare className="w-4 h-4 text-primary" />
        <h3 className="font-heading font-bold uppercase tracking-wider text-sm">Communication History</h3>
        <Badge variant="secondary" className="text-xs">{logs?.length ?? 0}</Badge>
      </div>

      {!logs || logs.length === 0 ? (
        <div className="bg-card border border-border rounded-xl p-8 text-center">
          <MessageSquare className="w-10 h-10 mx-auto mb-3 text-muted-foreground/40" />
          <p className="text-muted-foreground text-sm">No communication history yet.</p>
        </div>
      ) : (
        <div className="space-y-2">
          {logs.map((log: any) => {
            const Icon = CHANNEL_ICONS[log.channel] ?? MessageSquare;
            return (
              <div key={log.id} className="flex items-start gap-3 p-3 rounded-xl border border-border bg-card">
                <div className="w-9 h-9 rounded-lg bg-primary/10 flex items-center justify-center flex-shrink-0 mt-0.5">
                  <Icon className="w-4 h-4 text-primary" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <p className="text-sm font-medium truncate">{log.subject || `${log.channel} message`}</p>
                    <Badge variant="outline" className={`text-xs ${STATUS_COLORS[log.status] || ""}`}>
                      {log.status}
                    </Badge>
                  </div>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    To: {log.recipient}
                    {log.created_at && ` · ${format(new Date(log.created_at), "dd MMM yyyy, hh:mm a")}`}
                  </p>
                  {log.body && (
                    <p className="text-xs text-muted-foreground mt-1 line-clamp-2">{log.body}</p>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

"use client";

import { FileText, Upload, Download, Trash2, CheckCircle, XCircle, Clock, ExternalLink, Shield } from "lucide-react";
import { toast } from "sonner";
import { KYCDocument } from "@/lib/types";
import { kycService } from "@/lib/services/kyc.service";
import { useAuth } from "@/lib/context/auth-context";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { KYCUploadDialog } from "@/components/kyc/kyc-upload-dialog";
import { format } from "date-fns";

const KYC_LABEL: Record<string, string> = {
  aadhaar: "Aadhaar", pan: "PAN", gst: "GST", address_proof: "Address Proof",
  passport: "Passport", driving_license: "Driving License", voter_id: "Voter ID",
  bank_statement: "Bank Statement", company_registration: "Company Reg.", other: "Other",
};

interface DocumentsTabProps {
  customerId: string;
  kycDocs: KYCDocument[];
  onMutate: () => void;
  kycUploadOpen: boolean;
  setKycUploadOpen: (open: boolean) => void;
  customerName: string;
}

export function DocumentsTab({ customerId, kycDocs, onMutate, kycUploadOpen, setKycUploadOpen, customerName }: DocumentsTabProps) {
  const { role, user } = useAuth();
  const canVerify = role === "admin" || role === "manager";
  const canDelete = role === "admin";

  const pendingCount = kycDocs.filter(d => d.status === "pending").length;

  const handleVerify = async (id: string) => {
    if (!user) return;
    try {
      await kycService.verify(id, user.id);
      toast.success("Document verified");
      onMutate();
    } catch { toast.error("Failed to verify"); }
  };

  const handleReject = async (id: string) => {
    if (!user) return;
    try {
      await kycService.reject(id, user.id, "Does not meet requirements");
      toast.success("Document rejected");
      onMutate();
    } catch { toast.error("Failed to reject"); }
  };

  const handleDelete = async (id: string) => {
    try {
      await kycService.delete(id);
      toast.success("Document removed");
      onMutate();
    } catch { toast.error("Failed to delete"); }
  };

  const handleView = async (filePath: string) => {
    try {
      const url = await kycService.getSignedUrl(filePath);
      window.open(url, "_blank");
    } catch { toast.error("Could not load document"); }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Shield className="w-4 h-4 text-primary" />
          <h3 className="font-heading font-bold uppercase tracking-wider text-sm">KYC Documents</h3>
          <Badge variant="secondary" className="text-xs">{kycDocs.length}</Badge>
          {pendingCount > 0 && (
            <Badge className="bg-amber-500/10 text-amber-400 text-xs">{pendingCount} pending</Badge>
          )}
        </div>
        <Button size="sm" onClick={() => setKycUploadOpen(true)} className="gap-2">
          <Upload className="w-4 h-4" /> Upload Document
        </Button>
      </div>

      {kycDocs.length === 0 ? (
        <div className="bg-card border border-border rounded-xl p-8 text-center">
          <Shield className="w-10 h-10 mx-auto mb-3 text-muted-foreground/40" />
          <p className="text-muted-foreground text-sm">No KYC documents uploaded yet.</p>
          <Button size="sm" variant="outline" onClick={() => setKycUploadOpen(true)} className="gap-2 mt-3">
            <Upload className="w-4 h-4" /> Upload First Document
          </Button>
        </div>
      ) : (
        <div className="space-y-2">
          {kycDocs.map(doc => (
            <div key={doc.id} className="flex items-center gap-3 p-3 rounded-xl border border-border bg-card hover:bg-muted/20 transition-colors">
              <div className="w-9 h-9 rounded-lg bg-primary/10 flex items-center justify-center flex-shrink-0">
                <FileText className="w-4 h-4 text-primary" />
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium">
                  {KYC_LABEL[doc.document_type] || doc.document_type}
                  {doc.document_number && (
                    <span className="ml-2 text-xs font-mono text-muted-foreground">#{doc.document_number}</span>
                  )}
                </p>
                <p className="text-xs text-muted-foreground mt-0.5">
                  {doc.file_name}
                  {(doc as any).created_at && ` · ${format(new Date((doc as any).created_at), "dd MMM yyyy")}`}
                </p>
              </div>
              <div className="flex items-center gap-2 flex-shrink-0">
                <Badge variant="outline" className={`text-xs ${
                  doc.status === "verified" ? "bg-green-500/10 text-green-400 border-green-500/20"
                  : doc.status === "rejected" ? "bg-red-500/10 text-red-400 border-red-500/20"
                  : "bg-amber-500/10 text-amber-400 border-amber-500/20"
                }`}>
                  {doc.status === "verified" && <CheckCircle className="w-3 h-3 mr-1" />}
                  {doc.status === "rejected" && <XCircle className="w-3 h-3 mr-1" />}
                  {doc.status === "pending" && <Clock className="w-3 h-3 mr-1" />}
                  {doc.status}
                </Badge>
                {doc.file_path && (
                  <button onClick={() => handleView(doc.file_path)} className="text-muted-foreground hover:text-primary transition-colors" title="View">
                    <ExternalLink className="w-3.5 h-3.5" />
                  </button>
                )}
                {canVerify && doc.status === "pending" && (
                  <>
                    <Button variant="ghost" size="sm" onClick={() => handleVerify(doc.id)}
                      className="h-7 px-2 text-green-400 hover:text-green-300 hover:bg-green-500/10">
                      <CheckCircle className="w-3.5 h-3.5 mr-1" /><span className="text-xs">Verify</span>
                    </Button>
                    <Button variant="ghost" size="sm" onClick={() => handleReject(doc.id)}
                      className="h-7 px-2 text-red-400 hover:text-red-300 hover:bg-red-500/10">
                      <XCircle className="w-3.5 h-3.5 mr-1" /><span className="text-xs">Reject</span>
                    </Button>
                  </>
                )}
                {canDelete && (
                  <Button variant="ghost" size="sm" onClick={() => handleDelete(doc.id)}
                    className="h-7 px-2 text-muted-foreground hover:text-red-400">
                    <Trash2 className="w-3.5 h-3.5" />
                  </Button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      <KYCUploadDialog
        open={kycUploadOpen}
        onOpenChange={setKycUploadOpen}
        customerId={customerId}
        customerName={customerName}
        onSuccess={onMutate}
      />
    </div>
  );
}

"use client";

import useSWR from "swr";
import { CreditCard, TrendingUp, TrendingDown, IndianRupee, AlertCircle } from "lucide-react";
import { supabase } from "@/lib/supabase/client";
import { Policy } from "@/lib/types";
import { Skeleton } from "@/components/ui/skeleton";

async function fetchFinancialData(customerId: string) {
  const [premiumsRes, commissionsRes] = await Promise.all([
    supabase
      .from("premiums")
      .select("amount, status, collected_date")
      .eq("customer_id", customerId),
    supabase
      .from("commissions")
      .select("amount, status")
      .in(
        "policy_id",
        (
          await supabase
            .from("policies")
            .select("id")
            .eq("customer_id", customerId)
        ).data?.map((p: any) => p.id) ?? []
      ),
  ]);

  const premiums = premiumsRes.data ?? [];
  const commissions = commissionsRes.data ?? [];

  const totalPremiumPaid = premiums
    .filter((p: any) => p.status === "collected")
    .reduce((sum: number, p: any) => sum + (p.amount || 0), 0);

  const outstandingPremium = premiums
    .filter((p: any) => p.status === "pending" || p.status === "overdue")
    .reduce((sum: number, p: any) => sum + (p.amount || 0), 0);

  const totalCommission = commissions
    .filter((c: any) => c.status === "paid" || c.status === "approved")
    .reduce((sum: number, c: any) => sum + (c.amount || 0), 0);

  return { totalPremiumPaid, outstandingPremium, totalCommission };
}

interface FinancialTabProps {
  customerId: string;
  policies: Policy[];
}

export function FinancialTab({ customerId, policies }: FinancialTabProps) {
  const { data, isLoading } = useSWR(
    `financial-${customerId}`,
    () => fetchFinancialData(customerId),
    { revalidateOnFocus: false }
  );

  const totalSumInsured = policies
    .filter(p => p.status === "active")
    .reduce((sum, p) => sum + (p.sum_insured || 0), 0);

  const totalPremium = policies
    .filter(p => p.status === "active")
    .reduce((sum, p) => sum + (p.premium_amount || 0), 0);

  if (isLoading) {
    return (
      <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
        {[1, 2, 3, 4, 5].map(i => <Skeleton key={i} className="h-28 rounded-xl" />)}
      </div>
    );
  }

  const fmt = (n: number) =>
    n >= 10_00_000
      ? `₹${(n / 10_00_000).toFixed(2)}L`
      : n >= 1_000
      ? `₹${(n / 1_000).toFixed(1)}K`
      : `₹${n.toLocaleString("en-IN")}`;

  const cards = [
    {
      label: "Total Premium Paid",
      value: fmt(data?.totalPremiumPaid ?? 0),
      icon: IndianRupee,
      color: "text-green-400",
      bg: "bg-green-500/10",
    },
    {
      label: "Outstanding Premium",
      value: fmt(data?.outstandingPremium ?? 0),
      icon: AlertCircle,
      color: data?.outstandingPremium ? "text-red-400" : "text-muted-foreground",
      bg: data?.outstandingPremium ? "bg-red-500/10" : "bg-muted/30",
    },
    {
      label: "Total Commission",
      value: fmt(data?.totalCommission ?? 0),
      icon: TrendingUp,
      color: "text-blue-400",
      bg: "bg-blue-500/10",
    },
    {
      label: "Active Sum Insured",
      value: fmt(totalSumInsured),
      icon: CreditCard,
      color: "text-purple-400",
      bg: "bg-purple-500/10",
    },
    {
      label: "Active Annual Premium",
      value: fmt(totalPremium),
      icon: TrendingDown,
      color: "text-amber-400",
      bg: "bg-amber-500/10",
    },
  ];

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <CreditCard className="w-4 h-4 text-primary" />
        <h3 className="font-heading font-bold uppercase tracking-wider text-sm">Financial Summary</h3>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
        {cards.map(({ label, value, icon: Icon, color, bg }) => (
          <div key={label} className="bg-card border border-border rounded-xl p-4">
            <div className={`w-9 h-9 rounded-lg ${bg} flex items-center justify-center mb-3`}>
              <Icon className={`w-4 h-4 ${color}`} />
            </div>
            <p className="text-xs text-muted-foreground uppercase tracking-wider font-heading">{label}</p>
            <p className={`text-xl font-bold mt-1 ${color}`}>{value}</p>
          </div>
        ))}
      </div>

      {policies.length > 0 && (
        <div className="bg-card border border-border rounded-xl p-4">
          <p className="text-xs text-muted-foreground uppercase tracking-wider font-heading mb-3">Policy Breakdown</p>
          <div className="space-y-2">
            {policies.slice(0, 5).map(p => (
              <div key={p.id} className="flex items-center justify-between text-sm">
                <span className="text-muted-foreground truncate max-w-[200px]">
                  {p.policy_number} · {p.policy_type?.replace(/_/g, " ")}
                </span>
                <span className="font-medium">₹{(p.premium_amount || 0).toLocaleString("en-IN")}</span>
              </div>
            ))}
            {policies.length > 5 && (
              <p className="text-xs text-muted-foreground">+{policies.length - 5} more policies</p>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { Building2, FileText, Shield } from "lucide-react";
import { Policy } from "@/lib/types";
import { Badge } from "@/components/ui/badge";

interface InsurerRelationsTabProps {
  policies: Policy[];
}

export function InsurerRelationsTab({ policies }: InsurerRelationsTabProps) {
  // Group policies by insurer
  const insurerMap = new Map<string, { policies: Policy[]; claims: number; tpa?: string }>();

  for (const p of policies) {
    const insurer = p.insurer_name || "Unknown Insurer";
    if (!insurerMap.has(insurer)) {
      insurerMap.set(insurer, { policies: [], claims: 0 });
    }
    insurerMap.get(insurer)!.policies.push(p);
  }

  const insurers = Array.from(insurerMap.entries()).sort((a, b) => b[1].policies.length - a[1].policies.length);

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <Building2 className="w-4 h-4 text-primary" />
        <h3 className="font-heading font-bold uppercase tracking-wider text-sm">Insurer Relationships</h3>
        <Badge variant="secondary" className="text-xs">{insurers.length}</Badge>
      </div>

      {insurers.length === 0 ? (
        <div className="bg-card border border-border rounded-xl p-8 text-center">
          <Building2 className="w-10 h-10 mx-auto mb-3 text-muted-foreground/40" />
          <p className="text-muted-foreground text-sm">No insurer relationships yet.</p>
        </div>
      ) : (
        <div className="grid gap-3">
          {insurers.map(([insurer, data]) => {
            const activePolicies = data.policies.filter(p => p.status === "active");
            const policyTypes = [...new Set(data.policies.map(p => p.policy_type))];
            const totalPremium = data.policies.reduce((sum, p) => sum + (p.premium_amount || 0), 0);

            return (
              <div key={insurer} className="bg-card border border-border rounded-xl p-4">
                <div className="flex items-start justify-between gap-3">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-lg bg-primary/10 flex items-center justify-center flex-shrink-0">
                      <Building2 className="w-5 h-5 text-primary" />
                    </div>
                    <div>
                      <p className="font-medium text-sm">{insurer}</p>
                      <div className="flex gap-2 mt-1 flex-wrap">
                        {policyTypes.slice(0, 3).map(t => (
                          <Badge key={t} variant="outline" className="text-xs">
                            {t?.replace(/_/g, " ")}
                          </Badge>
                        ))}
                        {policyTypes.length > 3 && (
                          <Badge variant="outline" className="text-xs">+{policyTypes.length - 3} more</Badge>
                        )}
                      </div>
                    </div>
                  </div>
                  <div className="text-right flex-shrink-0">
                    <p className="text-xs text-muted-foreground">Total Premium</p>
                    <p className="text-sm font-bold">₹{totalPremium.toLocaleString("en-IN")}</p>
                  </div>
                </div>

                <div className="grid grid-cols-3 gap-3 mt-3 pt-3 border-t border-border">
                  <div className="text-center">
                    <p className="text-lg font-bold text-foreground">{data.policies.length}</p>
                    <p className="text-xs text-muted-foreground">Total Policies</p>
                  </div>
                  <div className="text-center">
                    <p className="text-lg font-bold text-green-400">{activePolicies.length}</p>
                    <p className="text-xs text-muted-foreground">Active</p>
                  </div>
                  <div className="text-center">
                    <p className="text-lg font-bold text-muted-foreground">
                      {data.policies.filter(p => p.status === "expired").length}
                    </p>
                    <p className="text-xs text-muted-foreground">Expired</p>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

