                </div>
              </button>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { TrendingUp, AlertTriangle, CheckCircle, Clock, RefreshCw } from "lucide-react";
import { Policy } from "@/lib/types";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { differenceInDays, format } from "date-fns";

interface RenewalRiskTabProps {
  customerId: string;
  policies: Policy[];
}

function getRiskLevel(daysLeft: number): { label: string; color: string; bg: string } {
  if (daysLeft < 0) return { label: "Expired", color: "text-red-400", bg: "bg-red-500/10" };
  if (daysLeft <= 15) return { label: "Critical", color: "text-red-400", bg: "bg-red-500/10" };
  if (daysLeft <= 30) return { label: "High Risk", color: "text-orange-400", bg: "bg-orange-500/10" };
  if (daysLeft <= 60) return { label: "Medium Risk", color: "text-amber-400", bg: "bg-amber-500/10" };
  if (daysLeft <= 90) return { label: "Low Risk", color: "text-yellow-400", bg: "bg-yellow-500/10" };
  return { label: "Safe", color: "text-green-400", bg: "bg-green-500/10" };
}

export function RenewalRiskTab({ customerId, policies }: RenewalRiskTabProps) {
  const router = useRouter();
  const today = new Date();

  // Only active policies with end dates
  const activePolicies = policies
    .filter(p => p.status === "active" && p.end_date)
    .map(p => ({
      ...p,
      daysLeft: differenceInDays(new Date(p.end_date), today),
    }))
    .sort((a, b) => a.daysLeft - b.daysLeft);

  const expiredCount = policies.filter(p => p.status === "expired" || p.status === "cancelled").length;
  const renewedCount = policies.filter(p => p.status === "active").length;
  const upcomingRenewals = activePolicies.filter(p => p.daysLeft <= 90).length;
  const criticalRenewals = activePolicies.filter(p => p.daysLeft <= 30).length;

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <TrendingUp className="w-4 h-4 text-primary" />
        <h3 className="font-heading font-bold uppercase tracking-wider text-sm">Renewal Risk</h3>
      </div>

      {/* Summary cards */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        {[
          { label: "Active Policies", value: renewedCount, icon: CheckCircle, color: "text-green-400" },
          { label: "Due in 90 Days", value: upcomingRenewals, icon: Clock, color: "text-amber-400" },
          { label: "Critical (≤30d)", value: criticalRenewals, icon: AlertTriangle, color: "text-red-400" },
          { label: "Expired / Cancelled", value: expiredCount, icon: RefreshCw, color: "text-gray-400" },
        ].map(({ label, value, icon: Icon, color }) => (
          <div key={label} className="bg-card border border-border rounded-xl p-3">
            <Icon className={`w-4 h-4 ${color} mb-2`} />
            <p className={`text-xl font-bold ${color}`}>{value}</p>
            <p className="text-xs text-muted-foreground mt-0.5">{label}</p>
          </div>
        ))}
      </div>

      {/* Link to Renewal Cockpit */}
      <div className="flex justify-end">
        <button
          onClick={() => router.push(`/dashboard/renewals?customer=${customerId}`)}
          className="text-xs text-primary hover:underline flex items-center gap-1"
        >
          <RefreshCw className="w-3 h-3" />
          View in Renewal Cockpit
        </button>
      </div>

      {/* Upcoming renewals list */}
      {activePolicies.length === 0 ? (
        <div className="bg-card border border-border rounded-xl p-8 text-center">
          <TrendingUp className="w-10 h-10 mx-auto mb-3 text-muted-foreground/40" />
          <p className="text-muted-foreground text-sm">No active policies to track.</p>
        </div>
      ) : (
        <div className="space-y-2">
          <p className="text-xs text-muted-foreground uppercase tracking-wider font-heading">Upcoming Renewals</p>
          {activePolicies.map(p => {
            const risk = getRiskLevel(p.daysLeft);
            return (
              <button
                key={p.id}
                onClick={() => router.push(`/dashboard/policies/${p.id}`)}
                className="w-full flex items-center justify-between gap-3 px-4 py-3 rounded-xl bg-card border border-border hover:bg-muted/30 transition-colors text-left"
              >
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium">{p.policy_number}</p>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    {p.policy_type?.replace(/_/g, " ")} · {p.insurer_name || "—"}
                  </p>
                </div>
                <div className="flex items-center gap-2 flex-shrink-0">
                  <div className="text-right">
                    <p className="text-xs font-medium">
                      {p.daysLeft < 0 ? `${Math.abs(p.daysLeft)}d ago` : `${p.daysLeft}d left`}
                    </p>
                    <p className="text-xs text-muted-foreground">{format(new Date(p.end_date), "dd MMM yyyy")}</p>
                  </div>
                  <Badge variant="outline" className={`text-xs ${risk.color} ${risk.bg}`}>
                    {risk.label}
                  </Badge>
                </div>
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import useSWR from "swr";
import { AlertTriangle, Plus, ExternalLink, Clock } from "lucide-react";
import { supabase } from "@/lib/supabase/client";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { format } from "date-fns";
import { CreateTicketDialog } from "@/components/service-desk/CreateTicketDialog";

const STATUS_COLORS: Record<string, string> = {
  open: "bg-blue-500/10 text-blue-400",
  in_progress: "bg-amber-500/10 text-amber-400",
  pending: "bg-orange-500/10 text-orange-400",
  resolved: "bg-green-500/10 text-green-400",
  closed: "bg-gray-500/10 text-gray-400",
};

const PRIORITY_COLORS: Record<string, string> = {
  urgent: "bg-red-500/10 text-red-400",
  high: "bg-orange-500/10 text-orange-400",
  medium: "bg-amber-500/10 text-amber-400",
  low: "bg-gray-500/10 text-gray-400",
};

async function fetchTickets(customerId: string) {
  const { data, error } = await supabase
    .from("service_tickets")
    .select("*")
    .eq("customer_id", customerId)
    .order("created_at", { ascending: false })
    .limit(20);
  if (error) throw error;
  return data ?? [];
}

export function ServiceIssuesTab({ customerId, customerName }: { customerId: string; customerName?: string }) {
  const router = useRouter();
  const [createDialogOpen, setCreateDialogOpen] = useState(false);
  const { data: tickets, isLoading, mutate } = useSWR(
    `tickets-${customerId}`,
    () => fetchTickets(customerId),
    { revalidateOnFocus: false }
  );

  if (isLoading) {
    return (
      <div className="space-y-3">
        {[1, 2].map(i => <Skeleton key={i} className="h-16 w-full rounded-xl" />)}
      </div>
    );
  }

  const open = (tickets ?? []).filter((t: any) => t.status === "open" || t.status === "in_progress").length;
  const overdue = (tickets ?? []).filter((t: any) => {
    if (!t.sla_deadline) return false;
    return new Date(t.sla_deadline) < new Date() && t.status !== "resolved" && t.status !== "closed";
  }).length;

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <AlertTriangle className="w-4 h-4 text-primary" />
          <h3 className="font-heading font-bold uppercase tracking-wider text-sm">Service Issues</h3>
          <Badge variant="secondary" className="text-xs">{tickets?.length ?? 0}</Badge>
        </div>
        <Button size="sm" variant="outline"
          onClick={() => setCreateDialogOpen(true)}
          className="gap-2">
          <Plus className="w-4 h-4" /> New Ticket
        </Button>
      </div>

      {/* Summary */}
      <div className="grid grid-cols-3 gap-3">
        {[
          { label: "Open", value: open, color: "text-blue-400" },
          { label: "Overdue", value: overdue, color: overdue > 0 ? "text-red-400" : "text-muted-foreground" },
          { label: "Total", value: tickets?.length ?? 0, color: "text-foreground" },
        ].map(({ label, value, color }) => (
          <div key={label} className="bg-card border border-border rounded-xl p-3 text-center">
            <p className={`text-xl font-bold ${color}`}>{value}</p>
            <p className="text-xs text-muted-foreground mt-0.5">{label}</p>
          </div>
        ))}
      </div>

      {!tickets || tickets.length === 0 ? (
        <div className="bg-card border border-border rounded-xl p-8 text-center">
          <AlertTriangle className="w-10 h-10 mx-auto mb-3 text-muted-foreground/40" />
          <p className="text-muted-foreground text-sm">No service tickets yet.</p>
        </div>
      ) : (
        <div className="space-y-2">
          {tickets.map((t: any) => {
            const isOverdue = t.sla_deadline && new Date(t.sla_deadline) < new Date()
              && t.status !== "resolved" && t.status !== "closed";
            return (
              <button
                key={t.id}
                onClick={() => router.push(`/dashboard/service-desk/${t.id}`)}
                className="w-full flex items-center justify-between gap-3 px-4 py-3 rounded-xl bg-card border border-border hover:bg-muted/30 transition-colors text-left"
              >
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <p className="text-sm font-medium">{t.ticket_number || "—"}</p>
                    {isOverdue && <Badge className="bg-red-500/10 text-red-400 text-xs">Overdue</Badge>}
                  </div>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    {t.category?.replace(/_/g, " ") || "—"}
                    {t.created_at && ` · ${format(new Date(t.created_at), "dd MMM yyyy")}`}
                  </p>
                </div>
                <div className="flex items-center gap-2 flex-shrink-0">
                  <Badge variant="outline" className={`text-xs ${PRIORITY_COLORS[t.priority] || ""}`}>
                    {t.priority}
                  </Badge>
                  <Badge variant="outline" className={`text-xs ${STATUS_COLORS[t.status] || ""}`}>
                    {t.status?.replace(/_/g, " ")}
                  </Badge>
                  <ExternalLink className="w-3.5 h-3.5 text-muted-foreground" />
                </div>
              </button>
            );
          })}
        </div>
      )}

      {/* Create Ticket Dialog */}
      <CreateTicketDialog
        open={createDialogOpen}
        onOpenChange={open => {
          setCreateDialogOpen(open);
          if (!open) mutate(); // Refresh tickets after creation
        }}
        prefillCustomerId={customerId}
        prefillCustomerName={customerName}
      />
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";
import {
  Search,
  Phone,
  Mail,
  MapPin,
  Copy,
  Check,
  FileText,
  UserSearch,
  Plus,
} from "lucide-react";
import { toast } from "sonner";

import { useCustomerByUID } from "@/lib/hooks/use-customers";
import { usePoliciesByCustomer } from "@/lib/hooks/use-policies";
import { Customer } from "@/lib/types";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { CustomerForm } from "@/components/customers/customer-form";

export function CustomerLookup() {
  const router = useRouter();
  const [uidInput, setUidInput] = useState("");
  const [searchUID, setSearchUID] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const [formOpen, setFormOpen] = useState(false);

  const { data: customer, isLoading, error } = useCustomerByUID(searchUID);
  const { data: linkedPolicies } = usePoliciesByCustomer(customer?.id ?? null);

  const handleSearch = () => {
    const cleaned = uidInput.trim().toUpperCase();
    if (!cleaned) {
      toast.error("Please enter a customer UID");
      return;
    }
    // Accept both "C-0001" and "0001"
    const uid = cleaned.startsWith("C-") ? cleaned : `C-${cleaned.padStart(4, "0")}`;
    setSearchUID(uid);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter") handleSearch();
  };

  const handleCopy = async (text: string) => {
    await navigator.clipboard.writeText(text);
    setCopied(true);
    toast.success("Copied!");
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="max-w-lg mx-auto space-y-6">
      {/* Header */}
      <div className="text-center">
        <div className="w-16 h-16 rounded-full bg-primary/10 flex items-center justify-center mx-auto mb-4">
          <UserSearch className="w-8 h-8 text-primary" />
        </div>
        <h1 className="text-2xl font-cabin font-bold text-foreground uppercase tracking-wider">
          Customer Lookup
        </h1>
        <p className="text-muted-foreground text-sm mt-1">
          Enter a 4-digit customer UID to view their details
        </p>
        <Button
          variant="outline"
          size="sm"
          className="mt-3 gap-1.5"
          onClick={() => setFormOpen(true)}
        >
          <Plus className="h-4 w-4" />
          Create Customer
        </Button>
      </div>

      {/* Search input */}
      <div className="flex gap-2">
        <div className="relative flex-1">
          <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground text-sm font-mono">
            C-
          </span>
          <Input
            value={uidInput}
            onChange={(e) => setUidInput(e.target.value.replace(/[^0-9cC-]/g, ""))}
            onKeyDown={handleKeyDown}
            placeholder="0001"
            maxLength={10}
            className="pl-10 font-mono text-lg tracking-widest"
            autoFocus
          />
        </div>
        <Button onClick={handleSearch} disabled={isLoading} className="gap-2 px-6">
          <Search className="w-4 h-4" />
          Lookup
        </Button>
      </div>

      {/* Results */}
      <div aria-live="polite" aria-atomic="true">
      <AnimatePresence mode="wait">
        {isLoading && searchUID && (
          <motion.div
            key="loading"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="bg-card border border-border rounded-xl p-8 text-center"
          >
            <div className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full animate-spin mx-auto" />
            <p className="text-muted-foreground text-sm mt-3">
              Looking up {searchUID}...
            </p>
          </motion.div>
        )}

        {!isLoading && error && (
          <motion.div
            key="error"
            initial={{ opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -8 }}
            className="bg-card border border-red-500/20 rounded-xl p-8 text-center"
          >
            <p className="text-red-400 font-cabin font-bold uppercase tracking-wider">
              Error
            </p>
            <p className="text-muted-foreground text-sm mt-1">
              Failed to lookup customer. Please try again.
            </p>
          </motion.div>
        )}

        {!isLoading && !error && searchUID && !customer && (
          <motion.div
            key="not-found"
            initial={{ opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -8 }}
            className="bg-card border border-red-500/20 rounded-xl p-8 text-center"
          >
            <p className="text-red-400 font-cabin font-bold uppercase tracking-wider">
              Customer Not Found
            </p>
            <p className="text-muted-foreground text-sm mt-1">
              No customer with UID <span className="font-mono">{searchUID}</span> exists.
            </p>
          </motion.div>
        )}

        {!isLoading && customer && (
          <motion.div
            key="result"
            initial={{ opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -8 }}
            className="bg-card border border-border rounded-xl p-6 space-y-4"
          >
            {/* Name + UID */}
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-full bg-primary/10 flex items-center justify-center flex-shrink-0">
                <span className="text-lg font-cabin font-bold text-primary">
                  {customer.name.charAt(0).toUpperCase()}
                </span>
              </div>
              <div>
                <p className="font-cabin font-bold text-foreground text-lg">
                  {customer.name}
                </p>
                <button
                  onClick={() => handleCopy(customer.uid)}
                  className="flex items-center gap-1"
                >
                  <Badge
                    variant="secondary"
                    className="text-primary bg-primary/10 font-mono"
                  >
                    {customer.uid}
                  </Badge>
                  {copied ? (
                    <Check className="w-3 h-3 text-green-400" />
                  ) : (
                    <Copy className="w-3 h-3 text-muted-foreground" />
                  )}
                </button>
              </div>
            </div>

            <Separator />

            {/* Details */}
            <div className="space-y-3">
              <div className="flex items-center gap-3 text-sm">
                <Phone className="w-4 h-4 text-muted-foreground" />
                <span className="text-foreground">{customer.phone}</span>
              </div>
              <div className="flex items-center gap-3 text-sm">
                <Mail className="w-4 h-4 text-muted-foreground" />
                <span className="text-foreground">{customer.email}</span>
              </div>
              {(customer.address || customer.city) && (
                <div className="flex items-start gap-3 text-sm">
                  <MapPin className="w-4 h-4 text-muted-foreground mt-0.5" />
                  <span className="text-foreground">
                    {[customer.address, customer.city, customer.state, customer.pincode]
                      .filter(Boolean)
                      .join(", ")}
                  </span>
                </div>
              )}
            </div>

            <Separator />

            {/* Linked policies */}
            <div>
              <p className="text-xs text-muted-foreground uppercase tracking-wider font-cabin mb-3 flex items-center gap-2">
                <FileText className="w-3.5 h-3.5" /> Linked Policies
                {linkedPolicies && linkedPolicies.length > 0 && (
                  <Badge variant="secondary" className="text-xs">{linkedPolicies.length}</Badge>
                )}
              </p>
              {linkedPolicies && linkedPolicies.length > 0 ? (
                <div className="space-y-1.5">
                  {linkedPolicies.map((p) => {
                    const statusColor: Record<string, string> = {
                      active: "bg-green-500/10 text-green-400",
                      expired: "bg-red-500/10 text-red-400",
                      cancelled: "bg-gray-500/10 text-gray-400",
                      archived: "bg-amber-500/10 text-amber-400",
                    };
                    return (
                      <button
                        key={p.id}
                        onClick={() => router.push(`/dashboard/policies/${p.id}`)}
                        className="w-full flex items-center justify-between gap-2 px-3 py-2 rounded-lg bg-muted/30 hover:bg-muted/60 transition-colors text-left text-sm"
                      >
                        <span className="text-foreground truncate">{p.policy_number || "—"}</span>
                        <Badge className={`text-xs capitalize ${statusColor[p.status] || ""}`}>
                          {p.status}
                        </Badge>
                      </button>
                    );
                  })}
                </div>
              ) : (
                <p className="text-muted-foreground text-sm text-center py-4">
                  No policies linked yet.
                </p>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
      </div>

      {/* Customer creation form dialog */}
      <CustomerForm
        open={formOpen}
        onOpenChange={setFormOpen}
      />
    </div>
  );
}

"use client";

import { UseFormReturn } from "react-hook-form";
import { 
  User, 
  Mail, 
  Phone, 
  UserCheck, 
  FileSearch, 
  Loader2,
  AlertCircle
} from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";

import { ManualCustomerFormData } from "@/lib/validations/customer";
import { extractPolicyDataFromFile } from "@/lib/helpers/pdf-extractor";
import { useActiveUsers } from "@/lib/hooks/use-settings";

import { 
  FormControl, 
  FormField, 
  FormItem, 
  FormLabel, 
  FormMessage,
  FormDescription
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";

interface BasicInfoProps {
  form: UseFormReturn<ManualCustomerFormData>;
}

export function BasicInfo({ form }: BasicInfoProps) {
  const { data: users, isLoading: usersLoading } = useActiveUsers();
  const [extracting, setExtracting] = useState(false);

  const type = form.watch("type");

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setExtracting(true);
    const toastId = toast.loading("Analyzing document for auto-fill...");

    try {
      const extracted = await extractPolicyDataFromFile(file);
      
      // Auto-fill fields if found
      if (extracted.customerName) form.setValue("name", extracted.customerName, { shouldValidate: true });
      if (extracted.customerPhone) form.setValue("phone", extracted.customerPhone, { shouldValidate: true });
      if (extracted.customerEmail) form.setValue("email", extracted.customerEmail, { shouldValidate: true });
      if (extracted.customerAddress) form.setValue("address", extracted.customerAddress, { shouldValidate: true });
      if (extracted.customerCity) form.setValue("city", extracted.customerCity, { shouldValidate: true });
      if (extracted.customerState) form.setValue("state", extracted.customerState, { shouldValidate: true });
      
      // Specific metadata
      if (type === "individual" && extracted.startDate) {
         // Use startDate as potential DOB or just leave it for now
      }

      toast.success("Form pre-filled from document", { id: toastId });
    } catch (error) {
      console.error("OCR failed:", error);
      toast.error("Could not extract data from this file", { id: toastId });
    } finally {
      setExtracting(false);
      // Reset input
      e.target.value = "";
    }
  };

  return (
    <Card className="border-primary/10 shadow-md bg-card/50 backdrop-blur-sm">
      <CardHeader className="pb-4 flex flex-row items-center justify-between">
        <div className="space-y-1">
          <CardTitle className="text-xl font-bold flex items-center gap-2">
            <User className="w-5 h-5 text-primary" />
            1. Core Identity
          </CardTitle>
          <p className="text-sm text-muted-foreground">
            Basic contact and assignment details.
          </p>
        </div>
        
        {/* OCR Trigger */}
        <div className="relative">
          <input
            type="file"
            id="ocr-upload"
            className="hidden"
            accept=".pdf,image/*"
            onChange={handleFileUpload}
            disabled={extracting}
          />
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="gap-2 bg-primary/5 border-primary/20 hover:bg-primary/10"
            onClick={() => document.getElementById("ocr-upload")?.click()}
            disabled={extracting}
          >
            {extracting ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              <FileSearch className="w-4 h-4 text-primary" />
            )}
            Auto-fill from Document
          </Button>
        </div>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Entity Name */}
          <FormField
            control={form.control}
            name="name"
            render={({ field }) => (
              <FormItem>
                <FormLabel className="flex items-center gap-2">
                  {type === "individual" ? "Full Name" : "Company Name"}
                  <span className="text-destructive">*</span>
                </FormLabel>
                <FormControl>
                  <div className="relative">
                    <Input 
                      placeholder={type === "individual" ? "e.g. Rahul Sharma" : "e.g. Acme Corp Pvt Ltd"} 
                      className="pl-10 py-6"
                      {...field} 
                    />
                    <User className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                  </div>
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          {/* Assigned To */}
          <FormField
            control={form.control}
            name="assigned_to"
            render={({ field }) => (
              <FormItem>
                <FormLabel className="flex items-center gap-2">
                  Relationship Manager / Sub Agent
                  <span className="text-destructive">*</span>
                </FormLabel>
                <Select onValueChange={field.onChange} defaultValue={field.value}>
                  <FormControl>
                    <SelectTrigger className="py-6 pl-10 relative">
                      <UserCheck className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground z-10" />
                      <SelectValue placeholder={usersLoading ? "Loading..." : "Select assignee"} />
                    </SelectTrigger>
                  </FormControl>
                  <SelectContent>
                    {users?.map((u) => (
                      <SelectItem key={u.id} value={u.id}>
                        {u.name} ({u.role})
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <FormMessage />
              </FormItem>
            )}
          />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Email */}
          <FormField
            control={form.control}
            name="email"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Email Address</FormLabel>
                <FormControl>
                  <div className="relative">
                    <Input 
                      placeholder="email@example.com" 
                      className="pl-10 py-6"
                      {...field} 
                    />
                    <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                  </div>
                </FormControl>
                <FormDescription>Optional for individuals, required for portal access.</FormDescription>
                <FormMessage />
              </FormItem>
            )}
          />

          {/* Phone */}
          <FormField
            control={form.control}
            name="phone"
            render={({ field }) => (
              <FormItem>
                <FormLabel className="flex items-center gap-2">
                  Mobile Number
                  <span className="text-destructive">*</span>
                </FormLabel>
                <FormControl>
                  <div className="relative">
                    <Input 
                      placeholder="10-digit mobile" 
                      className="pl-10 py-6"
                      {...field} 
                    />
                    <Phone className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                  </div>
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { UseFormReturn, useFieldArray } from "react-hook-form";
import { 
  Building2, 
  Plus, 
  Trash2, 
  Contact, 
  ChevronDown, 
  ChevronUp,
  Mail,
  Phone,
  Briefcase
} from "lucide-react";
import { useState } from "react";

import { ManualCustomerFormData } from "@/lib/validations/customer";

import { 
  FormControl, 
  FormField, 
  FormItem, 
  FormLabel, 
  FormMessage
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";

interface CorporateMembersProps {
  form: UseFormReturn<ManualCustomerFormData>;
}

export function CorporateMembers({ form }: CorporateMembersProps) {
  const [expandedIndex, setExpandedIndex] = useState<number | null>(0);

  const { fields, append, remove } = useFieldArray({
    control: form.control as any,
    name: "corporate_members",
  });

  const toggleExpand = (index: number) => {
    setExpandedIndex(expandedIndex === index ? null : index);
  };

  return (
    <Card className="border-primary/10 shadow-md bg-card/50 backdrop-blur-sm">
      <CardHeader className="flex flex-row items-center justify-between">
        <div className="space-y-1">
          <CardTitle className="text-xl font-bold flex items-center gap-2">
            <Contact className="w-5 h-5 text-primary" />
            Corporate Contacts / Directors
          </CardTitle>
          <p className="text-sm text-muted-foreground">
            List key decision makers or points of contact.
          </p>
        </div>
        <Button
          type="button"
          variant="outline"
          size="sm"
          className="gap-2 border-primary/20 hover:bg-primary/5"
          onClick={() => {
            append({ name: "", designation: "", department: "", email: "", mobile: "", role: "", branch_location: "", notes: "" });
            setExpandedIndex(fields.length);
          }}
        >
          <Plus className="w-4 h-4" />
          Add Contact
        </Button>
      </CardHeader>
      <CardContent className="space-y-4">
        {fields.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-10 border-2 border-dashed border-primary/10 rounded-xl bg-primary/2">
            <Contact className="w-10 h-10 text-muted-foreground/30 mb-2" />
            <p className="text-muted-foreground text-sm">No contacts added yet.</p>
          </div>
        ) : (
          <div className="space-y-3">
            {fields.map((field, index) => {
              const isExpanded = expandedIndex === index;
              const nameValue = form.watch(`corporate_members.${index}.name` as any);
              const designationValue = form.watch(`corporate_members.${index}.designation` as any);

              return (
                <div 
                  key={field.id} 
                  className={`border rounded-xl transition-all duration-300 overflow-hidden ${
                    isExpanded ? "border-primary/30 ring-1 ring-primary/10 shadow-md" : "border-primary/10 bg-muted/10 text-muted-foreground"
                  }`}
                >
                  <div 
                    className="flex items-center justify-between p-4 cursor-pointer hover:bg-muted/20"
                    onClick={() => toggleExpand(index)}
                  >
                    <div className="flex items-center gap-4">
                      <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center text-primary font-bold">
                        {index + 1}
                      </div>
                      <div>
                        <p className={`font-semibold ${isExpanded ? "text-foreground" : ""}`}>
                          {nameValue || "Unnamed Contact"}
                        </p>
                        {designationValue && (
                          <p className="text-xs">{designationValue}</p>
                        )}
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        className="text-destructive h-8 w-8"
                        onClick={(e) => {
                          e.stopPropagation();
                          remove(index);
                          if (expandedIndex === index) setExpandedIndex(null);
                        }}
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                      {isExpanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
                    </div>
                  </div>

                  {isExpanded && (
                    <div className="p-6 bg-background/40 space-y-6 animate-in slide-in-from-top-1 duration-200">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <FormField
                          control={form.control}
                          name={`corporate_members.${index}.name` as any}
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Full Name</FormLabel>
                              <FormControl>
                                <Input placeholder="Contact Person" className="py-6" {...field} />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={form.control}
                          name={`corporate_members.${index}.designation` as any}
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Designation</FormLabel>
                              <FormControl>
                                <div className="relative">
                                  <Input placeholder="e.g. Director" className="py-6 pl-10" {...field} />
                                  <Briefcase className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                                </div>
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <FormField
                          control={form.control}
                          name={`corporate_members.${index}.email` as any}
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Email Address</FormLabel>
                              <FormControl>
                                <div className="relative">
                                  <Input placeholder="email@corp.com" className="py-6 pl-10" {...field} />
                                  <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                                </div>
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={form.control}
                          name={`corporate_members.${index}.mobile` as any}
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Contact Number</FormLabel>
                              <FormControl>
                                <div className="relative">
                                  <Input placeholder="Mobile" className="py-6 pl-10" {...field} />
                                  <Phone className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                                </div>
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { UseFormReturn, useFieldArray } from "react-hook-form";
import { 
  Upload, 
  Trash2, 
  FileText, 
  FilePlus, 
  Loader2,
  CheckCircle2,
  AlertCircle
} from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";

import { ManualCustomerFormData } from "@/lib/validations/customer";
import { documentService } from "@/lib/services/document.service";
import { useAuth } from "@/lib/context/auth-context";

import { 
  FormControl, 
  FormField, 
  FormItem, 
  FormLabel, 
  FormMessage,
  FormDescription
} from "@/components/ui/form";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";

interface DocumentUploadProps {
  form: UseFormReturn<ManualCustomerFormData>;
}

const DOCUMENT_TYPES = [
  { value: "aadhaar", label: "Aadhaar Card" },
  { value: "pan", label: "PAN Card" },
  { value: "gst", label: "GST Certificate" },
  { value: "passport", label: "Passport" },
  { value: "voter_id", label: "Voter ID" },
  { value: "driving_license", label: "Driving License" },
  { value: "cancel_cheque", label: "Cancelled Cheque" },
  { value: "utility_bill", label: "Utility Bill" },
  { value: "other", label: "Other Document" },
];

export function DocumentUpload({ form }: DocumentUploadProps) {
  const { user } = useAuth();
  const [uploadingIndex, setUploadingIndex] = useState<number | null>(null);
  const [progress, setProgress] = useState(0);

  const { fields, append, remove, update } = useFieldArray({
    control: form.control as any,
    name: "documents",
  });

  const handleFileChange = async (index: number, file: File) => {
    if (!user) return;
    
    const docType = form.getValues(`documents.${index}.type` as any);
    if (!docType) {
      toast.error("Please select a document type first");
      return;
    }

    setUploadingIndex(index);
    setProgress(0);

    try {
      const result = await documentService.uploadAndCreate(file, {
        document_type: docType,
        uploaded_by: user.id
      }, (p) => setProgress(p));

      update(index, {
        type: docType,
        url: result.file_url,
        name: file.name
      });

      toast.success(`${file.name} uploaded successfully`);
    } catch (error) {
      console.error("Upload failed:", error);
      toast.error(`Failed to upload ${file.name}`);
    } finally {
      setUploadingIndex(null);
      setProgress(0);
    }
  };

  return (
    <Card className="border-primary/10 shadow-md bg-card/50 backdrop-blur-sm">
      <CardHeader className="flex flex-row items-center justify-between">
        <div className="space-y-1">
          <CardTitle className="text-xl font-bold flex items-center gap-2">
            <Upload className="w-5 h-5 text-primary" />
            KYC Repository
          </CardTitle>
          <p className="text-sm text-muted-foreground">
            Identity and address proofs.
          </p>
        </div>
        <Button
          type="button"
          variant="outline"
          size="sm"
          className="gap-2 border-primary/20 hover:bg-primary/5"
          onClick={() => append({ type: "", url: "", name: "" })}
        >
          <FilePlus className="w-4 h-4" />
          Add Row
        </Button>
      </CardHeader>
      <CardContent className="space-y-4">
        {fields.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-8 border-2 border-dashed border-primary/10 rounded-xl bg-primary/2">
            <FileText className="w-10 h-10 text-muted-foreground/30 mb-2" />
            <p className="text-muted-foreground text-sm">No documents attached.</p>
          </div>
        ) : (
          <div className="space-y-3">
            {fields.map((field, index) => {
              const url = form.watch(`documents.${index}.url` as any);
              const fileName = form.watch(`documents.${index}.name` as any);
              const isUploading = uploadingIndex === index;

              return (
                <div key={field.id} className="p-4 rounded-xl border border-primary/10 bg-muted/20 space-y-3 relative overflow-hidden">
                  <div className="flex items-start gap-3">
                    <div className="flex-1 space-y-3">
                      <FormField
                        control={form.control}
                        name={`documents.${index}.type` as any}
                        render={({ field }) => (
                          <FormItem>
                            <Select onValueChange={field.onChange} defaultValue={field.value} disabled={!!url || isUploading}>
                              <FormControl>
                                <SelectTrigger className="bg-background">
                                  <SelectValue placeholder="Select Document Type" />
                                </SelectTrigger>
                              </FormControl>
                              <SelectContent>
                                {DOCUMENT_TYPES.map((t) => (
                                  <SelectItem key={t.value} value={t.value}>{t.label}</SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      {!url && !isUploading ? (
                        <div className="flex items-center gap-2">
                          <input
                            type="file"
                            id={`doc-file-${index}`}
                            className="hidden"
                            onChange={(e) => {
                              const f = e.target.files?.[0];
                              if (f) handleFileChange(index, f);
                            }}
                          />
                          <Button
                            type="button"
                            variant="secondary"
                            size="sm"
                            className="w-full gap-2 border-dashed border-primary/20"
                            onClick={() => document.getElementById(`doc-file-${index}`)?.click()}
                          >
                            <Upload className="w-3 h-3" />
                            Upload File
                          </Button>
                        </div>
                      ) : isUploading ? (
                        <div className="space-y-2">
                          <div className="flex justify-between text-xs">
                            <span className="flex items-center gap-1">
                              <Loader2 className="w-3 h-3 animate-spin" />
                              Uploading...
                            </span>
                            <span>{progress}%</span>
                          </div>
                          <Progress value={progress} className="h-1" />
                        </div>
                      ) : (
                        <div className="flex items-center justify-between p-2 bg-primary/10 rounded-lg border border-primary/20">
                          <div className="flex items-center gap-2 overflow-hidden">
                            <CheckCircle2 className="w-4 h-4 text-primary shrink-0" />
                            <span className="text-xs font-medium truncate">{fileName}</span>
                          </div>
                          <Button
                            type="button"
                            variant="ghost"
                            size="icon"
                            className="h-6 w-6 text-destructive"
                            onClick={() => remove(index)}
                          >
                            <Trash2 className="w-3 h-3" />
                          </Button>
                        </div>
                      )}
                    </div>
                    
                    {!isUploading && !url && (
                      <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        className="text-muted-foreground hover:text-destructive"
                        onClick={() => remove(index)}
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { UseFormReturn, useFieldArray } from "react-hook-form";
import { 
  Users, 
  Plus, 
  Trash2, 
  UserPlus, 
  Calendar,
  ChevronDown,
  ChevronUp
} from "lucide-react";
import { useState } from "react";

import { ManualCustomerFormData } from "@/lib/validations/customer";

import { 
  FormControl, 
  FormField, 
  FormItem, 
  FormLabel, 
  FormMessage,
  FormDescription
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardContent, CardHeader, CardTitle, CardFooter } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { Separator } from "@/components/ui/separator";

interface FamilyDetailsProps {
  form: UseFormReturn<ManualCustomerFormData>;
}

const RELATIONSHIPS = [
  "Spouse", "Son", "Daughter", "Father", "Mother", 
  "Brother", "Sister", "Grandfather", "Grandmother",
  "Father-in-law", "Mother-in-law", "Relative", "Other"
];

export function FamilyDetails({ form }: FamilyDetailsProps) {
  const [expandedIndex, setExpandedIndex] = useState<number | null>(0);

  const { fields, append, remove } = useFieldArray({
    control: form.control as any,
    name: "family_members",
  });

  const toggleExpand = (index: number) => {
    setExpandedIndex(expandedIndex === index ? null : index);
  };

  return (
    <Card className="border-primary/10 shadow-md bg-card/50 backdrop-blur-sm">
      <CardHeader className="flex flex-row items-center justify-between">
        <div className="space-y-1">
          <CardTitle className="text-xl font-bold flex items-center gap-2">
            <Users className="w-5 h-5 text-primary" />
            Family Members / Dependents
          </CardTitle>
          <p className="text-sm text-muted-foreground">
            Add family members to link them under a single Family ID.
          </p>
        </div>
        <Button
          type="button"
          variant="outline"
          size="sm"
          className="gap-2 border-primary/20 hover:bg-primary/5"
          onClick={() => {
            append({ 
              name: "", 
              relationship: "", 
              dob: "", 
              gender: "male", 
              mobile: "", 
              notes: "", 
              create_profile: false 
            });
            setExpandedIndex(fields.length);
          }}
        >
          <Plus className="w-4 h-4" />
          Add Member
        </Button>
      </CardHeader>
      <CardContent className="space-y-4">
        {fields.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-12 border-2 border-dashed border-primary/10 rounded-xl bg-primary/2">
            <Users className="w-12 h-12 text-muted-foreground/30 mb-4" />
            <p className="text-muted-foreground font-medium">No family members added yet.</p>
            <Button
              type="button"
              variant="ghost"
              className="mt-2 text-primary hover:text-primary/80"
              onClick={() => {
                append({ 
                  name: "", 
                  relationship: "", 
                  dob: "", 
                  gender: "male", 
                  mobile: "", 
                  notes: "", 
                  create_profile: false 
                });
                setExpandedIndex(0);
              }}
            >
              Click to add first member
            </Button>
          </div>
        ) : (
          <div className="space-y-3">
            {fields.map((field, index) => {
              const isExpanded = expandedIndex === index;
              const nameValue = form.watch(`family_members.${index}.name` as any);
              const relationshipValue = form.watch(`family_members.${index}.relationship` as any);

              return (
                <div 
                  key={field.id} 
                  className={`border rounded-xl transition-all duration-300 overflow-hidden ${
                    isExpanded ? "border-primary/30 ring-1 ring-primary/10 shadow-lg" : "border-primary/10 bg-muted/20"
                  }`}
                >
                  {/* Collapsed Header */}
                  <div 
                    className="flex items-center justify-between p-4 cursor-pointer hover:bg-muted/30 transition-colors"
                    onClick={() => toggleExpand(index)}
                  >
                    <div className="flex items-center gap-4">
                      <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold ${
                        isExpanded ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground"
                      }`}>
                        {index + 1}
                      </div>
                      <div>
                        <p className="font-semibold">{nameValue || "Unnamed Member"}</p>
                        {relationshipValue && (
                          <p className="text-xs text-muted-foreground capitalize">{relationshipValue}</p>
                        )}
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                       <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        className="text-destructive hover:bg-destructive/10"
                        onClick={(e) => {
                          e.stopPropagation();
                          remove(index);
                          if (expandedIndex === index) setExpandedIndex(null);
                        }}
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                      {isExpanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
                    </div>
                  </div>

                  {/* Expanded Content */}
                  {isExpanded && (
                    <div className="p-6 bg-background/50 space-y-6 animate-in slide-in-from-top-2 duration-300">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <FormField
                          control={form.control}
                          name={`family_members.${index}.name` as any}
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Full Name</FormLabel>
                              <FormControl>
                                <Input placeholder="Member Name" className="py-6" {...field} />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={form.control}
                          name={`family_members.${index}.relationship` as any}
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Relationship</FormLabel>
                              <Select onValueChange={field.onChange} defaultValue={field.value}>
                                <FormControl>
                                  <SelectTrigger className="py-6">
                                    <SelectValue placeholder="Select" />
                                  </SelectTrigger>
                                </FormControl>
                                <SelectContent>
                                  {RELATIONSHIPS.map(rel => (
                                    <SelectItem key={rel} value={rel.toLowerCase()}>{rel}</SelectItem>
                                  ))}
                                </SelectContent>
                              </Select>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <FormField
                          control={form.control}
                          name={`family_members.${index}.dob` as any}
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Date of Birth</FormLabel>
                              <FormControl>
                                <div className="relative">
                                  <Input type="date" className="py-6 pl-10" {...field} />
                                  <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                                </div>
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={form.control}
                          name={`family_members.${index}.gender` as any}
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Gender</FormLabel>
                              <Select onValueChange={field.onChange} defaultValue={field.value}>
                                <FormControl>
                                  <SelectTrigger className="py-6">
                                    <SelectValue placeholder="Select" />
                                  </SelectTrigger>
                                </FormControl>
                                <SelectContent>
                                  <SelectItem value="male">Male</SelectItem>
                                  <SelectItem value="female">Female</SelectItem>
                                  <SelectItem value="other">Other</SelectItem>
                                </SelectContent>
                              </Select>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                         <FormField
                          control={form.control}
                          name={`family_members.${index}.mobile` as any}
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Mobile (Optional)</FormLabel>
                              <FormControl>
                                <Input placeholder="10-digit number" className="py-6" {...field} />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                      </div>

                      <Separator className="bg-primary/10" />

                      <div className="flex items-center justify-between p-3 bg-primary/5 rounded-xl border border-primary/10">
                        <div className="space-y-0.5">
                          <div className="flex items-center gap-2">
                            <UserPlus className="w-4 h-4 text-primary" />
                            <p className="font-semibold text-sm">Create Independent Profile</p>
                          </div>
                          <p className="text-xs text-muted-foreground">
                            When enabled, this member will get their own Customer UID and portal access.
                          </p>
                        </div>
                        <FormField
                          control={form.control}
                          name={`family_members.${index}.create_profile` as any}
                          render={({ field }) => (
                            <FormItem>
                              <FormControl>
                                <Switch
                                  checked={field.value}
                                  onCheckedChange={field.onChange}
                                />
                              </FormControl>
                            </FormItem>
                          )}
                        />
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

