import { cn } from "../../lib/utils/index";

interface StatItem {
  label: string;
  value: string | number;
  total: string;
  subValue?: string;
  subLabel?: string;
  icon: React.ElementType;
  iconClass: string;
  chipClass: string;
  accentClass?: string;
  href: string;
  alert?: boolean;
}

interface StatCardGridProps {
  stats: any;
  loading: boolean;
}

export function StatCardGrid({ stats, loading }: StatCardGridProps) {
  const statCards: StatItem[] = [
    {
