                    >
                      <Icon className={`h-5 w-5 ${item.iconClass}`} />
                    </div>
                  </div>
                  {loading ? (
                    <Skeleton className="h-9 w-20 bg-skeleton" />
                  ) : (
                    <div className="space-y-1">
                      <div className="flex items-baseline gap-2">
                        <p className="text-3xl font-bold tracking-tight text-foreground">
                          {item.value}
                        </p>
                        {item.subLabel && (
                          <span className={cn(
                            "text-[9px] font-black uppercase tracking-tighter px-1.5 py-0.5 rounded-md border",
                            item.alert ? "bg-rose-500/10 text-rose-500 border-rose-500/20" : "bg-primary/10 text-primary border-primary/20"
                          )}>
                             {item.subLabel}
                          </span>
                        )}
                      </div>
                      {item.total && (
                        <p className={`text-[11px] font-medium leading-tight ${item.accentClass ?? "text-muted-foreground/60"}`}>
                          {item.total}
                        </p>
                      )}
                    </div>
                  )}
                </CardContent>
              </Card>
            </Link>
          </motion.div>
        );
      })}
    </motion.div>
  );
}

"use client";
import React, { useMemo, useState } from "react";
import Link from "next/link";
import { ArrowRight, CalendarDays } from "lucide-react";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { hoverLift, staggerContainer, staggerItem } from "@/lib/helpers/animations";
import { cn } from "@/lib/utils";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";

interface RenewalItem {
  id: string;
  customer_name?: string;
  policy_number?: string;
  due_date?: string | null;
  policy_type?: string;
  premium_amount?: number;
}

interface UpcomingRenewalsWidgetProps {
  upcoming: RenewalItem[] | undefined;
}

export function UpcomingRenewalsWidget({ upcoming }: UpcomingRenewalsWidgetProps) {
  const [days, setDays] = useState("30");

  const filteredUpcoming = useMemo(() => {
    if (!upcoming) return [];
    const now = new Date();
    const limit = new Date();
    limit.setDate(now.getDate() + parseInt(days));
    return upcoming.filter(r => r.due_date && new Date(r.due_date) <= limit);
  }, [upcoming, days]);

  return (
    <Card className="border border-border/70 bg-card/40 backdrop-blur-md shadow-sm overflow-hidden">
      <CardHeader className="pb-4 border-b border-border/40">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div className="flex items-center gap-2">
            <div className="h-8 w-8 rounded-lg bg-primary/10 flex items-center justify-center">
               <CalendarDays className="h-4 w-4 text-primary" />
            </div>
            <div>
              <CardTitle className="text-sm font-bold tracking-tight">Renewal Intelligence</CardTitle>
              <p className="text-[10px] text-muted-foreground uppercase tracking-widest font-black">Forecast Insight</p>
            </div>
          </div>
          
          <Tabs defaultValue="30" className="w-auto" onValueChange={setDays}>
            <TabsList className="bg-background/50 h-8 p-1 rounded-lg">
              <TabsTrigger value="7" className="text-[10px] h-6 px-3 rounded-md font-bold uppercase tracking-tighter">7D</TabsTrigger>
              <TabsTrigger value="15" className="text-[10px] h-6 px-3 rounded-md font-bold uppercase tracking-tighter">15D</TabsTrigger>
              <TabsTrigger value="30" className="text-[10px] h-6 px-3 rounded-md font-bold uppercase tracking-tighter">30D</TabsTrigger>
            </TabsList>
          </Tabs>
        </div>
      </CardHeader>
      <CardContent className="p-0">
        {filteredUpcoming.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-12 px-6 opacity-40">
             <CalendarDays className="h-10 w-10 mb-2 stroke-1" />
             <p className="text-xs font-bold uppercase tracking-tighter">No renewals in next {days} days</p>
          </div>
        ) : (
          <div className="divide-y divide-border/30">
            {filteredUpcoming.slice(0, 6).map((r) => (
              <Link
                key={r.id}
                href={`/dashboard/renewals/${r.id}`}
                className="group flex items-center justify-between px-6 py-4 transition-all hover:bg-primary/5 border-l-2 border-transparent hover:border-primary active:bg-primary/10"
              >
                <div className="flex items-center gap-4 min-w-0">
                  <div className="hidden sm:flex h-10 w-10 rounded-xl bg-background/80 border border-border/50 items-center justify-center group-hover:scale-110 transition-transform shadow-inner">
                    <span className="text-[10px] font-black text-primary">{r.policy_type?.substring(0,2).toUpperCase() || "POL"}</span>
                  </div>
                  <div className="min-w-0">
                    <div className="flex items-center gap-2 mb-0.5">
                       <p className="truncate text-sm font-bold text-foreground">
                        {r.customer_name || "Unknown Business"}
                      </p>
                       <span className="text-[9px] font-black text-primary/60 border border-primary/20 px-1 rounded-sm bg-primary/5 uppercase">{r.policy_type || "General"}</span>
                    </div>
                    <p className="text-[10px] text-muted-foreground font-mono tracking-tighter">
                      PRM: ₹{r.premium_amount?.toLocaleString() || "TBC"} • {r.policy_number || "PENDING_ID"}
                    </p>
                  </div>
                </div>
                <div className="ml-4 shrink-0 text-right">
                  <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground/50">Expires</p>
                  <p className="text-xs font-bold text-orange-600 dark:text-orange-400">
                    {r.due_date ? new Date(r.due_date).toLocaleDateString("en-IN", {
                      day: "2-digit",
                      month: "short",
                    }) : "—"}
                  </p>
                </div>
              </Link>
            ))}
          </div>
        )}
        {filteredUpcoming.length > 0 && (
          <Link href="/dashboard/renewals" className="block border-t border-border/40 bg-background/20 p-3 text-center text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground hover:text-primary transition-colors">
            View Holistic Renewal Pipeline <ArrowRight className="inline-block h-3 w-3 ml-1" />
          </Link>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { useState, useEffect } from "react";
import { toast } from "sonner";
import { Loader2 } from "lucide-react";

import { useAuth } from "@/lib/context/auth-context";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";

interface DriverFormProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  customerId: string;
  editData?: any;
  onSuccess?: () => void;
}

export function DriverForm({ open, onOpenChange, customerId, editData, onSuccess }: DriverFormProps) {
  const { session } = useAuth();
  const token = session?.access_token ?? "";
  const isEdit = !!editData;

  const [form, setForm] = useState({
    name: "",
    license_number: "",
    license_expiry: "",
    mobile: "",
    address: "",
  });
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (editData) {
      setForm({
        name: editData.name || "",
        license_number: editData.license_number || "",
        license_expiry: editData.license_expiry ? editData.license_expiry.split("T")[0] : "",
        mobile: editData.mobile || "",
        address: editData.address || "",
      });
    } else {
      setForm({ name: "", license_number: "", license_expiry: "", mobile: "", address: "" });
    }
  }, [editData, open]);

  const handleSave = async () => {
    if (!form.name.trim()) { toast.error("Name is required"); return; }
    if (!form.license_number.trim()) { toast.error("License Number is required"); return; }
    if (!form.license_expiry) { toast.error("License Expiry is required"); return; }

    // Validate future date
    if (new Date(form.license_expiry) <= new Date()) {
      toast.error("License Expiry must be a future date");
      return;
    }

    setSaving(true);
    try {
      const url = isEdit
        ? `/api/fleet/${customerId}/drivers/${editData.id}`
        : `/api/fleet/${customerId}/drivers`;
      const method = isEdit ? "PUT" : "POST";

      const res = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify(form),
      });

      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || "Failed to save driver");
      }

      toast.success(isEdit ? "Driver updated" : "Driver added");
      onSuccess?.();
      onOpenChange(false);
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="font-heading uppercase tracking-wider">
            {isEdit ? "Edit Driver" : "Add Driver"}
          </DialogTitle>
        </DialogHeader>
        <div className="space-y-4 py-2">
          <div className="space-y-1.5">
            <Label>Full Name <span className="text-destructive">*</span></Label>
            <Input
              value={form.name}
              onChange={e => setForm(f => ({ ...f, name: e.target.value }))}
              placeholder="Driver full name"
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label>License Number <span className="text-destructive">*</span></Label>
              <Input
                value={form.license_number}
                onChange={e => setForm(f => ({ ...f, license_number: e.target.value.toUpperCase() }))}
                placeholder="MH0120XXXXXXXX"
                disabled={isEdit}
              />
            </div>
            <div className="space-y-1.5">
              <Label>License Expiry <span className="text-destructive">*</span></Label>
              <Input
                type="date"
                value={form.license_expiry}
                onChange={e => setForm(f => ({ ...f, license_expiry: e.target.value }))}
                min={new Date().toISOString().split("T")[0]}
              />
            </div>
          </div>
          <div className="space-y-1.5">
            <Label>Mobile</Label>
            <Input
              value={form.mobile}
              onChange={e => setForm(f => ({ ...f, mobile: e.target.value }))}
              placeholder="10-digit mobile"
            />
          </div>
          <div className="space-y-1.5">
            <Label>Address</Label>
            <Textarea
              value={form.address}
              onChange={e => setForm(f => ({ ...f, address: e.target.value }))}
              placeholder="Driver address"
              rows={2}
            />
          </div>
        </div>
        <DialogFooter>
          <Button variant="ghost" onClick={() => onOpenChange(false)} disabled={saving}>Cancel</Button>
          <Button onClick={handleSave} disabled={saving} className="gap-2">
            {saving && <Loader2 className="w-4 h-4 animate-spin" />}
            {isEdit ? "Update Driver" : "Add Driver"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import useSWR from "swr";
import { format } from "date-fns";
import { FileText, Plus, Minus } from "lucide-react";

import { useAuth } from "@/lib/context/auth-context";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";

interface EndorsementHistoryProps {
  customerId: string;
}

async function fetchEndorsements(customerId: string, token: string) {
  const res = await fetch(`/api/fleet/${customerId}/endorsements`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) return { data: [] };
  return res.json();
}

export function FleetEndorsementHistory({ customerId }: EndorsementHistoryProps) {
  const { session } = useAuth();
  const token = session?.access_token ?? "";

  const { data, isLoading } = useSWR(
    token ? `fleet-endorsements-${customerId}` : null,
    () => fetchEndorsements(customerId, token),
    { revalidateOnFocus: false }
  );

  const endorsements = data?.data ?? [];

  if (isLoading) {
    return (
      <div className="space-y-3">
        {[...Array(3)].map((_, i) => <Skeleton key={i} className="h-12 w-full" />)}
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <FileText className="w-4 h-4 text-primary" />
        <h3 className="font-heading font-bold uppercase tracking-wider text-sm">Endorsement History</h3>
        <Badge variant="secondary" className="text-xs">{endorsements.length}</Badge>
      </div>

      {endorsements.length === 0 ? (
        <div className="bg-card border border-border rounded-xl p-8 text-center">
          <FileText className="w-10 h-10 mx-auto mb-3 text-muted-foreground/40" />
          <p className="text-muted-foreground text-sm">No endorsements yet.</p>
        </div>
      ) : (
        <div className="bg-card border border-border rounded-xl overflow-hidden">
          <Table>
            <TableHeader>
              <TableRow className="border-border hover:bg-transparent">
                <TableHead className="text-xs uppercase tracking-wider font-heading">Endorsement #</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Type</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden md:table-cell">Date</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Registration #</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden sm:table-cell">Make / Model</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {endorsements.map((e: any) => (
                <TableRow key={e.id} className="border-border hover:bg-muted/30">
                  <TableCell className="font-mono text-sm">{e.endorsement_number}</TableCell>
                  <TableCell>
                    <Badge
                      variant="outline"
                      className={`text-xs gap-1 ${
                        e.endorsement_type === "Addition"
                          ? "bg-green-500/10 text-green-400"
                          : "bg-red-500/10 text-red-400"
                      }`}
                    >
                      {e.endorsement_type === "Addition"
                        ? <Plus className="w-3 h-3" />
                        : <Minus className="w-3 h-3" />
                      }
                      {e.endorsement_type}
                    </Badge>
                  </TableCell>
                  <TableCell className="hidden md:table-cell text-sm text-muted-foreground">
                    {e.endorsement_date ? format(new Date(e.endorsement_date), "dd MMM yyyy") : "—"}
                  </TableCell>
                  <TableCell className="font-mono text-sm">
                    {e.vehicle_details?.registration_number || "—"}
                  </TableCell>
                  <TableCell className="hidden sm:table-cell text-sm text-muted-foreground">
                    {e.vehicle_details?.make && e.vehicle_details?.model
                      ? `${e.vehicle_details.make} ${e.vehicle_details.model}`
                      : "—"}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { toast } from "sonner";
import { Loader2, Search } from "lucide-react";
import useSWR from "swr";

import { useAuth } from "@/lib/context/auth-context";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";

interface FleetClaimFormProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  customerId: string;
  onSuccess?: () => void;
}

export function FleetClaimForm({ open, onOpenChange, customerId, onSuccess }: FleetClaimFormProps) {
  const { session } = useAuth();
  const token = session?.access_token ?? "";

  const [form, setForm] = useState({
    policy_id: "",
    vehicle_id: "",
    claim_amount: "",
    claim_type: "own_damage",
    accident_details: "",
    surveyor_name: "",
    surveyor_phone: "",
    appointment_date: "",
  });
  const [vehicleSearch, setVehicleSearch] = useState("");
  const [saving, setSaving] = useState(false);

  const { data: policiesData } = useSWR(
    token && open ? `policies-fleet-${customerId}` : null,
    async () => {
      const res = await fetch(`/api/policies?customer_id=${customerId}&limit=50`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) return [];
      const d = await res.json();
      return d.data ?? [];
    },
    { revalidateOnFocus: false }
  );

  const { data: vehiclesData } = useSWR(
    token && open ? `fleet-vehicles-search-${customerId}-${vehicleSearch}` : null,
    async () => {
      const res = await fetch(`/api/fleet/${customerId}/vehicles?search=${vehicleSearch}&status=Active&limit=20`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) return [];
      const d = await res.json();
      return d.data ?? [];
    },
    { revalidateOnFocus: false }
  );

  const handleSave = async () => {
    if (!form.policy_id) { toast.error("Policy is required"); return; }
    if (!form.claim_amount || Number(form.claim_amount) <= 0) { toast.error("Valid claim amount is required"); return; }

    setSaving(true);
    try {
      const res = await fetch(`/api/fleet/${customerId}/claims`, {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({
          ...form,
          claim_amount: Number(form.claim_amount),
          vehicle_id: form.vehicle_id || undefined,
        }),
      });

      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || "Failed to register claim");
      }

      toast.success("Fleet claim registered");
      onSuccess?.();
      onOpenChange(false);
      setForm({ policy_id: "", vehicle_id: "", claim_amount: "", claim_type: "own_damage", accident_details: "", surveyor_name: "", surveyor_phone: "", appointment_date: "" });
      setVehicleSearch("");
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-lg max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="font-heading uppercase tracking-wider">Register Fleet Claim</DialogTitle>
        </DialogHeader>
        <div className="space-y-4 py-2">
          <div className="space-y-1.5">
            <Label>Policy <span className="text-destructive">*</span></Label>
            <Select value={form.policy_id} onValueChange={v => setForm(f => ({ ...f, policy_id: v }))}>
              <SelectTrigger><SelectValue placeholder="Select policy" /></SelectTrigger>
              <SelectContent>
                {(policiesData ?? []).map((p: any) => (
                  <SelectItem key={p.id} value={p.id}>{p.policy_number} · {p.policy_type}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-1.5">
            <Label>Vehicle (optional)</Label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <Input
                value={vehicleSearch}
                onChange={e => setVehicleSearch(e.target.value)}
                placeholder="Search by registration number..."
                className="pl-9"
              />
            </div>
            {vehiclesData && vehiclesData.length > 0 && vehicleSearch && (
              <div className="border border-border rounded-lg overflow-hidden max-h-40 overflow-y-auto">
                {vehiclesData.map((v: any) => (
                  <button
                    key={v.id}
                    onClick={() => { setForm(f => ({ ...f, vehicle_id: v.id })); setVehicleSearch(`${v.registration_number} — ${v.make} ${v.model}`); }}
                    className="w-full text-left px-3 py-2 text-sm hover:bg-muted/30 border-b border-border last:border-0"
                  >
                    <span className="font-mono font-medium">{v.registration_number}</span>
                    <span className="text-muted-foreground ml-2">{v.make} {v.model}</span>
                  </button>
                ))}
              </div>
            )}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label>Claim Type</Label>
              <Select value={form.claim_type} onValueChange={v => setForm(f => ({ ...f, claim_type: v }))}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="own_damage">Own Damage</SelectItem>
                  <SelectItem value="third_party">Third Party</SelectItem>
                  <SelectItem value="theft">Theft</SelectItem>
                  <SelectItem value="natural_disaster">Natural Disaster</SelectItem>
