"use client";

import { useState, useEffect } from "react";
import { toast } from "sonner";
import { ShieldCheck, Loader2 } from "lucide-react";

import { useAuth } from "@/lib/context/auth-context";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";

const DOC_TYPES = [
  { key: "permit_state", label: "Permit (State)" },
  { key: "permit_national", label: "Permit (National)" },
  { key: "fitness", label: "Fitness" },
  { key: "puc", label: "PUC" },
  { key: "rc", label: "RC" },
  { key: "tax_state", label: "Tax (State)" },
  { key: "tax_national", label: "Tax (National)" },
] as const;

type DocType = typeof DOC_TYPES[number]["key"];

interface ValidityEntry {
  issue_date: string;
  expiry_date: string;
}

interface ValidityUpdateDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  customerId: string;
  vehicleId: string;
  vehicleRegNumber: string;
  onSuccess?: () => void;
}

export function ValidityUpdateDialog({
  open,
  onOpenChange,
  customerId,
  vehicleId,
  vehicleRegNumber,
  onSuccess,
}: ValidityUpdateDialogProps) {
  const { session } = useAuth();
  const token = session?.access_token ?? "";

  const [entries, setEntries] = useState<Record<DocType, ValidityEntry>>(
    () => Object.fromEntries(DOC_TYPES.map(d => [d.key, { issue_date: "", expiry_date: "" }])) as Record<DocType, ValidityEntry>
  );
  const [saving, setSaving] = useState<DocType | null>(null);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const updateEntry = (docType: DocType, field: "issue_date" | "expiry_date", value: string) => {
    setEntries(prev => ({ ...prev, [docType]: { ...prev[docType], [field]: value } }));
    // Clear error on change
    setErrors(prev => { const next = { ...prev }; delete next[docType]; return next; });
  };

  const validateEntry = (docType: DocType): string | null => {
    const entry = entries[docType];
    if (!entry.expiry_date) return null; // Skip if no expiry date
    if (entry.issue_date && new Date(entry.expiry_date) <= new Date(entry.issue_date)) {
      return "Expiry date must be after issue date";
    }
    return null;
  };

  const handleSaveOne = async (docType: DocType) => {
    const entry = entries[docType];
    if (!entry.expiry_date) {
      toast.error("Expiry date is required");
      return;
    }

    const validationError = validateEntry(docType);
    if (validationError) {
      setErrors(prev => ({ ...prev, [docType]: validationError }));
      toast.error(validationError);
      return;
    }

    setSaving(docType);
    try {
      const res = await fetch(`/api/fleet/${customerId}/vehicles/${vehicleId}/validity`, {
        method: "PUT",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({
          document_type: docType,
          issue_date: entry.issue_date || null,
          expiry_date: entry.expiry_date,
        }),
      });

      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || "Failed to update validity");
      }

      toast.success(`${DOC_TYPES.find(d => d.key === docType)?.label} updated`);
      onSuccess?.();
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setSaving(null);
    }
  };

  const handleSaveAll = async () => {
    const toSave = DOC_TYPES.filter(d => entries[d.key].expiry_date);
    if (toSave.length === 0) {
      toast.error("Please enter at least one expiry date");
      return;
    }

    // Validate all
    const newErrors: Record<string, string> = {};
    for (const d of toSave) {
      const err = validateEntry(d.key);
      if (err) newErrors[d.key] = err;
    }
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      toast.error("Please fix validation errors");
      return;
    }

    setSaving("permit_state"); // Use any value to show loading
    try {
      await Promise.all(
        toSave.map(d =>
          fetch(`/api/fleet/${customerId}/vehicles/${vehicleId}/validity`, {
            method: "PUT",
            headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
            body: JSON.stringify({
              document_type: d.key,
              issue_date: entries[d.key].issue_date || null,
              expiry_date: entries[d.key].expiry_date,
            }),
          })
        )
      );
      toast.success(`${toSave.length} validity documents updated`);
      onSuccess?.();
      onOpenChange(false);
    } catch (err: any) {
      toast.error(err.message || "Failed to update some documents");
    } finally {
      setSaving(null);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-lg max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="font-heading uppercase tracking-wider flex items-center gap-2">
            <ShieldCheck className="w-5 h-5 text-primary" />
            Update Validity Dates
          </DialogTitle>
          <p className="text-sm text-muted-foreground font-mono">{vehicleRegNumber}</p>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {DOC_TYPES.map(({ key, label }) => (
            <div key={key} className="bg-muted/20 rounded-xl p-4 space-y-3">
              <div className="flex items-center justify-between">
                <p className="text-sm font-medium">{label}</p>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => handleSaveOne(key)}
                  disabled={saving !== null || !entries[key].expiry_date}
                  className="h-7 text-xs"
                >
                  {saving === key ? <Loader2 className="w-3 h-3 animate-spin" /> : "Save"}
                </Button>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1">
                  <Label className="text-xs text-muted-foreground">Issue Date</Label>
                  <Input
                    type="date"
                    value={entries[key].issue_date}
                    onChange={e => updateEntry(key, "issue_date", e.target.value)}
                    className="h-8 text-sm"
                  />
                </div>
                <div className="space-y-1">
                  <Label className="text-xs text-muted-foreground">Expiry Date</Label>
                  <Input
                    type="date"
                    value={entries[key].expiry_date}
                    onChange={e => updateEntry(key, "expiry_date", e.target.value)}
                    className="h-8 text-sm"
                  />
                </div>
              </div>
              {errors[key] && (
                <p className="text-xs text-red-400">{errors[key]}</p>
              )}
            </div>
          ))}
        </div>

        <DialogFooter>
          <Button variant="ghost" onClick={() => onOpenChange(false)} disabled={saving !== null}>Cancel</Button>
          <Button onClick={handleSaveAll} disabled={saving !== null} className="gap-2">
            {saving !== null && <Loader2 className="w-4 h-4 animate-spin" />}
            Save All
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { useRouter } from "next/navigation";
import { useAuth } from "@/lib/context/auth-context";
import { policyService } from "@/lib/services/policy.service";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { AlertTriangle, FileText, X } from "lucide-react";

/**
 * DailyReminderPopup
 * Shows once per day on first login if the user (employee/manager) uploaded
 * zero policies yesterday. Dismissable once per day — tracked in the database.
 * Admins are excluded.
 */
export function DailyReminderPopup() {
  const { user } = useAuth();
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [yesterdayCount, setYesterdayCount] = useState(0);
  const [checking, setChecking] = useState(true);

  const checkAndShow = useCallback(async () => {
    if (!user || user.role === "admin") {
      setChecking(false);
      return;
    }

    // Defer to avoid the initial burst of reads during auth hydration
    await new Promise((r) => setTimeout(r, 3000));

    const today = new Date();
    const todayStr = today.toISOString().split("T")[0]; // YYYY-MM-DD

    const MAX_RETRIES = 2;
    for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
      try {
        // 1. Check if already dismissed today (use sessionStorage in mock mode)
        const dismissKey = `reminder_dismissed_${user.id}_${todayStr}`;
        if (sessionStorage.getItem(dismissKey)) {
          setChecking(false);
          return;
        }

        // 2. Check yesterday's policy uploads
        const yesterday = new Date(today);
        yesterday.setDate(yesterday.getDate() - 1);
        const dayBefore = new Date(yesterday);
        dayBefore.setHours(0, 0, 0, 0);
        const dayAfter = new Date(yesterday);
        dayAfter.setHours(23, 59, 59, 999);

        // Get policies created by this user yesterday
        const allPolicies = await policyService.getByAssignedTo(user.id);
        const yesterdayPolicies = allPolicies.filter((p) => {
          const createdAt: unknown = p.createdAt;
          if (!createdAt) return false;
          const raw = typeof createdAt === "object" && createdAt !== null && "toDate" in createdAt && typeof (createdAt as any).toDate === "function"
            ? (createdAt as any).toDate()
            : createdAt instanceof Date ? createdAt : new Date(createdAt as string | number);
          const date = raw instanceof Date ? raw : new Date(raw);
          if (isNaN(date.getTime())) return false;
          return date >= dayBefore && date <= dayAfter;
        });

        setYesterdayCount(yesterdayPolicies.length);

        if (yesterdayPolicies.length === 0) {
          setOpen(true);
        }
        break; // Success — exit retry loop
      } catch (error) {
        const msg = (error as Error)?.message || "";
        const isOffline =
          msg.includes("client is offline") || msg.includes("Failed to get document");
        if (isOffline && attempt < MAX_RETRIES) {
          await new Promise((r) => setTimeout(r, 1500 * 2 ** attempt));
          continue;
        }
        // Non-offline error or retries exhausted — fail quietly
      }
    }
    setChecking(false);
  }, [user]);

  useEffect(() => {
    checkAndShow();
  }, [checkAndShow]);

  const handleDismiss = async () => {
    setOpen(false);

    if (!user) return;

    const todayStr = new Date().toISOString().split("T")[0];

    try {
      // Record dismissal in sessionStorage (mock mode)
      const dismissKey = `reminder_dismissed_${user.id}_${todayStr}`;
      sessionStorage.setItem(dismissKey, "1");
    } catch {
      // Best-effort — dismissal state is tracked locally by the Dialog closing
    }
  };

  // Don't show for admin or while checking
  if (!user || user.role === "admin" || checking) return null;

  return (
    <Dialog open={open} onOpenChange={(v) => !v && handleDismiss()}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-amber-500">
            <AlertTriangle className="h-5 w-5" />
            DAILY POLICY REMINDER
          </DialogTitle>
          <DialogDescription className="text-muted-foreground">
            You did not upload any policies yesterday.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-4">
          <div className="flex items-center gap-3 p-4 rounded-lg bg-amber-500/10 border border-amber-500/20">
            <FileText className="h-8 w-8 text-amber-500 flex-shrink-0" />
            <div>
              <p className="text-sm font-medium text-foreground">
                NO POLICIES UPLOADED YESTERDAY
              </p>
              <p className="text-xs text-muted-foreground mt-1">
                Please ensure you upload any pending policy documents today.
                Regular uploads help keep our records current and accurate.
              </p>
            </div>
          </div>

          <p className="text-xs text-muted-foreground text-center">
            This reminder appears once per day and can be dismissed.
          </p>
        </div>

        <div className="flex justify-end gap-2">
          <Button variant="outline" size="sm" onClick={handleDismiss}>
            <X className="h-4 w-4 mr-1" />
            DISMISS
          </Button>
          <Button
            size="sm"
            onClick={() => {
              handleDismiss();
              router.push("/dashboard/policies");
            }}
          >
            <FileText className="h-4 w-4 mr-1" />
            GO TO POLICIES
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";
import {
  Menu,
  Search,
  Moon,
  Sun,
