"use client";

import { useState, useEffect } from "react";
import { usePathname } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";
import { ChevronLeft, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { useAuth } from "@/lib/context/auth-context";
import { useAppSettings } from "@/lib/context/app-settings-context";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { menuItems } from "./sidebar-config";
import { SidebarMenuItem } from "./sidebar-menu-item";

// ---- Props ----

interface SidebarProps {
  collapsed: boolean;
  onToggleCollapse: () => void;
  mobileOpen: boolean;
  onMobileClose: () => void;
}

// ---- Component ----

export function Sidebar({ collapsed, onToggleCollapse, mobileOpen, onMobileClose }: SidebarProps) {
  const { role } = useAuth();
  const { settings } = useAppSettings();
  const [expandedMenus, setExpandedMenus] = useState<string[]>([]);

  // Derive short name and subtitle from company_name setting
  const companyName = settings?.company_name || "BP & AF Insurance Broker Pvt. Ltd.";
  const nameParts = companyName.split(" ");
  const shortName = nameParts.length >= 2
    ? nameParts.slice(0, 2).map((w: string) => w.charAt(0).toUpperCase()).join("")
    : companyName.substring(0, 2).toUpperCase();
  const brandLine1 = nameParts.length > 2 ? nameParts.slice(0, Math.min(nameParts.length, 3)).join(" ") : companyName;
  const brandLine2 = nameParts.length > 3 ? nameParts.slice(3).join(" ") : "";

  const filteredItems = menuItems.filter((item) => role && item.roles.includes(role));

  // Auto-expand submenus whose children match the current path
  const pathname = usePathname();

  useEffect(() => {
    const toExpand: string[] = [];
    for (const item of filteredItems) {
      if (item.children?.some((child) => pathname === child.href || pathname.startsWith(child.href + "/"))) {
        toExpand.push(item.label);
      }
    }
    if (toExpand.length > 0) {
      setExpandedMenus((prev) => {
        const merged = new Set([...prev, ...toExpand]);
        return Array.from(merged);
      });
    }
  }, [pathname]); // eslint-disable-line react-hooks/exhaustive-deps

  const toggleSubmenu = (label: string) => {
    setExpandedMenus((prev) =>
      prev.includes(label) ? prev.filter((l) => l !== label) : [...prev, label]
    );
  };

  const sidebarContent = (
    <div className="flex flex-col h-full">
      {/* Logo */}
      <div className={cn("flex h-16 items-center border-b border-sidebar-border px-4 shrink-0", collapsed && "justify-center px-2")}>
        {collapsed ? (
          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-sidebar-accent">
            <span className="font-cabin text-sm font-bold text-sidebar-accent-foreground">{shortName}</span>
          </div>
        ) : (
          <div className="flex items-center gap-3">
            <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-sidebar-accent">
              <span className="font-cabin text-sm font-bold text-sidebar-accent-foreground">{shortName}</span>
            </div>
            <div className="min-w-0">
              <p className="truncate font-cabin text-sm font-bold uppercase tracking-wider text-sidebar-foreground">
                {brandLine1}
              </p>
              {brandLine2 && (
              <p className="truncate text-[10px] uppercase tracking-wider text-sidebar-foreground/70">
                {brandLine2}
              </p>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Menu */}
      <ScrollArea className="flex-1 py-2">
        <nav aria-label="Main navigation" className="px-2 space-y-1">
          {filteredItems.map((item) => (
            <SidebarMenuItem
              key={item.label}
              item={item}
              collapsed={collapsed}
              isExpanded={expandedMenus.includes(item.label)}
              onToggleSubmenu={toggleSubmenu}
              onMobileClose={onMobileClose}
              role={role}
            />
          ))}
        </nav>
      </ScrollArea>

      {/* Collapse toggle (desktop only) */}
      <div className="hidden border-t border-sidebar-border p-2 lg:block">
        <Button
          variant="ghost"
          size="sm"
          onClick={onToggleCollapse}
          className="w-full text-sidebar-foreground/70 hover:bg-sidebar-accent hover:text-sidebar-foreground"
        >
          <ChevronLeft className={cn("w-4 h-4 transition-transform", collapsed && "rotate-180")} />
          {!collapsed && <span className="ml-2 text-xs uppercase tracking-wider">Collapse</span>}
        </Button>
      </div>
    </div>
  );

  return (
    <>
      {/* Desktop sidebar */}
      <aside
        className={cn(
          "fixed bottom-0 left-0 top-0 z-30 hidden flex-col border-r border-sidebar-border bg-sidebar/95 text-sidebar-foreground backdrop-blur-xl shadow-[0_10px_26px_rgba(47,62,64,0.05)] transition-all duration-300 lg:flex",
          collapsed ? "w-15" : "w-62.5"
        )}
      >
        {sidebarContent}
      </aside>

      {/* Mobile overlay */}
      <AnimatePresence>
        {mobileOpen && (
          <>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 z-40 bg-black/45 backdrop-blur-sm lg:hidden"
              onClick={onMobileClose}
            />
            <motion.aside
              initial={{ x: -300 }}
              animate={{ x: 0 }}
              exit={{ x: -300 }}
              transition={{ type: "spring", damping: 25, stiffness: 300 }}
              className="fixed bottom-0 left-0 top-0 z-50 w-70 border-r border-sidebar-border bg-sidebar/95 text-sidebar-foreground backdrop-blur-xl lg:hidden"
            >
              {/* Close button */}
              <div className="absolute top-4 right-4">
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={onMobileClose}
                  className="text-sidebar-foreground/70 hover:bg-sidebar-accent hover:text-sidebar-foreground"
                  aria-label="Close navigation"
                >
                  <X className="w-4 h-4" />
                </Button>
              </div>
              {sidebarContent}
            </motion.aside>
          </>
        )}
      </AnimatePresence>
    </>
  );
}

"use client";

import { useState, useRef, useCallback } from "react";
import * as XLSX from "xlsx";
import { Upload, FileSpreadsheet, CheckCircle, AlertTriangle, Download, X, ChevronRight } from "lucide-react";
import { toast } from "sonner";

import { useAuth } from "@/lib/context/auth-context";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";

interface BulkUploadWizardProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  jobType: "gmc_members" | "fleet_vehicles";
  customerId: string;
  policyId?: string;
  onComplete?: () => void;
}

const STEPS = ["Upload", "Preview", "Validate", "Confirm"];

const GMC_TEMPLATE_HEADERS = ["Employee ID", "Name", "DOB", "Gender", "Mobile", "Email", "Department", "Designation"];
const FLEET_TEMPLATE_HEADERS = ["Registration Number", "Make", "Model", "Variant", "Fuel Type", "MFG Year", "Seating Capacity", "GVW", "IDV", "Vehicle Category"];

export function BulkUploadWizard({ open, onOpenChange, jobType, customerId, policyId, onComplete }: BulkUploadWizardProps) {
  const { session } = useAuth();
  const token = session?.access_token ?? "";

  const [step, setStep] = useState(0);
  const [file, setFile] = useState<File | null>(null);
  const [rows, setRows] = useState<any[]>([]);
  const [headers, setHeaders] = useState<string[]>([]);
  const [uploading, setUploading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [result, setResult] = useState<{
    total_rows: number;
    successful_rows: number;
    failed_rows: number;
    errors: Array<{ row: number; field: string; message: string }>;
    error_report_url?: string;
  } | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const templateHeaders = jobType === "gmc_members" ? GMC_TEMPLATE_HEADERS : FLEET_TEMPLATE_HEADERS;
  const apiEndpoint = jobType === "gmc_members"
    ? `/api/gmc/${customerId}/members/bulk`
    : `/api/fleet/${customerId}/vehicles/bulk`;

  const reset = () => {
    setStep(0);
    setFile(null);
    setRows([]);
    setHeaders([]);
    setUploading(false);
    setProgress(0);
    setResult(null);
  };

  const handleClose = () => {
    reset();
    onOpenChange(false);
  };

  const parseFile = useCallback((f: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: "array" });
        const sheet = workbook.Sheets[workbook.SheetNames[0]];
        const jsonData = XLSX.utils.sheet_to_json(sheet, { header: 1 }) as any[][];

        if (jsonData.length < 2) {
          toast.error("File must have at least a header row and one data row");
          return;
        }

        const hdrs = (jsonData[0] as string[]).map(h => String(h).trim());
        const dataRows = jsonData.slice(1).filter(row => row.some((cell: any) => cell !== null && cell !== undefined && cell !== ""));

        setHeaders(hdrs);
        setRows(dataRows);
        setFile(f);
        setStep(1);
      } catch {
        toast.error("Failed to parse file. Please use Excel (.xlsx) or CSV format.");
      }
    };
    reader.readAsArrayBuffer(f);
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const f = e.target.files?.[0];
    if (f) parseFile(f);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    const f = e.dataTransfer.files[0];
    if (f) parseFile(f);
  };

  const handleUpload = async () => {
    if (!file) return;
    setUploading(true);
    setProgress(20);

    try {
      const formData = new FormData();
      formData.append("file", file);
      if (policyId) formData.append("policy_id", policyId);

      setProgress(50);

      const res = await fetch(apiEndpoint, {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
        body: formData,
      });

      setProgress(90);

      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || "Upload failed");
      }

      const data = await res.json();
      setResult(data);
      setProgress(100);
      setStep(3);
    } catch (err: any) {
      toast.error(err.message || "Upload failed");
    } finally {
      setUploading(false);
    }
  };

  const downloadTemplate = () => {
    const ws = XLSX.utils.aoa_to_sheet([templateHeaders]);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Template");
    XLSX.writeFile(wb, `${jobType}_template.xlsx`);
  };

  const previewRows = rows.slice(0, 5);

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="font-heading uppercase tracking-wider">
            Bulk Upload — {jobType === "gmc_members" ? "GMC Members" : "Fleet Vehicles"}
          </DialogTitle>
        </DialogHeader>

        {/* Step Indicator */}
        <div className="flex items-center gap-2 mb-4">
          {STEPS.map((s, i) => (
            <div key={s} className="flex items-center gap-2">
              <div className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold transition-colors ${
                i < step ? "bg-green-500 text-white"
                : i === step ? "bg-primary text-primary-foreground"
                : "bg-muted text-muted-foreground"
              }`}>
                {i < step ? <CheckCircle className="w-4 h-4" /> : i + 1}
              </div>
              <span className={`text-xs font-medium ${i === step ? "text-foreground" : "text-muted-foreground"}`}>{s}</span>
              {i < STEPS.length - 1 && <ChevronRight className="w-3 h-3 text-muted-foreground" />}
            </div>
          ))}
        </div>

        {/* Step 0: Upload */}
        {step === 0 && (
          <div className="space-y-4">
            <div
              onDragOver={e => { e.preventDefault(); setDragOver(true); }}
              onDragLeave={() => setDragOver(false)}
              onDrop={handleDrop}
              onClick={() => fileInputRef.current?.click()}
              className={`border-2 border-dashed rounded-xl p-10 text-center cursor-pointer transition-colors ${
                dragOver ? "border-primary bg-primary/5" : "border-border hover:border-primary/50"
              }`}
            >
              <Upload className="w-10 h-10 mx-auto mb-3 text-muted-foreground" />
              <p className="font-medium text-sm">Drag & drop your file here, or click to browse</p>
              <p className="text-xs text-muted-foreground mt-1">Supports Excel (.xlsx) and CSV (.csv) — max 10MB</p>
              <input
                ref={fileInputRef}
                type="file"
                accept=".xlsx,.xls,.csv"
                onChange={handleFileChange}
                className="hidden"
              />
            </div>
            <div className="flex items-center justify-between">
              <p className="text-xs text-muted-foreground">Need a template?</p>
              <Button variant="outline" size="sm" onClick={downloadTemplate} className="gap-2">
                <Download className="w-4 h-4" /> Download Template
              </Button>
            </div>
          </div>
        )}

        {/* Step 1: Preview */}
        {step === 1 && (
          <div className="space-y-4">
            <div className="flex items-center gap-2">
              <FileSpreadsheet className="w-4 h-4 text-primary" />
              <span className="text-sm font-medium">{file?.name}</span>
              <Badge variant="secondary">{rows.length} rows</Badge>
            </div>
            <p className="text-xs text-muted-foreground">Preview of first 5 rows:</p>
            <div className="overflow-x-auto rounded-xl border border-border">
              <Table>
                <TableHeader>
                  <TableRow className="hover:bg-transparent">
                    {headers.map(h => (
                      <TableHead key={h} className="text-xs whitespace-nowrap">{h}</TableHead>
                    ))}
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {previewRows.map((row, i) => (
                    <TableRow key={i} className="border-border">
                      {headers.map((_, j) => (
                        <TableCell key={j} className="text-xs whitespace-nowrap">{String(row[j] ?? "")}</TableCell>
                      ))}
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
            <div className="flex justify-between">
              <Button variant="ghost" onClick={() => setStep(0)}>Back</Button>
              <Button onClick={() => setStep(2)} className="gap-2">
                Continue <ChevronRight className="w-4 h-4" />
              </Button>
            </div>
          </div>
        )}

        {/* Step 2: Validate & Upload */}
        {step === 2 && (
          <div className="space-y-4">
            <div className="bg-muted/30 rounded-xl p-4 space-y-2">
              <p className="text-sm font-medium">Ready to upload</p>
              <div className="flex gap-4 text-sm text-muted-foreground">
                <span>File: <strong className="text-foreground">{file?.name}</strong></span>
                <span>Rows: <strong className="text-foreground">{rows.length}</strong></span>
              </div>
            </div>

            {uploading && (
              <div className="space-y-2">
                <div className="flex justify-between text-xs text-muted-foreground">
                  <span>Processing...</span>
                  <span>{progress}%</span>
                </div>
                <Progress value={progress} className="h-2" />
              </div>
            )}

            <div className="flex justify-between">
              <Button variant="ghost" onClick={() => setStep(1)} disabled={uploading}>Back</Button>
              <Button onClick={handleUpload} disabled={uploading} className="gap-2">
                {uploading ? (
                  <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                ) : (
                  <Upload className="w-4 h-4" />
                )}
                {uploading ? "Uploading..." : "Upload & Process"}
              </Button>
            </div>
          </div>
        )}

        {/* Step 3: Confirm */}
        {step === 3 && result && (
          <div className="space-y-4">
            <div className="grid grid-cols-3 gap-3">
              <div className="bg-card border border-border rounded-xl p-4 text-center">
                <p className="text-2xl font-bold">{result.total_rows}</p>
                <p className="text-xs text-muted-foreground mt-1">Total Rows</p>
              </div>
              <div className="bg-green-500/10 border border-green-500/20 rounded-xl p-4 text-center">
                <p className="text-2xl font-bold text-green-400">{result.successful_rows}</p>
                <p className="text-xs text-muted-foreground mt-1">Successful</p>
              </div>
              <div className={`${result.failed_rows > 0 ? "bg-red-500/10 border-red-500/20" : "bg-card border-border"} border rounded-xl p-4 text-center`}>
                <p className={`text-2xl font-bold ${result.failed_rows > 0 ? "text-red-400" : "text-muted-foreground"}`}>{result.failed_rows}</p>
                <p className="text-xs text-muted-foreground mt-1">Failed</p>
              </div>
            </div>

            {result.errors && result.errors.length > 0 && (
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <p className="text-sm font-medium flex items-center gap-2">
                    <AlertTriangle className="w-4 h-4 text-amber-400" />
                    Errors ({result.errors.length})
                  </p>
                  {result.error_report_url && (
                    <Button variant="outline" size="sm" asChild className="gap-2">
                      <a href={result.error_report_url} download>
                        <Download className="w-4 h-4" /> Download Error Report
                      </a>
                    </Button>
                  )}
                </div>
                <div className="max-h-48 overflow-y-auto rounded-xl border border-border">
                  <Table>
                    <TableHeader>
                      <TableRow className="hover:bg-transparent">
                        <TableHead className="text-xs">Row</TableHead>
                        <TableHead className="text-xs">Field</TableHead>
                        <TableHead className="text-xs">Error</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {result.errors.slice(0, 50).map((err, i) => (
                        <TableRow key={i} className="border-border">
                          <TableCell className="text-xs">{err.row}</TableCell>
                          <TableCell className="text-xs font-mono">{err.field}</TableCell>
                          <TableCell className="text-xs text-red-400">{err.message}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              </div>
            )}

            {result.successful_rows > 0 && (
              <div className="flex items-center gap-2 text-green-400 text-sm">
                <CheckCircle className="w-4 h-4" />
                {result.successful_rows} records imported successfully
              </div>
            )}

            <div className="flex justify-between">
              <Button variant="ghost" onClick={reset}>Upload Another</Button>
              <Button onClick={() => { onComplete?.(); handleClose(); }}>Done</Button>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState } from "react";
import { toast } from "sonner";
import { CreditCard, Download, Mail, Loader2, CheckCircle } from "lucide-react";

import { useAuth } from "@/lib/context/auth-context";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";

interface ECardGenerateDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  customerId: string;
  memberId: string;
  memberName: string;
  memberEmail?: string;
}

export function ECardGenerateDialog({
  open,
  onOpenChange,
  customerId,
  memberId,
  memberName,
  memberEmail,
}: ECardGenerateDialogProps) {
  const { session } = useAuth();
  const token = session?.access_token ?? "";

  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<{ file_url: string } | null>(null);
  const [sendEmail, setSendEmail] = useState(false);
  const [emailAddress, setEmailAddress] = useState(memberEmail || "");

  const handleGenerate = async () => {
    setLoading(true);
    try {
      const res = await fetch(`/api/gmc/${customerId}/members/${memberId}/ecard`, {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({
          send_email: sendEmail,
          email: sendEmail ? emailAddress : undefined,
        }),
      });

      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || "Failed to generate e-card");
      }

      const data = await res.json();
      setResult(data);
      toast.success("E-Card generated successfully");
    } catch (err: any) {
      toast.error(err.message || "Failed to generate e-card");
    } finally {
      setLoading(false);
    }
  };

  const handleClose = () => {
    setResult(null);
    setSendEmail(false);
    setEmailAddress(memberEmail || "");
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="font-heading uppercase tracking-wider flex items-center gap-2">
            <CreditCard className="w-5 h-5 text-primary" />
            Generate E-Card
          </DialogTitle>
        </DialogHeader>

        {!result ? (
          <div className="space-y-4 py-2">
            <div className="bg-muted/30 rounded-xl p-4">
              <p className="text-sm font-medium">{memberName}</p>
              <p className="text-xs text-muted-foreground mt-0.5">Member ID: {memberId.slice(0, 8)}...</p>
            </div>

            <div className="space-y-3">
              <div className="flex items-center gap-3">
                <button
                  onClick={() => setSendEmail(!sendEmail)}
                  className={`w-5 h-5 rounded border-2 flex items-center justify-center transition-colors ${
                    sendEmail ? "bg-primary border-primary" : "border-border"
                  }`}
                >
                  {sendEmail && <CheckCircle className="w-3 h-3 text-white" />}
                </button>
                <Label className="cursor-pointer" onClick={() => setSendEmail(!sendEmail)}>
                  Email E-Card to member
                </Label>
              </div>

              {sendEmail && (
                <div className="space-y-1.5 ml-8">
                  <Label>Email Address</Label>
                  <Input
                    type="email"
                    value={emailAddress}
                    onChange={e => setEmailAddress(e.target.value)}
                    placeholder="member@company.com"
                  />
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="space-y-4 py-2">
            <div className="flex items-center gap-3 text-green-400">
              <CheckCircle className="w-6 h-6" />
              <div>
                <p className="font-medium text-sm">E-Card generated successfully</p>
                {sendEmail && emailAddress && (
                  <p className="text-xs text-muted-foreground mt-0.5">Sent to {emailAddress}</p>
                )}
              </div>
            </div>
            <Button asChild className="w-full gap-2">
              <a href={result.file_url} target="_blank" rel="noopener noreferrer">
                <Download className="w-4 h-4" /> Download PDF
              </a>
            </Button>
          </div>
        )}

        <DialogFooter>
          {!result ? (
            <>
              <Button variant="ghost" onClick={handleClose} disabled={loading}>Cancel</Button>
              <Button onClick={handleGenerate} disabled={loading} className="gap-2">
                {loading ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  <CreditCard className="w-4 h-4" />
                )}
                {loading ? "Generating..." : "Generate E-Card"}
              </Button>
            </>
          ) : (
            <Button variant="ghost" onClick={handleClose}>Close</Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState, useEffect, useRef } from "react";
import { toast } from "sonner";
import { Upload, Eye, Save, X, Building2 } from "lucide-react";
import useSWR from "swr";

import { useAuth } from "@/lib/context/auth-context";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

interface ECardTemplateFormProps {
  customerId: string;
}

interface ECardTemplate {
  company_name: string;
  tpa_name: string;
  tpa_contact: string;
  tpa_email: string;
  emergency_contact: string;
  logo_url?: string;
}

function ECardPreview({ template, logoPreview }: { template: ECardTemplate; logoPreview?: string }) {
  return (
    <div className="bg-gradient-to-br from-blue-900 to-blue-700 rounded-xl p-5 text-white w-full max-w-sm mx-auto shadow-xl">
      <div className="flex items-center justify-between mb-4">
        {(logoPreview || template.logo_url) ? (
          <img
            src={logoPreview || template.logo_url}
            alt="Company Logo"
            className="h-10 w-auto object-contain bg-white rounded p-1"
          />
        ) : (
          <div className="h-10 w-20 bg-white/20 rounded flex items-center justify-center text-xs">Logo</div>
        )}
        <div className="text-right">
          <p className="text-xs opacity-70">Group Mediclaim</p>
          <p className="text-xs font-bold">E-CARD</p>
        </div>
      </div>
      <div className="border-t border-white/20 pt-3 mb-3">
        <p className="text-sm font-bold">{template.company_name || "Company Name"}</p>
      </div>
      <div className="space-y-1.5 text-xs">
        <div className="flex justify-between">
          <span className="opacity-70">Member Name</span>
          <span className="font-medium">John Doe</span>
        </div>
        <div className="flex justify-between">
          <span className="opacity-70">Employee ID</span>
          <span className="font-medium">EMP001</span>
        </div>
        <div className="flex justify-between">
          <span className="opacity-70">DOB</span>
          <span className="font-medium">01 Jan 1990</span>
        </div>
        <div className="flex justify-between">
          <span className="opacity-70">Policy No.</span>
          <span className="font-medium">POL-2024-00001</span>
        </div>
      </div>
      {(template.tpa_name || template.tpa_contact) && (
        <div className="border-t border-white/20 mt-3 pt-3 space-y-1 text-xs">
          {template.tpa_name && (
            <div className="flex justify-between">
              <span className="opacity-70">TPA</span>
              <span className="font-medium">{template.tpa_name}</span>
            </div>
          )}
          {template.tpa_contact && (
            <div className="flex justify-between">
              <span className="opacity-70">TPA Contact</span>
              <span className="font-medium">{template.tpa_contact}</span>
            </div>
          )}
        </div>
      )}
      {template.emergency_contact && (
        <div className="border-t border-white/20 mt-3 pt-2 text-xs">
          <span className="opacity-70">Emergency: </span>
          <span className="font-bold">{template.emergency_contact}</span>
        </div>
      )}
    </div>
  );
}

export function ECardTemplateForm({ customerId }: ECardTemplateFormProps) {
  const { session } = useAuth();
  const token = session?.access_token ?? "";

  const [form, setForm] = useState<ECardTemplate>({
    company_name: "",
    tpa_name: "",
    tpa_contact: "",
    tpa_email: "",
    emergency_contact: "",
  });
  const [logoFile, setLogoFile] = useState<File | null>(null);
  const [logoPreview, setLogoPreview] = useState<string>("");
  const [saving, setSaving] = useState(false);
  const [showPreview, setShowPreview] = useState(false);
  const logoInputRef = useRef<HTMLInputElement>(null);

  const { data, mutate } = useSWR(
    token ? `ecard-template-${customerId}` : null,
    async () => {
      const res = await fetch(`/api/gmc/${customerId}/ecard-template`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) return null;
      return res.json();
    },
    { revalidateOnFocus: false }
  );

  useEffect(() => {
    if (data) {
      setForm({
        company_name: data.company_name || "",
        tpa_name: data.tpa_name || "",
        tpa_contact: data.tpa_contact || "",
        tpa_email: data.tpa_email || "",
        emergency_contact: data.emergency_contact || "",
        logo_url: data.logo_url || "",
      });
    }
  }, [data]);

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const f = e.target.files?.[0];
    if (!f) return;
    if (f.size > 2 * 1024 * 1024) {
      toast.error("Logo must be less than 2MB");
      return;
    }
    if (!["image/png", "image/jpeg"].includes(f.type)) {
      toast.error("Logo must be PNG or JPG");
      return;
    }
    setLogoFile(f);
    const reader = new FileReader();
    reader.onload = (ev) => setLogoPreview(ev.target?.result as string);
    reader.readAsDataURL(f);
  };

  const handleSave = async () => {
    if (!form.company_name.trim()) {
      toast.error("Company Name is required");
      return;
    }
    setSaving(true);
    try {
      let logoUrl = form.logo_url;

      // Upload logo if changed
      if (logoFile) {
        const fd = new FormData();
        fd.append("file", logoFile);
        fd.append("folder", "ecard-logos");
        const uploadRes = await fetch("/api/upload", {
          method: "POST",
          headers: { Authorization: `Bearer ${token}` },
          body: fd,
        });
        if (uploadRes.ok) {
          const uploadData = await uploadRes.json();
          logoUrl = uploadData.url || uploadData.file_url;
        }
      }

      const res = await fetch(`/api/gmc/${customerId}/ecard-template`, {
        method: "PUT",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({ ...form, logo_url: logoUrl }),
      });

      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || "Failed to save template");
      }

      toast.success("E-Card template saved");
      mutate();
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-heading font-bold uppercase tracking-wider">E-Card Template</h2>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" onClick={() => setShowPreview(!showPreview)} className="gap-2">
            <Eye className="w-4 h-4" /> {showPreview ? "Hide" : "Preview"}
          </Button>
          <Button size="sm" onClick={handleSave} disabled={saving} className="gap-2">
            {saving ? (
              <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
            ) : (
              <Save className="w-4 h-4" />
            )}
            Save Template
          </Button>
        </div>
      </div>

      <div className={`grid gap-6 ${showPreview ? "grid-cols-1 lg:grid-cols-2" : "grid-cols-1"}`}>
        {/* Form */}
        <div className="space-y-4">
          {/* Logo Upload */}
          <div className="space-y-2">
            <Label>Company Logo (PNG/JPG, max 2MB)</Label>
            <div className="flex items-center gap-3">
              {(logoPreview || form.logo_url) ? (
                <div className="relative">
                  <img
                    src={logoPreview || form.logo_url}
                    alt="Logo preview"
                    className="h-16 w-auto object-contain border border-border rounded-lg p-1 bg-white"
                  />
                  <button
                    onClick={() => { setLogoFile(null); setLogoPreview(""); setForm(f => ({ ...f, logo_url: "" })); }}
                    className="absolute -top-2 -right-2 w-5 h-5 bg-red-500 rounded-full flex items-center justify-center"
                  >
                    <X className="w-3 h-3 text-white" />
                  </button>
                </div>
              ) : (
                <div className="h-16 w-24 border-2 border-dashed border-border rounded-lg flex items-center justify-center">
                  <Building2 className="w-6 h-6 text-muted-foreground" />
                </div>
              )}
              <Button variant="outline" size="sm" onClick={() => logoInputRef.current?.click()} className="gap-2">
                <Upload className="w-4 h-4" /> Upload Logo
              </Button>
              <input ref={logoInputRef} type="file" accept="image/png,image/jpeg" onChange={handleLogoChange} className="hidden" />
            </div>
          </div>

          <div className="space-y-1.5">
            <Label>Company Name <span className="text-destructive">*</span></Label>
            <Input
              value={form.company_name}
              onChange={e => setForm(f => ({ ...f, company_name: e.target.value }))}
              placeholder="e.g. Acme Corporation"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label>TPA Name</Label>
              <Input
                value={form.tpa_name}
                onChange={e => setForm(f => ({ ...f, tpa_name: e.target.value }))}
                placeholder="e.g. Medi Assist"
              />
            </div>
            <div className="space-y-1.5">
              <Label>TPA Contact</Label>
              <Input
                value={form.tpa_contact}
                onChange={e => setForm(f => ({ ...f, tpa_contact: e.target.value }))}
                placeholder="1800-XXX-XXXX"
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <Label>TPA Email</Label>
            <Input
              type="email"
              value={form.tpa_email}
              onChange={e => setForm(f => ({ ...f, tpa_email: e.target.value }))}
              placeholder="claims@tpa.com"
            />
          </div>

          <div className="space-y-1.5">
            <Label>Emergency Contact</Label>
            <Input
              value={form.emergency_contact}
              onChange={e => setForm(f => ({ ...f, emergency_contact: e.target.value }))}
              placeholder="1800-XXX-XXXX"
            />
          </div>
        </div>

        {/* Preview */}
        {showPreview && (
          <div className="space-y-2">
            <p className="text-sm text-muted-foreground font-medium">Preview</p>
            <ECardPreview template={form} logoPreview={logoPreview} />
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import useSWR from "swr";
import { format } from "date-fns";
import { FileText, Plus, Minus } from "lucide-react";

import { useAuth } from "@/lib/context/auth-context";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";

interface EndorsementHistoryProps {
  customerId: string;
}

async function fetchEndorsements(customerId: string, token: string) {
  const res = await fetch(`/api/gmc/${customerId}/endorsements`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) return { data: [] };
  return res.json();
}

export function GMCEndorsementHistory({ customerId }: EndorsementHistoryProps) {
  const { session } = useAuth();
  const token = session?.access_token ?? "";

  const { data, isLoading } = useSWR(
    token ? `gmc-endorsements-${customerId}` : null,
    () => fetchEndorsements(customerId, token),
    { revalidateOnFocus: false }
  );

  const endorsements = data?.data ?? [];

  if (isLoading) {
    return (
      <div className="space-y-3">
        {[...Array(3)].map((_, i) => <Skeleton key={i} className="h-12 w-full" />)}
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <FileText className="w-4 h-4 text-primary" />
        <h3 className="font-heading font-bold uppercase tracking-wider text-sm">Endorsement History</h3>
        <Badge variant="secondary" className="text-xs">{endorsements.length}</Badge>
      </div>

      {endorsements.length === 0 ? (
        <div className="bg-card border border-border rounded-xl p-8 text-center">
          <FileText className="w-10 h-10 mx-auto mb-3 text-muted-foreground/40" />
          <p className="text-muted-foreground text-sm">No endorsements yet.</p>
        </div>
      ) : (
        <div className="bg-card border border-border rounded-xl overflow-hidden">
          <Table>
            <TableHeader>
              <TableRow className="border-border hover:bg-transparent">
                <TableHead className="text-xs uppercase tracking-wider font-heading">Endorsement #</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Type</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden md:table-cell">Date</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading">Member Name</TableHead>
                <TableHead className="text-xs uppercase tracking-wider font-heading hidden sm:table-cell">Employee ID</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {endorsements.map((e: any) => (
                <TableRow key={e.id} className="border-border hover:bg-muted/30">
                  <TableCell className="font-mono text-sm">{e.endorsement_number}</TableCell>
                  <TableCell>
                    <Badge
                      variant="outline"
                      className={`text-xs gap-1 ${
                        e.endorsement_type === "Addition"
                          ? "bg-green-500/10 text-green-400"
                          : "bg-red-500/10 text-red-400"
                      }`}
                    >
                      {e.endorsement_type === "Addition"
                        ? <Plus className="w-3 h-3" />
                        : <Minus className="w-3 h-3" />
                      }
                      {e.endorsement_type}
                    </Badge>
                  </TableCell>
                  <TableCell className="hidden md:table-cell text-sm text-muted-foreground">
                    {e.endorsement_date ? format(new Date(e.endorsement_date), "dd MMM yyyy") : "—"}
                  </TableCell>
                  <TableCell className="text-sm">
                    {e.member_details?.name || "—"}
                  </TableCell>
                  <TableCell className="hidden sm:table-cell font-mono text-sm text-muted-foreground">
                    {e.member_details?.employee_id || "—"}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { toast } from "sonner";
import { Loader2, Search } from "lucide-react";
import useSWR from "swr";

import { useAuth } from "@/lib/context/auth-context";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";

interface GMCClaimFormProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  customerId: string;
  onSuccess?: () => void;
}

export function GMCClaimForm({ open, onOpenChange, customerId, onSuccess }: GMCClaimFormProps) {
  const { session } = useAuth();
  const token = session?.access_token ?? "";

  const [form, setForm] = useState({
    policy_id: "",
    member_id: "",
    tpa: "",
    claim_amount: "",
    claim_type: "cashless",
    description: "",
    hospital_name: "",
  });
  const [memberSearch, setMemberSearch] = useState("");
  const [saving, setSaving] = useState(false);

  const { data: policiesData } = useSWR(
    token && open ? `policies-gmc-${customerId}` : null,
    async () => {
      const res = await fetch(`/api/policies?customer_id=${customerId}&limit=50`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) return [];
      const d = await res.json();
      return d.data ?? [];
    },
    { revalidateOnFocus: false }
  );

  const { data: membersData } = useSWR(
    token && open ? `gmc-members-search-${customerId}-${memberSearch}` : null,
    async () => {
      const res = await fetch(`/api/gmc/${customerId}/members?search=${memberSearch}&status=Active&limit=20`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) return [];
      const d = await res.json();
      return d.data ?? [];
    },
    { revalidateOnFocus: false }
  );

  const handleSave = async () => {
    if (!form.policy_id) { toast.error("Policy is required"); return; }
    if (!form.claim_amount || Number(form.claim_amount) <= 0) { toast.error("Valid claim amount is required"); return; }

    setSaving(true);
    try {
      const res = await fetch(`/api/gmc/${customerId}/claims`, {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({
          ...form,
          claim_amount: Number(form.claim_amount),
          member_id: form.member_id || undefined,
        }),
      });

      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || "Failed to register claim");
      }

      toast.success("GMC claim registered");
      onSuccess?.();
      onOpenChange(false);
      setForm({ policy_id: "", member_id: "", tpa: "", claim_amount: "", claim_type: "cashless", description: "", hospital_name: "" });
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-lg max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="font-heading uppercase tracking-wider">Register GMC Claim</DialogTitle>
        </DialogHeader>
        <div className="space-y-4 py-2">
          <div className="space-y-1.5">
            <Label>Policy <span className="text-destructive">*</span></Label>
            <Select value={form.policy_id} onValueChange={v => setForm(f => ({ ...f, policy_id: v }))}>
              <SelectTrigger><SelectValue placeholder="Select policy" /></SelectTrigger>
              <SelectContent>
                {(policiesData ?? []).map((p: any) => (
                  <SelectItem key={p.id} value={p.id}>{p.policy_number} · {p.policy_type}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-1.5">
            <Label>Member (optional)</Label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <Input
                value={memberSearch}
                onChange={e => setMemberSearch(e.target.value)}
                placeholder="Search member by name or employee ID..."
                className="pl-9"
              />
            </div>
            {membersData && membersData.length > 0 && memberSearch && (
              <div className="border border-border rounded-lg overflow-hidden max-h-40 overflow-y-auto">
                {membersData.map((m: any) => (
                  <button
                    key={m.id}
                    onClick={() => { setForm(f => ({ ...f, member_id: m.id })); setMemberSearch(`${m.name} (${m.employee_id})`); }}
                    className="w-full text-left px-3 py-2 text-sm hover:bg-muted/30 border-b border-border last:border-0"
                  >
                    <span className="font-medium">{m.name}</span>
                    <span className="text-muted-foreground ml-2">{m.employee_id}</span>
                  </button>
                ))}
              </div>
            )}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label>Claim Type</Label>
              <Select value={form.claim_type} onValueChange={v => setForm(f => ({ ...f, claim_type: v }))}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="cashless">Cashless</SelectItem>
                  <SelectItem value="reimbursement">Reimbursement</SelectItem>
                  <SelectItem value="emergency">Emergency</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label>Claim Amount (₹) <span className="text-destructive">*</span></Label>
              <Input
                type="number"
                value={form.claim_amount}
                onChange={e => setForm(f => ({ ...f, claim_amount: e.target.value }))}
                placeholder="0"
                min="0"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label>TPA</Label>
              <Input
                value={form.tpa}
                onChange={e => setForm(f => ({ ...f, tpa: e.target.value }))}
                placeholder="e.g. Medi Assist"
              />
            </div>
            <div className="space-y-1.5">
              <Label>Hospital Name</Label>
              <Input
                value={form.hospital_name}
                onChange={e => setForm(f => ({ ...f, hospital_name: e.target.value }))}
                placeholder="Hospital name"
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <Label>Description</Label>
            <Textarea
              value={form.description}
              onChange={e => setForm(f => ({ ...f, description: e.target.value }))}
              placeholder="Claim description / diagnosis..."
              rows={3}
            />
          </div>
        </div>
        <DialogFooter>
          <Button variant="ghost" onClick={() => onOpenChange(false)} disabled={saving}>Cancel</Button>
          <Button onClick={handleSave} disabled={saving} className="gap-2">
            {saving && <Loader2 className="w-4 h-4 animate-spin" />}
            Register Claim
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState, useRef } from "react";
import { Upload, X, FileText, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { kycService } from "@/lib/services/kyc.service";
import { useAuth } from "@/lib/context/auth-context";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

const DOCUMENT_TYPES = [
  { value: "aadhaar", label: "Aadhaar Card" },
  { value: "pan", label: "PAN Card" },
  { value: "gst", label: "GST Certificate" },
  { value: "address_proof", label: "Address Proof" },
  { value: "passport", label: "Passport" },
  { value: "driving_license", label: "Driving License" },
  { value: "voter_id", label: "Voter ID" },
  { value: "bank_statement", label: "Bank Statement" },
  { value: "company_registration", label: "Company Registration" },
  { value: "other", label: "Other" },
];

const ACCEPTED = ["application/pdf", "image/jpeg", "image/png", "image/webp"];
const MAX_SIZE = 10 * 1024 * 1024; // 10MB

interface KYCUploadDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  customerId: string;
  customerName: string;
  onSuccess: () => void;
}

export function KYCUploadDialog({
  open,
  onOpenChange,
  customerId,
  customerName,
  onSuccess,
}: KYCUploadDialogProps) {
  const { user } = useAuth();
  const fileRef = useRef<HTMLInputElement>(null);

  const [documentType, setDocumentType] = useState("");
  const [documentNumber, setDocumentNumber] = useState("");
  const [file, setFile] = useState<File | null>(null);
  const [uploading, setUploading] = useState(false);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const f = e.target.files?.[0];
    if (!f) return;
    if (!ACCEPTED.includes(f.type)) {
      toast.error("Only PDF, JPEG, PNG, or WEBP files are allowed");
      return;
    }
    if (f.size > MAX_SIZE) {
      toast.error("File must be under 10MB");
      return;
    }
    setFile(f);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const f = e.dataTransfer.files?.[0];
    if (!f) return;
    if (!ACCEPTED.includes(f.type)) {
      toast.error("Only PDF, JPEG, PNG, or WEBP files are allowed");
      return;
    }
    if (f.size > MAX_SIZE) {
      toast.error("File must be under 10MB");
      return;
    }
    setFile(f);
  };

  const handleSubmit = async () => {
    if (!user) return;
    if (!documentType) { toast.error("Select a document type"); return; }
    if (!file) { toast.error("Choose a file to upload"); return; }

    setUploading(true);
    try {
      await kycService.upload(customerId, file, documentType, documentNumber, user.id);
      toast.success("KYC document uploaded successfully");
      handleClose();
      onSuccess();
    } catch (err: any) {
      toast.error(err?.message || "Upload failed. Please try again.");
    } finally {
      setUploading(false);
    }
  };

  const handleClose = () => {
    setDocumentType("");
    setDocumentNumber("");
    setFile(null);
    if (fileRef.current) fileRef.current.value = "";
    onOpenChange(false);
  };

  const formatBytes = (bytes: number) => {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle className="font-cabin uppercase tracking-wider text-sm">
            Upload KYC Document
          </DialogTitle>
          <p className="text-xs text-muted-foreground">
            For <span className="text-foreground font-medium">{customerName}</span>
          </p>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Document Type */}
          <div className="space-y-1.5">
            <Label className="text-xs font-cabin uppercase tracking-wider text-muted-foreground">
              Document Type <span className="text-red-400">*</span>
            </Label>
            <Select value={documentType} onValueChange={setDocumentType}>
              <SelectTrigger>
                <SelectValue placeholder="Select document type" />
              </SelectTrigger>
              <SelectContent>
                {DOCUMENT_TYPES.map((dt) => (
                  <SelectItem key={dt.value} value={dt.value}>
                    {dt.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Document Number */}
          <div className="space-y-1.5">
            <Label className="text-xs font-cabin uppercase tracking-wider text-muted-foreground">
              Document Number
            </Label>
            <Input
              placeholder="e.g. XXXX XXXX XXXX (optional)"
              value={documentNumber}
              onChange={(e) => setDocumentNumber(e.target.value)}
            />
          </div>

          {/* File Drop Zone */}
          <div className="space-y-1.5">
            <Label className="text-xs font-cabin uppercase tracking-wider text-muted-foreground">
              File <span className="text-red-400">*</span>
            </Label>

            {file ? (
              /* File selected preview */
              <div className="flex items-center gap-3 p-3 rounded-lg border border-border bg-muted/30">
                <div className="w-9 h-9 rounded-lg bg-primary/10 flex items-center justify-center flex-shrink-0">
                  <FileText className="w-4 h-4 text-primary" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-foreground truncate">{file.name}</p>
                  <p className="text-xs text-muted-foreground">{formatBytes(file.size)}</p>
                </div>
                <button
                  onClick={() => {
                    setFile(null);
                    if (fileRef.current) fileRef.current.value = "";
                  }}
                  className="text-muted-foreground hover:text-foreground transition-colors"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>
            ) : (
              /* Drop zone */
              <div
                onDrop={handleDrop}
                onDragOver={(e) => e.preventDefault()}
                onClick={() => fileRef.current?.click()}
                className="border-2 border-dashed border-border rounded-lg p-6 text-center cursor-pointer hover:border-primary/50 hover:bg-primary/5 transition-colors"
              >
                <Upload className="w-7 h-7 text-muted-foreground mx-auto mb-2" />
                <p className="text-sm text-foreground font-medium">
                  Drop file here or <span className="text-primary">browse</span>
                </p>
                <p className="text-xs text-muted-foreground mt-1">
                  PDF, JPEG, PNG, WEBP · Max 10MB
                </p>
              </div>
            )}

            <input
              ref={fileRef}
              type="file"
              accept=".pdf,.jpg,.jpeg,.png,.webp"
              onChange={handleFileChange}
              className="hidden"
            />
          </div>
        </div>

        <DialogFooter className="gap-2">
          <Button variant="outline" onClick={handleClose} disabled={uploading}>
            Cancel
          </Button>
          <Button onClick={handleSubmit} disabled={uploading || !documentType || !file}>
            {uploading ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin mr-2" />
                Uploading…
              </>
            ) : (
              <>
                <Upload className="w-4 h-4 mr-2" />
                Upload
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

