                      ))}
                      {policy.motor_meta.paid_driver_cover && (
                        <Badge variant="outline" className="text-[8px] font-black uppercase tracking-tight border-emerald-500/30 text-emerald-500 bg-emerald-500/5">
                          Paid Driver
