              <MetaField label="Commission %" value={policy.finance_meta?.commission_receivable_percent ? `${policy.finance_meta.commission_receivable_percent}%` : "0%"} />
              <MetaField label="Net Payable" value={formatCurrency(policy.finance_meta?.commission_payable_final || 0)} />
            </div>
            <div className="p-3 rounded-xl bg-muted/30 border border-border/40 italic text-[10px] text-muted-foreground">
              Bank details are fetched from the associated Master Agent/Broker profile for automated NEFT clearing.
            </div>
          </CardContent>
        </Card>

        <Card className="border-border/60 shadow-sm">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-black uppercase tracking-widest flex items-center gap-2">
              <FileCheck className="h-4 w-4 text-emerald-500" /> System Audit
            </CardTitle>
          </CardHeader>
          <CardContent className="py-4 space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <MetaField label="Login Date" value={policy.login_date} />
              <MetaField label="Verification" value={policy.verification_confirmed ? "CERTIFIED" : "PENDING"} />
            </div>
            <div className="flex items-center gap-2 text-[9px] font-bold text-muted-foreground uppercase">
              <div className={cn("h-2 w-2 rounded-full", policy.verification_confirmed ? "bg-emerald-500" : "bg-amber-500")} />
              Policy state sync&apos;d with Supabase Registry
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

function MetaField({ label, value, mono, color, capitalize }: { label: string; value?: string | number; mono?: boolean; color?: string; capitalize?: boolean }) {
  return (
    <div>
      <p className="text-[9px] font-black uppercase text-muted-foreground tracking-wider mb-1 opacity-70">{label}</p>
      <p className={cn(
        "text-sm font-bold tracking-tight text-foreground/90",
        mono && "font-mono text-xs uppercase",
        capitalize && "capitalize",
        color
      )}>
        {value || "—"}
      </p>
    </div>
  );
}

"use client";

import { useState } from "react";
import { 
  Table, 
  TableBody, 
  TableCell, 
  TableHead, 
  TableHeader, 
  TableRow 
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { 
  DropdownMenu, 
  DropdownMenuCheckboxItem, 
  DropdownMenuContent, 
  DropdownMenuTrigger 
} from "@/components/ui/dropdown-menu";
import { Settings2, Eye, Mail, Trash2, Loader2, AlertCircle, Zap } from "lucide-react";
import { formatCurrency, formatCurrencyLabel } from "@/lib/utils";
import { Policy } from "@/lib/types";
import { useRouter } from "next/navigation";
import { toast } from "sonner";

interface PolicyTableProps {
  policies: Policy[];
  onDelete: (policy: Policy) => void;
  onSendEmail: (policy: Policy) => void;
  sendingReminderId?: string | null;
  deletingPolicyId?: string | null;
  isAdmin?: boolean;
}

export function PolicyTable({ 
  policies, 
  onDelete, 
  onSendEmail, 
  sendingReminderId, 
  deletingPolicyId,
  isAdmin 
}: PolicyTableProps) {
  const router = useRouter();
  const [columnVisibility, setColumnVisibility] = useState({
    policyNumber: true,
    type: true,
    customer: true,
    insurer: true,
    premium: true,
    expiry: true,
    status: true,
    vehicleNo: false,
    assignedTo: false,
    netPremium: false,
    tpPremium: false,
    gst: false,
    commission: false,
  });

  const STATUS_COLORS: Record<string, string> = {
    active: "bg-green-500/20 text-green-400 border-green-500/30",
    expired: "bg-red-500/20 text-red-400 border-red-500/30",
    cancelled: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30",
    archived: "bg-muted-foreground/20 text-muted-foreground border-muted-foreground/30",
  };

  return (
    <div className="space-y-4">
        <div className="flex items-center gap-2">
          {isAdmin && (
            <Button 
              variant="outline" 
              size="sm" 
              className="h-8 border-dashed bg-primary/5 text-primary hover:bg-primary/10 border-primary/20"
              onClick={async () => {
                const { commissionService } = await import("@/lib/services/commission.service");
                toast.promise(commissionService.bulkCalculate("SYSTEM", "Policy Table Trigger"), {
                   loading: "Calculating commissions...",
                   success: (res) => `Calculated ${res.created} new commissions.`,
                   error: "Failed to run engine."
