          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="outline" size="sm" className="h-8 border-dashed bg-muted/20">
                <Settings2 className="mr-2 h-4 w-4" /> Columns
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-48">
              {Object.entries(columnVisibility).map(([key, value]) => (
                <DropdownMenuCheckboxItem
                  key={key}
                  checked={value}
                  onCheckedChange={(checked) => 
                    setColumnVisibility(prev => ({ ...prev, [key]: checked }))
                  }
                  className="capitalize"
                >
                  {key.replace(/([A-Z])/g, ' $1')}
                </DropdownMenuCheckboxItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>
        </div>

      <div className="overflow-hidden rounded-[1.75rem] border border-border bg-card/90 shadow-[0_10px_22px_rgba(47,62,64,0.04)]">
        <Table>
          <TableHeader>
            <TableRow className="bg-muted/55 hover:bg-transparent">
              {columnVisibility.policyNumber && <TableHead>Policy #</TableHead>}
              {columnVisibility.type && <TableHead>Type</TableHead>}
              {columnVisibility.customer && <TableHead>Customer</TableHead>}
              {columnVisibility.insurer && <TableHead>Insurer</TableHead>}
              {columnVisibility.vehicleNo && <TableHead>Vehicle No</TableHead>}
              {columnVisibility.assignedTo && <TableHead>Assigned To</TableHead>}
              {columnVisibility.premium && <TableHead className="text-right">Premium</TableHead>}
              {columnVisibility.expiry && <TableHead>Expiry</TableHead>}
              {columnVisibility.status && <TableHead>Status</TableHead>}
              {columnVisibility.netPremium && <TableHead className="text-right">Net Premium</TableHead>}
              {columnVisibility.tpPremium && <TableHead className="text-right">TP</TableHead>}
              {columnVisibility.gst && <TableHead className="text-right">GST</TableHead>}
              {columnVisibility.commission && <TableHead className="text-right">Comm %</TableHead>}
              <TableHead className="w-16" />
            </TableRow>
          </TableHeader>
          <TableBody>
            {policies.length === 0 ? (
              <TableRow>
                <TableCell colSpan={10} className="h-32 text-center text-muted-foreground italic">
                  No policies found.
                </TableCell>
              </TableRow>
            ) : (
              policies.map((policy) => (
                <TableRow
                  key={policy.id}
                  className="cursor-pointer transition-colors hover:bg-muted/45"
                  onClick={() => router.push(`/dashboard/policies/${policy.id}`)}
                >
                  {columnVisibility.policyNumber && (
                    <TableCell className="font-mono text-sm font-medium">
                      {policy.policy_number}
                    </TableCell>
                  )}
                  {columnVisibility.type && (
                    <TableCell>
                      <Badge variant="outline" className="text-[10px] font-black uppercase tracking-wider">
                        {policy.policy_type}
                      </Badge>
                    </TableCell>
                  )}
                  {columnVisibility.customer && (
                    <TableCell className="text-sm font-bold">
                      {policy.customer_name}
                    </TableCell>
                  )}
                  {columnVisibility.insurer && (
                    <TableCell className="text-sm text-muted-foreground">
                      {policy.insurer_name || "—"}
                    </TableCell>
                  )}
                  {columnVisibility.vehicleNo && (
                    <TableCell className="text-xs font-mono">
                      {policy.motor_meta?.registration_number || policy.vehicle_number || "—"}
                    </TableCell>
                  )}
                  {columnVisibility.assignedTo && (
                    <TableCell className="text-xs text-muted-foreground">
                      {policy.assigned_to_name || "—"}
                    </TableCell>
                  )}
                  {columnVisibility.premium && (
                    <TableCell className="text-right font-mono text-sm" aria-label={formatCurrencyLabel(policy.premium_amount)}>
                      {formatCurrency(policy.premium_amount)}
                    </TableCell>
                  )}
                  {columnVisibility.expiry && (
                    <TableCell>
                      <span className="text-xs text-muted-foreground whitespace-nowrap">
                        {new Date(policy.end_date).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })}
                      </span>
                    </TableCell>
                  )}
                  {columnVisibility.status && (
                    <TableCell>
                      <Badge className={`text-[9px] font-black uppercase tracking-widest ${STATUS_COLORS[policy.status] || ""}`}>
                        {policy.status}
                      </Badge>
                    </TableCell>
                  )}
                  {columnVisibility.netPremium && (
                    <TableCell className="text-right font-mono text-xs opacity-70">
                      {formatCurrency(policy.motor_meta?.net_premium || 0)}
                    </TableCell>
                  )}
                  {columnVisibility.tpPremium && (
                    <TableCell className="text-right font-mono text-xs opacity-70">
                      {formatCurrency(policy.motor_meta?.tp_premium || 0)}
                    </TableCell>
                  )}
                  {columnVisibility.gst && (
                    <TableCell className="text-right font-mono text-xs opacity-70">
                      {formatCurrency(policy.motor_meta?.gst_amount || 0)}
                    </TableCell>
                  )}
                  {columnVisibility.commission && (
                    <TableCell className="text-right font-mono text-xs text-primary font-bold">
                      {policy.finance_meta?.commission_receivable_percent || 0}%
                    </TableCell>
                  )}
                  <TableCell onClick={(e) => e.stopPropagation()}>
                    <div className="flex items-center justify-end gap-1">
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-8 w-8 text-amber-500 hover:text-amber-400 hover:bg-amber-500/10"
                        title="Send Email Reminder"
                        disabled={sendingReminderId === policy.id}
                        onClick={() => onSendEmail(policy)}
                      >
                        {sendingReminderId === policy.id ? (
                          <Loader2 className="h-4 w-4 animate-spin" />
                        ) : (
                          <Mail className="h-4 w-4" />
                        )}
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-8 w-8"
                        onClick={() => router.push(`/dashboard/policies/${policy.id}`)}
                      >
                        <Eye className="h-4 w-4" />
                      </Button>
                      {isAdmin && (
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 text-rose-400 hover:text-rose-300 hover:bg-rose-500/10"
                          disabled={deletingPolicyId === policy.id}
                          onClick={() => onDelete(policy)}
                        >
                          {deletingPolicyId === policy.id ? (
                            <Loader2 className="h-4 w-4 animate-spin" />
                          ) : (
                            <Trash2 className="h-4 w-4" />
                          )}
                        </Button>
                      )}
                    </div>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { 
  FileCheck, 
  AlertTriangle, 
  Calendar, 
  ShieldAlert, 
  Plus,
  RefreshCw
} from "lucide-react";
import { ValidityRegistry } from "@/lib/types";
import { validityService } from "@/lib/services/validity.service";
import { format } from "date-fns";
import { cn } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";

interface ValidityRegistryProps {
  vehicleNumber: string;
  policyId: string;
}

const DOC_TYPES: Record<string, string> = {
  permit_state: "State Permit",
  permit_national: "National Permit",
  fitness: "Fitness Certificate",
  puc: "PUC / Emission",
  rc: "RC Validity",
  tax_state: "State Tax",
  tax_national: "National Tax"
};

export function ValidityRegistryView({ vehicleNumber, policyId }: ValidityRegistryProps) {
  const [data, setData] = useState<ValidityRegistry[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  async function load() {
    if (!vehicleNumber) return;
    setIsLoading(true);
    try {
      const records = await validityService.getByVehicle(vehicleNumber);
      setData(records);
    } catch (err) {
      console.error("Failed to load validity records", err);
    } finally {
      setIsLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, [vehicleNumber]);

  if (!vehicleNumber) return null;

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground flex items-center gap-2">
          <ShieldAlert className="h-3.5 w-3.5 text-primary" />
          Vehicle Compliance Registry
        </h4>
        <Button 
          variant="ghost" 
          size="sm" 
          className="h-7 text-[9px] font-bold uppercase tracking-wider px-2"
          onClick={() => toast.info("Validity update wizard coming in Phase 4")}
        >
          <RefreshCw className="h-3 w-3 mr-1" /> Force Sync
        </Button>
      </div>

      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
        {isLoading ? (
          Array.from({ length: 3 }).map((_, i) => (
            <Skeleton key={i} className="h-24 w-full rounded-2xl" />
          ))
        ) : data.length > 0 ? (
          data.map((record) => (
            <ValidityCard key={record.id} record={record} />
          ))
        ) : (
          <div className="sm:col-span-3 p-8 rounded-2xl border border-dashed border-border/60 flex flex-col items-center justify-center text-center space-y-2">
            <AlertTriangle className="h-8 w-8 text-muted-foreground opacity-20" />
            <p className="text-xs font-bold text-muted-foreground uppercase tracking-widest leading-tight">
              No compliance records found <br />
              <span className="opacity-50">Syncing with RTO Dashboard...</span>
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

function ValidityCard({ record }: { record: ValidityRegistry }) {
  const isExpired = new Date(record.expiry_date) < new Date();
  const isExpiringSoon = !isExpired && 
    (new Date(record.expiry_date).getTime() - Date.now()) < (30 * 24 * 60 * 60 * 1000);

  return (
    <div className={cn(
      "relative p-4 rounded-2xl border transition-all duration-300",
      isExpired 
        ? "bg-rose-500/5 border-rose-500/30 shadow-sm" 
        : isExpiringSoon 
          ? "bg-amber-500/5 border-amber-500/30" 
          : "bg-muted/20 border-border/60 hover:border-primary/30"
    )}>
      <div className="flex items-center justify-between mb-3">
        <Badge variant="outline" className={cn(
          "text-[8px] font-black uppercase px-1.5 py-0 h-4 border",
          isExpired 
            ? "border-rose-500 text-rose-500 bg-rose-500/10" 
            : isExpiringSoon 
              ? "border-amber-500 text-amber-500 bg-amber-500/10" 
              : "border-emerald-500 text-emerald-500 bg-emerald-500/10"
        )}>
          {isExpired ? "EXPIRED" : isExpiringSoon ? "EXPIRING" : "VALID"}
        </Badge>
        <span className="text-[10px] font-black font-mono opacity-40 uppercase tracking-tighter">
          {record.vehicle_number}
        </span>
      </div>

      <div className="space-y-1">
        <p className="text-sm font-black tracking-tight text-foreground/90">
          {DOC_TYPES[record.document_type] || record.document_type}
        </p>
        <div className="flex items-center gap-1.5 text-muted-foreground">
          <Calendar className="h-3 w-3" />
          <span className="text-[10px] font-bold uppercase tabular-nums">
            {format(new Date(record.expiry_date), "dd MMM yyyy")}
          </span>
        </div>
      </div>

      {isExpired && (
        <div className="absolute top-2 right-2">
          <AlertTriangle className="h-4 w-4 text-rose-500 animate-pulse" />
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { toast } from "sonner";
import Papa from "papaparse";
import {
  FileSpreadsheet,
  Upload,
  CheckCircle2,
  XCircle,
  ArrowRight,
  ArrowLeft,
  Loader2,
  AlertTriangle,
  Download,
} from "lucide-react";

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

import { csvPolicyRowSchema, type CSVPolicyRow } from "@/lib/validations/policy";
import { policyService } from "@/lib/services/policy.service";
import { customerService } from "@/lib/services/customer.service";
import { auditLogService } from "@/lib/services/audit-log.service";


import { useAuth } from "@/lib/context/auth-context";
import { invalidatePolicies } from "@/lib/hooks/use-policies";

// ---- Types ----

interface BulkImportProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess?: () => void;
}

interface ParsedRow {
  raw: Record<string, string>;
  mapped: Partial<CSVPolicyRow>;
  errors: string[];
  status: "pending" | "success" | "error";
}

const REQUIRED_FIELDS = [
  { key: "policy_number", label: "Policy Number" },
  { key: "policy_type", label: "Policy Type" },
  { key: "customer_name", label: "Customer Name" },
  { key: "start_date", label: "Start Date" },
  { key: "end_date", label: "End Date" },
  { key: "premium_amount", label: "Premium Amount" },
] as const;

const OPTIONAL_FIELDS = [
  { key: "customer_phone", label: "Customer Phone" },
  { key: "customer_email", label: "Customer Email" },
  { key: "sum_insured", label: "Sum Insured" },
  { key: "insurer_name", label: "Insurer Name" },
  { key: "payment_frequency", label: "Payment Frequency" },
] as const;

const ALL_FIELDS = [...REQUIRED_FIELDS, ...OPTIONAL_FIELDS];

// ---- Component ----

export function BulkImport({ open, onOpenChange, onSuccess }: BulkImportProps) {
  const { user } = useAuth();
  const [step, setStep] = useState(1); // 1: Upload, 2: Map, 3: Preview, 4: Import
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [rawData, setRawData] = useState<Record<string, string>[]>([]);
  const [columnMap, setColumnMap] = useState<Record<string, string>>({});
  const [parsedRows, setParsedRows] = useState<ParsedRow[]>([]);
  const [importProgress, setImportProgress] = useState(0);
  const [importResults, setImportResults] = useState<{
    success: number;
    failed: number;
    total: number;
  } | null>(null);
  const [isImporting, setIsImporting] = useState(false);

  // ---- Step 1: Parse CSV ----
  const handleFileUpload = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.name.endsWith(".csv") && file.type !== "text/csv") {
      toast.error("Only CSV files are supported");
      return;
    }

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.errors.length > 0) {
          toast.error(`CSV parse errors: ${results.errors[0].message}`);
          return;
        }

        const headers = results.meta.fields || [];
        const data = results.data as Record<string, string>[];

        if (data.length === 0) {
          toast.error("CSV file is empty");
          return;
        }

        setCsvHeaders(headers);
        setRawData(data);

        // Auto-map columns by fuzzy matching with common aliases
        const ALIASES: Record<string, string[]> = {
          policy_type: ["type", "policy type", "policytype", "insurance type"],
          customer_name: ["customer", "name", "customer name", "insured", "insured name", "proposer"],
          start_date: ["start date", "startdate", "from", "from date", "inception", "inception date", "policy start"],
          end_date: ["end date", "enddate", "to", "to date", "expiry", "expiry date", "policy end"],
          premium_amount: ["premium", "premium amount", "amount", "net premium", "gross premium", "total premium"],
          policy_number: ["policy number", "policy no", "policyno", "policy #"],
          customer_phone: ["phone", "mobile", "contact", "customer phone"],
          customer_email: ["email", "customer email", "mail"],
          sum_insured: ["sum insured", "suminsured", "si", "cover amount", "idv"],
          insurer_name: ["insurer", "insurer name", "insurance company", "company"],
          payment_frequency: ["frequency", "payment frequency", "payment mode"],
        };

        const autoMap: Record<string, string> = {};
        for (const field of ALL_FIELDS) {
          const norm = (s: string) => s.toLowerCase().replace(/[_\s\-#.]/g, "");
          const aliases = ALIASES[field.key] || [];

          const match = headers.find((h) => {
            const hNorm = norm(h);
            // Exact normalized match
            if (hNorm === norm(field.key)) return true;
            // Alias match (normalized)
            if (aliases.some((a) => hNorm === norm(a))) return true;
            // Substring match
            if (h.toLowerCase().includes(field.key.replace(/_/g, " ").toLowerCase())) return true;
            return false;
          });
          if (match) autoMap[field.key] = match;
        }
        setColumnMap(autoMap);

        toast.success(`Loaded ${data.length} rows from CSV`);
        setStep(2);
      },
      error: (err) => {
        toast.error(`Failed to parse CSV: ${err.message}`);
      },
    });
  }, []);

  // ---- Step 2: Validate Mapping ----
  function handleMappingDone() {
    // Validate required fields are mapped
    const missing = REQUIRED_FIELDS.filter((f) => !columnMap[f.key]);
    if (missing.length > 0) {
      toast.error(`Missing required mappings: ${missing.map((m) => m.label).join(", ")}`);
      return;
    }

    // Map + validate rows
    const rows: ParsedRow[] = rawData.map((raw) => {
      const mapped: Partial<CSVPolicyRow> = {};
      for (const [fieldKey, csvHeader] of Object.entries(columnMap)) {
        if (csvHeader && raw[csvHeader] !== undefined) {
          // Trim whitespace from CSV values to avoid validation failures
          const val = typeof raw[csvHeader] === "string" ? raw[csvHeader].trim() : raw[csvHeader];
          (mapped as any)[fieldKey] = val;
        }
      }

      // Validate with Zod
      const result = csvPolicyRowSchema.safeParse(mapped);
      const errors: string[] = [];
      if (!result.success) {
        for (const issue of result.error.issues) {
          errors.push(`${issue.path.join(".")}: ${issue.message}`);
        }
      }

      return { raw, mapped, errors, status: "pending" as const };
    });

    setParsedRows(rows);
    setStep(3);
  }

  // ---- Step 4: Import ----
  async function handleImport() {
    if (!user) return;
    setIsImporting(true);
    setStep(4);
    setImportProgress(0);

    const validRows = parsedRows.filter((r) => r.errors.length === 0);
    let success = 0;
    let failed = 0;

    for (let i = 0; i < validRows.length; i++) {
      const row = validRows[i];
      try {
        // Find or create customer
        let customerId = "";
        let customerName = row.mapped.customer_name || "";

        if (row.mapped.customer_phone) {
          const existing = await customerService.phoneExists(row.mapped.customer_phone);
          if (existing) {
            const results = await customerService.searchByNameOrPhone(row.mapped.customer_phone);
            if (results.length > 0) {
              customerId = results[0].id!;
              customerName = results[0].name;
            }
          }
        }

        if (!customerId && customerName) {
          // Create new customer
          const result = await customerService.createCustomer({
            name: customerName,
            phone: row.mapped.customer_phone || "",
            email: row.mapped.customer_email || "",
          } as any, user.uid);
          customerId = result.id;
        }

        // Create policy
        await policyService.createPolicy({
          policy_number: row.mapped.policy_number || undefined,
          policy_type: row.mapped.policy_type as any,
          customer_id: customerId,
          customer_name: customerName,
          start_date: new Date(row.mapped.start_date!),
          end_date: new Date(row.mapped.end_date!),
          premium_amount: parseFloat(row.mapped.premium_amount!) || 0,
          sum_insured: row.mapped.sum_insured ? parseFloat(row.mapped.sum_insured) : undefined,
          insurer_name: row.mapped.insurer_name || undefined,
          payment_frequency: row.mapped.payment_frequency as any || undefined,
          status: "active",
          assigned_to: user.uid,
          assigned_to_name: user.name || "",
          lockedForEmployee: false,
          verification_confirmed: false,
          branch_id: user.branch_id || undefined,
          created_by: user.uid,
        } as any);

        row.status = "success";
        success++;
      } catch (err: any) {
        row.status = "error";
        row.errors.push(err.message || "Import failed");
        failed++;
      }

      setImportProgress(Math.round(((i + 1) / validRows.length) * 100));
    }

    setImportResults({ success, failed, total: validRows.length });
    setIsImporting(false);
    invalidatePolicies();

    // Audit log: bulk import
    if (user && success > 0) {
      auditLogService.logAction(
        user.uid, user.name || "", "bulk_import", "policies",
        `Bulk imported ${success} policies (${failed} failed) from CSV`
      ).catch(() => {});
    }

    if (success > 0) {
      toast.success(`Imported ${success} policies successfully`);
    }
    if (failed > 0) {
      toast.error(`${failed} policies failed to import`);
    }
  }

  // ---- Template Download ----
  function downloadTemplate() {
    const headers = ALL_FIELDS.map((f) => f.key).join(",");
    const sampleRow = [
      "MOT-2025-0001",
      "motor",
      "John Doe",
      "9876543210",
      "john@example.com",
      "2025-01-01",
      "2026-01-01",
      "15000",
      "500000",
      "Bajaj Allianz",
      "annual",
    ].join(",");

    const csv = `${headers}\n${sampleRow}`;
    const blob = new Blob([csv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "policy_import_template.csv";
    a.click();
    URL.revokeObjectURL(url);
  }

  function handleClose() {
    setStep(1);
    setCsvHeaders([]);
    setRawData([]);
    setColumnMap({});
    setParsedRows([]);
    setImportProgress(0);
    setImportResults(null);
    onOpenChange(false);
    if (importResults && importResults.success > 0) {
      onSuccess?.();
    }
  }

  const validCount = parsedRows.filter((r) => r.errors.length === 0).length;
  const errorCount = parsedRows.filter((r) => r.errors.length > 0).length;

  const STEP_LABELS = ["Upload", "Map", "Preview", "Import"];

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-4xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-lg">
            <FileSpreadsheet className="h-5 w-5 text-primary" />
            Bulk CSV Import
          </DialogTitle>
          <DialogDescription className="sr-only">
            Import policies from a CSV file
          </DialogDescription>
        </DialogHeader>

        {/* Step Progress Bar */}
        <div className="flex items-center justify-between px-2">
          {STEP_LABELS.map((label, i) => {
            const s = i + 1;
            const isActive = s === step;
            const isDone = s < step;
            return (
              <div key={s} className="flex flex-1 items-center">
                <div className="flex flex-col items-center gap-1">
                  <div
                    className={`flex h-8 w-8 items-center justify-center rounded-full text-xs font-bold transition-all ${
                      isDone
                        ? "bg-green-500 text-white"
                        : isActive
                          ? "bg-primary text-primary-foreground ring-2 ring-primary/30 ring-offset-2 ring-offset-background"
                          : "bg-muted text-muted-foreground"
                    }`}
                  >
                    {isDone ? <CheckCircle2 className="h-4 w-4" /> : s}
                  </div>
                  <span className={`text-[10px] font-medium ${isActive ? "text-primary" : "text-muted-foreground"}`}>
                    {label}
                  </span>
                </div>
                {s < 4 && (
                  <div className={`mx-2 h-0.5 flex-1 rounded transition-colors ${isDone ? "bg-green-500" : "bg-muted"}`} />
                )}
              </div>
            );
          })}
        </div>

        <AnimatePresence mode="wait">
          {/* Step 1: Upload */}
          {step === 1 && (
            <motion.div
              key="step1"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="space-y-5 py-2"
            >
              <div
                className="group flex cursor-pointer flex-col items-center gap-4 rounded-xl border-2 border-dashed border-muted-foreground/30 bg-muted/30 p-12 transition-all hover:border-primary/50 hover:bg-primary/5"
                onClick={() => document.getElementById("csv-upload")?.click()}
              >
                <div className="rounded-full bg-primary/10 p-4 transition-colors group-hover:bg-primary/20">
                  <Upload className="h-8 w-8 text-primary" />
                </div>
                <div className="text-center">
                  <p className="text-sm font-semibold">
                    Click to upload CSV file
                  </p>
                  <p className="mt-1 text-xs text-muted-foreground">
                    Supported format: .csv with headers
                  </p>
                </div>
                <input
                  id="csv-upload"
                  type="file"
                  accept=".csv"
                  className="hidden"
                  aria-label="Upload CSV file"
                  onChange={handleFileUpload}
                />
              </div>

              <div className="flex items-center justify-center">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={downloadTemplate}
                  className="gap-2"
                >
                  <Download className="h-4 w-4" />
                  Download Sample Template
                </Button>
              </div>
            </motion.div>
          )}

          {/* Step 2: Map Columns */}
          {step === 2 && (
            <motion.div
              key="step2"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
            >
              <div className="mb-3 rounded-lg border bg-muted/30 px-4 py-3">
                <p className="text-sm text-muted-foreground">
                  Map your CSV columns to the policy fields below. Required fields are marked with <span className="font-semibold text-red-400">*</span>
                </p>
              </div>

              <div className="max-h-[50vh] overflow-y-auto rounded-lg border p-3">
                <div className="space-y-1.5">
                  {/* Required Fields */}
                  <p className="mb-2 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                    Required Fields
                  </p>
                  {REQUIRED_FIELDS.map((field) => {
                    const isMapped = !!columnMap[field.key];
                    return (
                      <div
                        key={field.key}
                        className={`flex items-center gap-4 rounded-lg border px-4 py-2.5 transition-colors ${
                          isMapped
                            ? "border-green-500/30 bg-green-500/5"
                            : "border-red-500/30 bg-red-500/5"
                        }`}
                      >
                        <div className="flex w-44 shrink-0 items-center gap-2">
                          {isMapped ? (
                            <CheckCircle2 className="h-3.5 w-3.5 text-green-500" />
                          ) : (
                            <XCircle className="h-3.5 w-3.5 text-red-400" />
                          )}
                          <span className="text-sm font-medium">
                            {field.label}
                            <span className="ml-0.5 text-red-400">*</span>
                          </span>
                        </div>
                        <Select
                          value={columnMap[field.key] || ""}
                          onValueChange={(v) =>
                            setColumnMap((prev) => ({
                              ...prev,
                              [field.key]: v === "__none__" ? "" : v,
                            }))
                          }
                        >
                          <SelectTrigger className="flex-1">
                            <SelectValue placeholder="— Select CSV column —" />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="__none__">— Skip —</SelectItem>
                            {csvHeaders.map((h) => (
                              <SelectItem key={h} value={h}>
                                {h}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>
                    );
                  })}

                  {/* Optional Fields */}
                  <p className="mb-2 mt-4 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                    Optional Fields
                  </p>
                  {OPTIONAL_FIELDS.map((field) => {
                    const isMapped = !!columnMap[field.key];
                    return (
                      <div
                        key={field.key}
                        className={`flex items-center gap-4 rounded-lg border px-4 py-2.5 transition-colors ${
                          isMapped ? "border-border bg-muted/20" : "border-transparent bg-transparent"
                        }`}
                      >
                        <div className="flex w-44 shrink-0 items-center gap-2">
                          {isMapped ? (
                            <CheckCircle2 className="h-3.5 w-3.5 text-muted-foreground" />
                          ) : (
                            <div className="h-3.5 w-3.5" />
                          )}
                          <span className="text-sm text-muted-foreground">
                            {field.label}
                          </span>
                        </div>
                        <Select
                          value={columnMap[field.key] || ""}
                          onValueChange={(v) =>
                            setColumnMap((prev) => ({
                              ...prev,
                              [field.key]: v === "__none__" ? "" : v,
                            }))
                          }
                        >
                          <SelectTrigger className="flex-1">
                            <SelectValue placeholder="— Skip —" />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="__none__">— Skip —</SelectItem>
                            {csvHeaders.map((h) => (
                              <SelectItem key={h} value={h}>
                                {h}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>
                    );
                  })}
                </div>
              </div>

              <div className="flex items-center justify-between border-t pt-4 mt-4">
                <Button variant="ghost" onClick={() => setStep(1)}>
                  <ArrowLeft className="mr-1.5 h-4 w-4" /> Back
                </Button>
                <Button onClick={handleMappingDone}>
                  Preview Data <ArrowRight className="ml-1.5 h-4 w-4" />
                </Button>
              </div>
            </motion.div>
          )}

          {/* Step 3: Preview */}
          {step === 3 && (
            <motion.div
              key="step3"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
            >
              {/* Stats bar */}
              <div className="mb-3 flex items-center gap-3 rounded-lg border bg-muted/30 px-4 py-3">
                <div className="flex items-center gap-2">
                  <div className="h-2.5 w-2.5 rounded-full bg-green-500" />
                  <span className="text-sm font-medium">{validCount} valid</span>
                </div>
                {errorCount > 0 && (
                  <div className="flex items-center gap-2">
                    <div className="h-2.5 w-2.5 rounded-full bg-red-500" />
                    <span className="text-sm font-medium">{errorCount} errors</span>
                  </div>
                )}
                <span className="ml-auto text-xs text-muted-foreground">
                  {parsedRows.length} total rows &middot; Only valid rows will be imported
                </span>
              </div>

              {/* Error alert when all rows fail */}
              {errorCount > 0 && validCount === 0 && (
                <div className="mb-3 rounded-lg border border-red-500/30 bg-red-500/10 p-4">
                  <div className="flex gap-3">
                    <AlertTriangle className="mt-0.5 h-5 w-5 shrink-0 text-red-400" />
                    <div className="space-y-2">
                      <p className="text-sm font-semibold text-red-300">
                        All rows failed validation
                      </p>
                      <p className="text-xs leading-relaxed text-red-400/80">
                        Go back and check that your CSV columns are correctly mapped.
                        Required: Policy Type, Customer Name, Start Date, End Date, Premium Amount.
                      </p>
                      {parsedRows[0]?.errors.length > 0 && (
                        <div className="rounded-md bg-red-950/50 p-2.5">
                          <p className="mb-1 text-[10px] font-semibold uppercase tracking-wider text-red-400/60">Row 1 errors</p>
                          {parsedRows[0].errors.map((err, i) => (
                            <p key={i} className="text-xs text-red-300">&bull; {err}</p>
                          ))}
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              )}

              {/* Data table */}
              <div className="max-h-[50vh] overflow-y-auto rounded-lg border">
                <Table>
                  <TableHeader>
                    <TableRow className="bg-muted/50">
                      <TableHead className="sticky top-0 z-10 w-10 bg-muted/90 text-center">#</TableHead>
                      <TableHead className="sticky top-0 z-10 bg-muted/90">Customer</TableHead>
                      <TableHead className="sticky top-0 z-10 bg-muted/90">Type</TableHead>
                      <TableHead className="sticky top-0 z-10 bg-muted/90 text-right">Premium</TableHead>
                      <TableHead className="sticky top-0 z-10 bg-muted/90">Period</TableHead>
                      <TableHead className="sticky top-0 z-10 w-28 bg-muted/90 text-center">Status</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {parsedRows.slice(0, 50).map((row, idx) => {
                      const hasError = row.errors.length > 0;
                      return (
                        <TableRow
                          key={idx}
                          className={hasError ? "bg-red-500/5" : ""}
                        >
                          <TableCell className="text-center text-xs text-muted-foreground">
                            {idx + 1}
                          </TableCell>
                          <TableCell className="font-medium">
                            {row.mapped.customer_name || "—"}
                          </TableCell>
                          <TableCell>
                            <Badge variant="outline" className="text-xs font-normal capitalize">
                              {row.mapped.policy_type || "—"}
                            </Badge>
                          </TableCell>
                          <TableCell className="text-right tabular-nums">
                            {row.mapped.premium_amount
                              ? `₹${Number(row.mapped.premium_amount).toLocaleString("en-IN")}`
                              : "—"}
                          </TableCell>
                          <TableCell className="text-xs text-muted-foreground">
                            {row.mapped.start_date || "—"} → {row.mapped.end_date || "—"}
                          </TableCell>
                          <TableCell className="text-center">
                            {!hasError ? (
                              <Badge className="bg-green-500/15 text-green-500 hover:bg-green-500/15">
                                <CheckCircle2 className="mr-1 h-3 w-3" /> Valid
                              </Badge>
                            ) : (
                              <div className="group relative inline-block">
                                <Badge className="cursor-help bg-red-500/15 text-red-400 hover:bg-red-500/15">
                                  <XCircle className="mr-1 h-3 w-3" /> Error
                                </Badge>
                                <div className="absolute bottom-full right-0 z-50 mb-2 hidden w-64 rounded-lg border border-red-500/30 bg-popover p-3 shadow-lg group-hover:block">
                                  <p className="mb-1.5 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">
                                    Validation Errors
                                  </p>
                                  {row.errors.map((err, i) => (
                                    <p key={i} className="text-xs text-red-400">
                                      &bull; {err}
                                    </p>
                                  ))}
                                </div>
                              </div>
                            )}
                          </TableCell>
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
                {parsedRows.length > 50 && (
                  <div className="border-t px-4 py-2 text-center text-xs text-muted-foreground">
                    Showing first 50 of {parsedRows.length} rows
                  </div>
                )}
              </div>

              <div className="flex items-center justify-between border-t pt-4 mt-4">
                <Button variant="ghost" onClick={() => setStep(2)}>
                  <ArrowLeft className="mr-1.5 h-4 w-4" /> Back
                </Button>
                <Button
                  onClick={handleImport}
                  disabled={validCount === 0}
                  size="lg"
                >
                  Import {validCount} {validCount === 1 ? "Policy" : "Policies"}
                  <ArrowRight className="ml-1.5 h-4 w-4" />
                </Button>
              </div>
            </motion.div>
          )}

          {/* Step 4: Importing / Results */}
          {step === 4 && (
            <motion.div
              key="step4"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="py-4"
            >
              {isImporting ? (
                <div className="space-y-6 py-8 text-center" role="status" aria-live="polite">
                  <Loader2 className="mx-auto h-12 w-12 animate-spin text-primary" />
                  <div>
                    <p className="text-base font-semibold">Importing policies...</p>
                    <p className="mt-1 text-sm text-muted-foreground">
                      Please don&apos;t close this window
                    </p>
                  </div>
                  <div className="mx-auto max-w-sm space-y-2">
                    <Progress value={importProgress} className="h-2" />
                    <p className="text-sm font-medium text-muted-foreground">{importProgress}%</p>
                  </div>
                </div>
              ) : importResults ? (
                <div className="space-y-6 py-8 text-center">
                  <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-green-500/10">
                    <CheckCircle2 className="h-10 w-10 text-green-500" />
                  </div>
                  <div>
                    <p className="text-xl font-bold">Import Complete</p>
                    <p className="mt-1 text-sm text-muted-foreground">
                      Your policies have been imported successfully
                    </p>
                  </div>
                  <div className="flex items-center justify-center gap-4">
                    <div className="rounded-lg border bg-green-500/10 px-5 py-3 text-center">
                      <p className="text-2xl font-bold text-green-500">{importResults.success}</p>
                      <p className="text-xs text-muted-foreground">Imported</p>
                    </div>
                    {importResults.failed > 0 && (
                      <div className="rounded-lg border bg-red-500/10 px-5 py-3 text-center">
                        <p className="text-2xl font-bold text-red-400">{importResults.failed}</p>
                        <p className="text-xs text-muted-foreground">Failed</p>
                      </div>
                    )}
                  </div>
                  <Button onClick={handleClose} size="lg">
                    Done
                  </Button>
                </div>
              ) : null}
            </motion.div>
          )}
        </AnimatePresence>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useFormContext, useWatch } from "react-hook-form";
import { Calendar, IndianRupee, Megaphone, UserCheck, MapPin, Car, ShieldCheck } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import {
  POLICY_TYPES,
  PAYMENT_FREQUENCIES,
  SUPPORTED_INSURERS,
  parsePolicyTypes,
  type PolicyFormData,
} from "@/lib/validations/policy";
import { getPolicySpecificFields } from "@/lib/validations/policy-fields-config";
import { useAppSettings } from "@/lib/context/app-settings-context";
import { Separator } from "@/components/ui/separator";
import type { Campaign, User } from "@/lib/types";

interface PolicyDetailsGridProps {
  isEdit: boolean;
  campaigns?: Campaign[];
  users?: User[];
  showAssignTo?: boolean;
}

export function PolicyDetailsGrid({ isEdit, campaigns, users, showAssignTo }: PolicyDetailsGridProps) {
  const { control, setValue } = useFormContext<PolicyFormData>();
  const { settings } = useAppSettings();
  const policyTypes = parsePolicyTypes(settings.policy_types);

  // Watch the policy_type to dynamically render specific fields
  const selectedPolicyType = useWatch({ control, name: "policy_type" });
  const specificFields = getPolicySpecificFields(selectedPolicyType);

  return (
    <>
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
        {/* Policy Number */}
        <FormField
          control={control}
          name="policy_number"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Policy Number</FormLabel>
              <FormControl>
                <Input
                  {...field}
                  placeholder="Auto-generated if blank"
                  disabled={isEdit}
                />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        {/* Policy Type */}
        <FormField
          control={control}
          name="policy_type"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Policy Type *</FormLabel>
              <Select onValueChange={field.onChange} value={field.value}>
                <FormControl>
                  <SelectTrigger>
                    <SelectValue placeholder="Select type" />
                  </SelectTrigger>
                </FormControl>
                <SelectContent position="popper" className="max-h-60">
                  {policyTypes.map((t) => (
                    <SelectItem key={t.value} value={t.value}>
                      {t.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <FormMessage />
            </FormItem>
          )}
        />

        {/* Start Date */}
        <FormField
          control={control}
          name="start_date"
          render={({ field }) => (
            <FormItem>
              <FormLabel className="flex items-center gap-1.5">
                <Calendar className="h-3.5 w-3.5" /> Start Date *
              </FormLabel>
              <FormControl>
                <Input type="date" {...field} />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        {/* End Date */}
        <FormField
          control={control}
          name="end_date"
          render={({ field }) => (
            <FormItem>
              <FormLabel className="flex items-center gap-1.5">
                <Calendar className="h-3.5 w-3.5" /> End Date *
              </FormLabel>
              <FormControl>
                <Input type="date" {...field} />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        {/* Premium Amount */}
        <FormField
          control={control}
          name="premium_amount"
          render={({ field }) => (
            <FormItem>
              <FormLabel className="flex items-center gap-1.5">
                <IndianRupee className="h-3.5 w-3.5" /> Premium *
              </FormLabel>
              <FormControl>
                <Input
                  type="number"
                  step="0.01"
                  {...field}
                  onChange={(e) =>
                    field.onChange(parseFloat(e.target.value) || 0)
                  }
                />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        {/* Sum Insured */}
        <FormField
          control={control}
          name="sum_insured"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Sum Insured</FormLabel>
              <FormControl>
                <Input
                  type="number"
                  step="0.01"
                  {...field}
                  value={field.value || ""}
                  onChange={(e) =>
                    field.onChange(parseFloat(e.target.value) || 0)
                  }
                />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        {/* Insurer */}
        <FormField
          control={control}
          name="insurer_name"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Insurer</FormLabel>
              <Select onValueChange={field.onChange} value={field.value || ""}>
                <FormControl>
                  <SelectTrigger>
                    <SelectValue placeholder="Select insurer" />
                  </SelectTrigger>
                </FormControl>
                <SelectContent position="popper" className="max-h-60">
                  {SUPPORTED_INSURERS.map((ins) => (
                    <SelectItem key={ins} value={ins}>
                      {ins}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <FormMessage />
            </FormItem>
          )}
        />

        {/* Payment Frequency */}
        <FormField
          control={control}
          name="payment_frequency"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Payment Frequency</FormLabel>
              <Select onValueChange={field.onChange} value={field.value || ""}>
                <FormControl>
                  <SelectTrigger>
                    <SelectValue placeholder="Select frequency" />
                  </SelectTrigger>
                </FormControl>
                <SelectContent position="popper" className="max-h-60">
                  {PAYMENT_FREQUENCIES.map((f) => (
                    <SelectItem key={f.value} value={f.value}>
                      {f.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <FormMessage />
            </FormItem>
          )}
        />

        {/* Campaign (optional) */}
        {campaigns && campaigns.length > 0 && (
          <FormField
            control={control}
            name="campaign_id"
            render={({ field }) => (
              <FormItem>
                <FormLabel className="flex items-center gap-1.5">
                  <Megaphone className="h-3.5 w-3.5" /> Campaign
                  <span className="text-muted-foreground text-xs">(optional)</span>
                </FormLabel>
                <Select
                  onValueChange={(v) => field.onChange(v === "__none__" ? "" : v)}
                  value={field.value || "__none__"}
                >
                  <FormControl>
                    <SelectTrigger>
                      <SelectValue placeholder="Link to campaign" />
                    </SelectTrigger>
                  </FormControl>
                  <SelectContent position="popper" className="max-h-60">
                    <SelectItem value="__none__">No Campaign</SelectItem>
                    {campaigns
                      .filter((c) => c.status === "active" || c.status === "draft")
                      .map((c) => (
                        <SelectItem key={c.id} value={c.id}>
                          {c.name} ({c.channel})
                        </SelectItem>
                      ))}
                  </SelectContent>
                </Select>
                <FormMessage />
              </FormItem>
            )}
          />
        )}

        {/* Assign To (Admin/Manager only) */}
        {showAssignTo && users && users.length > 0 && (
          <FormField
            control={control}
            name="assigned_to"
            render={({ field }) => (
              <FormItem>
                <FormLabel className="flex items-center gap-1.5">
                  <UserCheck className="h-3.5 w-3.5" /> Assign To *
                </FormLabel>
                <Select
                  onValueChange={(v) => {
                    field.onChange(v);
                    const u = users.find((usr) => usr.id === v);
                    if (u) {
                      setValue("assigned_to_name", u.name);
                    }
                  }}
                  value={field.value || ""}
                >
                  <FormControl>
                    <SelectTrigger>
                      <SelectValue placeholder="Select employee" />
                    </SelectTrigger>
                  </FormControl>
                  <SelectContent position="popper" className="max-h-60">
                    {users.map((u) => (
                      <SelectItem key={u.id} value={u.id}>
                        {u.name} ({u.role})
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <FormMessage />
              </FormItem>
            )}
          />
        )}
      </div>

      {/* Policy-type-specific fields — rendered dynamically */}
      {specificFields.length > 0 && (
        <>
          <Separator />
          <div className="space-y-1">
            <h4 className="flex items-center gap-1.5 text-sm font-medium">
              <ShieldCheck className="h-3.5 w-3.5 text-primary" />
              {selectedPolicyType === "motor" ? "Motor Details" :
               selectedPolicyType === "health" ? "Health Details" :
               selectedPolicyType === "life" ? "Life Insurance Details" :
               selectedPolicyType === "fire" ? "Fire Insurance Details" :
               selectedPolicyType === "marine" ? "Marine Details" :
               selectedPolicyType === "burglary" ? "Burglary Insurance Details" :
               selectedPolicyType === "liability" ? "Liability Details" :
               selectedPolicyType === "workmen_compensation" ? "Workmen Compensation Details" :
               selectedPolicyType === "car_ear" ? "CAR / EAR Details" :
               selectedPolicyType === "surety_bond" ? "Surety Bond Details" :
               "Additional Details"}
            </h4>
          </div>
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            {specificFields.map((fieldDef) => (
              <FormField
                key={fieldDef.name}
                control={control}
                name={fieldDef.name as keyof PolicyFormData}
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>{fieldDef.label}</FormLabel>
                    {fieldDef.type === "select" && fieldDef.options ? (
                      <Select
                        onValueChange={field.onChange}
                        value={(field.value as string) || ""}
                      >
                        <FormControl>
                          <SelectTrigger>
                            <SelectValue placeholder={fieldDef.placeholder || "Select..."} />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent position="popper" className="max-h-60">
                          {fieldDef.options.map((opt) => (
                            <SelectItem key={opt.value} value={opt.value}>
                              {opt.label}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    ) : (
                      <FormControl>
                        <Input
                          {...field}
                          value={(field.value as string) || ""}
                          placeholder={fieldDef.placeholder || ""}
                        />
                      </FormControl>
                    )}
                    <FormMessage />
                  </FormItem>
                )}
              />
            ))}
          </div>
        </>
      )}

      {/* Remark */}
      <FormField
        control={control}
        name="remark"
        render={({ field }) => (
          <FormItem>
            <FormLabel>Remark</FormLabel>
            <FormControl>
              <Textarea
                {...field}
                placeholder="Optional notes about this policy..."
                rows={2}
              />
            </FormControl>
            <FormMessage />
          </FormItem>
        )}
      />
    </>
  );
}

"use client";

import { useState, useCallback, useEffect } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { AnimatePresence } from "framer-motion";
import { toast } from "sonner";
import {
  FileUp,
  PenLine,
  Loader2,
  Shield,
} from "lucide-react";

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Form } from "@/components/ui/form";

import { VerificationPopup } from "@/components/policies/verification-popup";
import { PolicyUploadZone } from "@/components/policies/policy-upload-zone";
import { CustomerSearchField } from "@/components/policies/customer-search-field";
import { PolicyDetailsGrid } from "@/components/policies/policy-details-grid";
import {
  policySchema,
  POLICY_TYPES,
  type PolicyFormData,
} from "@/lib/validations/policy";
import { policyService } from "@/lib/services/policy.service";
import { customerService } from "@/lib/services/customer.service";
import { auditLogService } from "@/lib/services/audit-log.service";
import { documentService } from "@/lib/services/document.service";
import { extractPolicyDataFromFile, isSupportedFileType, type ExtractedPolicyData } from "@/lib/helpers/pdf-extractor";
import { compressFile } from "@/lib/helpers/compress-file";
import { getMaxFileSize } from "@/lib/helpers/storage";
import { getAccessToken } from "@/lib/services/auth.service";
import { useAuth } from "@/lib/context/auth-context";
import { invalidatePolicies } from "@/lib/hooks/use-policies";
import { invalidateCustomers } from "@/lib/hooks/use-customers";
import { invalidateDocuments } from "@/lib/hooks/use-documents";
import { useCampaigns } from "@/lib/hooks/use-campaigns";
import { useActiveUsers } from "@/lib/hooks/use-settings";
import { friendlyError } from "@/lib/helpers/friendly-error";
import type { Policy, Customer, UserRole } from "@/lib/types";

// ---- Props ----

interface PolicyFormProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  editPolicy?: Policy | null;
  onSuccess?: () => void;
}

// ---- Component ----

export function PolicyForm({
  open,
  onOpenChange,
  editPolicy,
  onSuccess,
}: PolicyFormProps) {
  const { user, session } = useAuth();
  const isEmployee = user?.role === "employee";
  const isAdminOrManager = user?.role === "admin" || user?.role === "manager";
  const isEdit = !!editPolicy;

  // Fetch campaigns and users for dropdowns (admin/manager only)
  const { data: campaigns } = useCampaigns();
  const { data: activeUsers } = useActiveUsers();

  // State
  const [mode, setMode] = useState<"manual" | "upload">(isEmployee ? "upload" : "manual");
  const [uploadedFile, setUploadedFile] = useState<File | null>(null);
  const [extractedData, setExtractedData] = useState<ExtractedPolicyData | null>(null);
  const [isExtracting, setIsExtracting] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showVerification, setShowVerification] = useState(false);
  const [customerSearchQuery, setCustomerSearchQuery] = useState("");
  const [customerResults, setCustomerResults] = useState<Customer[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [fuzzyMatches, setFuzzyMatches] = useState<Customer[]>([]);
  const [isAutoCreating, setIsAutoCreating] = useState(false);
  const [autoCreatedCustomer, setAutoCreatedCustomer] = useState<Customer | null>(null);

  // Form
  const form = useForm<PolicyFormData>({
    resolver: zodResolver(policySchema),
    defaultValues: {
      policy_number: "",
      policy_type: undefined,
      customer_id: "",
      customer_name: "",
      start_date: "",
      end_date: "",
      premium_amount: 0,
      sum_insured: 0,
      insurer_name: "",
      payment_frequency: undefined,
      assigned_to: user?.uid || "",
      assigned_to_name: user?.name || "",
      remark: "",
      branch_id: user?.branch_id || "",
      campaign_id: "",
      motor_category: undefined,
      vehicle_number: "",
      vehicle_type: undefined,
      health_policy_type: undefined,
      plan_name: "",
      life_plan_type: undefined,
      risk_location: "",
      marine_policy_type: undefined,
      liability_type: undefined,
      policy_tenure: "",
      project_name: "",
      project_location: "",
      principal: "",
      surety_bond_type: undefined,
    },
  });

  // Pre-fill for edit mode
  useEffect(() => {
    if (editPolicy && open) {
      form.reset({
        policy_number: editPolicy.policy_number || "",
        policy_type: editPolicy.policy_type,
        customer_id: editPolicy.customer_id,
        customer_name: editPolicy.customer_name,
        start_date: editPolicy.start_date
          ? new Date(editPolicy.start_date).toISOString().split("T")[0]
          : "",
        end_date: editPolicy.end_date
          ? new Date(editPolicy.end_date).toISOString().split("T")[0]
          : "",
        premium_amount: editPolicy.premium_amount,
        sum_insured: editPolicy.sum_insured || 0,
        insurer_name: editPolicy.insurer_name || "",
        payment_frequency: editPolicy.payment_frequency,
        assigned_to: editPolicy.assigned_to,
        assigned_to_name: editPolicy.assigned_to_name || "",
        remark: editPolicy.remark || "",
        branch_id: editPolicy.branch_id || "",
        campaign_id: editPolicy.campaign_id || "",
        motor_category: editPolicy.motor_category || undefined,
        vehicle_number: editPolicy.vehicle_number || "",
        vehicle_type: editPolicy.vehicle_type as PolicyFormData["vehicle_type"] || undefined,
        health_policy_type: editPolicy.health_policy_type || undefined,
        plan_name: editPolicy.plan_name || "",
        life_plan_type: editPolicy.life_plan_type || undefined,
        risk_location: editPolicy.risk_location || "",
        marine_policy_type: editPolicy.marine_policy_type || undefined,
        liability_type: editPolicy.liability_type || undefined,
        policy_tenure: editPolicy.policy_tenure || "",
        project_name: editPolicy.project_name || "",
        project_location: editPolicy.project_location || "",
        principal: editPolicy.principal || "",
        surety_bond_type: editPolicy.surety_bond_type || undefined,
      });
    }
  }, [editPolicy, open, form]);

  // Reset on close
  useEffect(() => {
    if (!open) {
      form.reset();
      setUploadedFile(null);
      setExtractedData(null);
      setSelectedCustomer(null);
      setCustomerResults([]);
      setFuzzyMatches([]);
      setUploadProgress(0);
      setAutoCreatedCustomer(null);
      setIsAutoCreating(false);
    }
  }, [open, form]);

  // ---- Document Extraction ----
  const handleFileUpload = useCallback(
    async (file: File) => {
      if (!isSupportedFileType(file.type)) {
        toast.error("Unsupported file type. Use PDF, JPG, PNG, WEBP, BMP, or TIFF.");
        return;
      }
      if (file.size > getMaxFileSize()) {
        const maxMB = getMaxFileSize() / (1024 * 1024);
        toast.error(`File too large. Maximum ${maxMB}MB`);
        return;
      }

      setIsExtracting(true);

      try {
        // Compress file and extract data in parallel (they are independent)
        const [compressed, data] = await Promise.all([
          compressFile(file),
          extractPolicyDataFromFile(file),
        ]);
        setUploadedFile(compressed);
        setExtractedData(data);

        // Auto-fill form
        if (data.policyNumber) {
          form.setValue("policy_number", data.policyNumber);
        }
        if (data.policyType) {
          const typeMatch = POLICY_TYPES.find(
            (t) => t.value === data.policyType
          );
          if (typeMatch) {
            form.setValue("policy_type", typeMatch.value as PolicyFormData["policy_type"]);
          }
        }
        if (data.premium) {
          form.setValue("premium_amount", data.premium);
        }
        if (data.startDate) {
          form.setValue("start_date", data.startDate);
        }
        if (data.endDate) {
          form.setValue("end_date", data.endDate);
        }
        if (data.insurerName) {
          form.setValue("insurer_name", data.insurerName);
        }
        if (data.sumInsured) {
          form.setValue("sum_insured", data.sumInsured);
        }
        if (data.customerName) {
          form.setValue("customer_name", data.customerName);
        }
        if (data.paymentFrequency) {
          form.setValue("payment_frequency", data.paymentFrequency as PolicyFormData["payment_frequency"]);
        }

        // Auto-fill policy-type-specific fields
        if (data.motorCategory) form.setValue("motor_category", data.motorCategory as PolicyFormData["motor_category"]);
        if (data.vehicleNumber) form.setValue("vehicle_number", data.vehicleNumber);
        if (data.vehicleType) form.setValue("vehicle_type", data.vehicleType as PolicyFormData["vehicle_type"]);
        if (data.healthPolicyType) form.setValue("health_policy_type", data.healthPolicyType as PolicyFormData["health_policy_type"]);
        if (data.planName) form.setValue("plan_name", data.planName);
        if (data.lifePlanType) form.setValue("life_plan_type", data.lifePlanType as PolicyFormData["life_plan_type"]);
        if (data.riskLocation) form.setValue("risk_location", data.riskLocation);
        if (data.marinePolicyType) form.setValue("marine_policy_type", data.marinePolicyType as PolicyFormData["marine_policy_type"]);
        if (data.liabilityType) form.setValue("liability_type", data.liabilityType as PolicyFormData["liability_type"]);
        if (data.policyTenure) form.setValue("policy_tenure", data.policyTenure);
        if (data.projectName) form.setValue("project_name", data.projectName);
        if (data.projectLocation) form.setValue("project_location", data.projectLocation);
        if (data.principal) form.setValue("principal", data.principal);
        if (data.suretyBondType) form.setValue("surety_bond_type", data.suretyBondType as PolicyFormData["surety_bond_type"]);

        // Fuzzy-match customer
        if (data.customerName || data.customerPhone || data.customerEmail) {
          try {
            const matches = await customerService.findMatchingCustomers(
              data.customerName || "",
              data.customerPhone || "",
              data.customerEmail || ""
            );
            if (matches.length > 0) {
              setFuzzyMatches(matches);
              // Auto-select first match if high confidence
              if (matches.length === 1) {
                selectCustomer(matches[0]);
              }
            }
          } catch {
            // Fuzzy match failed, not critical
          }
        }

        toast.success(
          `Document extracted with ${Math.round(data.confidence * 100)}% confidence`
        );
      } catch (err) {
        console.error("Document extraction error:", err);
        const message = err instanceof Error ? err.message : "";
        if (message.includes("not configured") || message.includes("503")) {
          toast.error("Document extraction service is not configured. Please fill the form manually.");
        } else {
          toast.error("Failed to extract data from document. Please fill manually.");
        }
      } finally {
        setIsExtracting(false);
      }
    },
    [form]
  );

  // ---- Customer Search ----
  const searchCustomers = useCallback(
    async (query: string) => {
      setCustomerSearchQuery(query);
      if (query.length < 2) {
        setCustomerResults([]);
        return;
      }
      setIsSearching(true);
      try {
        const results = await customerService.searchByNameOrPhone(query);
        setCustomerResults(results.slice(0, 8));
      } catch {
        setCustomerResults([]);
      } finally {
        setIsSearching(false);
      }
    },
    []
  );

  function selectCustomer(customer: Customer) {
    setSelectedCustomer(customer);
    form.setValue("customer_id", customer.id!);
    form.setValue("customer_name", customer.name);
    setCustomerResults([]);
    setFuzzyMatches([]);
    setCustomerSearchQuery("");
  }

  // ---- Auto-Create Customer from Extracted Data ----
  const handleAutoCreateCustomer = useCallback(async () => {
    if (!extractedData || !user) return;

    setIsAutoCreating(true);
    try {
      const token = await getAccessToken();
      if (!token) throw new Error("Not authenticated");

      const apiRes = await fetch("/api/customers/auto-create", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          name: extractedData.customerName || "Unknown Customer",
          phone: extractedData.customerPhone || "N/A",
          email: extractedData.customerEmail || "N/A",
          address: extractedData.customerAddress || undefined,
          city: extractedData.customerCity || undefined,
          state: extractedData.customerState || undefined,
          pincode: extractedData.customerPincode || undefined,
        }),
      });

      if (!apiRes.ok) {
        const errBody = await apiRes.json().catch(() => null);
        throw new Error(errBody?.error || "Failed to auto-create customer");
      }

      const result = await apiRes.json();
      const isNew = !result.found;
      const customer = result as Customer;

      // Set customer in form
      setSelectedCustomer(customer);
      setAutoCreatedCustomer(customer);
      form.setValue("customer_id", customer.id!);
      form.setValue("customer_name", customer.name);
      setFuzzyMatches([]);
      setCustomerSearchQuery("");

      // Invalidate customer cache so the new customer shows up everywhere
      invalidateCustomers();

      if (isNew) {
        toast.success(`Customer "${customer.name}" (${customer.uid}) created automatically from document`);
      } else {
        toast.info(`Existing customer "${customer.name}" (${customer.uid}) linked from document`);
      }
    } catch (err: unknown) {
      console.error("Auto-create customer error:", err);
      toast.error(friendlyError(err instanceof Error ? err : new Error(String(err)), "Failed to auto-create customer. Please add manually."));
    } finally {
      setIsAutoCreating(false);
    }
  }, [extractedData, user, form]);

  // ---- Submit ----
  async function onSubmit(data: PolicyFormData) {
    // For employees, show verification popup first
    if (isEmployee && !isEdit) {
      setShowVerification(true);
      return;
    }
    await savePolicy(data);
  }

  async function handleVerifiedSave() {
    const data = form.getValues();
    setShowVerification(false);
    await savePolicy(data);
  }

  async function savePolicy(data: PolicyFormData) {
    if (!user) return;
    setIsSubmitting(true);

    try {
      let pdfUrl: string | undefined;

      // Upload document if new
      if (uploadedFile && !isEdit) {
        setIsUploading(true);
        setUploadProgress(0);

        const token = await getAccessToken();
        if (!token) throw new Error("Not authenticated");

        const timestamp = Date.now();
        const safeName = uploadedFile.name.replace(/[^a-zA-Z0-9._-]/g, "_");
        const storagePath = `policies/${user!.uid}/${timestamp}_${safeName}`;

        const uploadInitRes = await fetch("/api/upload", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            path: storagePath,
            mimeType: uploadedFile.type,
            size: uploadedFile.size,
          }),
        });

        if (!uploadInitRes.ok) {
          const err = await uploadInitRes.json().catch(() => ({ error: "Failed to initialize upload" }));
          throw new Error(err.error ?? "Failed to initialize upload");
        }

        const uploadInit = await uploadInitRes.json() as {
          uploadUrl: string;
          storagePath: string;
        };

        await new Promise<void>((resolve, reject) => {
          if (typeof XMLHttpRequest !== "undefined") {
            const xhr = new XMLHttpRequest();
            xhr.open("PUT", uploadInit.uploadUrl);
            xhr.setRequestHeader("Content-Type", uploadedFile.type || "application/octet-stream");
            xhr.upload.onprogress = (event) => {
              if (event.lengthComputable) setUploadProgress(Math.round((event.loaded / event.total) * 100));
            };
            xhr.onload = () => {
              if (xhr.status >= 200 && xhr.status < 300) { setUploadProgress(100); resolve(); }
              else reject(new Error(`Upload failed with status ${xhr.status}`));
            };
            xhr.onerror = () => reject(new Error("Upload failed due to a network error"));
            xhr.send(uploadedFile);
          } else {
            fetch(uploadInit.uploadUrl, {
              method: "PUT",
              headers: { "Content-Type": uploadedFile.type || "application/octet-stream" },
              body: uploadedFile,
            }).then((res) => {
              if (res.ok) { setUploadProgress(100); resolve(); }
              else reject(new Error(`Upload failed with status ${res.status}`));
            }).catch(reject);
          }
        });

        // Store the storage path — resolved to a signed URL on demand
        pdfUrl = uploadInit.storagePath;
        setIsUploading(false);
      }

      if (isEdit && editPolicy?.id) {
        // Update existing policy
        await policyService.update(editPolicy.id, {
          policy_type: data.policy_type,
          customer_id: data.customer_id,
          customer_name: data.customer_name,
          premium_amount: data.premium_amount,
          sum_insured: data.sum_insured || undefined,
          insurer_name: data.insurer_name || undefined,
          payment_frequency: data.payment_frequency || undefined,
          remark: data.remark || undefined,
          campaign_id: data.campaign_id || undefined,
          motor_category: data.motor_category || undefined,
          vehicle_number: data.vehicle_number || undefined,
          vehicle_type: data.vehicle_type || undefined,
          health_policy_type: data.health_policy_type || undefined,
          plan_name: data.plan_name || undefined,
          life_plan_type: data.life_plan_type || undefined,
          risk_location: data.risk_location || undefined,
          marine_policy_type: data.marine_policy_type || undefined,
          liability_type: data.liability_type || undefined,
          policy_tenure: data.policy_tenure || undefined,
          project_name: data.project_name || undefined,
          project_location: data.project_location || undefined,
          principal: data.principal || undefined,
          surety_bond_type: data.surety_bond_type || undefined,
          ...(isAdminOrManager ? {
            assigned_to: data.assigned_to,
            assigned_to_name: data.assigned_to_name || undefined,
          } : {}),
        });
        toast.success("Policy updated successfully");

        // Audit log: policy update
        auditLogService.logAction(
          user.uid, user.name || "", "update", "policies",
          `Updated policy ${editPolicy.id} (${data.policy_type}) for ${data.customer_name}`
        ).catch(() => {});
      } else {
        // Create new policy via server API (auto-generates policy_number if blank)
        const idToken = session?.access_token;
        const apiRes = await fetch("/api/policies", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${idToken}`,
          },
          body: JSON.stringify({
            policy_number: data.policy_number || "",
            policy_type: data.policy_type,
            customer_id: data.customer_id,
            customer_name: data.customer_name,
            start_date: data.start_date,
            end_date: data.end_date,
            premium_amount: data.premium_amount,
            sum_insured: data.sum_insured || undefined,
            insurer_name: data.insurer_name || undefined,
            payment_frequency: data.payment_frequency || undefined,
            assigned_to: data.assigned_to || user.uid,
            assigned_to_name: data.assigned_to_name || user.name || "",
            pdf_url: pdfUrl,
            remark: data.remark || undefined,
            branch_id: data.branch_id || user.branch_id || "",
            campaign_id: data.campaign_id || null,
            motor_category: data.motor_category || null,
            vehicle_number: data.vehicle_number || null,
            vehicle_type: data.vehicle_type || null,
            health_policy_type: data.health_policy_type || null,
            plan_name: data.plan_name || null,
            life_plan_type: data.life_plan_type || null,
            risk_location: data.risk_location || null,
            marine_policy_type: data.marine_policy_type || null,
            liability_type: data.liability_type || null,
            policy_tenure: data.policy_tenure || null,
            project_name: data.project_name || null,
            project_location: data.project_location || null,
            principal: data.principal || null,
            surety_bond_type: data.surety_bond_type || null,
          }),
        });
        if (!apiRes.ok) {
          const errBody = await apiRes.json().catch(() => null);
          throw new Error(errBody?.error || "Failed to create policy");
        }
        const created = await apiRes.json();

        // Create a document record so the file appears in the Documents tab
        if (pdfUrl && uploadedFile) {
          try {
            await documentService.create({
              file_path: pdfUrl,
              file_url: pdfUrl,
              file_name: uploadedFile.name,
              file_size: uploadedFile.size,
              uploaded_by: user.uid,
              document_type: "policy",
              policy_id: created.id,
              customer_id: data.customer_id,
            });
            invalidateDocuments();
          } catch (docErr) {
            console.warn("[policy-form] Failed to create document record:", docErr);
          }
        }

        toast.success(`Policy ${created.policy_number} created successfully`);
      }

      invalidatePolicies();
      onSuccess?.();
      onOpenChange(false);
    } catch (err: unknown) {
      console.error("Policy save error:", err);
      toast.error(friendlyError(err instanceof Error ? err : new Error(String(err)), "Failed to save policy"));
    } finally {
      setIsSubmitting(false);
      setIsUploading(false);
    }
  }

  return (
    <>
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-2xl">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Shield className="h-5 w-5 text-primary" />
              {isEdit ? "Edit Policy" : "Add New Policy"}
            </DialogTitle>
            <DialogDescription>
              {isEmployee
                ? "Upload a policy document (PDF or image) to auto-fill details, then verify and save."
                : "Create a new policy manually or extract from a document."}
            </DialogDescription>
          </DialogHeader>

          {/* Mode Tabs — Admin/Manager only */}
          {!isEmployee && !isEdit && (
            <Tabs value={mode} onValueChange={(v) => setMode(v as "manual" | "upload")}>
              <TabsList className="grid w-full grid-cols-2">
                <TabsTrigger value="manual" className="flex items-center gap-2">
                  <PenLine className="h-4 w-4" /> Manual
                </TabsTrigger>
                <TabsTrigger value="upload" className="flex items-center gap-2">
                  <FileUp className="h-4 w-4" /> Upload
                </TabsTrigger>
              </TabsList>
            </Tabs>
          )}

          {/* PDF Upload Zone */}
          <AnimatePresence>
            {(mode === "upload" || isEmployee) && !isEdit && (
              <PolicyUploadZone
                uploadedFile={uploadedFile}
                extractedData={extractedData}
                isExtracting={isExtracting}
                isUploading={isUploading}
                uploadProgress={uploadProgress}
                fuzzyMatches={fuzzyMatches}
                isAutoCreating={isAutoCreating}
                autoCreatedCustomer={autoCreatedCustomer}
                onFileUpload={handleFileUpload}
                onClearFile={() => {
                  setUploadedFile(null);
                  setExtractedData(null);
                  setAutoCreatedCustomer(null);
                }}
                onSelectCustomer={selectCustomer}
                onAutoCreateCustomer={handleAutoCreateCustomer}
              />
            )}
          </AnimatePresence>

          {/* Form */}
          <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
              {/* Customer Search */}
              {!isEdit && (
                <CustomerSearchField
                  selectedCustomer={selectedCustomer}
                  searchQuery={customerSearchQuery}
                  results={customerResults}
                  isSearching={isSearching}
                  errorMessage={form.formState.errors.customer_id?.message}
                  onSearch={searchCustomers}
                  onSelect={selectCustomer}
                  onClear={() => {
                    setSelectedCustomer(null);
                    form.setValue("customer_id", "");
                    form.setValue("customer_name", "");
                  }}
                />
              )}

              <Separator />

              {/* Policy Details */}
              <PolicyDetailsGrid
                isEdit={isEdit}
                campaigns={isAdminOrManager ? campaigns ?? [] : []}
                users={isAdminOrManager ? activeUsers ?? [] : []}
                showAssignTo={isAdminOrManager}
              />

              {/* Submit */}
              <div className="flex justify-end gap-2 pt-2">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => onOpenChange(false)}
                  disabled={isSubmitting}
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  disabled={isSubmitting || isExtracting}
                  className="bg-primary text-primary-foreground hover:bg-primary/90"
                >
                  {isSubmitting ? (
                    <span className="flex items-center gap-2">
                      <Loader2 className="h-4 w-4 animate-spin" />
                      {isEdit ? "Updating..." : "Saving..."}
                    </span>
                  ) : isEdit ? (
                    "Update Policy"
                  ) : isEmployee ? (
                    "Verify & Save"
                  ) : (
                    "Create Policy"
                  )}
                </Button>
              </div>
            </form>
          </Form>
        </DialogContent>
      </Dialog>

      {/* Verification Popup for Employees */}
      <VerificationPopup
        open={showVerification}
        onOpenChange={setShowVerification}
        policyData={form.getValues()}
        onConfirm={handleVerifiedSave}
        isSubmitting={isSubmitting}
      />
    </>
  );
}

"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  Upload,
  FileText,
  Sparkles,
  Loader2,
  X,
  User,
  UserPlus,
  CheckCircle2,
  ChevronDown,
  ChevronUp,
  FileCheck,
  AlertTriangle,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { getMaxFileSize } from "@/lib/helpers/storage";
import type { ExtractedPolicyData } from "@/lib/helpers/pdf-extractor";
import type { Customer } from "@/lib/types";

interface PolicyUploadZoneProps {
  uploadedFile: File | null;
  extractedData: ExtractedPolicyData | null;
  isExtracting: boolean;
  isUploading: boolean;
  uploadProgress: number;
  fuzzyMatches: Customer[];
  isAutoCreating?: boolean;
  autoCreatedCustomer?: Customer | null;
  onFileUpload: (file: File) => void;
  onClearFile: () => void;
  onSelectCustomer: (customer: Customer) => void;
  onAutoCreateCustomer?: () => void;
}

/** Confidence color based on percentage */
function confidenceColor(confidence: number): string {
  if (confidence >= 0.75) return "text-green-600 dark:text-green-400";
  if (confidence >= 0.5) return "text-amber-600 dark:text-amber-400";
  return "text-red-600 dark:text-red-400";
}

function confidenceBg(confidence: number): string {
  if (confidence >= 0.75) return "bg-green-500/20 text-green-600 dark:text-green-400";
  if (confidence >= 0.5) return "bg-amber-500/20 text-amber-600 dark:text-amber-400";
  return "bg-red-500/20 text-red-600 dark:text-red-400";
}

/** Labeled extraction field for the summary panel */
function ExtractionField({ label, value }: { label: string; value: string | number | null }) {
  const filled = value !== null && value !== undefined && value !== "" && value !== 0;
  return (
    <div className="flex items-center gap-2 text-xs">
      {filled ? (
        <FileCheck className="h-3 w-3 shrink-0 text-green-500" />
      ) : (
        <AlertTriangle className="h-3 w-3 shrink-0 text-muted-foreground/50" />
      )}
      <span className="w-24 shrink-0 font-medium text-muted-foreground">{label}</span>
      <span className={filled ? "text-foreground" : "italic text-muted-foreground/50"}>
        {filled ? String(value) : "Not found"}
      </span>
    </div>
  );
}

export function PolicyUploadZone({
  uploadedFile,
  extractedData,
  isExtracting,
  isUploading,
  uploadProgress,
  fuzzyMatches,
  isAutoCreating,
  autoCreatedCustomer,
  onFileUpload,
  onClearFile,
  onSelectCustomer,
  onAutoCreateCustomer,
}: PolicyUploadZoneProps) {
  const [showDetails, setShowDetails] = useState(false);

  function handleDrop(e: React.DragEvent) {
    e.preventDefault();
    const file = e.dataTransfer.files[0];
    if (file) onFileUpload(file);
  }

  function handleFileInput(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (file) onFileUpload(file);
  }

  return (
    <>
      {/* PDF Upload Zone */}
      <motion.div
        initial={{ opacity: 0, height: 0 }}
        animate={{ opacity: 1, height: "auto" }}
        exit={{ opacity: 0, height: 0 }}
      >
        {!uploadedFile ? (
          <div
            onDragOver={(e) => e.preventDefault()}
            onDrop={handleDrop}
            className="flex cursor-pointer flex-col items-center gap-3 rounded-lg border-2 border-dashed border-muted-foreground/40 p-8 transition-colors hover:border-primary/60"
            onClick={() => document.getElementById("doc-upload-input")?.click()}
          >
            <Upload className="h-10 w-10 text-muted-foreground" />
            <div className="text-center">
              <p className="text-sm font-medium text-foreground">
                Drop file here or click to browse
              </p>
              <p className="text-xs text-muted-foreground">
                Max {getMaxFileSize() / (1024 * 1024)}MB &bull; PDF or image &bull; Indian insurer formats
              </p>
            </div>
            <input
              id="doc-upload-input"
              type="file"
              accept=".pdf,.jpg,.jpeg,.png,.webp,.bmp,.tiff,.tif,.gif"
              className="hidden"
              aria-label="Upload policy document"
              onChange={handleFileInput}
            />
          </div>
        ) : (
          <div className="rounded-lg border border-muted-foreground/30 bg-card p-3">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <FileText className="h-5 w-5 text-primary" />
                <div>
                  <p className="text-sm font-medium text-foreground">
                    {uploadedFile.name}
                  </p>
                  <p className="text-xs text-muted-foreground">
                    {(uploadedFile.size / 1024).toFixed(0)} KB
                  </p>
                </div>
              </div>
              <div className="flex items-center gap-2">
                {isExtracting && (
                  <Badge variant="outline" className="gap-1">
                    <Loader2 className="h-3 w-3 animate-spin" />
                    Extracting...
                  </Badge>
                )}
                {extractedData && (
                  <Badge className="gap-1 bg-primary/20 text-primary">
                    <Sparkles className="h-3 w-3" />
                    {Math.round(extractedData.confidence * 100)}%
                  </Badge>
                )}
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-7 w-7"
                  onClick={onClearFile}
                >
                  <X className="h-4 w-4" />
                </Button>
              </div>
            </div>
          </div>
        )}
      </motion.div>

      {/* Extraction Details — expandable summary */}
      <AnimatePresence>
        {extractedData && !isExtracting && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            className="rounded-lg border border-border bg-card p-3"
          >
            <button
              type="button"
              className="flex w-full items-center justify-between text-left"
              onClick={() => setShowDetails((v) => !v)}
            >
              <div className="flex items-center gap-2">
                <Sparkles className="h-4 w-4 text-primary" />
                <span className="text-sm font-medium text-foreground">
                  Extraction Summary
                </span>
                <Badge className={`gap-1 ${confidenceBg(extractedData.confidence)}`}>
                  {Math.round(extractedData.confidence * 100)}% confidence
                </Badge>
              </div>
              {showDetails ? (
                <ChevronUp className="h-4 w-4 text-muted-foreground" />
              ) : (
                <ChevronDown className="h-4 w-4 text-muted-foreground" />
              )}
            </button>

            <AnimatePresence>
              {showDetails && (
                <motion.div
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={{ opacity: 0, height: 0 }}
                  className="mt-3 space-y-3"
                >
                  {/* Policy Fields */}
                  <div>
                    <p className="mb-1.5 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                      Policy Details
                    </p>
                    <div className="space-y-1">
                      <ExtractionField label="Policy No." value={extractedData.policyNumber} />
                      <ExtractionField label="Type" value={extractedData.policyType} />
                      <ExtractionField label="Insurer" value={extractedData.insurerName} />
                      <ExtractionField label="Premium" value={extractedData.premium ? `₹${extractedData.premium.toLocaleString("en-IN")}` : null} />
                      <ExtractionField label="Sum Insured" value={extractedData.sumInsured ? `₹${extractedData.sumInsured.toLocaleString("en-IN")}` : null} />
                      <ExtractionField label="Start Date" value={extractedData.startDate} />
                      <ExtractionField label="End Date" value={extractedData.endDate} />
                      <ExtractionField label="Frequency" value={extractedData.paymentFrequency} />
                    </div>
                  </div>

                  {/* Customer Fields */}
                  <div>
                    <p className="mb-1.5 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                      Customer Details
                    </p>
                    <div className="space-y-1">
                      <ExtractionField label="Name" value={extractedData.customerName} />
                      <ExtractionField label="Phone" value={extractedData.customerPhone} />
                      <ExtractionField label="Email" value={extractedData.customerEmail} />
                      <ExtractionField label="Address" value={extractedData.customerAddress} />
                      <ExtractionField label="City" value={extractedData.customerCity} />
                      <ExtractionField label="State" value={extractedData.customerState} />
                      <ExtractionField label="Pincode" value={extractedData.customerPincode} />
                    </div>
                  </div>

                  {extractedData.confidence < 0.5 && (
                    <p className="flex items-center gap-1.5 text-xs text-amber-600 dark:text-amber-400">
                      <AlertTriangle className="h-3 w-3" />
                      Low confidence — please verify all fields before saving.
                    </p>
                  )}
                </motion.div>
              )}
            </AnimatePresence>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Fuzzy Customer Matches */}
      <AnimatePresence>
        {fuzzyMatches.length > 0 && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            className="rounded-lg border border-primary/30 bg-primary/5 p-3"
          >
            <p className="mb-2 text-xs font-medium text-primary">
              Matching customers found:
            </p>
            <div className="space-y-1">
              {fuzzyMatches.map((c) => (
                <button
                  key={c.id}
                  type="button"
                  className="flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-left text-sm transition-colors hover:bg-primary/10"
                  onClick={() => onSelectCustomer(c)}
                >
                  <User className="h-3.5 w-3.5 text-muted-foreground" />
                  <span className="font-medium">{c.name}</span>
                  <span className="text-xs text-muted-foreground">{c.uid}</span>
                </button>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Auto-Create Customer — shown when extraction done but no matches found */}
      <AnimatePresence>
        {extractedData && !isExtracting && fuzzyMatches.length === 0 && extractedData.customerName && !autoCreatedCustomer && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            className="rounded-lg border border-amber-500/30 bg-amber-500/5 p-3"
          >
            <p className="mb-2 text-xs font-medium text-amber-600 dark:text-amber-400">
              No matching customer found. Auto-create from extracted data?
            </p>
            <div className="mb-2 space-y-1 text-xs text-muted-foreground">
              <p><span className="font-medium text-foreground">Name:</span> {extractedData.customerName}</p>
              {extractedData.customerPhone && (
                <p><span className="font-medium text-foreground">Phone:</span> {extractedData.customerPhone}</p>
              )}
              {extractedData.customerEmail && (
                <p><span className="font-medium text-foreground">Email:</span> {extractedData.customerEmail}</p>
              )}
              {extractedData.customerAddress && (
                <p><span className="font-medium text-foreground">Address:</span> {extractedData.customerAddress}</p>
              )}
              {extractedData.customerCity && (
                <p><span className="font-medium text-foreground">City:</span> {extractedData.customerCity}</p>
              )}
              {extractedData.customerState && (
                <p><span className="font-medium text-foreground">State:</span> {extractedData.customerState}</p>
              )}
              {extractedData.customerPincode && (
                <p><span className="font-medium text-foreground">Pincode:</span> {extractedData.customerPincode}</p>
              )}
            </div>
            <Button
              type="button"
              size="sm"
              variant="outline"
              className="gap-1.5 border-amber-500/50 text-amber-600 hover:bg-amber-500/10 dark:text-amber-400"
              onClick={onAutoCreateCustomer}
              disabled={isAutoCreating}
            >
              {isAutoCreating ? (
                <>
                  <Loader2 className="h-3.5 w-3.5 animate-spin" />
                  Creating...
                </>
              ) : (
                <>
                  <UserPlus className="h-3.5 w-3.5" />
                  Auto-Create Customer & Assign Policy
                </>
              )}
            </Button>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Auto-Created Customer Success */}
      <AnimatePresence>
        {autoCreatedCustomer && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            className="rounded-lg border border-green-500/30 bg-green-500/5 p-3"
          >
            <div className="flex items-center gap-2">
              <CheckCircle2 className="h-4 w-4 text-green-600 dark:text-green-400" />
              <p className="text-xs font-medium text-green-600 dark:text-green-400">
                Customer created & assigned automatically
              </p>
            </div>
            <div className="mt-1.5 flex items-center gap-2 text-sm">
              <User className="h-3.5 w-3.5 text-muted-foreground" />
              <span className="font-medium">{autoCreatedCustomer.name}</span>
              <Badge variant="outline" className="text-xs">{autoCreatedCustomer.uid}</Badge>
              {autoCreatedCustomer.phone && autoCreatedCustomer.phone !== "0000000000" && (
                <span className="text-xs text-muted-foreground">{autoCreatedCustomer.phone}</span>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Upload Progress */}
      <AnimatePresence>
        {isUploading && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="space-y-1"
          >
            <div className="flex justify-between text-xs text-muted-foreground">
              <span>Uploading PDF...</span>
              <span>{uploadProgress}%</span>
            </div>
            <Progress value={uploadProgress} className="h-1.5" />
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}

"use client";

import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { motion, AnimatePresence } from "framer-motion";
import { ShieldCheck, CheckCircle2, AlertTriangle } from "lucide-react";

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";

import {
  verificationSchema,
  type VerificationFormData,
} from "@/lib/validations/policy";
import type { PolicyFormData } from "@/lib/validations/policy";

interface VerificationPopupProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  policyData: Partial<PolicyFormData>;
  onConfirm: () => void;
  isSubmitting?: boolean;
}

const VERIFICATION_ITEMS = [
  {
    key: "policyNumberCorrect" as const,
    label: "Policy number is correct",
    description: "I have verified the policy number matches the document",
  },
  {
    key: "datesCorrect" as const,
    label: "Policy dates are correct",
    description: "Start and end dates match the original policy document",
  },
  {
    key: "premiumCorrect" as const,
    label: "Premium amount is correct",
    description: "The premium amount matches the policy document",
  },
  {
    key: "customerCorrect" as const,
    label: "Customer details are correct",
    description: "Customer name and other details are accurately filled",
  },
  {
    key: "finalConfirmation" as const,
    label: "I confirm all details are accurate",
    description:
      "I take responsibility for the accuracy of this policy entry",
  },
];

export function VerificationPopup({
  open,
  onOpenChange,
  policyData,
  onConfirm,
  isSubmitting = false,
}: VerificationPopupProps) {
  const form = useForm<VerificationFormData>({
    resolver: zodResolver(verificationSchema),
    defaultValues: {
      policyNumberCorrect: false as unknown as true,
      datesCorrect: false as unknown as true,
      premiumCorrect: false as unknown as true,
      customerCorrect: false as unknown as true,
      finalConfirmation: false as unknown as true,
    },
  });

  const watchAll = form.watch();

  // Check if all items are true
  const isAllChecked =
    watchAll.policyNumberCorrect === true &&
    watchAll.datesCorrect === true &&
    watchAll.premiumCorrect === true &&
    watchAll.customerCorrect === true &&
    watchAll.finalConfirmation === true;

  function handleSubmit() {
    if (isAllChecked) {
      onConfirm();
    }
  }

  function handleClose() {
    form.reset();
    onOpenChange(false);
  }

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <ShieldCheck className="h-5 w-5 text-primary" />
            Verify Policy Details
          </DialogTitle>
          <DialogDescription>
            Please verify all details before saving. All checkboxes must be
            confirmed.
          </DialogDescription>
        </DialogHeader>

        {/* Policy Summary */}
        <div className="rounded-lg border border-muted-foreground/30 bg-card p-3 text-sm">
          <div className="grid grid-cols-2 gap-2">
            <div>
              <span className="text-muted-foreground">Policy #:</span>{" "}
              <span className="font-medium text-foreground">
                {policyData.policy_number || "—"}
              </span>
            </div>
            <div>
              <span className="text-muted-foreground">Type:</span>{" "}
              <span className="font-medium text-foreground">
                {policyData.policy_type || "—"}
              </span>
            </div>
            <div>
              <span className="text-muted-foreground">Premium:</span>{" "}
              <span className="font-medium text-foreground">
                {policyData.premium_amount
                  ? `₹${policyData.premium_amount.toLocaleString("en-IN")}`
                  : "—"}
              </span>
            </div>
            <div>
              <span className="text-muted-foreground">Customer:</span>{" "}
              <span className="font-medium text-foreground">
                {policyData.customer_name || "—"}
              </span>
            </div>
            <div>
              <span className="text-muted-foreground">Start:</span>{" "}
              <span className="font-medium text-foreground">
                {policyData.start_date || "—"}
              </span>
            </div>
            <div>
              <span className="text-muted-foreground">End:</span>{" "}
              <span className="font-medium text-foreground">
                {policyData.end_date || "—"}
              </span>
            </div>
          </div>
        </div>

        {/* Verification Checklist */}
        <Form {...form}>
          <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-3">
            {VERIFICATION_ITEMS.map((item, index) => (
              <motion.div
                key={item.key}
                initial={{ opacity: 0, x: -10 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: index * 0.08 }}
              >
                <FormField
                  control={form.control}
                  name={item.key}
                  render={({ field }) => (
                    <FormItem className="flex flex-row items-start space-x-3 space-y-0 rounded-md border border-muted-foreground/20 p-3 transition-colors hover:border-primary/40">
                      <FormControl>
                        <Checkbox
                          checked={field.value === true}
                          onCheckedChange={(checked) => {
                            field.onChange(checked === true ? true : false);
                          }}
                        />
                      </FormControl>
                      <div className="space-y-0.5 leading-none">
                        <FormLabel className="cursor-pointer text-sm font-medium">
                          {item.label}
                        </FormLabel>
                        <p className="text-xs text-muted-foreground">
                          {item.description}
                        </p>
                      </div>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </motion.div>
            ))}

            <DialogFooter className="pt-2">
              <Button
                type="button"
                variant="outline"
                onClick={handleClose}
                disabled={isSubmitting}
              >
                Cancel
              </Button>
              <Button
                type="submit"
                disabled={!isAllChecked || isSubmitting}
                className="bg-primary text-primary-foreground hover:bg-primary/90"
              >
                {isSubmitting ? (
                  <span className="flex items-center gap-2">
                    <motion.span
                      animate={{ rotate: 360 }}
                      transition={{ repeat: Infinity, duration: 1, ease: "linear" }}
                      className="inline-block h-4 w-4 border-2 border-current border-t-transparent rounded-full"
                    />
                    Saving…
                  </span>
                ) : (
                  <span className="flex items-center gap-2">
                    <CheckCircle2 className="h-4 w-4" />
                    Confirm & Save
                  </span>
                )}
              </Button>
            </DialogFooter>
          </form>
        </Form>

        {/* Warning if not all checked */}
        <AnimatePresence>
          {!isAllChecked && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: "auto" }}
              exit={{ opacity: 0, height: 0 }}
              className="flex items-center gap-2 rounded-md bg-yellow-500/10 px-3 py-2 text-xs text-yellow-400"
            >
              <AlertTriangle className="h-3.5 w-3.5 shrink-0" />
              All checkboxes must be confirmed to save
            </motion.div>
          )}
        </AnimatePresence>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState } from "react";
import { toast } from "sonner";
import { CheckCircle2, Star, TrendingDown, TrendingUp, Loader2 } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { useAuth } from "@/lib/context/auth-context";
import { useRouter } from "next/navigation";

interface Quote {
  id: string;
  insurer_name: string;
  premium_amount: number;
  sum_insured: number;
  coverage_details?: string;
  terms?: string;
  validity_date: string;
  is_recommended: boolean;
  is_accepted: boolean;
  is_expired: boolean;
}

interface QuoteComparisonMatrixProps {
  quoteRequestId: string;
  quotes: Quote[];
  onQuoteUpdated?: () => void;
}

export function QuoteComparisonMatrix({
  quoteRequestId,
  quotes,
  onQuoteUpdated,
}: QuoteComparisonMatrixProps) {
  const { session } = useAuth();
  const router = useRouter();
  const [acceptingId, setAcceptingId] = useState<string | null>(null);
  const [confirmQuote, setConfirmQuote] = useState<Quote | null>(null);
  const [loading, setLoading] = useState(false);

  if (quotes.length === 0) {
    return (
      <div className="text-center py-12 text-muted-foreground">
        No quotes added yet. Add quotes to compare.
      </div>
    );
  }

  const minPremium = Math.min(...quotes.map((q) => q.premium_amount));
  const maxSumInsured = Math.max(...quotes.map((q) => q.sum_insured));

  const fmt = (n: number) =>
    n >= 10_00_000
      ? `₹${(n / 10_00_000).toFixed(2)}L`
      : `₹${n.toLocaleString("en-IN")}`;

  const handleAccept = async (quote: Quote) => {
    setLoading(true);
    setAcceptingId(quote.id);
    try {
      const token = session?.access_token;
      if (!token) throw new Error("Not authenticated");

      const res = await fetch(
        `/api/quotes/${quoteRequestId}/quotes/${quote.id}/accept`,
        {
          method: "POST",
          headers: { Authorization: `Bearer ${token}` },
        }
      );

      const data = await res.json();
      if (!res.ok) throw new Error(data.error ?? "Failed to accept quote");

      toast.success(`Quote from ${quote.insurer_name} accepted`);
      onQuoteUpdated?.();

      if (data.redirect_to) {
        router.push(data.redirect_to);
      }
    } catch (err: any) {
      toast.error(err.message ?? "Failed to accept quote");
    } finally {
      setLoading(false);
      setAcceptingId(null);
      setConfirmQuote(null);
    }
  };

  const rows = [
    { label: "Premium", key: "premium_amount", render: (q: Quote) => (
      <span className={q.premium_amount === minPremium ? "text-green-400 font-bold" : ""}>
        {fmt(q.premium_amount)}
        {q.premium_amount === minPremium && (
          <TrendingDown className="w-3 h-3 inline ml-1 text-green-400" />
        )}
      </span>
    )},
    { label: "Sum Insured", key: "sum_insured", render: (q: Quote) => (
      <span className={q.sum_insured === maxSumInsured ? "text-blue-400 font-bold" : ""}>
        {fmt(q.sum_insured)}
        {q.sum_insured === maxSumInsured && (
          <TrendingUp className="w-3 h-3 inline ml-1 text-blue-400" />
        )}
      </span>
    )},
    { label: "Coverage", key: "coverage_details", render: (q: Quote) => (
      <span className="text-xs">{q.coverage_details || "—"}</span>
    )},
    { label: "Terms", key: "terms", render: (q: Quote) => (
      <span className="text-xs">{q.terms || "—"}</span>
    )},
    { label: "Valid Until", key: "validity_date", render: (q: Quote) => (
      <span className="text-xs">
        {new Date(q.validity_date).toLocaleDateString("en-IN", {
          day: "2-digit", month: "short", year: "numeric",
        })}
      </span>
    )},
  ];

  return (
    <>
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-border">
              <th className="text-left py-3 px-4 text-xs uppercase tracking-wider font-heading text-muted-foreground w-32">
                Feature
              </th>
              {quotes.map((q) => (
                <th key={q.id} className="py-3 px-4 text-center min-w-[180px]">
                  <div className="space-y-1">
                    <p className="font-bold text-sm">{q.insurer_name}</p>
                    <div className="flex items-center justify-center gap-1 flex-wrap">
                      {q.is_recommended && (
                        <Badge className="text-xs bg-amber-500/10 text-amber-400 border-amber-500/20 gap-1">
                          <Star className="w-3 h-3" /> Recommended
                        </Badge>
                      )}
                      {q.is_accepted && (
                        <Badge className="text-xs bg-green-500/10 text-green-400 border-green-500/20 gap-1">
                          <CheckCircle2 className="w-3 h-3" /> Accepted
                        </Badge>
                      )}
                      {q.is_expired && (
                        <Badge variant="outline" className="text-xs text-muted-foreground">
                          Expired
                        </Badge>
                      )}
                    </div>
                  </div>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map(({ label, render }) => (
              <tr key={label} className="border-b border-border/50 hover:bg-muted/20">
                <td className="py-3 px-4 text-xs text-muted-foreground font-medium uppercase tracking-wider">
                  {label}
                </td>
                {quotes.map((q) => (
                  <td
                    key={q.id}
                    className={`py-3 px-4 text-center ${
                      label === "Premium" && q.premium_amount === minPremium
                        ? "bg-green-500/5"
                        : label === "Sum Insured" && q.sum_insured === maxSumInsured
                        ? "bg-blue-500/5"
                        : ""
                    }`}
                  >
                    {render(q)}
                  </td>
                ))}
              </tr>
            ))}
            {/* Actions row */}
            <tr>
              <td className="py-4 px-4 text-xs text-muted-foreground font-medium uppercase tracking-wider">
                Action
              </td>
              {quotes.map((q) => (
                <td key={q.id} className="py-4 px-4 text-center">
                  {!q.is_accepted && !q.is_expired ? (
                    <Button
                      size="sm"
                      onClick={() => setConfirmQuote(q)}
                      disabled={loading && acceptingId === q.id}
                      className="gap-1"
                    >
                      {loading && acceptingId === q.id ? (
                        <Loader2 className="w-3 h-3 animate-spin" />
                      ) : (
                        <CheckCircle2 className="w-3 h-3" />
                      )}
                      Accept
                    </Button>
                  ) : q.is_accepted ? (
                    <Badge className="bg-green-500/10 text-green-400 border-green-500/20">
                      Accepted
                    </Badge>
                  ) : (
                    <Badge variant="outline" className="text-muted-foreground">
                      Expired
                    </Badge>
                  )}
                </td>
              ))}
            </tr>
          </tbody>
        </table>
      </div>

      {/* Confirm Accept Dialog */}
      <AlertDialog open={!!confirmQuote} onOpenChange={(open) => !open && setConfirmQuote(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle className="font-heading uppercase tracking-wider">
              Accept Quote
            </AlertDialogTitle>
            <AlertDialogDescription>
              Accept the quote from <strong>{confirmQuote?.insurer_name}</strong> for{" "}
              <strong>₹{confirmQuote?.premium_amount?.toLocaleString("en-IN")}</strong>?
              This will mark the quote request as converted and redirect you to create a policy.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => confirmQuote && handleAccept(confirmQuote)}
              disabled={loading}
            >
              {loading && <Loader2 className="w-4 h-4 animate-spin mr-2" />}
              Accept & Create Policy
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

"use client";

import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { toast } from "sonner";
import { Loader2, Plus } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { useAuth } from "@/lib/context/auth-context";

const schema = z.object({
  insurer_name: z.string().min(1, "Insurer name is required"),
  premium_amount: z.string().min(1, "Premium is required"),
  sum_insured: z.string().min(1, "Sum insured is required"),
  coverage_details: z.string().optional(),
  terms: z.string().optional(),
  validity_date: z.string().min(1, "Validity date is required"),
  is_recommended: z.boolean().optional(),
});

type FormData = z.infer<typeof schema>;

interface QuoteEntryFormProps {
  quoteRequestId: string;
  onCreated?: () => void;
}

export function QuoteEntryForm({ quoteRequestId, onCreated }: QuoteEntryFormProps) {
  const { session } = useAuth();
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);

  const {
    register,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm<FormData>({
    resolver: zodResolver(schema),
  });

  const onSubmit = async (data: FormData) => {
    setLoading(true);
    try {
      const token = session?.access_token;
      if (!token) throw new Error("Not authenticated");

      const res = await fetch(`/api/quotes/${quoteRequestId}/quotes`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          ...data,
          premium_amount: parseFloat(data.premium_amount),
          sum_insured: parseFloat(data.sum_insured),
        }),
      });

      const result = await res.json();
      if (!res.ok) throw new Error(result.error ?? "Failed to add quote");

      toast.success(`Quote from ${data.insurer_name} added`);
      reset();
      setOpen(false);
      onCreated?.();
    } catch (err: any) {
      toast.error(err.message ?? "Failed to add quote");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button size="sm" className="gap-2">
          <Plus className="w-3.5 h-3.5" /> Add Quote
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle className="font-heading uppercase tracking-wider">
            Add Quote
          </DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="col-span-2 space-y-1.5">
              <Label htmlFor="insurer_name">Insurer Name *</Label>
              <Input id="insurer_name" placeholder="e.g., HDFC Ergo" {...register("insurer_name")} />
              {errors.insurer_name && (
                <p className="text-xs text-red-400">{errors.insurer_name.message}</p>
              )}
            </div>

            <div className="space-y-1.5">
              <Label htmlFor="premium_amount">Premium Amount (₹) *</Label>
              <Input
                id="premium_amount"
                type="number"
                step="0.01"
                placeholder="0.00"
                {...register("premium_amount")}
              />
              {errors.premium_amount && (
                <p className="text-xs text-red-400">{errors.premium_amount.message}</p>
              )}
            </div>

            <div className="space-y-1.5">
              <Label htmlFor="sum_insured">Sum Insured (₹) *</Label>
              <Input
                id="sum_insured"
                type="number"
                step="0.01"
                placeholder="0.00"
                {...register("sum_insured")}
              />
              {errors.sum_insured && (
                <p className="text-xs text-red-400">{errors.sum_insured.message}</p>
              )}
            </div>

            <div className="col-span-2 space-y-1.5">
              <Label htmlFor="validity_date">Valid Until *</Label>
              <Input id="validity_date" type="date" {...register("validity_date")} />
              {errors.validity_date && (
                <p className="text-xs text-red-400">{errors.validity_date.message}</p>
              )}
            </div>

            <div className="col-span-2 space-y-1.5">
              <Label htmlFor="coverage_details">Coverage Details</Label>
              <Textarea
                id="coverage_details"
                placeholder="Key coverage highlights..."
                rows={2}
                {...register("coverage_details")}
              />
            </div>

            <div className="col-span-2 space-y-1.5">
              <Label htmlFor="terms">Terms & Conditions</Label>
              <Textarea
                id="terms"
                placeholder="Special terms, exclusions..."
                rows={2}
                {...register("terms")}
              />
            </div>
          </div>

          <div className="flex justify-end gap-2">
            <Button type="button" variant="outline" onClick={() => setOpen(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={loading}>
              {loading && <Loader2 className="w-4 h-4 animate-spin mr-2" />}
              Add Quote
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState } from "react";
import { toast } from "sonner";
import { Loader2, CheckCircle2, Shield, AlertTriangle } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { useAuth } from "@/lib/context/auth-context";

interface DiscrepancyRecord {
  id: string;
  policy_number?: string;
  discrepancy_type?: string;
  statement_commission?: number;
  crm_commission?: number;
  discrepancy_amount?: number;
  resolution_status: string;
}

interface DiscrepancyResolutionDialogProps {
  runId: string;
  record: DiscrepancyRecord | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onResolved?: () => void;
}

const RESOLUTION_OPTIONS = [
  {
    value: "accept_statement",
    label: "Accept Statement",
    description: "Update CRM commission to match the insurer statement amount",
    icon: CheckCircle2,
    color: "text-green-400",
    bg: "bg-green-500/10 border-green-500/20",
  },
  {
    value: "accept_crm",
    label: "Accept CRM",
    description: "Keep the CRM commission amount as correct, mark resolved",
    icon: Shield,
    color: "text-blue-400",
    bg: "bg-blue-500/10 border-blue-500/20",
  },
  {
    value: "escalate",
    label: "Escalate",
    description: "Create a service ticket and notify the manager for review",
    icon: AlertTriangle,
    color: "text-amber-400",
    bg: "bg-amber-500/10 border-amber-500/20",
  },
];

export function DiscrepancyResolutionDialog({
  runId,
  record,
  open,
  onOpenChange,
  onResolved,
}: DiscrepancyResolutionDialogProps) {
  const { session } = useAuth();
  const [selectedResolution, setSelectedResolution] = useState<string | null>(null);
  const [notes, setNotes] = useState("");
  const [loading, setLoading] = useState(false);

  const handleResolve = async () => {
    if (!selectedResolution || !record) return;

    setLoading(true);
    try {
      const token = session?.access_token;
      if (!token) throw new Error("Not authenticated");

      const res = await fetch(
        `/api/reconciliation/${runId}/records/${record.id}/resolve`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({ resolution: selectedResolution, notes }),
        }
      );

      const data = await res.json();
      if (!res.ok) throw new Error(data.error ?? "Failed to resolve");

      toast.success("Discrepancy resolved");
      setSelectedResolution(null);
      setNotes("");
      onOpenChange(false);
      onResolved?.();
    } catch (err: any) {
      toast.error(err.message ?? "Failed to resolve");
    } finally {
      setLoading(false);
    }
  };

  if (!record) return null;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle className="font-heading uppercase tracking-wider">
            Resolve Discrepancy
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          {/* Discrepancy Info */}
          <div className="bg-muted/30 rounded-xl p-4 space-y-2 text-sm">
            <div className="flex justify-between">
              <span className="text-muted-foreground">Policy #</span>
              <span className="font-mono">{record.policy_number ?? "—"}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-muted-foreground">Type</span>
              <Badge variant="outline" className="text-xs capitalize">
                {record.discrepancy_type?.replace(/_/g, " ") ?? "—"}
              </Badge>
            </div>
            <div className="flex justify-between">
              <span className="text-muted-foreground">CRM Amount</span>
              <span>₹{(record.crm_commission ?? 0).toLocaleString("en-IN")}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-muted-foreground">Statement Amount</span>
              <span>₹{(record.statement_commission ?? 0).toLocaleString("en-IN")}</span>
            </div>
            {record.discrepancy_amount && (
              <div className="flex justify-between text-red-400">
                <span>Difference</span>
                <span>₹{record.discrepancy_amount.toLocaleString("en-IN")}</span>
              </div>
            )}
          </div>

          {/* Resolution Options */}
          <div className="space-y-2">
            <Label>Select Resolution *</Label>
            {RESOLUTION_OPTIONS.map((opt) => {
              const Icon = opt.icon;
              return (
                <button
                  key={opt.value}
                  type="button"
                  onClick={() => setSelectedResolution(opt.value)}
                  className={`w-full flex items-start gap-3 p-3 rounded-xl border text-left transition-colors ${
                    selectedResolution === opt.value
                      ? opt.bg
                      : "border-border hover:bg-muted/30"
                  }`}
                >
                  <Icon className={`w-4 h-4 mt-0.5 flex-shrink-0 ${opt.color}`} />
                  <div>
                    <p className="text-sm font-medium">{opt.label}</p>
                    <p className="text-xs text-muted-foreground">{opt.description}</p>
                  </div>
                </button>
              );
            })}
          </div>

          {/* Notes */}
          <div className="space-y-1.5">
            <Label htmlFor="resolution-notes">Notes (optional)</Label>
            <Textarea
              id="resolution-notes"
              placeholder="Add resolution notes..."
              rows={2}
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
            />
          </div>

          <div className="flex justify-end gap-2">
            <Button variant="outline" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button
              onClick={handleResolve}
              disabled={!selectedResolution || loading}
            >
              {loading && <Loader2 className="w-4 h-4 animate-spin mr-2" />}
              Resolve
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { toast } from "sonner";
import { Loader2, Plus } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useAuth } from "@/lib/context/auth-context";

const schema = z.object({
  task_type: z.enum(["call", "email", "meeting", "whatsapp"]),
  due_date: z.string().min(1, "Due date is required"),
  notes: z.string().optional(),
  assigned_to: z.string().min(1, "Assigned to is required"),
  assigned_to_name: z.string().optional(),
});

type FormData = z.infer<typeof schema>;

interface FollowUpTaskFormProps {
  renewalId: string;
  onCreated?: () => void;
}

export function FollowUpTaskForm({ renewalId, onCreated }: FollowUpTaskFormProps) {
  const { session, user } = useAuth();
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);

  const {
    register,
    handleSubmit,
    setValue,
    watch,
    reset,
    formState: { errors },
  } = useForm<FormData>({
    resolver: zodResolver(schema),
    defaultValues: {
      task_type: "call",
      assigned_to: user?.uid ?? "",
      assigned_to_name: user?.name ?? "",
    },
  });

  const taskType = watch("task_type");

  const onSubmit = async (data: FormData) => {
    setLoading(true);
    try {
      const token = session?.access_token;
      if (!token) throw new Error("Not authenticated");

      const res = await fetch(`/api/renewals/${renewalId}/follow-up`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(data),
      });

      const result = await res.json();
      if (!res.ok) throw new Error(result.error ?? "Failed to create task");

      toast.success("Follow-up task created");
      reset();
      setOpen(false);
      onCreated?.();
    } catch (err: any) {
      toast.error(err.message ?? "Failed to create task");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button size="sm" variant="outline" className="gap-2">
          <Plus className="w-3.5 h-3.5" /> Add Follow-up
        </Button>
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle className="font-heading uppercase tracking-wider">
            Create Follow-up Task
          </DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
          <div className="space-y-1.5">
            <Label>Task Type *</Label>
            <Select
              value={taskType}
              onValueChange={(v) => setValue("task_type", v as any)}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="call">Call</SelectItem>
                <SelectItem value="email">Email</SelectItem>
                <SelectItem value="meeting">Meeting</SelectItem>
                <SelectItem value="whatsapp">WhatsApp</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="due_date">Due Date *</Label>
            <Input
              id="due_date"
              type="datetime-local"
              {...register("due_date")}
            />
            {errors.due_date && (
              <p className="text-xs text-red-400">{errors.due_date.message}</p>
            )}
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="notes">Notes</Label>
            <Textarea
              id="notes"
              placeholder="Task notes..."
              rows={2}
              {...register("notes")}
            />
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="assigned_to_name">Assigned To</Label>
            <Input
              id="assigned_to_name"
              placeholder="Assignee name"
              {...register("assigned_to_name")}
            />
          </div>

          <div className="flex justify-end gap-2">
            <Button
              type="button"
              variant="outline"
              onClick={() => setOpen(false)}
            >
              Cancel
            </Button>
            <Button type="submit" disabled={loading}>
              {loading && <Loader2 className="w-4 h-4 animate-spin mr-2" />}
              Create Task
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState } from "react";
import { format } from "date-fns";
import { toast } from "sonner";
import { CheckCircle2, Clock, Phone, Mail, Users, MessageCircle, RotateCcw } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { useAuth } from "@/lib/context/auth-context";

interface FollowUpTask {
  id: string;
  renewal_id: string;
  task_type: "call" | "email" | "meeting" | "whatsapp";
  due_date: string;
  notes?: string;
  assigned_to_name?: string;
  status: "pending" | "completed" | "snoozed";
  completed_at?: string;
  completion_notes?: string;
}

interface FollowUpTaskListProps {
  renewalId: string;
  tasks: FollowUpTask[];
  onTaskUpdated?: () => void;
}

const TASK_ICONS = {
  call: Phone,
  email: Mail,
  meeting: Users,
  whatsapp: MessageCircle,
};

const STATUS_COLORS = {
  pending: "bg-amber-500/10 text-amber-400 border-amber-500/20",
  completed: "bg-green-500/10 text-green-400 border-green-500/20",
  snoozed: "bg-gray-500/10 text-gray-400 border-gray-500/20",
};

export function FollowUpTaskList({ renewalId, tasks, onTaskUpdated }: FollowUpTaskListProps) {
  const { session } = useAuth();
  const [loadingId, setLoadingId] = useState<string | null>(null);

  const updateTask = async (taskId: string, payload: any) => {
    setLoadingId(taskId);
    try {
      const token = session?.access_token;
      if (!token) throw new Error("Not authenticated");

      const res = await fetch(`/api/renewals/${renewalId}/follow-up/${taskId}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(payload),
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error ?? "Failed to update task");

      toast.success("Task updated");
      onTaskUpdated?.();
    } catch (err: any) {
      toast.error(err.message ?? "Failed to update task");
    } finally {
      setLoadingId(null);
    }
  };

  const handleComplete = (taskId: string) => {
    updateTask(taskId, { status: "completed" });
  };

  const handleSnooze = (taskId: string) => {
    // Snooze by 1 day
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    updateTask(taskId, { status: "snoozed", due_date: tomorrow.toISOString() });
  };

  if (tasks.length === 0) {
    return (
      <div className="text-center py-6 text-muted-foreground text-sm">
        No follow-up tasks yet.
      </div>
    );
  }

  const sorted = [...tasks].sort(
    (a, b) => new Date(a.due_date).getTime() - new Date(b.due_date).getTime()
  );

  return (
    <div className="space-y-2">
      {sorted.map((task) => {
        const Icon = TASK_ICONS[task.task_type] ?? Clock;
        const isOverdue =
          task.status === "pending" && new Date(task.due_date) < new Date();

        return (
          <div
            key={task.id}
            className={`flex items-start gap-3 p-3 rounded-xl border ${
              isOverdue ? "border-red-500/30 bg-red-500/5" : "border-border bg-card"
            }`}
          >
            <div className="w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center flex-shrink-0 mt-0.5">
              <Icon className="w-4 h-4 text-primary" />
            </div>
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 flex-wrap">
                <span className="text-sm font-medium capitalize">{task.task_type}</span>
                <Badge
                  variant="outline"
                  className={`text-xs ${STATUS_COLORS[task.status]}`}
                >
                  {task.status}
                </Badge>
                {isOverdue && (
                  <Badge variant="outline" className="text-xs bg-red-500/10 text-red-400 border-red-500/20">
                    Overdue
                  </Badge>
                )}
              </div>
              <p className="text-xs text-muted-foreground mt-0.5">
                Due: {format(new Date(task.due_date), "dd MMM yyyy, HH:mm")}
                {task.assigned_to_name && ` · ${task.assigned_to_name}`}
              </p>
              {task.notes && (
                <p className="text-xs text-muted-foreground mt-1 truncate">{task.notes}</p>
              )}
            </div>
            {task.status === "pending" && (
              <div className="flex gap-1 flex-shrink-0">
                <Button
                  size="sm"
                  variant="ghost"
                  className="h-7 w-7 p-0 text-green-400 hover:bg-green-500/10"
                  title="Mark Complete"
                  disabled={loadingId === task.id}
                  onClick={() => handleComplete(task.id)}
                >
                  <CheckCircle2 className="w-3.5 h-3.5" />
                </Button>
                <Button
                  size="sm"
                  variant="ghost"
                  className="h-7 w-7 p-0 text-amber-400 hover:bg-amber-500/10"
                  title="Snooze 1 day"
                  disabled={loadingId === task.id}
                  onClick={() => handleSnooze(task.id)}
                >
                  <RotateCcw className="w-3.5 h-3.5" />
                </Button>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

"use client";

import { useState } from "react";
import { toast } from "sonner";
import { Loader2 } from "lucide-react";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { useAuth } from "@/lib/context/auth-context";
import { supabase } from "@/lib/supabase/client";

const STAGES = [
  { value: "due", label: "Due" },
  { value: "contacted", label: "Contacted" },
  { value: "negotiating", label: "Negotiating" },
  { value: "renewed", label: "Renewed" },
  { value: "lost", label: "Lost" },
] as const;

type Stage = (typeof STAGES)[number]["value"];

interface RenewalStageSelectorProps {
  renewalId: string;
  currentStage: Stage;
  onStageUpdated?: (newStage: Stage) => void;
}

export function RenewalStageSelector({
  renewalId,
  currentStage,
  onStageUpdated,
}: RenewalStageSelectorProps) {
  const { session } = useAuth();
  const [loading, setLoading] = useState(false);
  const [lostDialogOpen, setLostDialogOpen] = useState(false);
  const [pendingStage, setPendingStage] = useState<Stage | null>(null);
  const [lostReason, setLostReason] = useState("");

  const isTerminal = currentStage === "renewed" || currentStage === "lost";

  const handleStageChange = async (newStage: Stage) => {
    if (newStage === currentStage) return;

    if (newStage === "lost") {
      setPendingStage(newStage);
      setLostDialogOpen(true);
      return;
    }

    await updateStage(newStage);
  };

  const updateStage = async (stage: Stage, lost_reason?: string) => {
    setLoading(true);
    try {
      const token = session?.access_token;
      if (!token) throw new Error("Not authenticated");

      const res = await fetch(`/api/renewals/${renewalId}/stage`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ stage, lost_reason }),
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error ?? "Failed to update stage");

      toast.success(`Stage updated to ${stage}`);
      onStageUpdated?.(stage);
    } catch (err: any) {
      toast.error(err.message ?? "Failed to update stage");
    } finally {
      setLoading(false);
    }
  };

  const handleLostConfirm = async () => {
    if (!lostReason.trim()) {
      toast.error("Please provide a reason for marking as lost");
      return;
    }
    setLostDialogOpen(false);
    await updateStage("lost", lostReason);
    setLostReason("");
    setPendingStage(null);
  };

  return (
    <>
      <div className="flex items-center gap-2">
        <Select
          value={currentStage}
          onValueChange={(v) => handleStageChange(v as Stage)}
          disabled={loading || isTerminal}
        >
          <SelectTrigger className="w-[140px] h-8 text-xs">
            {loading ? (
              <Loader2 className="w-3 h-3 animate-spin" />
            ) : (
              <SelectValue />
            )}
          </SelectTrigger>
          <SelectContent>
            {STAGES.map((s) => (
              <SelectItem key={s.value} value={s.value} className="text-xs">
                {s.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <Dialog open={lostDialogOpen} onOpenChange={setLostDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="font-heading uppercase tracking-wider">
              Mark as Lost
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-3">
            <Label htmlFor="lost-reason">Reason for Loss *</Label>
            <Textarea
              id="lost-reason"
              placeholder="e.g., Customer chose competitor, price too high, no response..."
              value={lostReason}
              onChange={(e) => setLostReason(e.target.value)}
              rows={3}
            />
          </div>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setLostDialogOpen(false);
                setLostReason("");
                setPendingStage(null);
              }}
            >
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={handleLostConfirm}
              disabled={!lostReason.trim()}
            >
              Confirm Lost
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { motion } from "framer-motion";
import { toast } from "sonner";
import {
  Phone,
  CheckCircle2,
  XCircle,
  AlertCircle,
  CalendarClock,
  MessageSquare,
  Loader2,
} from "lucide-react";

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

import { renewalService } from "@/lib/services/renewal.service";
import { auditLogService } from "@/lib/services/audit-log.service";

import { useAuth } from "@/lib/context/auth-context";
import { invalidateRenewals } from "@/lib/hooks/use-renewals";
import { friendlyError } from "@/lib/helpers/friendly-error";
import {
  renewalUpdateSchema,
  RENEWAL_STATUSES,
  type RenewalUpdateFormData,
} from "@/lib/validations/renewal";
import type { Renewal, RenewalStatus } from "@/lib/types";

// ---- Status Update Dialog ----

interface StatusUpdateDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  renewal: Renewal | null;
  onSuccess?: () => void;
}

export function StatusUpdateDialog({
  open,
  onOpenChange,
  renewal,
  onSuccess,
}: StatusUpdateDialogProps) {
  const { user } = useAuth();
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [status, setStatus] = useState<RenewalStatus>(
    renewal?.status || "due"
  );
  const [notes, setNotes] = useState(renewal?.notes || "");

  // Reset when renewal changes or dialog opens
  useEffect(() => {
    if (renewal && open) {
      setStatus(renewal.status);
      setNotes(renewal.notes || "");
    }
  }, [renewal, open]);

  const canUpdate = user?.role === "admin" || user?.role === "manager";

  async function handleSave() {
    if (!renewal || !user || !canUpdate) return;
    setIsSubmitting(true);

    try {
      await renewalService.updateStatus(
        renewal.id,
        status,
        user.uid,
        notes || undefined
      );
      toast.success(`Renewal marked as "${status}"`);
      invalidateRenewals();
      auditLogService.logAction(
        user.uid, user.name || "", "update", "renewals",
        `Updated renewal ${renewal.id} status to ${status}`
      ).catch(() => {});
      onSuccess?.();
      onOpenChange(false);
    } catch (err: any) {
      console.error("Renewal update error:", err);
      toast.error(friendlyError(err, "Failed to update renewal"));
    } finally {
      setIsSubmitting(false);
    }
  }

  if (!renewal) return null;

  const dueDate = renewal.due_date ? new Date(renewal.due_date) : undefined;
  const isOverdue = dueDate && dueDate < new Date();

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <CalendarClock className="h-5 w-5 text-primary" />
            Update Renewal Status
          </DialogTitle>
          <DialogDescription>
            {renewal.policy_number} — {renewal.customer_name}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          {/* Current info */}
          <div className="rounded-lg border border-muted-foreground/20 bg-card p-3">
            <div className="grid grid-cols-2 gap-2 text-sm">
              <div>
                <span className="text-muted-foreground">Due Date:</span>
                <p className="font-medium text-foreground">
                  {dueDate?.toLocaleDateString("en-IN", {
                    day: "2-digit",
                    month: "short",
                    year: "numeric",
                  })}
                </p>
              </div>
              <div>
                <span className="text-muted-foreground">Status:</span>
                <div className="mt-0.5">
                  <Badge
                    style={{
                      backgroundColor: `${
                        RENEWAL_STATUSES.find((s) => s.value === renewal.status)
                          ?.color || "#5D5D5D"
                      }20`,
                      color:
                        RENEWAL_STATUSES.find((s) => s.value === renewal.status)
                          ?.color || "#5D5D5D",
                    }}
                  >
                    {renewal.status}
                  </Badge>
                  {isOverdue && renewal.status !== "renewed" && renewal.status !== "lost" && (
                    <Badge variant="destructive" className="ml-1 text-xs">
                      Overdue
                    </Badge>
                  )}
                </div>
              </div>
            </div>
          </div>

          {/* New status */}
          <div className="space-y-2">
            <Label>New Status</Label>
            <Select
              value={status}
              onValueChange={(v) => setStatus(v as RenewalStatus)}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {RENEWAL_STATUSES.map((s) => (
                  <SelectItem key={s.value} value={s.value}>
                    <span className="flex items-center gap-2">
                      <span
                        className="h-2 w-2 rounded-full"
                        style={{ backgroundColor: s.color }}
                      />
                      {s.label}
                    </span>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Notes */}
          <div className="space-y-2">
            <Label>Notes (optional)</Label>
            <Textarea
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              placeholder="e.g. Called customer, will renew next week..."
              rows={3}
              maxLength={500}
              className="resize-none"
            />
            <p className="text-xs text-muted-foreground">{notes.length}/500</p>
          </div>

          {/* Actions */}
          <div className="flex justify-end gap-2">
            {!canUpdate && (
              <p className="text-sm text-muted-foreground self-center mr-auto">
                Only admin/manager can update renewals
              </p>
            )}
            <Button
              variant="outline"
              onClick={() => onOpenChange(false)}
              disabled={isSubmitting}
            >
              Cancel
            </Button>
            <Button
              onClick={handleSave}
              disabled={isSubmitting || !canUpdate}
              className="bg-primary text-primary-foreground hover:bg-primary/90"
            >
              {isSubmitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Save
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

// ---- Quick Action Buttons ----

interface QuickActionsProps {
  renewal: Renewal;
  onStatusChange?: () => void;
}

export function RenewalQuickActions({
  renewal,
  onStatusChange,
}: QuickActionsProps) {
  const { user } = useAuth();
  const [loading, setLoading] = useState<string | null>(null);
  const canUpdate = user?.role === "admin" || user?.role === "manager";

  async function quickUpdate(newStatus: RenewalStatus) {
    if (!user) return;
    setLoading(newStatus);
    try {
      await renewalService.updateStatus(renewal.id, newStatus, user.uid);
      toast.success(`Marked as "${newStatus}"`);
      invalidateRenewals();
      auditLogService.logAction(
        user.uid, user.name || "", "update", "renewals",
        `Quick-action: marked renewal ${renewal.id} as ${newStatus}`
      ).catch(() => {});
      onStatusChange?.();
    } catch (err: any) {
      toast.error(friendlyError(err, "Update failed"));
    } finally {
      setLoading(null);
    }
  }

  if (renewal.status === "renewed" || renewal.status === "lost") {
    return null; // No actions for terminal states
  }

  // Only admin/manager can update renewals (matches RLS policies)
  if (!canUpdate) return null;

  return (
    <div className="flex items-center gap-1">
      {renewal.status === "due" && (
        <Button
          variant="ghost"
          size="sm"
          className="h-7 gap-1 text-xs text-blue-400 hover:text-blue-300"
          onClick={() => quickUpdate("contacted")}
          disabled={!!loading}
        >
          {loading === "contacted" ? (
            <Loader2 className="h-3 w-3 animate-spin" />
          ) : (
            <Phone className="h-3 w-3" />
          )}
          Contacted
        </Button>
      )}
      <Button
        variant="ghost"
        size="sm"
        className="h-7 gap-1 text-xs text-green-400 hover:text-green-300"
        onClick={() => quickUpdate("renewed")}
        disabled={!!loading}
      >
        {loading === "renewed" ? (
          <Loader2 className="h-3 w-3 animate-spin" />
        ) : (
          <CheckCircle2 className="h-3 w-3" />
        )}
        Renewed
      </Button>
      <Button
        variant="ghost"
        size="sm"
        className="h-7 gap-1 text-xs text-red-400 hover:text-red-300"
        onClick={() => quickUpdate("lost")}
        disabled={!!loading}
      >
        {loading === "lost" ? (
          <Loader2 className="h-3 w-3 animate-spin" />
        ) : (
          <XCircle className="h-3 w-3" />
        )}
        Lost
      </Button>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { Loader2, Plus, Save } from "lucide-react";
import { toast } from "sonner";

import { updateLead, checkDuplicateLead } from "@/lib/services/lead.service";
import { auditLogService } from "@/lib/services/audit-log.service";
import { useAuth } from "@/lib/context/auth-context";
import { getAccessToken } from "@/lib/services/auth.service";
import { invalidateLeads } from "@/lib/hooks/use-leads";
import { useActiveUsers } from "@/lib/hooks/use-settings";
import { friendlyError } from "@/lib/helpers/friendly-error";
import {
  leadSchema,
  LeadFormData,
  LEAD_SOURCE_OPTIONS,
  LEAD_PRIORITY_OPTIONS,
  LEAD_STATUS_OPTIONS,
  CLIENT_TYPE_OPTIONS,
} from "@/lib/validations/lead";
import { SalesLead } from "@/lib/types";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";

interface LeadFormProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  editData?: SalesLead | null;
  onSuccess?: (lead: SalesLead) => void;
}

export function LeadForm({ open, onOpenChange, editData, onSuccess }: LeadFormProps) {
  const { user } = useAuth();
  const { data: users } = useActiveUsers();
  const [saving, setSaving] = useState(false);
  const [duplicateWarning, setDuplicateWarning] = useState<string | null>(null);

  const isEdit = !!editData;

  const form = useForm<LeadFormData>({
    resolver: zodResolver(leadSchema),
    defaultValues: {
      customer_name: "",
      mobile: "",
      alt_mobile: "",
      email: "",
      source: "other",
      assigned_to: "",
      priority: "medium",
      status: "new",
      notes: "",
      follow_up_date: "",
      meeting_date: "",
      poc_name: "",
      location: "",
      client_type: "individual",
      estimated_value: 0,
    },
  });

  // Re-initialize form when editData changes
  useEffect(() => {
    if (open) {
      form.reset({
        customer_name: editData?.customer_name || "",
        mobile: editData?.mobile || "",
        alt_mobile: editData?.alt_mobile || "",
        email: editData?.email || "",
        source: editData?.source || "other",
        assigned_to: editData?.assigned_to || "",
        priority: editData?.priority || "medium",
        status: editData?.status || "new",
        notes: editData?.notes || "",
        follow_up_date: editData?.follow_up_date || "",
        meeting_date: editData?.meeting_date || "",
        poc_name: editData?.poc_name || "",
        location: editData?.location || "",
        client_type: editData?.client_type || "individual",
        estimated_value: editData?.estimated_value || 0,
      });
      setDuplicateWarning(null);
    }
  }, [editData, open, form]);

  // Duplicate check on mobile blur
  const handleMobileBlur = async () => {
    const mobile = form.getValues("mobile");
    if (!mobile || mobile.length !== 10 || isEdit) return;
    try {
      const duplicates = await checkDuplicateLead(mobile);
      if (duplicates.length > 0) {
        setDuplicateWarning(
          `Possible duplicate: ${duplicates.map((d) => `${d.lead_number} (${d.customer_name})`).join(", ")}`
        );
      } else {
        setDuplicateWarning(null);
      }
    } catch {
      // non-critical
    }
  };

  const onSubmit = async (data: LeadFormData) => {
    if (!user) return;
    setSaving(true);

    try {
      const assignedUser = users?.find((u) => u.id === data.assigned_to);

      if (isEdit && editData) {
        await updateLead(editData.id, {
          customer_name: data.customer_name,
          mobile: data.mobile,
          alt_mobile: data.alt_mobile || null,
          email: data.email || null,
          source: data.source,
          assigned_to: data.assigned_to,
          assigned_to_name: assignedUser?.name || editData.assigned_to_name,
          priority: data.priority,
          status: data.status || editData.status,
          notes: data.notes || null,
          follow_up_date: data.follow_up_date || null,
          meeting_date: data.meeting_date || null,
          poc_name: data.poc_name || null,
          location: data.location || null,
          client_type: data.client_type || editData.client_type,
          estimated_value: data.estimated_value || 0,
        });
        await auditLogService.logAction(
          user.id,
          user.name,
          "update",
          "sales-leads",
          `Updated lead: ${editData.lead_number} — ${data.customer_name}`
        );
        toast.success("Lead updated successfully");
        invalidateLeads();
        onOpenChange(false);
        onSuccess?.(editData);
      } else {
        // Create via API route (handles notifications, audit, RLS bypass)
        const token = await getAccessToken();
        if (!token) throw new Error("Not authenticated");

        const apiRes = await fetch("/api/leads", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            customer_name: data.customer_name,
            mobile: data.mobile,
            alt_mobile: data.alt_mobile || undefined,
            email: data.email || undefined,
            source: data.source,
            assigned_to: data.assigned_to,
            assigned_to_name: assignedUser?.name,
            priority: data.priority,
            status: data.status,
            notes: data.notes || undefined,
            follow_up_date: data.follow_up_date || undefined,
            meeting_date: data.meeting_date || undefined,
            poc_name: data.poc_name || undefined,
            location: data.location || undefined,
            client_type: data.client_type || undefined,
            estimated_value: data.estimated_value || undefined,
            branch_id: user.branch_id,
          }),
        });

        if (!apiRes.ok) {
          const errBody = await apiRes.json().catch(() => null);
          throw new Error(errBody?.error || "Failed to create lead");
        }

        const result = await apiRes.json();
        toast.success(`Lead created — ${result.lead_number}`);
        invalidateLeads();
        onOpenChange(false);
        onSuccess?.(result);
      }
    } catch (error: unknown) {
      toast.error(friendlyError(error, "Failed to save lead"));
    } finally {
      setSaving(false);
    }
  };

  const handleClose = () => {
    form.reset();
    setDuplicateWarning(null);
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-[640px] max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="font-cabin uppercase tracking-wider">
            {isEdit ? "Edit Lead" : "Add New Lead"}
          </DialogTitle>
          <DialogDescription className="text-muted-foreground">
            {isEdit
              ? `Editing ${editData?.lead_number} — ${editData?.customer_name}`
              : "Fill in the lead details. Lead number will be auto-generated."}
          </DialogDescription>
        </DialogHeader>

        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
            {/* Customer Name */}
            <FormField
              control={form.control}
              name="customer_name"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Customer Name *</FormLabel>
                  <FormControl>
                    <Input placeholder="Full name" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            {/* Mobile + Alt Mobile */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <FormField
                control={form.control}
                name="mobile"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Mobile *</FormLabel>
                    <FormControl>
                      <Input
                        placeholder="10-digit number"
                        {...field}
                        onBlur={() => {
                          field.onBlur();
                          handleMobileBlur();
                        }}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="alt_mobile"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Alt Mobile</FormLabel>
                    <FormControl>
                      <Input placeholder="Optional" {...field} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            {/* Duplicate Warning */}
            {duplicateWarning && (
              <div className="rounded-lg bg-amber-500/10 border border-amber-500/30 px-3 py-2 text-sm text-amber-500">
                {duplicateWarning}
              </div>
            )}

            {/* Email */}
            <FormField
              control={form.control}
              name="email"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Email</FormLabel>
                  <FormControl>
                    <Input placeholder="email@example.com" type="email" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            {/* POC Name + Location */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <FormField
                control={form.control}
                name="poc_name"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>POC Name</FormLabel>
                    <FormControl>
                      <Input placeholder="Point of contact" {...field} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="location"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Location</FormLabel>
                    <FormControl>
                      <Input placeholder="City / Area" {...field} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            {/* Client Type + Estimated Value */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <FormField
                control={form.control}
                name="client_type"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Client Type</FormLabel>
                    <Select onValueChange={field.onChange} value={field.value}>
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue placeholder="Select type" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {CLIENT_TYPE_OPTIONS.map((o) => (
                          <SelectItem key={o.value} value={o.value}>
                            {o.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="estimated_value"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Estimated Value</FormLabel>
                    <FormControl>
                      <Input
                        type="number"
                        min={0}
                        placeholder="0"
                        {...field}
                        onChange={(e) => field.onChange(e.target.valueAsNumber || 0)}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            {/* Source + Priority */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <FormField
                control={form.control}
                name="source"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Source *</FormLabel>
                    <Select onValueChange={field.onChange} value={field.value}>
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue placeholder="Select source" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {LEAD_SOURCE_OPTIONS.map((o) => (
                          <SelectItem key={o.value} value={o.value}>
                            {o.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="priority"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Priority *</FormLabel>
                    <Select onValueChange={field.onChange} value={field.value}>
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue placeholder="Select priority" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {LEAD_PRIORITY_OPTIONS.map((o) => (
                          <SelectItem key={o.value} value={o.value}>
                            {o.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            {/* Assigned To */}
            <FormField
              control={form.control}
              name="assigned_to"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Assigned To *</FormLabel>
                  <Select onValueChange={field.onChange} value={field.value}>
                    <FormControl>
                      <SelectTrigger>
                        <SelectValue placeholder="Select employee" />
                      </SelectTrigger>
                    </FormControl>
                    <SelectContent>
                      {(users ?? []).map((u) => (
                        <SelectItem key={u.id} value={u.id}>
                          {u.name} ({u.role})
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <FormMessage />
                </FormItem>
              )}
            />

            {/* Status (edit mode only) + Follow-Up Date */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              {isEdit && (
                <FormField
                  control={form.control}
                  name="status"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Status</FormLabel>
                      <Select onValueChange={field.onChange} value={field.value}>
                        <FormControl>
                          <SelectTrigger>
                            <SelectValue placeholder="Select status" />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          {LEAD_STATUS_OPTIONS.map((o) => (
                            <SelectItem key={o.value} value={o.value}>
                              {o.label}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              )}
              <FormField
                control={form.control}
                name="follow_up_date"
                render={({ field }) => (
                  <FormItem className={isEdit ? "" : "col-span-2"}>
                    <FormLabel>Follow-Up Date</FormLabel>
                    <FormControl>
                      <Input type="date" {...field} value={field.value ?? ""} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            {/* Meeting Date */}
            <FormField
              control={form.control}
              name="meeting_date"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Date of Meeting</FormLabel>
                  <FormControl>
                    <Input type="date" {...field} value={field.value ?? ""} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            {/* Notes */}
            <FormField
              control={form.control}
              name="notes"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Notes</FormLabel>
                  <FormControl>
                    <Textarea
                      placeholder="Any initial observations..."
                      rows={3}
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            {/* Actions */}
            <div className="flex justify-end gap-3 pt-2">
              <Button type="button" variant="ghost" onClick={handleClose} disabled={saving}>
                Cancel
              </Button>
              <Button type="submit" disabled={saving} className="gap-2">
                {saving ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : isEdit ? (
                  <Save className="w-4 h-4" />
                ) : (
                  <Plus className="w-4 h-4" />
                )}
                {saving ? "Saving..." : isEdit ? "Update Lead" : "Create Lead"}
              </Button>
            </div>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Loader2, Ticket, CheckCircle } from "lucide-react";
import { toast } from "sonner";
import { useRouter } from "next/navigation";

import { useAuth } from "@/lib/context/auth-context";
import { useCustomerSearch } from "@/lib/hooks/use-customers";
import { usePoliciesByCustomer } from "@/lib/hooks/use-policies";

import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";

const CATEGORIES = [
  { value: "ecard_request",      label: "E-Card Request" },
  { value: "member_endorsement", label: "Member Endorsement" },
  { value: "name_correction",    label: "Name Correction" },
  { value: "address_correction", label: "Address Correction" },
  { value: "invoice_dispute",    label: "Invoice Dispute" },
  { value: "claim_assistance",   label: "Claim Assistance" },
  { value: "general_query",      label: "General Query" },
];

const PRIORITIES = [
  { value: "low",    label: "Low" },
  { value: "medium", label: "Medium" },
  { value: "high",   label: "High" },
  { value: "urgent", label: "Urgent" },
];

const schema = z.object({
  category:       z.string().min(1, "Category is required"),
  priority:       z.string().min(1, "Priority is required"),
  description:    z.string().min(5, "Description must be at least 5 characters"),
  internal_notes: z.string().optional(),
});

type FormData = {
  category: string;
  priority: string;
  description: string;
  internal_notes?: string;
};

interface CreateTicketDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  prefillCustomerId?: string;
  prefillCustomerName?: string;
  prefillPolicyId?: string;
  prefillPolicyNumber?: string;
}

export function CreateTicketDialog({
  open,
  onOpenChange,
  prefillCustomerId,
  prefillCustomerName,
  prefillPolicyId,
  prefillPolicyNumber,
}: CreateTicketDialogProps) {
  const router = useRouter();
  const { session } = useAuth();
  const [saving, setSaving] = useState(false);
  const [created, setCreated] = useState<{ ticket_number: string; id: string; sla_hours: number } | null>(null);

  // Customer search (only needed when no prefill)
  const [customerSearch, setCustomerSearch] = useState("");
  const [selectedCustomerId, setSelectedCustomerId] = useState(prefillCustomerId || "");
  const [selectedPolicyId, setSelectedPolicyId] = useState(prefillPolicyId || "");

  const { data: searchResults } = useCustomerSearch(
    !prefillCustomerId && customerSearch.length >= 2 ? customerSearch : ""
  );
  const { data: policies } = usePoliciesByCustomer(
    !prefillPolicyId && selectedCustomerId ? selectedCustomerId : null
  );

  const form = useForm<FormData>({
    resolver: zodResolver(schema),
    defaultValues: { category: "", priority: "medium", description: "", internal_notes: "" },
  });

  const onSubmit = async (data: FormData) => {
    const custId = prefillCustomerId || selectedCustomerId;
    if (!custId) {
      toast.error("Please select a customer");
      return;
    }

    setSaving(true);
    try {
      const token = session?.access_token;
      const res = await fetch("/api/service-desk/tickets", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
        body: JSON.stringify({
          customer_id: custId,
          policy_id: prefillPolicyId || selectedPolicyId || null,
          category: data.category,
          priority: data.priority,
          description: data.description,
          internal_notes: data.internal_notes || null,
        }),
      });

      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || "Failed to create ticket");
      }

      const ticket = await res.json();
      setCreated(ticket);
      toast.success(`Ticket ${ticket.ticket_number} created`);
    } catch (err: any) {
      toast.error(err.message || "Failed to create ticket");
    } finally {
      setSaving(false);
    }
  };

  const handleClose = () => {
    form.reset();
    setCreated(null);
    setCustomerSearch("");
    setSelectedCustomerId(prefillCustomerId || "");
    setSelectedPolicyId(prefillPolicyId || "");
    onOpenChange(false);
  };

  const handleViewTicket = () => {
    if (created) {
      router.push(`/dashboard/service-desk/${created.id}`);
      handleClose();
    }
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-lg max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="font-heading uppercase tracking-wider flex items-center gap-2">
            <Ticket className="w-5 h-5 text-primary" />
            Create Service Ticket
          </DialogTitle>
          <DialogDescription>
            {prefillCustomerName
              ? `Creating ticket for ${prefillCustomerName}${prefillPolicyNumber ? ` · Policy ${prefillPolicyNumber}` : ""}`
              : "Log a new service request"}
          </DialogDescription>
        </DialogHeader>

        {created ? (
          // Success state
          <div className="py-6 flex flex-col items-center gap-4 text-center">
            <div className="w-16 h-16 rounded-full bg-green-500/10 flex items-center justify-center">
              <CheckCircle className="w-8 h-8 text-green-400" />
            </div>
            <div>
              <p className="font-heading font-bold text-lg uppercase tracking-wider">Ticket Created</p>
              <Badge variant="secondary" className="font-mono text-primary bg-primary/10 mt-2 text-base px-4 py-1">
                {created.ticket_number}
              </Badge>
              <p className="text-sm text-muted-foreground mt-2">
                SLA: {created.sla_hours}h from creation
              </p>
            </div>
            <div className="flex gap-3 mt-2">
              <Button variant="outline" onClick={handleClose}>Close</Button>
              <Button onClick={handleViewTicket}>View Ticket</Button>
            </div>
          </div>
        ) : (
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4 py-2">
            {/* Customer selection (only if no prefill) */}
            {!prefillCustomerId && (
              <div className="space-y-1.5">
                <Label>Customer <span className="text-destructive">*</span></Label>
                <Input
                  placeholder="Search customer by name or phone..."
                  value={customerSearch}
                  onChange={e => setCustomerSearch(e.target.value)}
                />
                {searchResults && searchResults.length > 0 && !selectedCustomerId && (
                  <div className="border border-border rounded-lg overflow-hidden max-h-40 overflow-y-auto">
                    {searchResults.map(c => (
                      <button
                        key={c.id}
                        type="button"
                        onClick={() => {
                          setSelectedCustomerId(c.id);
                          setCustomerSearch(c.name);
                        }}
                        className="w-full text-left px-3 py-2 hover:bg-muted/50 text-sm flex items-center gap-2"
                      >
                        <Badge variant="secondary" className="font-mono text-xs">{c.uid}</Badge>
                        {c.name}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            )}

            {/* Policy selection (only if no prefill and customer selected) */}
            {!prefillPolicyId && selectedCustomerId && (
              <div className="space-y-1.5">
                <Label>Policy (optional)</Label>
                <Select value={selectedPolicyId} onValueChange={setSelectedPolicyId}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select policy (optional)" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="">No policy</SelectItem>
                    {(policies ?? []).map(p => (
                      <SelectItem key={p.id} value={p.id}>
                        {p.policy_number} · {p.policy_type?.replace(/_/g, " ")}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}

            {/* Category */}
            <div className="space-y-1.5">
              <Label>Category <span className="text-destructive">*</span></Label>
              <Select
                value={form.watch("category")}
                onValueChange={v => form.setValue("category", v, { shouldValidate: true })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select category" />
                </SelectTrigger>
                <SelectContent>
                  {CATEGORIES.map(c => (
                    <SelectItem key={c.value} value={c.value}>{c.label}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {form.formState.errors.category && (
                <p className="text-xs text-destructive">{form.formState.errors.category.message}</p>
              )}
            </div>

            {/* Priority */}
            <div className="space-y-1.5">
              <Label>Priority</Label>
              <Select
                value={form.watch("priority")}
                onValueChange={v => form.setValue("priority", v)}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {PRIORITIES.map(p => (
                    <SelectItem key={p.value} value={p.value}>{p.label}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Description */}
            <div className="space-y-1.5">
              <Label>Description <span className="text-destructive">*</span></Label>
              <Textarea
                placeholder="Describe the issue or request..."
                rows={3}
                {...form.register("description")}
              />
              {form.formState.errors.description && (
                <p className="text-xs text-destructive">{form.formState.errors.description.message}</p>
              )}
            </div>

            {/* Internal notes */}
            <div className="space-y-1.5">
              <Label>Internal Notes <span className="text-xs text-muted-foreground">(staff only)</span></Label>
              <Textarea
                placeholder="Notes visible only to staff..."
                rows={2}
                {...form.register("internal_notes")}
              />
            </div>

            <div className="flex justify-end gap-3 pt-2">
              <Button type="button" variant="ghost" onClick={handleClose}>Cancel</Button>
              <Button type="submit" disabled={saving} className="gap-2">
                {saving && <Loader2 className="w-4 h-4 animate-spin" />}
                {saving ? "Creating..." : "Create Ticket"}
              </Button>
            </div>
          </form>
        )}
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod/v4";
import { toast } from "sonner";
import { Loader2, Search, X, Paperclip } from "lucide-react";

import { useAuth } from "@/lib/context/auth-context";
import { supabase } from "@/lib/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Badge } from "@/components/ui/badge";

const CATEGORIES = [
  { value: "ecard_request", label: "E-Card Request" },
  { value: "member_endorsement", label: "Member Endorsement" },
  { value: "name_correction", label: "Name Correction" },
  { value: "address_correction", label: "Address Correction" },
  { value: "invoice_dispute", label: "Invoice Dispute" },
  { value: "claim_assistance", label: "Claim Assistance" },
  { value: "general_query", label: "General Query" },
  { value: "validity_renewal", label: "Validity Renewal" },
  { value: "vehicle_endorsement", label: "Vehicle Endorsement" },
  { value: "policy_query", label: "Policy Query" },
  { value: "document_request", label: "Document Request" },
];

const PRIORITIES = [
  { value: "urgent", label: "Urgent" },
  { value: "high", label: "High" },
  { value: "medium", label: "Medium" },
  { value: "low", label: "Low" },
];

const schema = z.object({
  customer_id: z.string().min(1, "Customer is required"),
  policy_id: z.string().optional(),
  category: z.string().min(1, "Category is required"),
  priority: z.string().min(1, "Priority is required"),
  description: z.string().min(10, "Description must be at least 10 characters"),
  internal_notes: z.string().optional(),
  template_id: z.string().optional(),
});

type FormValues = z.infer<typeof schema>;

interface CreateTicketFormProps {
  prefillCustomerId?: string;
  prefillCustomerName?: string;
  prefillPolicyId?: string;
  prefillPolicyNumber?: string;
  onSuccess?: (ticketId: string, ticketNumber: string, slaDeadline: string) => void;
  onCancel?: () => void;
}

export function CreateTicketForm({
  prefillCustomerId,
  prefillCustomerName,
  prefillPolicyId,
  prefillPolicyNumber,
  onSuccess,
  onCancel,
}: CreateTicketFormProps) {
  const { session } = useAuth();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [customerSearch, setCustomerSearch] = useState(prefillCustomerName ?? "");
  const [customerResults, setCustomerResults] = useState<Array<{ id: string; name: string; phone: string }>>([]);
  const [selectedCustomer, setSelectedCustomer] = useState<{ id: string; name: string } | null>(
    prefillCustomerId ? { id: prefillCustomerId, name: prefillCustomerName ?? "" } : null
  );
  const [policies, setPolicies] = useState<Array<{ id: string; policy_number: string; policy_type: string }>>([]);
  const [attachments, setAttachments] = useState<File[]>([]);
  const [templates, setTemplates] = useState<Array<{ id: string; name: string; category: string; priority: string; description_template: string }>>([]);

  const form = useForm<FormValues>({
    resolver: zodResolver(schema),
    defaultValues: {
      customer_id: prefillCustomerId ?? "",
      policy_id: prefillPolicyId ?? "",
      category: "",
      priority: "medium",
      description: "",
      internal_notes: "",
      template_id: "",
    },
  });

  // Search customers
  useEffect(() => {
    if (prefillCustomerId) return;
    if (!customerSearch.trim() || customerSearch.length < 2) {
      setCustomerResults([]);
      return;
    }
    const timer = setTimeout(async () => {
      const { data } = await supabase
        .from("customers")
        .select("id, name, phone")
        .ilike("name", `%${customerSearch}%`)
        .limit(10);
      setCustomerResults(data ?? []);
    }, 300);
    return () => clearTimeout(timer);
  }, [customerSearch, prefillCustomerId]);

  // Fetch policies when customer selected
  useEffect(() => {
    if (!selectedCustomer) {
      setPolicies([]);
      return;
    }
    supabase
      .from("policies")
      .select("id, policy_number, policy_type")
      .eq("customer_id", selectedCustomer.id)
      .eq("status", "active")
      .then(({ data }) => setPolicies(data ?? []));
  }, [selectedCustomer]);

  // Fetch templates
  useEffect(() => {
    supabase
      .from("ticket_templates")
      .select("id, name, category, priority, description_template")
      .eq("is_active", true)
      .then(({ data }) => setTemplates(data ?? []));
  }, []);

  const handleTemplateSelect = (templateId: string) => {
    const template = templates.find(t => t.id === templateId);
    if (!template) return;
    form.setValue("template_id", templateId);
    form.setValue("category", template.category);
    form.setValue("priority", template.priority);
    if (template.description_template) {
      form.setValue("description", template.description_template);
    }
  };

  const handleCustomerSelect = (customer: { id: string; name: string }) => {
    setSelectedCustomer(customer);
    setCustomerSearch(customer.name);
    setCustomerResults([]);
    form.setValue("customer_id", customer.id);
    form.setValue("policy_id", "");
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files ?? []);
    setAttachments(prev => [...prev, ...files]);
  };

  const removeAttachment = (index: number) => {
    setAttachments(prev => prev.filter((_, i) => i !== index));
  };

  const onSubmit = async (values: FormValues) => {
    if (!session?.access_token) {
      toast.error("Not authenticated");
      return;
    }

    setIsSubmitting(true);
    try {
      const res = await fetch("/api/service-desk/tickets", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${session.access_token}`,
        },
        body: JSON.stringify(values),
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error ?? "Failed to create ticket");

      // Upload attachments
      if (attachments.length > 0) {
        for (const file of attachments) {
          const formData = new FormData();
          formData.append("file", file);
          await fetch(`/api/service-desk/tickets/${data.id}/documents`, {
            method: "POST",
            headers: { Authorization: `Bearer ${session.access_token}` },
            body: formData,
          });
        }
      }

      toast.success(`Ticket ${data.ticket_number} created successfully`);
      onSuccess?.(data.id, data.ticket_number, data.sla_deadline);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to create ticket");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
        {/* Template selector */}
        {templates.length > 0 && (
          <div className="space-y-1.5">
            <Label className="text-xs text-muted-foreground uppercase tracking-wider">
              Template (optional)
            </Label>
            <Select onValueChange={handleTemplateSelect}>
              <SelectTrigger>
                <SelectValue placeholder="Select a template..." />
              </SelectTrigger>
              <SelectContent>
                {templates.map(t => (
                  <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        )}

        {/* Customer search */}
        {!prefillCustomerId ? (
          <FormField
            control={form.control}
            name="customer_id"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Customer *</FormLabel>
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                  <Input
                    placeholder="Search customer by name..."
                    value={customerSearch}
                    onChange={e => setCustomerSearch(e.target.value)}
                    className="pl-9"
                  />
                  {customerResults.length > 0 && (
                    <div className="absolute top-full left-0 right-0 z-50 mt-1 bg-card border border-border rounded-xl shadow-lg overflow-hidden">
                      {customerResults.map(c => (
                        <button
                          key={c.id}
                          type="button"
                          onClick={() => handleCustomerSelect(c)}
                          className="w-full flex items-center gap-3 px-3 py-2 hover:bg-muted/30 text-left text-sm"
                        >
                          <div>
                            <p className="font-medium">{c.name}</p>
                            <p className="text-xs text-muted-foreground">{c.phone}</p>
                          </div>
                        </button>
                      ))}
                    </div>
                  )}
                </div>
                <FormMessage />
              </FormItem>
            )}
          />
        ) : (
          <div className="space-y-1.5">
            <Label>Customer</Label>
            <div className="flex items-center gap-2 px-3 py-2 bg-muted/30 rounded-lg border border-border">
              <span className="text-sm font-medium">{prefillCustomerName}</span>
              <Badge variant="secondary" className="text-xs">Pre-filled</Badge>
            </div>
          </div>
        )}

        {/* Policy selector */}
        {!prefillPolicyId && selectedCustomer && policies.length > 0 && (
          <FormField
            control={form.control}
            name="policy_id"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Policy (optional)</FormLabel>
                <Select onValueChange={field.onChange} value={field.value}>
                  <FormControl>
                    <SelectTrigger>
                      <SelectValue placeholder="Select a policy..." />
                    </SelectTrigger>
                  </FormControl>
                  <SelectContent>
                    {policies.map(p => (
                      <SelectItem key={p.id} value={p.id}>
                        {p.policy_number} ({p.policy_type})
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <FormMessage />
              </FormItem>
            )}
          />
        )}

        {prefillPolicyId && (
          <div className="space-y-1.5">
            <Label>Policy</Label>
            <div className="flex items-center gap-2 px-3 py-2 bg-muted/30 rounded-lg border border-border">
              <span className="text-sm font-medium">{prefillPolicyNumber}</span>
              <Badge variant="secondary" className="text-xs">Pre-filled</Badge>
            </div>
          </div>
        )}

        {/* Category */}
        <FormField
          control={form.control}
          name="category"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Category *</FormLabel>
              <Select onValueChange={field.onChange} value={field.value}>
                <FormControl>
                  <SelectTrigger>
                    <SelectValue placeholder="Select category..." />
                  </SelectTrigger>
                </FormControl>
                <SelectContent>
                  {CATEGORIES.map(c => (
                    <SelectItem key={c.value} value={c.value}>{c.label}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <FormMessage />
            </FormItem>
          )}
        />

        {/* Priority */}
        <FormField
          control={form.control}
          name="priority"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Priority *</FormLabel>
              <Select onValueChange={field.onChange} value={field.value}>
                <FormControl>
                  <SelectTrigger>
                    <SelectValue placeholder="Select priority..." />
                  </SelectTrigger>
                </FormControl>
                <SelectContent>
                  {PRIORITIES.map(p => (
                    <SelectItem key={p.value} value={p.value}>{p.label}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <FormMessage />
            </FormItem>
          )}
        />

        {/* Description */}
        <FormField
          control={form.control}
          name="description"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Description *</FormLabel>
              <FormControl>
                <Textarea
                  placeholder="Describe the issue in detail..."
                  rows={4}
                  {...field}
                />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        {/* Internal notes */}
        <FormField
          control={form.control}
          name="internal_notes"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Internal Notes (optional)</FormLabel>
              <FormControl>
                <Textarea
                  placeholder="Notes visible only to staff..."
                  rows={2}
                  {...field}
                />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        {/* Attachments */}
        <div className="space-y-2">
          <Label>Attachments (optional)</Label>
          <div className="flex items-center gap-2">
            <label className="cursor-pointer">
              <input
                type="file"
                multiple
                accept=".pdf,.jpg,.jpeg,.png,.docx,.xlsx"
                onChange={handleFileChange}
                className="hidden"
              />
              <div className="flex items-center gap-2 px-3 py-2 border border-dashed border-border rounded-lg hover:bg-muted/30 transition-colors text-sm text-muted-foreground">
                <Paperclip className="w-4 h-4" />
                Attach files
              </div>
            </label>
          </div>
          {attachments.length > 0 && (
            <div className="space-y-1">
              {attachments.map((file, i) => (
                <div key={i} className="flex items-center justify-between px-3 py-1.5 bg-muted/30 rounded-lg text-sm">
                  <span className="truncate">{file.name}</span>
                  <button type="button" onClick={() => removeAttachment(i)}>
                    <X className="w-4 h-4 text-muted-foreground hover:text-foreground" />
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Actions */}
        <div className="flex gap-2 pt-2">
          {onCancel && (
            <Button type="button" variant="outline" onClick={onCancel} className="flex-1">
              Cancel
            </Button>
          )}
          <Button type="submit" disabled={isSubmitting} className="flex-1">
            {isSubmitting && <Loader2 className="w-4 h-4 animate-spin mr-2" />}
            Create Ticket
          </Button>
        </div>
      </form>
    </Form>
  );
}

"use client";

import { useState, useEffect, useCallback, useRef } from "react";
import { useRouter } from "next/navigation";
import { motion } from "framer-motion";
import { Plus, RefreshCw, Download, Users2 } from "lucide-react";
import { toast } from "sonner";
import useSWR from "swr";

import { useAuth } from "@/lib/context/auth-context";
import { pageTransition } from "@/lib/helpers/animations";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";

import { TicketQueueTabs, type QueueType } from "./TicketQueueTabs";
import { TicketMetricsBar } from "./TicketMetricsBar";
import { TicketListTable } from "./TicketListTable";
import { TicketFilters, type TicketFiltersState } from "./TicketFilters";

const DEFAULT_FILTERS: TicketFiltersState = {
  search: "",
  category: "",
  priority: "",
  status: "",
  assignedTo: "",
  customerId: "",
  policyId: "",
  breachedOnly: false,
  escalatedOnly: false,
  includeArchived: false,
};

async function fetchTickets(url: string, token: string) {
  const res = await fetch(url, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) throw new Error("Failed to fetch tickets");
  return res.json();
}

async function fetchMetrics(url: string, token: string) {
  const res = await fetch(url, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) throw new Error("Failed to fetch metrics");
  return res.json();
}

export function ServiceDeskDashboard() {
  const router = useRouter();
  const { session, role } = useAuth();
  const token = session?.access_token ?? "";

  const [activeQueue, setActiveQueue] = useState<QueueType>("my");
  const [filters, setFilters] = useState<TicketFiltersState>(DEFAULT_FILTERS);
  const [page, setPage] = useState(1);
  const [sort, setSort] = useState({ field: "created_at", order: "desc" as "asc" | "desc" });
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const searchDebounceRef = useRef<NodeJS.Timeout | null>(null);
  const [debouncedSearch, setDebouncedSearch] = useState("");

  // Build query params
  const buildQueryParams = useCallback(() => {
    const params = new URLSearchParams();
    params.set("queue", activeQueue);
    params.set("page", String(page));
    params.set("limit", "25");
    params.set("sort", sort.field);
    params.set("order", sort.order);
    if (debouncedSearch) params.set("search", debouncedSearch);
    if (filters.category) params.set("category", filters.category);
    if (filters.priority) params.set("priority", filters.priority);
    if (filters.status) params.set("status", filters.status);
    if (filters.assignedTo) params.set("assigned_to", filters.assignedTo);
    if (filters.customerId) params.set("customer_id", filters.customerId);
    if (filters.policyId) params.set("policy_id", filters.policyId);
    if (filters.breachedOnly) params.set("breached_only", "true");
    if (filters.escalatedOnly) params.set("escalated_only", "true");
    if (filters.includeArchived) params.set("include_archived", "true");
    return params.toString();
  }, [activeQueue, page, sort, debouncedSearch, filters]);

  const ticketsKey = token ? `/api/service-desk/tickets?${buildQueryParams()}` : null;
  const metricsKey = token ? `/api/service-desk/metrics` : null;

  const { data: ticketsData, isLoading: ticketsLoading, mutate: mutateTickets } = useSWR(
    ticketsKey,
    (url: string) => fetchTickets(url, token),
    { revalidateOnFocus: false, keepPreviousData: true }
  );

  const { data: metricsData, isLoading: metricsLoading } = useSWR(
    metricsKey,
    (url: string) => fetchMetrics(url, token),
    { revalidateOnFocus: false, refreshInterval: 60000 }
  );

  // Debounce search
  const handleSearchChange = (search: string) => {
    setFilters(prev => ({ ...prev, search }));
    if (searchDebounceRef.current) clearTimeout(searchDebounceRef.current);
    searchDebounceRef.current = setTimeout(() => {
      setDebouncedSearch(search);
      setPage(1);
    }, 300);
  };

  const handleSortChange = (field: string) => {
    setSort(prev => ({
      field,
      order: prev.field === field && prev.order === "desc" ? "asc" : "desc",
    }));
    setPage(1);
  };

  const handleQueueChange = (queue: QueueType) => {
    setActiveQueue(queue);
    setPage(1);
    setSelectedIds([]);
    // Persist in localStorage
    try {
      localStorage.setItem("service_desk_queue", queue);
    } catch { /* ignore */ }
  };

  // Restore queue preference
  useEffect(() => {
    try {
      const saved = localStorage.getItem("service_desk_queue") as QueueType | null;
      if (saved && ["my", "team", "unassigned", "all"].includes(saved)) {
        setActiveQueue(saved);
      }
    } catch { /* ignore */ }
  }, []);

  const handleExport = async () => {
    if (!token) return;
    try {
      const res = await fetch("/api/service-desk/tickets/bulk", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          operation: "export",
          ticket_ids: ticketsData?.data?.map((t: { id: string }) => t.id) ?? [],
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error);

      // Convert to CSV
      const tickets = data.data ?? [];
      if (tickets.length === 0) {
        toast.info("No tickets to export");
        return;
      }

      const headers = ["Ticket #", "Customer", "Category", "Priority", "Status", "SLA Deadline", "Created", "Resolved", "Owner"];
      const rows = tickets.map((t: Record<string, unknown>) => [
        t.ticket_number,
        (t.customers as { name: string } | null)?.name ?? "",
        t.category,
        t.priority,
        t.status,
        t.sla_deadline ?? "",
        t.created_at,
        t.resolved_at ?? "",
        (t.owner as { name: string } | null)?.name ?? "",
      ]);

      const csv = [headers, ...rows].map(r => r.map((v: unknown) => `"${v}"`).join(",")).join("\n");
      const blob = new Blob([csv], { type: "text/csv" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `tickets-${new Date().toISOString().split("T")[0]}.csv`;
      a.click();
      URL.revokeObjectURL(url);
      toast.success(`Exported ${tickets.length} tickets`);
    } catch (err) {
      toast.error("Export failed");
    }
  };

  const tickets = ticketsData?.data ?? [];
  const total = ticketsData?.total ?? 0;
  const totalPages = Math.ceil(total / 25);

  const metrics = metricsData ?? {
    status_counts: {},
    overdue_count: 0,
    sla_on_time_rate: 100,
    avg_resolution_minutes: 0,
    breach_count: 0,
  };

  return (
    <motion.div {...pageTransition} className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-heading font-bold text-foreground uppercase tracking-wider flex items-center gap-2">
            <Users2 className="w-6 h-6 text-primary" />
            Service Desk
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            {total} tickets · {metrics.overdue_count} overdue
          </p>
        </div>
        <div className="flex gap-2 flex-wrap">
          <Button variant="outline" size="sm" onClick={() => mutateTickets()} className="gap-2">
            <RefreshCw className="w-4 h-4" />
            Refresh
          </Button>
          <Button variant="outline" size="sm" onClick={handleExport} className="gap-2">
            <Download className="w-4 h-4" />
            Export
          </Button>
          <Button size="sm" onClick={() => router.push("/dashboard/service-desk/new")} className="gap-2">
            <Plus className="w-4 h-4" />
            New Ticket
          </Button>
        </div>
      </div>

      {/* Metrics Bar */}
      <TicketMetricsBar
        statusCounts={metrics.status_counts}
        overdueCount={metrics.overdue_count}
        slaOnTimeRate={metrics.sla_on_time_rate}
        avgResolutionMinutes={metrics.avg_resolution_minutes}
        breachCount={metrics.breach_count}
        isLoading={metricsLoading}
      />

      {/* Main content */}
      <div className="flex gap-4">
        {/* Left sidebar: Queue tabs + Filters */}
        <div className="w-56 flex-shrink-0 space-y-4">
          <div className="bg-card border border-border rounded-xl p-3">
            <p className="text-xs font-heading uppercase tracking-wider text-muted-foreground mb-2 px-1">
              Queues
            </p>
            <TicketQueueTabs
              activeQueue={activeQueue}
              onQueueChange={handleQueueChange}
              counts={{
                my: metricsData?.queue_counts?.my,
                team: metricsData?.queue_counts?.team,
                unassigned: metricsData?.queue_counts?.unassigned,
                all: total,
              }}
            />
          </div>

          <div className="bg-card border border-border rounded-xl p-3">
            <TicketFilters
              filters={filters}
              onFiltersChange={f => { setFilters(f); setPage(1); }}
              onSearchChange={handleSearchChange}
            />
          </div>
        </div>

        {/* Main table */}
        <div className="flex-1 min-w-0">
          <div className="bg-card border border-border rounded-xl overflow-hidden">
            <TicketListTable
              tickets={tickets}
              isLoading={ticketsLoading}
              sort={sort}
              onSortChange={handleSortChange}
              selectedIds={selectedIds}
              onSelectionChange={setSelectedIds}
              showBulkActions={role === "admin" || role === "manager"}
            />
          </div>

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex items-center justify-between mt-4">
              <p className="text-sm text-muted-foreground">
                Showing {(page - 1) * 25 + 1}–{Math.min(page * 25, total)} of {total}
              </p>
              <div className="flex gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  disabled={page === 1}
                  onClick={() => setPage(p => p - 1)}
                >
                  Previous
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  disabled={page === totalPages}
                  onClick={() => setPage(p => p + 1)}
                >
                  Next
                </Button>
              </div>
            </div>
          )}
        </div>
      </div>
    </motion.div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { motion } from "framer-motion";
import { toast } from "sonner";
import {
  ArrowLeft, RefreshCw, UserCheck, ChevronUp, Plus, Upload,
  ExternalLink, Building2, FileText,
} from "lucide-react";
import useSWR from "swr";

import { useAuth } from "@/lib/context/auth-context";
import { pageTransition } from "@/lib/helpers/animations";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

import { TicketHeader } from "./TicketHeader";
import { StatusTimeline } from "./StatusTimeline";
import { NotesSection } from "./NotesSection";
import { ActivityLogSection } from "./ActivityLogSection";
import { DocumentAttachments } from "./DocumentAttachments";
import { EscalationDialog } from "./EscalationDialog";
import { AssignOwnerDialog } from "./AssignOwnerDialog";

const VALID_TRANSITIONS: Record<string, string[]> = {
  open: ["in_progress"],
  in_progress: ["pending", "resolved"],
  pending: ["in_progress"],
  resolved: ["closed"],
  closed: [],
};

const STATUS_LABELS: Record<string, string> = {
  in_progress: "In Progress",
  pending: "Pending",
  resolved: "Resolved",
  closed: "Closed",
};

async function fetchTicket(url: string, token: string) {
  const res = await fetch(url, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) throw new Error("Failed to fetch ticket");
  return res.json();
}

interface TicketDetailViewProps {
  ticketId: string;
}

export function TicketDetailView({ ticketId }: TicketDetailViewProps) {
  const router = useRouter();
  const { session, role } = useAuth();
  const token = session?.access_token ?? "";

  const [escalateOpen, setEscalateOpen] = useState(false);
  const [assignOpen, setAssignOpen] = useState(false);
  const [isUpdatingStatus, setIsUpdatingStatus] = useState(false);

  const { data: ticket, isLoading, mutate } = useSWR(
    token ? `/api/service-desk/tickets/${ticketId}` : null,
    (url: string) => fetchTicket(url, token),
    { revalidateOnFocus: false }
  );

  const handleStatusChange = async (newStatus: string) => {
    if (!token || !ticket) return;
    setIsUpdatingStatus(true);
    try {
      const res = await fetch(`/api/service-desk/tickets/${ticketId}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ status: newStatus }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error);
      mutate();
      toast.success(`Status updated to ${newStatus.replace(/_/g, " ")}`);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to update status");
    } finally {
      setIsUpdatingStatus(false);
    }
  };

  if (isLoading) {
    return (
      <div className="space-y-6">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-24 rounded-xl" />
        <div className="grid grid-cols-3 gap-4">
          <div className="col-span-2 space-y-4">
            <Skeleton className="h-48 rounded-xl" />
            <Skeleton className="h-64 rounded-xl" />
          </div>
          <div className="space-y-4">
            <Skeleton className="h-32 rounded-xl" />
            <Skeleton className="h-48 rounded-xl" />
          </div>
        </div>
      </div>
    );
  }

  if (!ticket) {
    return (
      <div className="flex flex-col items-center justify-center py-20 gap-4">
        <p className="text-muted-foreground">Ticket not found</p>
        <Button onClick={() => router.push("/dashboard/service-desk")}>
          Back to Service Desk
        </Button>
      </div>
    );
  }

  const allowedTransitions = VALID_TRANSITIONS[ticket.status as string] ?? [];
  const canEscalate = ticket.status !== "resolved" && ticket.status !== "closed" &&
    (ticket.escalation_level ?? 0) < 2;
  const canAssign = role === "admin" || role === "manager";

  return (
    <motion.div {...pageTransition} className="space-y-6">
      {/* Back button */}
      <div className="flex items-center gap-4">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => router.push("/dashboard/service-desk")}
          className="gap-2"
        >
          <ArrowLeft className="w-4 h-4" />
          Service Desk
        </Button>
        <Button
          variant="ghost"
          size="sm"
          onClick={() => mutate()}
          className="gap-2 ml-auto"
        >
          <RefreshCw className="w-4 h-4" />
          Refresh
        </Button>
      </div>

      {/* Ticket header */}
      <div className="bg-card border border-border rounded-xl p-6">
        <TicketHeader
          ticketNumber={ticket.ticket_number}
          category={ticket.category}
          priority={ticket.priority}
          status={ticket.status}
          createdAt={ticket.created_at}
          slaDeadline={ticket.sla_deadline}
          isBreached={ticket.is_breached}
          escalationLevel={ticket.escalation_level}
          ownerName={(ticket.owner as { name: string } | null)?.name}
        />
      </div>

      {/* Status timeline */}
      <div className="bg-card border border-border rounded-xl p-6">
        <h3 className="text-sm font-heading uppercase tracking-wider text-muted-foreground mb-4">
          Status Timeline
        </h3>
        <StatusTimeline currentStatus={ticket.status} />
      </div>

      {/* Main content grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        {/* Left column (2/3) */}
        <div className="lg:col-span-2 space-y-4">
          {/* Description */}
          <div className="bg-card border border-border rounded-xl p-6">
            <h3 className="text-sm font-heading uppercase tracking-wider text-muted-foreground mb-3">
              Description
            </h3>
            <p className="text-sm whitespace-pre-wrap">
              {ticket.description ?? "No description provided."}
            </p>
          </div>

          {/* Notes */}
          <div className="bg-card border border-border rounded-xl p-6">
            <h3 className="text-sm font-heading uppercase tracking-wider text-muted-foreground mb-3">
              Notes
            </h3>
            <NotesSection
              ticketId={ticketId}
              notes={ticket.notes ?? []}
              onNotesChange={() => mutate()}
            />
          </div>

          {/* Activity log */}
          <div className="bg-card border border-border rounded-xl p-6">
            <h3 className="text-sm font-heading uppercase tracking-wider text-muted-foreground mb-3">
              Activity Log
            </h3>
            <ActivityLogSection entries={ticket.activity_log ?? []} />
          </div>
        </div>

        {/* Right column (1/3) */}
        <div className="space-y-4">
          {/* Quick actions */}
          <div className="bg-card border border-border rounded-xl p-4 space-y-2">
            <h3 className="text-sm font-heading uppercase tracking-wider text-muted-foreground mb-3">
              Quick Actions
            </h3>

            {/* Status update */}
            {allowedTransitions.length > 0 && (
              <Select onValueChange={handleStatusChange} disabled={isUpdatingStatus}>
                <SelectTrigger className="w-full">
                  <SelectValue placeholder="Update Status..." />
                </SelectTrigger>
                <SelectContent>
                  {allowedTransitions.map(s => (
                    <SelectItem key={s} value={s}>
                      → {STATUS_LABELS[s] ?? s}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            )}

            {canAssign && (
              <Button
                variant="outline"
                size="sm"
                className="w-full gap-2"
                onClick={() => setAssignOpen(true)}
              >
                <UserCheck className="w-4 h-4" />
