              </Button>
            )}
          </div>

          {/* Customer info */}
          {ticket.customers && (
            <div className="bg-card border border-border rounded-xl p-4">
              <h3 className="text-sm font-heading uppercase tracking-wider text-muted-foreground mb-3">
