"use client";

import { useEffect, useState } from "react";

/**
 * Hook to detect if a media query matches.
 * Used for responsive layout switching (e.g. table → card view on mobile).
 *
 * Returns `undefined` during SSR / initial hydration to avoid mismatch,
 * then resolves to a boolean once the client has measured.
 *
 * @example
 * const isMobile = useMediaQuery("(max-width: 767px)");
 * // isMobile is undefined on first render, then true/false
 */
export function useMediaQuery(query: string): boolean | undefined {
  const [matches, setMatches] = useState<boolean | undefined>(undefined);

  useEffect(() => {
    const media = window.matchMedia(query);
    // Set initial value once we're on the client
    setMatches(media.matches);

    const handler = (e: MediaQueryListEvent) => setMatches(e.matches);
    media.addEventListener("change", handler);

    return () => media.removeEventListener("change", handler);
  }, [query]);

  return matches;
}

// ---- Preset breakpoints ----

export function useIsMobile() {
  return useMediaQuery("(max-width: 767px)");
}

export function useIsTablet() {
  return useMediaQuery("(min-width: 768px) and (max-width: 1023px)");
}

export function useIsDesktop() {
  return useMediaQuery("(min-width: 1024px)");
}

"use client";

import { useState, useEffect, useCallback, useMemo, useRef } from "react";
import { useAuth } from "@/lib/context/auth-context";
import { supabase } from "@/lib/supabase/client";
import { useRealtimeTable } from "./use-realtime";

const FALLBACK_POLL_MS = 300_000; // 5min safety-net poll; Realtime handles instant updates
const RT_DEBOUNCE_MS = 500; // debounce Realtime events to prevent cascade refetches

// Simple in-memory cache so navigating back shows data instantly
const queryCache = new Map<string, { data: unknown[]; ts: number }>();
const CACHE_TTL_MS = 60_000; // serve cached data for up to 60s while revalidating
const CACHE_MAX_ENTRIES = 100;

function cacheGet(key: string) {
  const entry = queryCache.get(key);
  if (!entry) return undefined;
  if (Date.now() - entry.ts > CACHE_TTL_MS) {
    queryCache.delete(key);
    return undefined;
  }
  return entry;
}

function cacheSet(key: string, data: unknown[]) {
  if (queryCache.size >= CACHE_MAX_ENTRIES && !queryCache.has(key)) {
    let oldestKey: string | undefined;
    let oldestTs = Infinity;
    for (const [k, v] of queryCache) {
      if (v.ts < oldestTs) { oldestTs = v.ts; oldestKey = k; }
    }
    if (oldestKey) queryCache.delete(oldestKey);
  }
  queryCache.set(key, { data, ts: Date.now() });
}

// Types

export interface QueryFilter {
  field: string;
  operator:
    | "=="
    | "!="
    | ">"
    | ">="
    | "<"
    | "<="
    | "in"
    | "array-contains"
    | "array-contains-any"
    | "not-in";
  value: unknown;
}

interface CollectionResult<T> {
  data: T[] | undefined;
  error: Error | undefined;
  isLoading: boolean;
  mutate: () => void;
}

interface DocResult<T> {
  data: T | null | undefined;
  error: Error | undefined;
  isLoading: boolean;
  mutate: () => void;
}

function resolveHookError(err: unknown, fallbackMessage: string): Error {
  if (err instanceof Error) return err;
  if (typeof err === "string") return new Error(err);

  // Supabase/PostgREST errors are often plain objects, not Error instances.
  if (err && typeof err === "object") {
    const maybe = err as {
      message?: string;
      code?: string;
      details?: string;
      hint?: string;
    };

    if (maybe.message) {
      const extras = [maybe.code, maybe.details, maybe.hint].filter(Boolean).join(" | ");
      return new Error(extras ? `${maybe.message} (${extras})` : maybe.message);
    }
  }

  return new Error(fallbackMessage);
}

function mapFieldName(field: string): string {
  switch (field) {
    case "createdAt":
      return "created_at";
    case "updatedAt":
      return "updated_at";
    case "lastLoginAt":
      return "last_login_at";
    case "avatarUrl":
      return "avatar_url";
    default:
      return field;
  }
}

function normalizeRow<T extends { id: string }>(row: Record<string, unknown>): T {
  return {
    ...row,
    createdAt: row.createdAt ?? row.created_at,
    updatedAt: row.updatedAt ?? row.updated_at,
    lastLoginAt: row.lastLoginAt ?? row.last_login_at,
    avatarUrl: row.avatarUrl ?? row.avatar_url,
  } as unknown as T;
}

/**
 * Returns true when the filter set contains a condition that would produce an
 * empty result set without needing a round-trip (e.g., `.in(field, [])` is
 * always empty).  The caller should short-circuit and return `[]`.
 */
function hasShortCircuitFilter(filters: QueryFilter[]): boolean {
  return filters.some((f) => {
    if (f.operator === "in" || f.operator === "array-contains-any" || f.operator === "not-in") {
      return Array.isArray(f.value) && f.value.length === 0;
    }
    return false;
  });
}

function applyFilter(
  queryBuilder: ReturnType<typeof supabase.from>,
  filter: QueryFilter
) {
  const field = mapFieldName(filter.field);
  const val = filter.value;

  // Guard: skip filters whose value is undefined, null, or NaN — they produce
  // malformed PostgREST query strings and result in 400 Bad Request.
  if (val === undefined || val === null || (typeof val === "number" && Number.isNaN(val))) {
    console.warn(`[Supabase] skipping filter on "${field}" — value is ${String(val)}`);
    return queryBuilder;
  }

  switch (filter.operator) {
    case "==":
      return queryBuilder.eq(field, val);
    case "!=":
      return queryBuilder.neq(field, val);
    case ">":
      return queryBuilder.gt(field, val);
    case ">=":
      return queryBuilder.gte(field, val);
    case "<":
      return queryBuilder.lt(field, val);
    case "<=":
      return queryBuilder.lte(field, val);
    case "in": {
      const arr = Array.isArray(val) ? val : [val];
      if (arr.length === 0) return queryBuilder; // would be caught by hasShortCircuitFilter
      return queryBuilder.in(field, arr);
    }
    case "array-contains":
      return queryBuilder.contains(field, Array.isArray(val) ? val : [val]);
    case "array-contains-any": {
      const arr = Array.isArray(val) ? val : [val];
      if (arr.length === 0) return queryBuilder;
      return queryBuilder.overlaps(field, arr);
    }
    case "not-in": {
      const arr = Array.isArray(val) ? val : [val];
      if (arr.length === 0) return queryBuilder;
      // Escape double-quotes in string values to prevent PostgREST filter injection
      const escaped = arr.map(v =>
        typeof v === "string" ? `"${v.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"` : String(v)
      );
      return queryBuilder.not(field, "in", `(${escaped.join(",")})`);
    }
    default:
      throw new Error(`Unsupported Supabase hook filter operator: ${filter.operator}`);
  }
}

export function useCollection<T extends { id: string }>(
  key: string | null,
  collectionName: string,
  filters?: QueryFilter[],
  sortField?: string,
  sortDir?: "asc" | "desc",
  maxResults?: number
): CollectionResult<T> {
  const { user, loading } = useAuth();
  const filtersKey = useMemo(() => JSON.stringify(filters), [filters]);
  const cacheKey = `${key}:${collectionName}:${filtersKey}:${sortField}:${sortDir}:${maxResults}`;

  const cached = cacheGet(cacheKey);
  const [data, setData] = useState<T[] | undefined>(
    cached ? (cached.data as T[]) : undefined
  );
  const [error, setError] = useState<Error | undefined>(undefined);
  // Fix: stay loading if key exists but no cached data (prevents empty flash)
  const [isLoading, setIsLoading] = useState(key !== null && cached === undefined);
  const [version, setVersion] = useState(0);
  const [pollingSuspended, setPollingSuspended] = useState(false);
  const visibleRef = useRef(true);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Track tab visibility — pause polling when hidden
  useEffect(() => {
    const handler = () => { visibleRef.current = document.visibilityState === "visible"; };
    document.addEventListener("visibilitychange", handler);
    return () => document.removeEventListener("visibilitychange", handler);
  }, []);

  useEffect(() => {
    // key is null → hook is disabled, clear data
    if (!key) {
      setData(undefined);
      setIsLoading(false);
      return;
    }

    // Auth still loading → wait without wiping data, stay loading if no data
    if (loading || !user) {
      if (!data) setIsLoading(true);
      return;
    }

    if (pollingSuspended) {
      setIsLoading(false); // don't leave stuck in loading state
      return;
    }

    let cancelled = false;
    let consecutiveErrors = 0;

    const fetchCollection = async (isPolling = false) => {
      // Skip background polls when tab is hidden
      if (isPolling && !visibleRef.current) return;

      setError(undefined);
      if (!isPolling && !data) setIsLoading(true);

      try {
        // Short-circuit: if a filter guarantees zero rows, skip the network call.
        if (filters && filters.length > 0 && hasShortCircuitFilter(filters)) {
          if (!cancelled) {
            setData([]);
            setIsLoading(false);
          }
          return;
        }

        let queryBuilder = supabase.from(collectionName).select("*");

        for (const filter of filters ?? []) {
          queryBuilder = applyFilter(queryBuilder, filter);
        }

        if (sortField) {
          queryBuilder = queryBuilder.order(mapFieldName(sortField), {
            ascending: (sortDir ?? "desc") === "asc",
          });
        }

        if (maxResults) {
          queryBuilder = queryBuilder.limit(maxResults);
        }

        const { data: rows, error: queryError } = await queryBuilder;
        if (queryError) throw queryError;
        consecutiveErrors = 0;

        if (!cancelled) {
          const normalized = (rows ?? []).map((row) => normalizeRow<T>(row as Record<string, unknown>));
          setData(normalized);
          setIsLoading(false);
          cacheSet(cacheKey, normalized);
        }
      } catch (err) {
        if (cancelled) return;

        // Transient auth-lock / abort errors (Web Locks API contention during
        // token refresh) — silently retry on the next poll cycle.
        const isAbort =
          (err instanceof DOMException && err.name === "AbortError") ||
          (err instanceof Error && err.name === "AbortError") ||
          (err instanceof Error && err.message.includes("Lock broken"));
        if (isAbort) {
          console.debug(`[Supabase] ${collectionName}: transient abort — will retry`);
          return;
        }

        const resolvedError = resolveHookError(
          err,
          `Failed to load collection: ${collectionName}`
        );
        console.error(`[Supabase] ${collectionName}:`, resolvedError);
        setError(resolvedError);
        setIsLoading(false);

        consecutiveErrors += 1;
        if (consecutiveErrors >= 3) {
          console.warn(
            `[Supabase] ${collectionName}: polling suspended after 3 consecutive errors`
          );
          setPollingSuspended(true);
        }
      }
    };

    void fetchCollection(false);
    const intervalId = window.setInterval(() => fetchCollection(true), FALLBACK_POLL_MS);

    return () => {
      cancelled = true;
      window.clearInterval(intervalId);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, collectionName, cacheKey, sortField, sortDir, maxResults, version, user, loading, pollingSuspended]);

  // Realtime subscription — debounced to prevent cascade refetches
  useRealtimeTable(key && user ? collectionName : null, () => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      setVersion((v) => v + 1);
    }, RT_DEBOUNCE_MS);
  });

  // Cleanup debounce on unmount
  useEffect(() => {
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
    };
  }, []);

  const mutate = useCallback(() => {
    queryCache.delete(cacheKey);
    setPollingSuspended(false);
    setVersion((v) => v + 1);
  }, [cacheKey]);
  return { data, error, isLoading, mutate };
}

export function useDoc<T extends { id: string }>(
  key: string | null,
  collectionName: string,
  docId: string | null
): DocResult<T> {
  const { user, loading } = useAuth();
  const docCacheKey = `${key}:${collectionName}:doc:${docId}`;
  const cached = cacheGet(docCacheKey);
  const [data, setData] = useState<T | null | undefined>(
    cached ? (cached.data[0] as T) : undefined
  );
  const [error, setError] = useState<Error | undefined>(undefined);
  // Fix: stay loading if key exists but no cached data (prevents empty flash)
  const [isLoading, setIsLoading] = useState(key !== null && cached === undefined);
  const [version, setVersion] = useState(0);
  const [pollingSuspended, setPollingSuspended] = useState(false);
  const visibleRef = useRef(true);
  const dataRef = useRef(data);
  dataRef.current = data;
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    const handler = () => { visibleRef.current = document.visibilityState === "visible"; };
    document.addEventListener("visibilitychange", handler);
    return () => document.removeEventListener("visibilitychange", handler);
  }, []);

  useEffect(() => {
    // key/docId is null → hook is disabled, clear data
    if (!key || !docId) {
      setData(undefined);
      setIsLoading(false);
      return;
    }

    // Auth still loading → wait without wiping data, stay loading if no data
    if (loading || !user) {
      if (!dataRef.current) setIsLoading(true);
      return;
    }

    if (pollingSuspended) {
      setIsLoading(false);
      return;
    }

    let cancelled = false;
    let consecutiveErrors = 0;

    const fetchDoc = async (isPolling = false) => {
      if (isPolling && !visibleRef.current) return;
      setError(undefined);
      if (!dataRef.current) setIsLoading(true);

      try {
        const { data: row, error: queryError } = await supabase
          .from(collectionName)
          .select("*")
          .eq("id", docId)
          .single();

        if (queryError) {
          if (queryError.code === "PGRST116") {
            if (!cancelled) {
              setData(null);
              setIsLoading(false);
            }
            return;
          }
          throw queryError;
        }

        if (!cancelled) {
          const normalized = normalizeRow<T>((row ?? {}) as Record<string, unknown>);
          setData(normalized);
          setIsLoading(false);
          cacheSet(docCacheKey, [normalized]);
        }
        consecutiveErrors = 0;
      } catch (err) {
        if (cancelled) return;

        const isAbort =
          (err instanceof DOMException && err.name === "AbortError") ||
          (err instanceof Error && err.name === "AbortError") ||
          (err instanceof Error && err.message.includes("Lock broken"));
        if (isAbort) {
          console.debug(`[Supabase] ${collectionName}/${docId}: transient abort — will retry`);
          return;
        }

        const resolvedError = resolveHookError(
          err,
          `Failed to load document: ${collectionName}/${docId}`
        );
        console.error(`[Supabase] ${collectionName}/${docId}:`, resolvedError);
        setError(resolvedError);
        setIsLoading(false);

        consecutiveErrors += 1;
        if (consecutiveErrors >= 3) {
          console.warn(
            `[Supabase] ${collectionName}/${docId}: polling suspended after 3 consecutive errors`
          );
          setPollingSuspended(true);
        }
      }
    };

    void fetchDoc(false);
    const intervalId = window.setInterval(() => fetchDoc(true), FALLBACK_POLL_MS);

    return () => {
      cancelled = true;
      window.clearInterval(intervalId);
    };
  }, [key, collectionName, docId, version, user, loading, pollingSuspended]);

  // Realtime subscription — debounced
  useRealtimeTable(key && docId && user ? collectionName : null, () => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      setVersion((v) => v + 1);
    }, RT_DEBOUNCE_MS);
  });

  useEffect(() => {
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
    };
  }, []);

  const mutate = useCallback(() => {
    queryCache.delete(docCacheKey);
    setPollingSuspended(false);
    setVersion((v) => v + 1);
  }, [docCacheKey]);
  return { data, error, isLoading, mutate };
}

/**
 * API Monitoring Middleware
 * Automatically tracks errors and performance for all API routes
 */

import { NextRequest, NextResponse } from 'next/server';
import { trackAPIError, trackPerformance } from './enhanced-error-tracker';

export interface MonitoringOptions {
  trackPerformance?: boolean;
  trackErrors?: boolean;
  slowThreshold?: number; // milliseconds
}

/**
 * Wrap API route handler with monitoring
 * 
 * Usage:
 * export const GET = withMonitoring(async (req) => {
 *   // Your handler code
 * });
 */
export function withMonitoring<T extends (...args: any[]) => Promise<NextResponse>>(
  handler: T,
  options: MonitoringOptions = {}
): T {
  const {
    trackPerformance: shouldTrackPerformance = true,
    trackErrors: shouldTrackErrors = true,
    slowThreshold = 1000, // 1 second
  } = options;

  return (async (...args: any[]) => {
    const req = args[0] as NextRequest;
    const start = Date.now();
    
    // Extract request info
    const url = req.url;
    const method = req.method;
    const endpoint = new URL(url).pathname;
    
    // Get user info from headers (if available)
    let userId: string | undefined;
    let userEmail: string | undefined;
    let userRole: string | undefined;
    
    try {
      const authHeader = req.headers.get('authorization');
      if (authHeader) {
        // Extract user info from token (simplified - adjust based on your auth)
        // In production, decode JWT token here
        userId = req.headers.get('x-user-id') || undefined;
        userEmail = req.headers.get('x-user-email') || undefined;
        userRole = req.headers.get('x-user-role') || undefined;
      }
    } catch (err) {
      // Ignore auth parsing errors
    }

    try {
      // Execute handler
      const response = await handler(...args);
      const duration = Date.now() - start;

      // Track performance
      if (shouldTrackPerformance) {
        await trackPerformance(endpoint, duration, {
          method,
          endpoint,
          user_id: userId,
          status: response.status,
          slow: duration > slowThreshold,
        });
      }

      // Log slow requests
      if (duration > slowThreshold) {
        console.warn(`[Slow Request] ${method} ${endpoint} took ${duration}ms`);
      }

      return response;
    } catch (error: any) {
      const duration = Date.now() - start;

      // Track error
      if (shouldTrackErrors) {
        await trackAPIError(
          endpoint,
          error,
          {
            method,
            headers: Object.fromEntries(req.headers.entries()),
          },
          {
            status: 500,
          },
          userId && userEmail && userRole
            ? { id: userId, email: userEmail, role: userRole }
            : undefined
        );
      }

      // Track performance even on error
      if (shouldTrackPerformance) {
        await trackPerformance(endpoint, duration, {
          method,
          endpoint,
          user_id: userId,
          error: true,
          error_message: error.message,
        });
      }

      // Re-throw error
      throw error;
    }
  }) as T;
}

/**
 * Monitoring middleware for Next.js middleware.ts
 * Tracks all requests at the edge
 */
export async function monitoringMiddleware(
  req: NextRequest,
  next: () => Promise<NextResponse>
): Promise<NextResponse> {
  const start = Date.now();
  const url = req.url;
  const method = req.method;
  const endpoint = new URL(url).pathname;

  try {
    const response = await next();
    const duration = Date.now() - start;

    // Track performance for API routes only
    if (endpoint.startsWith('/api/')) {
      await trackPerformance(endpoint, duration, {
        method,
        endpoint,
        status: response.status,
      });
    }

    return response;
  } catch (error: any) {
    const duration = Date.now() - start;

    // Track error
    if (endpoint.startsWith('/api/')) {
      await trackAPIError(
        endpoint,
        error,
        { method },
        { status: 500 }
      );

      await trackPerformance(endpoint, duration, {
        method,
        endpoint,
        error: true,
      });
    }

    throw error;
  }
}

/**
 * Create a monitored API handler
 * Simpler alternative to withMonitoring
 */
export function createMonitoredHandler<T extends (...args: any[]) => Promise<NextResponse>>(
  handler: T
): T {
  return withMonitoring(handler);
}

/**
 * Batch monitoring wrapper for multiple handlers
 */
export function monitorHandlers<T extends Record<string, (...args: any[]) => Promise<NextResponse>>>(
  handlers: T
): T {
  const monitored: any = {};
  
  for (const [key, handler] of Object.entries(handlers)) {
    monitored[key] = withMonitoring(handler);
  }
  
  return monitored;
}

// ============================================================================
// EXPORTS
// ============================================================================

export default {
  withMonitoring,
  monitoringMiddleware,
  createMonitoredHandler,
  monitorHandlers,
};

/**
 * Enhanced Error Tracking & Monitoring System
 * Complete monitoring with database logging, alerts, and dashboards
 */

 

import * as Sentry from '@sentry/nextjs';
import { supabase } from '@/lib/supabase/client';

export type ErrorSeverity = 'fatal' | 'error' | 'warning' | 'info' | 'debug';
export type AlertChannel = 'email' | 'slack' | 'console';

export interface ErrorContext {
  user?: {
    id: string;
    email: string;
    role: string;
  };
  request?: {
    url: string;
    method: string;
    headers?: Record<string, string>;
    body?: unknown;
    params?: Record<string, string>;
  };
  response?: {
    status: number;
    body?: unknown;
  };
  extra?: Record<string, unknown>;
}

export interface ErrorLog {
  id?: string;
  timestamp: Date;
  severity: ErrorSeverity;
  message: string;
  stack?: string;
  endpoint?: string;
  method?: string;
  user_id?: string;
  user_email?: string;
  request_data?: unknown;
  response_data?: unknown;
  metadata?: Record<string, unknown>;
  resolved: boolean;
}

export interface PerformanceLog {
  id?: string;
  timestamp: Date;
  operation: string;
  duration: number;
  endpoint?: string;
  method?: string;
  user_id?: string;
  metadata?: Record<string, unknown>;
}

// ============================================================================
// DATABASE LOGGING
// ============================================================================

/**
 * Log error to database for dashboard
 */
async function logErrorToDatabase(errorLog: ErrorLog): Promise<void> {
  try {
    const { error } = await (supabase as any).from('error_logs').insert({
      timestamp: errorLog.timestamp.toISOString(),
      severity: errorLog.severity,
      message: errorLog.message,
      stack: errorLog.stack,
      endpoint: errorLog.endpoint,
      method: errorLog.method,
      user_id: errorLog.user_id,
      user_email: errorLog.user_email,
      request_data: errorLog.request_data,
      response_data: errorLog.response_data,
      metadata: errorLog.metadata,
      resolved: false,
    });

    if (error) {
      console.error('[Error Logger] Failed to log to database:', error);
    }
  } catch (err) {
    console.error('[Error Logger] Database logging failed:', err);
  }
}

/**
 * Log performance metric to database
 */
async function logPerformanceToDatabase(perfLog: PerformanceLog): Promise<void> {
  try {
    const { error } = await (supabase as any).from('performance_logs').insert({
      timestamp: perfLog.timestamp.toISOString(),
      operation: perfLog.operation,
      duration: perfLog.duration,
      endpoint: perfLog.endpoint,
      method: perfLog.method,
      user_id: perfLog.user_id,
      metadata: perfLog.metadata,
    });

    if (error) {
      console.error('[Performance Logger] Failed to log to database:', error);
    }
  } catch (err) {
    console.error('[Performance Logger] Database logging failed:', err);
  }
}

// ============================================================================
// ALERT SYSTEM
// ============================================================================

/**
 * Send alert through configured channels
 */
async function sendAlert(
  severity: ErrorSeverity,
  message: string,
  context?: ErrorContext,
  channels: AlertChannel[] = ['console']
): Promise<void> {
  // Only alert on error and fatal
  if (severity !== 'error' && severity !== 'fatal') return;

  const alertMessage = `
🚨 ${severity.toUpperCase()} ALERT
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Message: ${message}
Time: ${new Date().toISOString()}
${context?.request?.url ? `Endpoint: ${context.request.method} ${context.request.url}` : ''}
${context?.user?.email ? `User: ${context.user.email}` : ''}
${context?.extra ? `\nDetails: ${JSON.stringify(context.extra, null, 2)}` : ''}
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  `.trim();

  for (const channel of channels) {
    switch (channel) {
      case 'console':
        console.error(alertMessage);
        break;

      case 'email':
        await sendEmailAlert(severity, alertMessage, context);
        break;

      case 'slack':
        await sendSlackAlert(severity, alertMessage, context);
        break;
    }
  }
}

/**
 * Send email alert
 */
async function sendEmailAlert(
  severity: ErrorSeverity,
  message: string,
  context?: ErrorContext
): Promise<void> {
  try {
    // Only send in production
    if (process.env.NODE_ENV !== 'production') return;

    const adminEmail = process.env.ADMIN_EMAIL || process.env.ALERT_EMAIL;
    if (!adminEmail) {
      console.warn('[Alert] No admin email configured');
      return;
    }

    await fetch('/api/email', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        to: adminEmail,
        subject: `🚨 ${severity.toUpperCase()} Alert - ${context?.request?.url || 'System'}`,
        text: message,
        html: `<pre>${message}</pre>`,
      }),
    });
  } catch (error) {
    console.error('[Alert] Failed to send email:', error);
  }
}

/**
 * Send Slack alert
 */
async function sendSlackAlert(
  severity: ErrorSeverity,
  message: string,
  context?: ErrorContext
): Promise<void> {
  try {
    const webhookUrl = process.env.SLACK_WEBHOOK_URL;
    if (!webhookUrl) {
      console.warn('[Alert] No Slack webhook configured');
      return;
    }

    const color = severity === 'fatal' ? '#FF0000' : '#FFA500';
    const emoji = severity === 'fatal' ? ':rotating_light:' : ':warning:';

    await fetch(webhookUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        text: `${emoji} ${severity.toUpperCase()} Alert`,
        attachments: [
          {
            color,
            text: message,
            ts: Math.floor(Date.now() / 1000),
          },
        ],
      }),
    });
  } catch (error) {
    console.error('[Alert] Failed to send Slack message:', error);
  }
}

// ============================================================================
// CORE TRACKING FUNCTIONS
// ============================================================================

/**
 * Track an error with full context and alerting
 */
export async function trackError(
  error: Error,
  context?: ErrorContext,
  severity: ErrorSeverity = 'error'
): Promise<void> {
  const errorLog: ErrorLog = {
    timestamp: new Date(),
    severity,
    message: error.message,
    stack: error.stack,
    endpoint: context?.request?.url,
    method: context?.request?.method,
    user_id: context?.user?.id,
    user_email: context?.user?.email,
    request_data: context?.request,
    response_data: context?.response,
    metadata: context?.extra,
    resolved: false,
  };

  // Log to console in development
  if (process.env.NODE_ENV === 'development') {
    console.error('[Error Tracker]', {
      message: error.message,
      stack: error.stack,
      context,
      severity,
    });
  }

  // Log to database
  await logErrorToDatabase(errorLog);

  // Send to Sentry
  if (process.env.NEXT_PUBLIC_SENTRY_DSN) {
    Sentry.withScope((scope) => {
      scope.setLevel(severity);

      if (context?.user) {
        scope.setUser({
          id: context.user.id,
          email: context.user.email,
          role: context.user.role,
        });
      }

      if (context?.request) {
        scope.setContext('request', context.request);
      }

      if (context?.response) {
        scope.setContext('response', context.response);
      }

      if (context?.extra) {
        Object.entries(context.extra).forEach(([key, value]) => {
          scope.setExtra(key, value);
        });
      }

      Sentry.captureException(error);
    });
  }

  // Send alerts for critical errors
  if (severity === 'fatal' || severity === 'error') {
    const channels: AlertChannel[] = ['console'];
    
    if (process.env.ADMIN_EMAIL || process.env.ALERT_EMAIL) {
      channels.push('email');
    }
    
    if (process.env.SLACK_WEBHOOK_URL) {
      channels.push('slack');
    }

    await sendAlert(severity, error.message, context, channels);
  }
}

/**
 * Track API errors with detailed context
 */
export async function trackAPIError(
  endpoint: string,
  error: Error,
  request?: {
    method: string;
    body?: unknown;
    params?: Record<string, string>;
    headers?: Record<string, string>;
  },
  response?: {
    status: number;
    body?: unknown;
  },
  user?: {
    id: string;
    email: string;
    role: string;
  }
): Promise<void> {
  await trackError(
    error,
    {
      user,
      request: {
        url: endpoint,
        method: request?.method || 'UNKNOWN',
        headers: request?.headers,
        body: request?.body,
        params: request?.params,
      },
      response,
      extra: {
        endpoint,
        api_error: true,
      },
    },
    'error'
  );
}

/**
 * Track critical business errors with immediate alerts
 */
export async function trackCriticalError(
  operation: string,
  error: Error,
  context?: ErrorContext
): Promise<void> {
  await trackError(
    error,
    {
      ...context,
      extra: {
        ...context?.extra,
        operation,
        critical: true,
      },
    },
    'fatal'
  );
}

/**
 * Track performance metrics
 */
export async function trackPerformance(
  operation: string,
  duration: number,
  metadata?: Record<string, unknown>
): Promise<void> {
  const perfLog: PerformanceLog = {
    timestamp: new Date(),
    operation,
    duration,
    endpoint: metadata?.endpoint as string,
    method: metadata?.method as string,
    user_id: metadata?.user_id as string,
    metadata,
  };

  // Log to console in development
  if (process.env.NODE_ENV === 'development') {
    console.log('[Performance]', operation, `${duration}ms`, metadata);
  }

  // Log to database
  await logPerformanceToDatabase(perfLog);

  // Send to Sentry
  if (process.env.NEXT_PUBLIC_SENTRY_DSN) {
    Sentry.captureMessage(`Performance: ${operation}`, {
      level: 'info',
      extra: {
        duration,
        ...metadata,
      },
    });
  }

  // Alert on slow operations (>5 seconds)
  if (duration > 5000) {
    await sendAlert(
      'warning',
      `Slow operation detected: ${operation} took ${duration}ms`,
      {
        extra: {
          operation,
          duration,
          ...metadata,
        },
      },
      ['console']
    );
  }
}

/**
 * Measure and track function execution time
 */
export async function measurePerformance<T>(
  operation: string,
  fn: () => Promise<T>,
  metadata?: Record<string, unknown>
): Promise<T> {
  const start = Date.now();
  try {
    const result = await fn();
    const duration = Date.now() - start;
    await trackPerformance(operation, duration, metadata);
    return result;
  } catch (error) {
    const duration = Date.now() - start;
    await trackPerformance(operation, duration, {
      ...metadata,
      error: true,
    });
    throw error;
  }
}

/**
 * Track custom events
 */
export async function trackEvent(
  eventName: string,
  data?: Record<string, unknown>
): Promise<void> {
  if (process.env.NODE_ENV === 'development') {
    console.log('[Event Tracker]', eventName, data);
  }

  if (process.env.NEXT_PUBLIC_SENTRY_DSN) {
    Sentry.captureMessage(eventName, {
      level: 'info',
      extra: data,
    });
  }
}

/**
 * Track user actions
 */
export async function trackUserAction(
  action: string,
  userId: string,
  metadata?: Record<string, unknown>
): Promise<void> {
  await trackEvent(`user_action:${action}`, {
    userId,
    timestamp: new Date().toISOString(),
    ...metadata,
  });
}

/**
 * Track business metrics
 */
export async function trackBusinessMetric(
  metric: string,
  value: number,
  metadata?: Record<string, unknown>
): Promise<void> {
  if (process.env.NODE_ENV === 'development') {
    console.log('[Business Metric]', metric, value, metadata);
  }

  if (process.env.NEXT_PUBLIC_SENTRY_DSN) {
    Sentry.captureMessage(`Metric: ${metric}`, {
      level: 'info',
      extra: {
        value,
        timestamp: new Date().toISOString(),
        ...metadata,
      },
    });
  }
}

// ============================================================================
// EXPORTS
// ============================================================================

export default {
  trackError,
  trackAPIError,
  trackCriticalError,
  trackPerformance,
  measurePerformance,
  trackEvent,
  trackUserAction,
  trackBusinessMetric,
};

/**
 * Supabase Customer Service
 * Replaces lib/mock/services.ts customerService
 */

import { supabase } from "@/lib/supabase/client";
import { Customer } from "@/lib/types";
import type { ExtractedPolicyData } from "@/lib/helpers/pdf-extractor";
import { manualCustomerValidationSchema, type ManualCustomerFormData } from "@/lib/validations/customer";
import { documentService } from "@/lib/services/document.service";

const TABLE = "customers";

// ── Helpers ──────────────────────────────────────────────────────

/**
 * Atomically increments the customer counter and returns the next UID.
 * Uses Supabase RPC function for atomic counter increment.
 */
async function nextCustomerUID(): Promise<string> {
  const { data, error } = await supabase.rpc("next_customer_uid");
  if (error) throw new Error(error.message);
  return data as string;
}

/**
 * Atomically reserves `count` UIDs in a single call.
 * Returns an array of UID strings in order.
 */
async function bulkNextCustomerUIDs(count: number): Promise<string[]> {
  const { data, error } = await supabase.rpc("bulk_next_customer_uids", { count });
  if (error) throw new Error(error.message);
  return data as string[];
}

export interface BulkCustomerRow {
  name: string;
  email: string;
  phone: string;
  address?: string;
  city?: string;
  state?: string;
  pincode?: string;
}

export interface BulkImportResult {
  created: number;
  skipped: number;
  errors: { row: number; reason: string }[];
}

/**
 * Bulk-create customers from validated rows.
 * Skips rows whose phone already exist.
 * Uses Supabase batch insert for performance.
 */
export async function bulkCreateCustomers(
  rows: BulkCustomerRow[],
  createdBy: string
): Promise<BulkImportResult> {
  const result: BulkImportResult = { created: 0, skipped: 0, errors: [] };

  // Deduplicate rows within file by phone
  const seenPhones = new Set<string>();
  const validRows: (BulkCustomerRow & { _rowIndex: number })[] = [];
  for (let i = 0; i < rows.length; i++) {
    const r = rows[i];
    if (seenPhones.has(r.phone)) {
      result.errors.push({ row: i + 1, reason: `Duplicate phone in file: ${r.phone}` });
      result.skipped++;
      continue;
    }
    seenPhones.add(r.phone);
    validRows.push({ ...r, _rowIndex: i + 1 });
  }

  // Check existing phones in Supabase
  const allPhones = validRows.map((r) => r.phone);
  const existingPhones = new Set<string>();
  // Supabase `in` filter supports arrays directly
  if (allPhones.length > 0) {
    // Chunk into batches of 500 for the .in() query
    for (let i = 0; i < allPhones.length; i += 500) {
      const batch = allPhones.slice(i, i + 500);
      const { data: existing } = await supabase
        .from(TABLE)
        .select("phone")
        .in("phone", batch);
      existing?.forEach((d) => existingPhones.add(d.phone));
    }
  }

  const toCreate = validRows.filter((r) => {
    if (existingPhones.has(r.phone)) {
      result.errors.push({ row: r._rowIndex, reason: `Phone already exists: ${r.phone}` });
      result.skipped++;
      return false;
    }
    return true;
  });

  if (toCreate.length === 0) return result;

  // Reserve UIDs atomically
  const uids = await bulkNextCustomerUIDs(toCreate.length);
  const now = new Date().toISOString();

  // Insert in chunks of 500
  for (let i = 0; i < toCreate.length; i += 500) {
    const chunk = toCreate.slice(i, i + 500);
    const records = chunk.map((row, idx) => ({
      uid: uids[i + idx],
      name: row.name,
      email: row.email?.toLowerCase().trim() || "N/A",
      phone: row.phone?.trim() || "N/A",
      address: row.address || "",
      city: row.city || "",
      state: row.state || "",
      pincode: row.pincode || "",
      status: "active",
      customer_type: (row as unknown as Record<string, unknown>).type || (row as unknown as Record<string, unknown>).customer_type || "individual",
      entity_meta: (row as unknown as Record<string, unknown>).entity_meta || {},
      family_id: (row as unknown as Record<string, unknown>).family_id || null,
      created_by: createdBy,
      created_at: now,
      updated_at: now,
    }));
    const { error } = await supabase.from(TABLE).insert(records);
    if (error) {
      // Track partial inserts up to this point, then throw
      throw new Error(`Chunk insert failed after ${result.created} created: ${error.message}`);
    }
    result.created += chunk.length;
  }

  return result;
}

// Properties that exist on the TS types but NOT as columns in the DB.
const CAMEL_CASE_STRIP_KEYS = new Set([
  "createdAt",
  "updatedAt",
  "deletedAt",
  "lastLoginAt",
  "avatarUrl",
  "isActive",
  "lockedForEmployee",
  "pdfUploaded",
  "isRecurring",
  "familyId", // Strip camelCase versions
  "entityMeta",
  "kycStatus",
  "type" // Maps to customer_type in DB, handled separately
]);

/**
 * Strip camelCase-only keys that don't exist as PostgreSQL columns.
 * Prevents PostgREST 400 "column X of relation Y does not exist".
 */
function stripCamelCaseKeys<T extends Record<string, unknown>>(obj: T): T {
  const cleaned = { ...obj };
  for (const key of CAMEL_CASE_STRIP_KEYS) {
    delete (cleaned as Record<string, unknown>)[key];
  }
  // Also remove `id` if present (auto-generated by DB)
  delete (cleaned as Record<string, unknown>)["id"];
  return cleaned;
}

// ── CRUD ─────────────────────────────────────────────────────────

export async function getCustomer(id: string): Promise<Customer | null> {
  const { data, error } = await supabase
    .from(TABLE)
    .select("*")
    .eq("id", id)
    .single();
  if (error && error.code !== "PGRST116") throw new Error(error.message);
  return (data as Customer) ?? null;
}

export async function createCustomer(
  data: Omit<Customer, "id" | "uid" | "createdAt" | "updatedAt">,
  createdBy: string
): Promise<Customer> {
  const uid = await nextCustomerUID();
  const now = new Date().toISOString();
  // Ensure required fields are present
  const email = (data as unknown as Record<string, string>).email?.trim() || "N/A";
  const phone = (data as unknown as Record<string, string>).phone?.trim() || "N/A";

  const payload = {
    ...stripCamelCaseKeys(data as Record<string, unknown>),
    uid,
    status: "active",
    email,  // Explicitly set email to ensure it's never null
    phone,  // Explicitly set phone to ensure it's never null
    customer_type: (data as unknown as Record<string, unknown>).type || (data as unknown as Record<string, unknown>).customer_type || "individual",
    entity_meta: (data as unknown as Record<string, unknown>).entity_meta || {},
    family_id: (data as unknown as Record<string, unknown>).family_id || null,
    created_by: createdBy,
    created_at: now,
    updated_at: now,
  };
  const { data: created, error } = await supabase
    .from(TABLE)
    .insert(payload)
    .select()
    .single();
  if (error) throw new Error(error.message);
  return created as Customer;
}

export async function updateCustomer(
  id: string,
  data: Partial<Customer>
): Promise<void> {
  const { data: rows, error } = await supabase
    .from(TABLE)
    .update({ ...stripCamelCaseKeys(data as Record<string, unknown>), updated_at: new Date().toISOString() })
    .eq("id", id)
    .select();
  if (error) throw new Error(error.message);
  if (!rows || rows.length === 0) throw new Error("Customer not found");
}

export async function deleteCustomer(id: string, deletedBy?: string): Promise<void> {
  // Soft delete: mark as inactive, keep data
  const { data: rows, error } = await supabase
    .from(TABLE)
    .update({
      status: "inactive",
      deleted_at: new Date().toISOString(),
      deleted_by: deletedBy || null,
      updated_at: new Date().toISOString(),
    })
    .eq("id", id)
    .select();
  if (error) throw new Error(error.message);
  if (!rows || rows.length === 0) throw new Error("Customer not found");
}

/**
 * Soft-delete a customer AND cascade to all related data:
 * - Cancel all active policies belonging to this customer
 * - Soft-cancel related premiums (mark as "cancelled")
 * - Mark related commissions as "rejected"
 * - Mark related renewals as "lost"
 * - Delete related documents (with Storage cleanup)
 */
export async function deleteCustomerWithCascade(
  id: string,
  deletedBy?: string
): Promise<{
  cancelledPolicies: number;
  cancelledPremiums: number;
  rejectedCommissions: number;
  lostRenewals: number;
  deletedDocuments: number;
}> {
  const counts = {
    cancelledPolicies: 0,
    cancelledPremiums: 0,
    rejectedCommissions: 0,
    lostRenewals: 0,
    deletedDocuments: 0,
  };
  const now = new Date().toISOString();

  // 1. Find all policies for this customer
  const { data: policies } = await supabase
    .from("policies")
    .select("id")
    .eq("customer_id", id);
  const policyIds = (policies ?? []).map((p) => p.id);

  // 2. Cancel all policies
  if (policyIds.length > 0) {
    const { data: updatedPolicies } = await supabase
      .from("policies")
      .update({ status: "cancelled", updated_at: now })
      .eq("customer_id", id)
      .select("id");
    counts.cancelledPolicies = updatedPolicies?.length ?? 0;
  }

  // 3. For each policy, cascade to premiums, commissions, renewals
  for (const policyId of policyIds) {
    // Cancel pending premiums
    const { data: updatedPremiums } = await supabase
      .from("premiums")
      .update({ status: "cancelled", updated_at: now })
      .eq("policy_id", policyId)
      .eq("status", "pending")
      .select("id");
    counts.cancelledPremiums += updatedPremiums?.length ?? 0;

    // Reject pending commissions
    const { data: updatedCommissions } = await supabase
      .from("commissions")
      .update({ status: "rejected", updated_at: now })
      .eq("policy_id", policyId)
      .eq("status", "pending")
      .select("id");
    counts.rejectedCommissions += updatedCommissions?.length ?? 0;

    // Mark due/contacted renewals as lost
    const { data: updatedRenewals } = await supabase
      .from("renewals")
      .update({ status: "lost", updated_at: now })
      .eq("policy_id", policyId)
      .in("status", ["due", "contacted"])
      .select("id");
    counts.lostRenewals += updatedRenewals?.length ?? 0;
  }

  // 4. Delete documents linked to this customer (with Storage cleanup)
  const { data: docs } = await supabase
    .from("documents")
    .select("id, file_url")
    .eq("customer_id", id);
  if (docs && docs.length > 0) {
    for (const d of docs) {
      if (d.file_url) {
        try {
          // Extract storage path from URL and delete from Supabase Storage
          const url = new URL(d.file_url);
          const pathMatch = url.pathname.match(/\/storage\/v1\/object\/public\/(.+)/);
          if (pathMatch) {
            const [bucket, ...rest] = pathMatch[1].split("/");
            await supabase.storage.from(bucket).remove([rest.join("/")]);
          }
        } catch {
          // best-effort
        }
      }
    }
    const docIds = docs.map((d) => d.id);
    await supabase.from("documents").delete().in("id", docIds);
    counts.deletedDocuments = docs.length;
  }

  // 5. Finally soft-delete the customer itself
  const { error: softDelErr } = await supabase
    .from(TABLE)
    .update({
      status: "inactive",
      deleted_at: now,
      deleted_by: deletedBy || null,
      updated_at: now,
    })
    .eq("id", id);
  if (softDelErr) throw new Error(softDelErr.message);

  return counts;
}

export async function getFamilyMembers(familyId: string): Promise<Customer[]> {
