}

function parsePassword(raw) {
  if (!raw) return null;
  const m = raw.match(/^postgresql:\/\/[^:]+:(.+)@[^@]+:\d+\//);
  if (m) {
    const extracted = m[1].replace(/^\[|\]$/g, "");
    try { return decodeURIComponent(extracted); } catch { return extracted; }
  }
  return raw;
}

