    var status = exec('docker ps --filter "name=supabase-db" --format "{{.Status}}"');
    isRunning = status.includes("Up");
  } catch (e) {}

  if (isRunning) {
    log("[OK]", "Supabase containers already running");
  } else {
    log("[...]", "Starting Supabase Docker containers...");
    try {
      execSync("docker compose up -d", { cwd: supabaseDir, stdio: "inherit" });
    } catch (e) {
      log("[ERROR]", "Failed to start Supabase containers");
      process.exit(1);
    }

    // Wait for DB to be healthy (max 60 seconds)
    log("[...]", "Waiting for database to be healthy...");
    for (var i = 0; i < 30; i++) {
      try {
        var health = exec("docker inspect --format={{.State.Health.Status}} supabase-db");
        if (health === "healthy") break;
      } catch (e) {}
      await sleep(2000);
    }

    // Wait for Kong (API gateway)
    for (var j = 0; j < 20; j++) {
      try {
        var kongHealth = exec("docker inspect --format={{.State.Health.Status}} supabase-kong");
        if (kongHealth === "healthy") break;
      } catch (e) {}
      await sleep(2000);
    }

    log("[OK]", "Supabase containers started");
  }

  // Step 4: Quick API health check
  log("[...]", "Verifying Supabase API...");
  try {
    exec("curl -s -o /dev/null -w %{http_code} http://localhost:8000/rest/v1/");
    log("[OK]", "Supabase API responding on http://localhost:8000");
  } catch (e) {
    log("[WARN]", "Supabase API not ready yet, but starting app anyway...");
  }

  // Step 5: Print info
  console.log("");
  console.log("==========================================");
  console.log("  Services:");
  console.log("    Admin Portal:    http://localhost:3000");
  console.log("    Customer Portal: http://localhost:3001");
  console.log("    Supabase API:    http://localhost:8000");
  console.log("    Supabase Studio: http://localhost:8001");
  console.log("    DB:              localhost:5432");
  console.log("");
  console.log("  Admin Login: admin@bpaf.com / Admin@123456");
  console.log("==========================================");
  console.log("");

  // Step 6: Start both Next.js dev servers using concurrently
  log("[...]", "Starting Admin Portal and Customer Portal...");
  console.log("");

  var devAll = spawn("npm", ["run", "dev:all"], {
    cwd: path.resolve(__dirname, ".."),
    stdio: "inherit",
    shell: true,
  });

  devAll.on("close", function (code) {
    process.exit(code || 0);
  });

  // Forward signals for clean shutdown
  process.on("SIGINT", function () { devAll.kill("SIGINT"); });
  process.on("SIGTERM", function () { devAll.kill("SIGTERM"); });
}

main().catch(function (err) {
  console.error(err);
  process.exit(1);
});

/**
 * run-migrations.mjs
 * ─────────────────────────────────────────────────────────────
 * Runs all 4 phase SQL migrations against your Supabase database.
 *
 * Usage:
 *   node scripts/run-migrations.mjs              # run all phases
 *   node scripts/run-migrations.mjs --phase 1    # run only phase 1
 *   node scripts/run-migrations.mjs --phase 1,2  # run phases 1 and 2
 *
 * Prerequisites:
 *   npm install pg dotenv   (or: node --env-file=.env.local ...)
 *
 * Environment variables needed (from .env.local):
 *   DATABASE_URL  — postgres connection string
 *   OR
 *   NEXT_PUBLIC_SUPABASE_URL + SUPABASE_SERVICE_ROLE_KEY
 */

import { readFileSync } from "fs";
import { fileURLToPath } from "url";
import { dirname, join } from "path";
import { createClient } from "@supabase/supabase-js";

const __dirname = dirname(fileURLToPath(import.meta.url));

// ── Load env ─────────────────────────────────────────────────
function loadEnv() {
  try {
    const envFile = readFileSync(join(__dirname, "../.env.local"), "utf8");
    for (const line of envFile.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) continue;
      const eqIdx = trimmed.indexOf("=");
      if (eqIdx === -1) continue;
      const key = trimmed.slice(0, eqIdx).trim();
      const val = trimmed.slice(eqIdx + 1).trim().replace(/^["']|["']$/g, "");
      if (!process.env[key]) process.env[key] = val;
    }
  } catch {
    // .env.local not found — rely on process.env
  }
}

loadEnv();

const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL;
const SERVICE_KEY  = process.env.SUPABASE_SERVICE_ROLE_KEY;

if (!SUPABASE_URL || !SERVICE_KEY) {
  console.error("❌  Missing NEXT_PUBLIC_SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY");
  console.error("    Add them to .env.local and retry.");
  process.exit(1);
}

// ── Parse --phase argument ────────────────────────────────────
const args = process.argv.slice(2);
const phaseArg = args[args.indexOf("--phase") + 1];
const requestedPhases = phaseArg
  ? phaseArg.split(",").map(Number)
  : [1, 2, 3, 4];

const PHASE_FILES = {
  1: "migrate-phase-1.sql",
  2: "migrate-phase-2.sql",
  3: "migrate-phase-3.sql",
  4: "migrate-phase-4.sql",
};

// ── Execute via Supabase REST (rpc exec_sql) ──────────────────
// Supabase doesn't expose raw SQL via JS client directly,
// so we use the pg driver if DATABASE_URL is set,
// otherwise we print instructions.

async function runWithPg(sql, phase) {
  const { default: pg } = await import("pg");
  const client = new pg.Client({ connectionString: process.env.DATABASE_URL });
  await client.connect();
  try {
    console.log(`  Executing SQL...`);
    await client.query(sql);
    console.log(`  ✅  Phase ${phase} complete`);
  } finally {
    await client.end();
  }
}

async function runPhase(phase) {
  const fileName = PHASE_FILES[phase];
  const filePath = join(__dirname, fileName);

  let sql;
  try {
    sql = readFileSync(filePath, "utf8");
  } catch {
    console.error(`  ❌  File not found: ${filePath}`);
    return false;
  }

  console.log(`\n${"─".repeat(60)}`);
  console.log(`🚀  Running Phase ${phase}: ${fileName}`);
  console.log(`${"─".repeat(60)}`);

  if (process.env.DATABASE_URL) {
    try {
      await runWithPg(sql, phase);
      return true;
    } catch (err) {
      console.error(`  ❌  Phase ${phase} failed:`, err.message);
      return false;
    }
  } else {
    // No DATABASE_URL — print the SQL for manual execution
    console.log(`\n⚠️   DATABASE_URL not set.`);
    console.log(`    Copy and run the following SQL in your Supabase SQL Editor:\n`);
    console.log(`    File: scripts/${fileName}`);
    console.log(`\n    Or set DATABASE_URL in .env.local and re-run this script.`);
    console.log(`    Format: postgresql://postgres:[password]@db.[project-ref].supabase.co:5432/postgres`);
    return false;
  }
}

// ── Main ─────────────────────────────────────────────────────
async function main() {
  console.log("╔══════════════════════════════════════════════════════════╗");
  console.log("║     BP & AF Insurance CRM — Database Migration Runner    ║");
  console.log("╚══════════════════════════════════════════════════════════╝");
  console.log(`\nTarget: ${SUPABASE_URL}`);
  console.log(`Phases: ${requestedPhases.join(", ")}`);

  let allPassed = true;
  for (const phase of requestedPhases) {
    if (!PHASE_FILES[phase]) {
      console.error(`\n❌  Unknown phase: ${phase}`);
      allPassed = false;
      continue;
    }
    const ok = await runPhase(phase);
    if (!ok) allPassed = false;
  }

  console.log(`\n${"═".repeat(60)}`);
  if (allPassed) {
    console.log("✅  All migrations completed successfully!");
    console.log("\nNext steps:");
    console.log("  1. Verify tables in Supabase Dashboard → Table Editor");
    console.log("  2. Enable pg_cron extension if not already enabled:");
    console.log("     Dashboard → Database → Extensions → pg_cron → Enable");
    console.log("  3. Start your dev server: npm run dev");
  } else {
    console.log("⚠️   Some migrations need manual attention.");
    console.log("    Run the .sql files directly in Supabase SQL Editor.");
    console.log("    Files are in: scripts/migrate-phase-*.sql");
  }
  console.log(`${"═".repeat(60)}\n`);
}

main().catch(err => {
  console.error("Fatal error:", err);
  process.exit(1);
});

/**
 * Test Runner for Monitoring System
 * Runs all monitoring tests and generates a report
 */

import { exec } from 'child_process';
import { promisify } from 'util';
import fs from 'fs/promises';
import path from 'path';

const execAsync = promisify(exec);

interface TestResult {
  suite: string;
  passed: number;
  failed: number;
  skipped: number;
  duration: number;
  errors: string[];
}

async function runTests(): Promise<void> {
  console.log('🧪 Running Monitoring System Tests...\n');

  const testFiles = [
    'tests/monitoring/enhanced-error-tracker.test.ts',
    'tests/monitoring/api-middleware.test.ts',
    'tests/monitoring/integration.test.ts',
  ];

  const results: TestResult[] = [];
  let totalPassed = 0;
  let totalFailed = 0;
  let totalSkipped = 0;
  let totalDuration = 0;

  for (const testFile of testFiles) {
    const suiteName = path.basename(testFile, '.test.ts');
    console.log(`\n📝 Running ${suiteName}...`);

    try {
      const startTime = Date.now();
      const { stdout, stderr } = await execAsync(`npx vitest run ${testFile} --reporter=json`);
      const duration = Date.now() - startTime;

      // Parse test results
      const result: TestResult = {
        suite: suiteName,
        passed: 0,
        failed: 0,
        skipped: 0,
        duration,
        errors: [],
      };

      // Count results from output
      const passedMatch = stdout.match(/(\d+) passed/);
      const failedMatch = stdout.match(/(\d+) failed/);
      const skippedMatch = stdout.match(/(\d+) skipped/);

      if (passedMatch) result.passed = parseInt(passedMatch[1]);
      if (failedMatch) result.failed = parseInt(failedMatch[1]);
      if (skippedMatch) result.skipped = parseInt(skippedMatch[1]);

      if (stderr) {
        result.errors.push(stderr);
      }

      results.push(result);

      totalPassed += result.passed;
      totalFailed += result.failed;
      totalSkipped += result.skipped;
      totalDuration += result.duration;

      // Print result
      if (result.failed === 0) {
        console.log(`✅ ${suiteName}: ${result.passed} passed (${duration}ms)`);
      } else {
        console.log(`❌ ${suiteName}: ${result.passed} passed, ${result.failed} failed (${duration}ms)`);
      }
    } catch (error: any) {
      console.error(`❌ ${suiteName}: Failed to run tests`);
      console.error(error.message);

      results.push({
        suite: suiteName,
        passed: 0,
        failed: 1,
        skipped: 0,
        duration: 0,
        errors: [error.message],
      });

      totalFailed++;
    }
  }

  // Generate report
  console.log('\n' + '='.repeat(60));
  console.log('📊 Test Summary');
  console.log('='.repeat(60));
  console.log(`Total Tests: ${totalPassed + totalFailed + totalSkipped}`);
  console.log(`✅ Passed: ${totalPassed}`);
  console.log(`❌ Failed: ${totalFailed}`);
  console.log(`⏭️  Skipped: ${totalSkipped}`);
  console.log(`⏱️  Duration: ${totalDuration}ms`);
  console.log('='.repeat(60));

  // Generate detailed report
  const report = {
    timestamp: new Date().toISOString(),
    summary: {
      total: totalPassed + totalFailed + totalSkipped,
      passed: totalPassed,
      failed: totalFailed,
      skipped: totalSkipped,
      duration: totalDuration,
    },
    suites: results,
  };

  // Save report
  const reportPath = path.join(process.cwd(), 'test-results', 'monitoring-tests.json');
  await fs.mkdir(path.dirname(reportPath), { recursive: true });
  await fs.writeFile(reportPath, JSON.stringify(report, null, 2));

  console.log(`\n📄 Report saved to: ${reportPath}`);

  // Exit with error code if tests failed
  if (totalFailed > 0) {
    console.log('\n❌ Some tests failed!');
    process.exit(1);
  } else {
    console.log('\n✅ All tests passed!');
    process.exit(0);
  }
}

// Run tests
runTests().catch((error) => {
  console.error('❌ Test runner failed:', error);
  process.exit(1);
});

import { execSync } from "child_process";
import { existsSync, readFileSync, writeFileSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";
import { createInterface } from "readline";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, "..");

const rl = createInterface({
  input: process.stdin,
  output: process.stdout,
});

const question = (query) => new Promise((resolve) => rl.question(query, resolve));

async function main() {
  console.log("╔══════════════════════════════════════════════════════════╗");
  console.log("║           BP & AF Insurance Broker — Setup Wizard        ║");
  console.log("╚══════════════════════════════════════════════════════════╝\n");

  // Step 1: Check and create .env.local
  const envLocalPath = join(ROOT, ".env.local");
  const envExamplePath = join(ROOT, ".env.example");

  if (!existsSync(envLocalPath)) {
    console.log("📄 Creating .env.local from .env.example...");
    if (existsSync(envExamplePath)) {
      const exampleContent = readFileSync(envExamplePath, "utf-8");
      writeFileSync(envLocalPath, exampleContent, "utf-8");
      console.log("   ✅ Created .env.local\n");
    } else {
      console.error("   ❌ .env.example not found! Please create .env.local manually.");
      process.exit(1);
    }
  } else {
    console.log("📄 .env.local already exists. Skipping creation.\n");
  }

  // Step 2: Read current .env.local and check if Supabase URL and Password are set
  let envContent = readFileSync(envLocalPath, "utf-8");
  const hasSupabaseUrl = envContent.includes("NEXT_PUBLIC_SUPABASE_URL=") && !envContent.match(/NEXT_PUBLIC_SUPABASE_URL=\s*\n/);
  const hasServiceKey = envContent.includes("SUPABASE_SERVICE_ROLE_KEY=") && !envContent.match(/SUPABASE_SERVICE_ROLE_KEY=\s*\n/);

  if (!hasSupabaseUrl || !hasServiceKey) {
    console.log("⚠️ Supabase credentials are missing or incomplete in .env.local.");
    console.log("   Please provide your Supabase project details.\n");

    const url = await question("   👉 Enter NEXT_PUBLIC_SUPABASE_URL (e.g. https://xxx.supabase.co): ");
    const anonKey = await question("   👉 Enter NEXT_PUBLIC_SUPABASE_ANON_KEY: ");
    const serviceKey = await question("   👉 Enter SUPABASE_SERVICE_ROLE_KEY: ");

    // Update the env content
    envContent = envContent.replace(/NEXT_PUBLIC_SUPABASE_URL=.*/, `NEXT_PUBLIC_SUPABASE_URL=${url}`);
    envContent = envContent.replace(/NEXT_PUBLIC_SUPABASE_ANON_KEY=.*/, `NEXT_PUBLIC_SUPABASE_ANON_KEY=${anonKey}`);
    envContent = envContent.replace(/SUPABASE_SERVICE_ROLE_KEY=.*/, `SUPABASE_SERVICE_ROLE_KEY=${serviceKey}`);

    writeFileSync(envLocalPath, envContent, "utf-8");
    console.log("\n   ✅ Updated .env.local with Supabase credentials.\n");
  } else {
    console.log("✅ Supabase credentials found in .env.local.\n");
  }

  // Ensure SUPABASE_DB_PASSWORD is known if pushing DB (db-push will ask if missing, but we can instruct the user)
  console.log("📦 Step 3: Installing NPM dependencies...");
  try {
    execSync("npm install", { stdio: "inherit", cwd: ROOT });
    console.log("\n   ✅ Dependencies installed.\n");
  } catch (error) {
    console.error("\n   ❌ Error installing dependencies.");
    process.exit(1);
  }

  // Step 4: Push DB Schema and Seed
  console.log("🗄️  Step 4: Pushing Database Migrations and Seed Data...");
  console.log("   You may be prompted for your database password.");
  try {
    execSync("npm run db:push", { stdio: "inherit", cwd: ROOT });
    console.log("\n   ✅ Database setup and seeding complete.\n");
  } catch (error) {
    console.error("\n   ❌ Error setting up database. Please check your credentials.");
    process.exit(1);
  }

  // Step 5: Finish
  console.log("🎉 Setup complete! The project is ready to run.\n");
  console.log("   To start the development server, run:");
  console.log("   $ npm run dev\n");
  console.log("   Login with test credentials:");
  console.log("   Admin:    admin@bpaf.com      / Admin@123456");
  console.log("   Manager:  manager@bpaf.com    / Manager@123456");
  console.log("   Employee: employee@bpaf.com   / Employee@123456\n");

  rl.close();
}

main().catch((err) => {
  console.error("Fatal Error:", err);
  rl.close();
  process.exit(1);
});

/**
 * API Tests: Authentication & Authorization
 * Tests auth middleware and permission system
 */

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { requireAuth, isAuthError } from '@/lib/api/auth-middleware';
import { hasPermission, getAccessibleModules, getAllowedActions } from '@/lib/permissions';

describe('Authentication Middleware', () => {
  describe('requireAuth()', () => {
    it('should reject requests without Authorization header', async () => {
      const mockReq = {
        headers: {
          get: vi.fn().mockReturnValue(null)
        }
      } as any;

      // Simulate requireAuth behavior
      const header = mockReq.headers.get('authorization') ?? '';
      const token = header.startsWith('Bearer ') ? header.slice(7) : null;

      expect(token).toBeNull();
    });

    it('should reject requests with invalid Bearer token', async () => {
      const mockReq = {
        headers: {
          get: vi.fn().mockReturnValue('Bearer invalid-token')
        }
      } as any;

      const header = mockReq.headers.get('authorization');
      expect(header).toBe('Bearer invalid-token');
      expect(header.startsWith('Bearer ')).toBe(true);
    });

    it('should reject expired tokens', async () => {
      const expiredToken = 'expired-jwt-token';
      const mockReq = {
        headers: {
          get: vi.fn().mockReturnValue(`Bearer ${expiredToken}`)
        }
      } as any;

      const header = mockReq.headers.get('authorization');
      expect(header).toContain('Bearer');
    });

    it('should return user claims for valid token', async () => {
      const validClaims = {
        uid: 'user-123',
        email: 'test@example.com',
        role: 'admin' as const,
        branch_id: 'branch-1'
      };

      expect(validClaims.uid).toBeTruthy();
      expect(validClaims.email).toContain('@');
      expect(['admin', 'manager', 'employee'].includes(validClaims.role)).toBe(true);
    });

    it('should enforce role restrictions', async () => {
      const employeeClaims = {
        uid: 'user-123',
        email: 'employee@example.com',
        role: 'employee' as const
      };

      const allowedRoles: Array<'admin' | 'manager'> = ['admin', 'manager'];
      const isAllowed = allowedRoles.includes(employeeClaims.role as any);

      expect(isAllowed).toBe(false);
    });

    it('should return 401 for missing token', async () => {
      const authError = { error: 'Unauthorized — missing Bearer token', status: 401 as const };
      expect(authError.status).toBe(401);
      expect(authError.error).toContain('Unauthorized');
    });

    it('should return 403 for insufficient permissions', async () => {
      const authError = { error: 'Forbidden — requires role: admin', status: 403 as const };
      expect(authError.status).toBe(403);
      expect(authError.error).toContain('Forbidden');
    });
  });

  describe('isAuthError()', () => {
    it('should identify auth errors', () => {
      const error = { error: 'Unauthorized', status: 401 as const };
      expect(isAuthError(error)).toBe(true);
    });

    it('should identify valid claims', () => {
      const claims = { uid: '123', email: 'test@test.com', role: 'admin' as const };
      expect(isAuthError(claims)).toBe(false);
    });

    it('should distinguish between error and claims by presence of error field', () => {
      const error = { error: 'Test error', status: 401 as const };
      const claims = { uid: '123', email: 'test@test.com', role: 'admin' as const };

      expect('error' in error).toBe(true);
      expect('error' in claims).toBe(false);
    });
  });
});

